import { h } from "../../kit/dom";
import { button } from "../../kit/controls";
import { card, stack, stats, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { confirmAction, choose } from "../../kit/overlays";
import { toast } from "../../kit/feedback";
import type { PageContext } from "../../shell/context";
import { floorFields, lastFloor } from "../shared";

export async function summaryHidingPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const status = await ctx.summary.compression.inspect(state);
  const config = state.catalog.compression;
  const policy = form([
    { key: "enabled", label: "自动隐藏已总结的原消息", type: "switch", value: config.enabled,
      hint: "隐藏只影响发给主模型的上下文，消息本身不会删除" },
    { key: "keepRecentMessages", label: "保留最近的原消息", type: "number", min: 0, max: 1000, value: config.keepRecentMessages,
      hint: "最近这么多条消息始终可见" },
    { key: "recentBatchCount", label: "固定注入的近期批次", type: "number", min: 0, max: 100, value: config.recentBatchCount,
      hint: "最近这么多个批次的总结固定注入，其余靠召回" },
    { key: "deletionPolicy", label: "删除总结切片时", type: "select", value: config.deletionPolicy,
      options: [["restore_first", "先恢复对应的原消息"], ["confirm_restore", "每次询问"], ["keep_hidden", "原消息保持隐藏"]] },
  ]);
  const range = form(floorFields(0, lastFloor()), { track: false });
  return stack(
    stats([["已隐藏", String(status.hidden)], ["固定可见", String(status.pinned)], ["可以隐藏", String(status.compressible)],
      ["总结召回", state.catalog.recallEnabled ? "已启用" : "未启用"]]),
    status.blockedReason ? callout("warning", status.blockedReason) : null,
    !state.catalog.recallEnabled && config.enabled ? callout("warning", "总结召回未启用时，被隐藏的经历不会再进入主模型的上下文。",
      button("去启用", () => ctx.navigate("recall/strategy"), { variant: "ghost", small: true, icon: "arrow-right" })) : null,
    formCard("隐藏策略", policy, async (values) => {
      ctx.guard();
      await ctx.summary.saveCompression({ enabled: values.enabled, keepRecentMessages: values.keepRecentMessages,
        recentBatchCount: values.recentBatchCount, deletionPolicy: values.deletionPolicy });
      await ctx.refresh();
    }, { scope: "chat", after: h("div", "ec-row",
      button("重新应用隐藏", async () => {
        ctx.guard();
        const current = await ctx.summary.load();
        const visibility = await ctx.summary.compression.inspectVisibility(current);
        ctx.guard();
        const pinned = visibility.filter((batch) => batch.pinned > 0);
        const unpin = pinned.length > 0 && await choose({
          title: "解除固定可见？", cancelValue: false,
          message: `${pinned.length} 个批次中有固定可见的原消息，通常来自恢复操作。解除后会按策略重新隐藏。`,
          choices: [{ value: false, label: "保留固定可见" }, { value: true, label: "解除并重新隐藏", variant: "primary", focus: true }],
        });
        const result = await ctx.run("重新应用隐藏", () => unpin
          ? ctx.summary.compression.recompressBatch(current, pinned.map((batch) => batch.batchId))
          : ctx.summary.compression.reconcile(current));
        toast(result.blockedReason ?? `已应用：隐藏 ${result.hidden} 条，固定可见 ${result.pinned} 条。`, result.blockedReason ? "warning" : "success");
        await ctx.refresh();
      }, { icon: "arrows-rotate", small: true })) }),
    card("恢复原消息", { description: "恢复后的消息会固定可见，直到重新应用隐藏并选择解除。" }, range.node,
      h("div", "ec-row ec-card-foot",
        button("恢复全部", async () => {
          if (!await confirmAction({ title: "恢复所有由 Echoes 隐藏的原消息？", confirmLabel: "恢复" })) return;
          ctx.guard();
          await ctx.summary.compression.restoreAll(state);
          await ctx.refresh();
        }, { icon: "eye" }),
        button("恢复所选范围", async () => {
          const values = range.values();
          ctx.guard();
          await ctx.summary.compression.restoreRange(state, values.start, values.end);
          await ctx.refresh();
        }, { variant: "primary", icon: "eye" }))),
  );
}
