import { h, icon, uid } from "./dom";
import { reportError } from "./feedback";
import { overlayHost } from "./theme";

export type ButtonVariant = "primary" | "secondary" | "danger" | "ghost";
export interface ButtonOptions {
  icon?: string | undefined;
  variant?: ButtonVariant | undefined;
  small?: boolean | undefined;
  title?: string | undefined;
  disabled?: boolean | undefined;
}

/** A button whose async handler disables it while pending and reports failures. */
export function button(label: string, onClick: () => unknown, options: ButtonOptions = {}): HTMLButtonElement {
  const glyph = options.icon ? icon(options.icon) : null;
  const node = h("button", `ec-btn is-${options.variant ?? "secondary"}${options.small ? " is-small" : ""}`,
    glyph, label ? h("span", "", label) : null);
  node.type = "button";
  if (options.title) node.title = options.title;
  node.disabled = Boolean(options.disabled);
  node.addEventListener("click", () => {
    if (node.disabled) return;
    let result: unknown;
    try {
      result = onClick();
    } catch (error) {
      reportError(error);
      return;
    }
    if (!(result instanceof Promise)) return;
    node.disabled = true;
    node.setAttribute("aria-busy", "true");
    const original = glyph?.className;
    if (glyph) glyph.className = "fa-solid fa-spinner fa-spin";
    void result.catch(reportError).finally(() => {
      node.disabled = false;
      node.removeAttribute("aria-busy");
      if (glyph && original) glyph.className = original;
    });
  });
  return node;
}

export function iconButton(label: string, glyph: string, onClick: () => unknown, options: Omit<ButtonOptions, "icon"> = {}): HTMLButtonElement {
  const node = button("", onClick, { ...options, icon: glyph, variant: options.variant ?? "ghost" });
  node.classList.add("is-icon");
  node.title = options.title ?? label;
  node.setAttribute("aria-label", label);
  return node;
}

export interface SwitchOptions {
  hint?: string | undefined;
  disabled?: boolean | undefined;
}

/** A labelled switch that applies immediately and reverts when the change fails. */
export function switchControl(label: string, checked: boolean, onChange: (value: boolean) => unknown, options: SwitchOptions = {}): HTMLLabelElement {
  const input = h("input", "ec-switch");
  input.type = "checkbox";
  input.setAttribute("role", "switch");
  input.checked = checked;
  input.disabled = Boolean(options.disabled);
  const text = h("span", "ec-switch-text", h("span", "", label), options.hint ? h("small", "", options.hint) : null);
  const node = h("label", "ec-switch-row", text, input);
  input.addEventListener("change", () => {
    const next = input.checked;
    const revert = (error: unknown) => {
      input.checked = !next;
      reportError(error);
    };
    let result: unknown;
    try {
      result = onChange(next);
    } catch (error) {
      revert(error);
      return;
    }
    if (result instanceof Promise) {
      input.disabled = true;
      void result.catch(revert).finally(() => { input.disabled = Boolean(options.disabled); });
    }
  });
  return node;
}

export function selectControl(label: string, options: Array<[string, string]>, value: string,
  onChange: (value: string) => unknown): HTMLSelectElement {
  const node = h("select", "ec-select");
  node.setAttribute("aria-label", label);
  for (const [optionValue, optionLabel] of options) node.add(new Option(optionLabel, optionValue));
  node.value = value;
  node.addEventListener("change", () => {
    try {
      const result = onChange(node.value);
      if (result instanceof Promise) void result.catch(reportError);
    } catch (error) {
      reportError(error);
    }
  });
  return node;
}

export type Tone = "neutral" | "accent" | "success" | "warning" | "danger";
export function badge(text: string, tone: Tone = "neutral"): HTMLElement {
  return h("span", `ec-badge is-${tone}`, text);
}
export function scope(kind: "global" | "chat"): HTMLElement {
  const node = h("span", `ec-scope is-${kind}`, kind === "global" ? "全局" : "当前聊天");
  node.title = kind === "global" ? "对所有聊天生效" : "只保存在当前聊天";
  return node;
}
export function dot(tone: Tone = "warning", label = "有待处理事项"): HTMLElement {
  const node = h("span", `ec-dot is-${tone}`);
  node.setAttribute("role", "img");
  node.setAttribute("aria-label", label);
  return node;
}

export interface MenuItem {
  label: string;
  icon?: string | undefined;
  danger?: boolean | undefined;
  disabled?: boolean | undefined;
  onSelect: () => unknown;
}

/** An overflow menu; items run like buttons and the menu closes first. */
export function menu(label: string, items: Array<MenuItem | null | false>, glyph = "ellipsis"): HTMLButtonElement {
  const trigger = iconButton(label, glyph, () => open());
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.setAttribute("aria-expanded", "false");
  const open = () => {
    const entries = items.filter((item): item is MenuItem => Boolean(item));
    const list = h("div", "ec-menu");
    list.id = uid("menu");
    list.setAttribute("role", "menu");
    const close = () => {
      list.remove();
      trigger.setAttribute("aria-expanded", "false");
      document.removeEventListener("pointerdown", outside, true);
      window.removeEventListener("resize", close);
      document.removeEventListener("scroll", scrolled, true);
    };
    const outside = (event: Event) => {
      if (!list.contains(event.target as Node) && event.target !== trigger) close();
    };
    const scrolled = (event: Event) => {
      if (!list.contains(event.target as Node)) close();
    };
    const buttons = entries.map((item) => {
      const node = h("button", `ec-menu-item${item.danger ? " is-danger" : ""}`,
        item.icon ? icon(item.icon) : h("span", "ec-menu-gap"), h("span", "", item.label));
      node.type = "button";
      node.setAttribute("role", "menuitem");
      node.disabled = Boolean(item.disabled);
      node.addEventListener("click", () => {
        close();
        trigger.focus();
        try {
          const result = item.onSelect();
          if (result instanceof Promise) void result.catch(reportError);
        } catch (error) {
          reportError(error);
        }
      });
      return node;
    });
    list.append(...buttons);
    list.addEventListener("keydown", (event) => {
      const enabled = buttons.filter((node) => !node.disabled);
      const index = enabled.indexOf(document.activeElement as HTMLButtonElement);
      if (event.key === "Escape" || event.key === "Tab") {
        event.preventDefault();
        event.stopPropagation();
        close();
        trigger.focus();
      } else if (event.key === "ArrowDown" || event.key === "ArrowUp") {
        event.preventDefault();
        const step = event.key === "ArrowDown" ? 1 : -1;
        enabled[(index + step + enabled.length) % enabled.length]?.focus();
      }
    });
    overlayHost().append(list);
    const rect = trigger.getBoundingClientRect();
    const width = list.offsetWidth, height = list.offsetHeight;
    const left = Math.max(8, Math.min(window.innerWidth - width - 8, rect.right - width));
    const below = rect.bottom + 4 + height <= window.innerHeight - 8;
    list.style.left = `${left}px`;
    list.style.top = `${below ? rect.bottom + 4 : Math.max(8, rect.top - height - 4)}px`;
    trigger.setAttribute("aria-expanded", "true");
    document.addEventListener("pointerdown", outside, true);
    window.addEventListener("resize", close);
    document.addEventListener("scroll", scrolled, true);
    buttons.find((node) => !node.disabled)?.focus();
  };
  return trigger;
}
