import { getSettings } from "../state/settings";
import type { StatusWorldbookState } from "../worldbook/status-worldbook";
import { statusCoordinator as coordinator } from "./status-coordinator";

const POSITION_KEY = "echoes.status-floating-position";

export function installStatusFloatingButton(onUpdated: () => void): void {
  if (document.getElementById("echoes-status-floating")) return;
  const root = document.createElement("div");
  root.id = "echoes-status-floating";
  root.hidden = true;
  const button = document.createElement("button");
  button.type = "button";
  const glyph = document.createElement("i");
  glyph.setAttribute("aria-hidden", "true");
  const label = document.createElement("span");
  label.className = "echoes-status-announcement";
  label.setAttribute("aria-live", "polite");
  button.append(glyph);
  root.append(button, label);
  document.body.append(root);
  let state: StatusWorldbookState | null = null;
  let revision = 0;
  let dragged = false;
  let drag: { id: number; x: number; y: number; left: number; top: number } | null = null;
  let position: { left: number; top: number } | null = null;
  try {
    const saved = JSON.parse(localStorage.getItem(POSITION_KEY) ?? "null");
    if (saved && Number.isFinite(saved.left) && Number.isFinite(saved.top)) position = saved;
  } catch {}
  const place = () => {
    if (!position || root.hidden) return;
    const rect = root.getBoundingClientRect();
    position.left = Math.max(8, Math.min(window.innerWidth - rect.width - 8, position.left));
    position.top = Math.max(8, Math.min(window.innerHeight - rect.height - 8, position.top));
    Object.assign(root.style, { left: position.left + "px", top: position.top + "px", right: "auto", bottom: "auto" });
  };
  const render = () => {
    const chatId = SillyTavern.getContext().chatId;
    const worldbook = window.TavernHelper?.getChatWorldbookName("current");
    const activity = coordinator.activity;
    const trace = coordinator.trace;
    root.hidden = !chatId || !state?.catalog.enabled || state.catalog.chatId !== chatId
      || state.worldbookName !== worldbook || !getSettings().statusFloatingButton;
    if (root.hidden || !state) return;
    const current = coordinator.current(state);
    const failed = (trace?.outcome === "failed" || trace?.outcome === "decision_required")
      && (!current || current.snapshot.updatedAt < trace.startedAt);
    const stale = !current || SillyTavern.getContext().chat.some((message, index) =>
      index > current.messageIndex && message.is_user !== true && message.role !== "user"
      && Boolean(String(message.mes ?? message.message ?? "").trim()));
    root.dataset.state = activity.running ? "running" : failed ? "failed" : stale ? "pending" : "ready";
    label.textContent = activity.running ? "状态更新中" : failed ? "状态更新失败" : stale ? "状态待同步" : "状态记忆";
    glyph.className = "fa-solid " + (activity.running ? "fa-spinner fa-spin" : failed ? "fa-triangle-exclamation" : "fa-arrows-rotate");
    button.disabled = activity.running;
    button.setAttribute("aria-busy", String(activity.running));
    button.title = activity.running ? activity.message || "正在更新状态"
      : failed ? `${trace?.message ?? "状态更新失败"}\n点击重试状态同步`
        : "点击手动同步状态；可拖动调整位置";
    button.setAttribute("aria-label", `${label.textContent}。${button.title}`);
    place();
  };
  const refresh = async () => {
    const ticket = ++revision;
    const name = window.TavernHelper?.getChatWorldbookName("current");
    state = null;
    render();
    if (!name) return;
    try {
      // A new chat need not have a status catalog yet; find() returns null for that case.
      const next = await coordinator.worldbook.find(name);
      if (revision !== ticket) return;
      state = next;
      render();
    } catch (error) {
      if (revision === ticket) {
        root.hidden = true;
        console.warn("[Echoes] Cannot read floating status control.", error);
      }
    }
  };
  button.addEventListener("click", () => {
    if (dragged) { dragged = false; return; }
    if (coordinator.activity.running) return;
    const chatId = SillyTavern.getContext().chatId;
    void coordinator.synchronize().then(() => {
      if (SillyTavern.getContext().chatId !== chatId) return;
      const trace = coordinator.trace;
      if (trace?.outcome === "completed") toastr.success("状态已更新。", "Echoes");
      else if (trace?.outcome === "unchanged") toastr.info(trace.message ?? "状态未变化。", "Echoes");
      else toastr.warning(trace?.message ?? "本次未写入新的状态快照。", "Echoes");
      onUpdated();
    }).catch((error: unknown) => {
      toastr.error(error instanceof Error ? error.message : String(error), "Echoes 状态更新失败");
    });
  });
  root.addEventListener("pointerdown", (event) => {
    if (event.button !== 0) return;
    const rect = root.getBoundingClientRect();
    dragged = false;
    drag = { id: event.pointerId, x: event.clientX, y: event.clientY, left: rect.left, top: rect.top };
    button.setPointerCapture(event.pointerId);
  });
  root.addEventListener("pointermove", (event) => {
    if (!drag || drag.id !== event.pointerId) return;
    const dx = event.clientX - drag.x, dy = event.clientY - drag.y;
    if (Math.abs(dx) + Math.abs(dy) < 5 && !dragged) return;
    dragged = true;
    position = { left: drag.left + dx, top: drag.top + dy };
    place();
  });
  const endDrag = () => {
    if (dragged && position) {
      try { localStorage.setItem(POSITION_KEY, JSON.stringify(position)); } catch {}
    }
    drag = null;
    setTimeout(() => { dragged = false; }, 0);
  };
  root.addEventListener("pointerup", endDrag);
  root.addEventListener("pointercancel", () => { endDrag(); dragged = false; });
  window.addEventListener("resize", place);
  window.addEventListener("echoes-status-configuration-changed", () => void refresh());
  coordinator.subscribe(() => {
    if (coordinator.activity.running) render();
    else void refresh();
  });
  for (const event of ["chat_changed", "chat_id_changed", "message_received", "message_edited",
    "message_swiped", "message_deleted", "generation_ended", "generation_stopped"]) {
    SillyTavern.getContext().eventSource?.on(event, () => void refresh());
  }
  void refresh();
}
