import type { JobRecord } from "../../../shared/domain";
import type { SummaryCoordinator } from "../../summary/summary-coordinator";

/** Everything a tab page receives. One context per render; it is aborted on re-render. */
export interface PageContext {
  route: string;
  chatId: string;
  worldbook: string | null;
  summary: SummaryCoordinator;
  signal: AbortSignal;
  /** Per-chat UI memory (filters, pages, drafts) that survives re-renders. */
  memo<T>(key: string, initial: () => T): T;
  forget(key: string): void;
  /** Throws when the chat or bound worldbook changed since this render began. */
  guard(): void;
  refresh(): Promise<void>;
  navigate(route: string): void;
  /** Runs work as a tracked task shown in the task tray. */
  run<T>(label: string, work: () => Promise<T>, stop?: () => Promise<unknown>): Promise<T>;
  /** Starts a server job, tracks it in the tray, waits for its result. */
  job<T>(label: string, start: () => Promise<JobRecord<T>>): Promise<T>;
  /** Refreshes sidebar and tab markers after a page changes attention state. */
  markers(): void;
}

export type PageRenderer = (ctx: PageContext) => Promise<HTMLElement> | HTMLElement;

export interface TabDefinition {
  id: string;
  label: string;
  render: PageRenderer;
  /** Defaults to the module setting. */
  requiresChat?: boolean | undefined;
}

export interface ModuleDefinition {
  id: string;
  label: string;
  icon: string;
  group: "top" | "memory" | "tools" | "config";
  requiresChat: boolean;
  tabs: TabDefinition[];
}

export const GROUP_LABELS: Record<ModuleDefinition["group"], string> = {
  top: "", memory: "记忆", tools: "工具", config: "配置",
};
