import type { SummaryPreprocessRule } from "../../../shared/domain";
import { summaryPreprocessRuleSchema } from "../../../shared/schemas";
import { indexedChatMessages, messageRangeByFloor } from "../../chat-message-index";
import { previewSummaryPreprocess } from "../../summary/preprocess";
import { h, fill, uid } from "../kit/dom";
import { button, badge } from "../kit/controls";
import { form } from "../kit/forms";
import { formModal, modal } from "../kit/overlays";
import { sortable } from "../kit/sortable";
import { lazy } from "../kit/layout";
import { floorFields, lastFloor } from "./shared";

const OPERATIONS = { extract: "保留匹配", remove: "删除匹配", replace: "替换" } as const;

/** Linear prefix/suffix diff: highlights the changed span without quadratic diffing. */
function compare(before: string, after: string): HTMLElement {
  let start = 0;
  while (start < before.length && start < after.length && before[start] === after[start]) start++;
  let suffix = 0;
  while (suffix < before.length - start && suffix < after.length - start
    && before[before.length - suffix - 1] === after[after.length - suffix - 1]) suffix++;
  const render = (text: string, kind: "del" | "ins") => h("pre", "ec-code",
    text.slice(0, start), h(kind, "", text.slice(start, text.length - suffix)), suffix ? text.slice(-suffix) : "");
  return h("div", "ec-compare", h("div", "", h("h4", "", "原文"), render(before, "del")),
    h("div", "", h("h4", "", after ? "清洗后" : "清洗后为空"), render(after, "ins")));
}

function previewRules(rules: SummaryPreprocessRule[]): void {
  const ordered = rules.map((rule, order) => ({ ...rule, order }));
  const range = form(floorFields(Math.max(0, lastFloor() - 3), lastFloor()), { track: false });
  const result = h("div", "ec-stack");
  modal("清洗效果预览（未保存的规则）", [range.node, h("div", "ec-row", button("生成对照", async () => {
    const { start, end } = range.values();
    const messages = messageRangeByFloor(start, end).messages;
    const floors = new Map(indexedChatMessages().map(({ floor, message }) => [message.id, floor]));
    const report = await previewSummaryPreprocess(messages, ordered);
    const cleaned = new Map(report.messages.map((message) => [message.id, message.content]));
    fill(result, ...messages.map((message) => {
      const text = cleaned.get(message.id) ?? "";
      return lazy(h("span", "", `第 ${floors.get(message.id)} 楼 · ${message.role === "user" ? "主持人" : "助手"} `,
        badge(text === message.content ? "未改变" : text ? "已改变" : "清洗后为空", text === message.content ? "neutral" : "accent")),
      () => h("div", "ec-stack", compare(message.content, text),
        ...report.notes.filter((note) => note.messageId === message.id).map((note) => h("p", "ec-muted", `${note.rule}：${note.reason}`))));
    }));
  }, { icon: "eye", variant: "primary" })), result], { size: "large" });
}

function editRule(item: SummaryPreprocessRule | undefined, done: (rule: SummaryPreprocessRule) => void, drafts: SummaryPreprocessRule[]): void {
  const target = form([
    { key: "name", label: "名称", value: item?.name ?? "", required: true },
    { key: "type", label: "操作", type: "select", value: item?.type ?? "remove", options: Object.entries(OPERATIONS) },
    { key: "pattern", label: "正则表达式", type: "code", rows: 2, value: item?.pattern ?? "", required: true },
    { key: "flags", label: "标志", value: item?.flags ?? "g" },
    { key: "replacement", label: "替换为", value: item?.replacement ?? "" },
    { key: "extractionMode", label: "保留的内容", type: "select", value: item?.extraction?.mode ?? (item ? "auto" : "match"),
      options: [["match", "完整匹配"], ["group", "指定捕获组"], ["auto", "全部捕获组（无组时用完整匹配）"]] },
    { key: "group", label: "捕获组序号", type: "number", min: 1, max: 99, value: item?.extraction?.group ?? 1 },
    { key: "separator", label: "片段之间的分隔", type: "textarea", rows: 2, value: item?.extraction?.separator ?? "\n" },
    { key: "user", label: "作用于主持人消息", type: "switch", value: item?.roles.includes("user") ?? true },
    { key: "assistant", label: "作用于助手消息", type: "switch", value: item?.roles.includes("assistant") ?? true },
  ]);
  const sync = () => {
    const type = target.control("type").value;
    target.show("replacement", type === "replace");
    for (const key of ["extractionMode", "separator"]) target.show(key, type === "extract");
    target.show("group", type === "extract" && target.control("extractionMode").value === "group");
  };
  target.control("type").addEventListener("change", sync);
  target.control("extractionMode").addEventListener("change", sync);
  sync();
  const read = () => {
    const values = target.values();
    new RegExp(values.pattern, values.flags);
    return summaryPreprocessRuleSchema.parse({
      id: item?.id ?? uid("rule"), name: values.name, type: values.type, pattern: values.pattern, flags: values.flags,
      replacement: values.replacement ?? item?.replacement ?? "",
      extraction: { mode: values.extractionMode ?? item?.extraction?.mode ?? "match", group: values.group ?? item?.extraction?.group ?? 1,
        separator: values.separator ?? item?.extraction?.separator ?? "\n" },
      roles: [...(values.user ? ["user" as const] : []), ...(values.assistant ? ["assistant" as const] : [])],
      enabled: item?.enabled ?? true, order: item?.order ?? 0,
    });
  };
  formModal(item ? `编辑清洗规则 · ${item.name}` : "添加清洗规则", target, () => done(read()), { size: "large", extra: [
    button("预览效果", () => {
      const draft = read();
      const next = structuredClone(drafts);
      const index = item ? next.findIndex((rule) => rule.id === item.id) : -1;
      if (index < 0) next.push(draft);
      else next[index] = draft;
      previewRules(next);
    }, { variant: "ghost", icon: "eye" }),
  ] });
}

/** Ordered regex cleaning rules, applied to messages before they are sent. */
export function cleaningList(rules: readonly SummaryPreprocessRule[], save: (rules: SummaryPreprocessRule[]) => unknown): HTMLElement {
  return sortable<SummaryPreprocessRule>({
    items: rules,
    describe: (rule) => ({ title: rule.name, tag: OPERATIONS[rule.type], note: `/${rule.pattern}/${rule.flags}` }),
    edit: editRule,
    save: (items) => save(items.map((rule, order) => ({ ...rule, order }))),
    toggle: { get: (rule) => rule.enabled, set: (rule, value) => ({ ...rule, enabled: value }) },
    addLabel: "添加规则",
    extra: (drafts) => [button("预览效果", () => previewRules(drafts()), { small: true, variant: "ghost", icon: "eye" })],
    emptyText: "没有清洗规则，消息按原文发送。",
  });
}
