import { summaryBatchSnapshot } from "../../../worldbook/summary-worldbook";
import { summaryProviderMessages } from "../../../../shared/summary-protocol";
import { getSettings } from "../../../state/settings";
import { checkpointFloor } from "../../../chat-message-index";
import type { SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { h, fill, formatTime, download } from "../../kit/dom";
import { button, badge, switchControl } from "../../kit/controls";
import { card, kv, lazy, muted, stack, callout, code } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formModal, modal, confirmAction } from "../../kit/overlays";
import { table } from "../../kit/data";
import type { PageContext } from "../../shell/context";
import { floorFields, floorText, lastFloor } from "../shared";

const TRACE_STATE = { running: "运行中", succeeded: "完成", incomplete: "未完成", failed: "失败", cancelled: "已取消" } as const;

function runCard(ctx: PageContext, initial: SummaryWorldbookState): HTMLElement {
  const host = h("div", "ec-stack");
  let revision = 0;
  const render = async (state: SummaryWorldbookState) => {
    const ticket = ++revision;
    const pending = await ctx.summary.pendingStatus(state);
    if (ctx.signal.aborted || ticket !== revision) return;
    const running = ctx.summary.isRunning();
    fill(host,
      kv([
        ["状态", running ? badge(pending.reason, "accent") : h("span", "", pending.reason)],
        ["检查点", floorText(state.catalog.lastCommittedMessageId)],
        ["下一批次编号", String(state.catalog.nextBatchNumber)],
        ["待处理", pending.pendingCount ? `第 ${pending.start}–${pending.end} 楼，${pending.pendingCount} 条有内容的消息` : "检查点之后没有待处理的正文"],
        ["停止点", pending.stop === null ? "未设置" : pending.stop < 0 ? "停止点消息已不存在" : `第 ${pending.stop} 楼`],
      ]),
      pending.ranges.length ? table([
        { label: "后续批次", cell: (_range, index) => String(index + 1) },
        { label: "楼层", cell: (range) => `${range.start}–${range.end}` },
        { label: "消息", cell: (range) => String(range.count) },
        { label: "", cell: (range) => pending.stop !== null && (pending.stop < 0 || range.end > pending.stop) ? badge("越过停止点", "warning") : "" },
      ], pending.ranges) : null,
      h("div", "ec-row",
        button("检查待处理消息", async () => {
          await ctx.run("自动总结", () => { ctx.guard(); return ctx.summary.checkPending(); }, () => ctx.summary.stop());
          await ctx.refresh();
        }, { icon: "play", disabled: running }),
        button("完成当前批次后停止", async () => {
          if (!await confirmAction({ title: "完成当前批次后停止？", confirmLabel: "确定",
            message: "当前批次的索引同步和批次总结会照常完成，之后不再开始下一批；取消或结果不确定时立即暂停。" })) return;
          ctx.guard();
          await ctx.summary.stopAfterCurrentBatch();
        }, { icon: "hourglass-end", disabled: !running }),
        button("停止", () => ctx.summary.stop(), { variant: "danger", icon: "stop", disabled: !running }),
        button("设置停止点", () => {
          const target = form([{ key: "floor", label: "自动总结最多处理到楼层", type: "number", min: -1, max: lastFloor(), required: true,
            value: pending.stop ?? -1, hint: "-1 表示取消停止点。批次不会被截短，越过停止点的批次不会开始。" }], { className: "is-single" });
          formModal("自动总结停止点", target, async (values) => {
            ctx.guard();
            await ctx.summary.setAutomaticStopFloor(values.floor);
            await render(await ctx.summary.load());
          }, { size: "small" });
        }, { variant: "ghost", icon: "flag-checkered" }),
        menuButtons(ctx, state)),
    );
  };
  void render(initial);
  const unsubscribe = ctx.summary.subscribeProgress((state) => void render(state));
  ctx.signal.addEventListener("abort", unsubscribe, { once: true });
  return card("运行", { scope: "chat", actions: [switchControl("自动总结", initial.catalog.autoRun, async (value) => {
    ctx.guard();
    await ctx.run("更新自动总结设置", () => ctx.summary.setAutoRun(value));
    if (value) void ctx.run("自动总结", () => ctx.summary.runAutomatic(), () => ctx.summary.stop()).catch(() => undefined);
  })] }, host);
}

function menuButtons(ctx: PageContext, state: SummaryWorldbookState): HTMLElement {
  return h("div", "ec-row",
    button("修改检查点", () => {
      const target = form([{ key: "floor", label: "检查点楼层", type: "number", min: -1, max: lastFloor(), required: true,
        value: checkpointFloor(state.catalog.lastCommittedMessageId), hint: "-1 表示尚未处理。修改后自动总结会关闭，已有切片保留。" }], { className: "is-single" });
      formModal("修改总结检查点", target, async (values) => {
        ctx.guard();
        await ctx.summary.relocateCheckpointToFloor(values.floor);
        await ctx.refresh();
      }, { size: "small", saveLabel: "修改" });
    }, { variant: "ghost", icon: "pen" }),
    button("下一批次编号", () => {
      const target = form([{ key: "number", label: "下一批次编号", type: "number", min: 1, value: state.catalog.nextBatchNumber, required: true }], { className: "is-single" });
      formModal("设置下一批次编号", target, async (values) => {
        ctx.guard();
        await ctx.summary.setNextBatchNumber(values.number);
        await ctx.refresh();
      }, { size: "small" });
    }, { variant: "ghost", icon: "hashtag" }));
}

export async function summaryGenerationPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const checkpoint = checkpointFloor(state.catalog.lastCommittedMessageId);
  const manual = form(floorFields(Math.min(checkpoint + 1, lastFloor()), lastFloor()), { track: false });
  const draft = (await ctx.summary.pendingStatus(state)).draft;
  const rebuilds = ctx.summary.rebuildDrafts();
  const pendingResults = draft || rebuilds.length ? card("待确认的结果", { description: "以下结果还没有写入世界书。" },
    draft ? h("div", "ec-subcard",
      h("div", "ec-row", h("strong", "", "未提交的恢复草稿"),
        badge(`${draft.parts.filter((part) => part.slices).length}/${draft.parts.length} 个子请求已完成`),
        badge(draft.status === "ready" ? "可以写入" : "需要确认后继续", "warning")),
      draft.reason ? muted(draft.reason) : null,
      lazy("草稿详情", draft),
      h("div", "ec-row",
        button("继续", async () => {
          if (!await confirmAction({ title: "继续这项总结任务？", cost: true, confirmLabel: "继续",
            message: "复用已成功的子请求，重试失败的子请求，之后建立索引和批次总结；不会自动继续后面的批次。" })) return;
          await ctx.run("恢复总结", () => ctx.summary.resumeRecovery(), () => ctx.summary.stop());
          await ctx.refresh();
        }, { variant: "primary", icon: "play", small: true }),
        button("导出草稿", () => download("echoes-summary-draft.json", JSON.stringify(draft, null, 2)), { variant: "ghost", small: true, icon: "download" }),
        button("放弃", async () => {
          if (!await confirmAction({ title: "放弃未提交的草稿？", danger: true, confirmLabel: "放弃",
            message: "已正式保存的记忆不受影响；后台请求会尽量取消，已产生的费用无法撤回。" })) return;
          ctx.guard();
          await ctx.summary.discardRecovery();
          await ctx.refresh();
        }, { variant: "danger", small: true, icon: "trash" }))) : null,
    ...rebuilds.map((item) => h("div", "ec-subcard",
      h("div", "ec-row", h("strong", "", `批次 ${item.batch.batchNumber} 的重建候选`), badge(`${item.candidates.length} 个切片`)),
      h("div", "ec-row",
        button("核对", () => modal(`批次 ${item.batch.batchNumber} 重建对照`, h("div", "ec-compare",
          h("div", "", h("h4", "", "当前保存的切片"), code(JSON.stringify(state.slices.filter((slice) => slice.batch.id === item.batch.id)
            .map(({ timestamp, title, content, tags }) => ({ timestamp, title, content, tags })), null, 2))),
          h("div", "", h("h4", "", "待确认的生成结果"), code(JSON.stringify(item.candidates, null, 2)))), { size: "large" }),
        { variant: "ghost", small: true, icon: "code-compare" }),
        button("替换该批次", async () => {
          if (!await confirmAction({ title: `用候选替换批次 ${item.batch.batchNumber}？`, cost: true, confirmLabel: "替换",
            message: "不会重新生成切片，但会单独调用总结端点生成批次总结。" })) return;
          await ctx.run("写入重建候选", () => ctx.summary.commitRebuildDraft(item.batch.id, summaryBatchSnapshot(state.slices, item.batch.id)), () => ctx.summary.stop());
          await ctx.refresh();
        }, { variant: "primary", small: true, icon: "floppy-disk" }),
        button("丢弃", async () => {
          if (!await confirmAction({ title: "丢弃这些重建候选？", danger: true, confirmLabel: "丢弃" })) return;
          ctx.guard();
          await ctx.summary.discardRebuildDraft(item.batch.id);
          await ctx.refresh();
        }, { variant: "danger", small: true, icon: "trash" })))),
  ) : null;
  const history = ctx.summary.history();
  return stack(
    runCard(ctx, state),
    pendingResults,
    card("手动生成", { description: "为指定楼层范围生成一个新批次。" }, manual.node, h("div", "ec-row ec-card-foot",
      button("预览请求", async () => {
        const values = manual.values();
        ctx.guard();
        const request = await ctx.summary.previewManual(values.start, values.end);
        const messages = summaryProviderMessages({ promptMessages: request.promptMessages, extractAttributes: getSettings().continuity.extractAttributes });
        modal("总结请求预览", [
          ...messages.map((message, index) => lazy(`${index + 1} · ${message.role} · ${message.content.length} 字`, () => code(message.content))),
          lazy("完整请求数据（含子请求）", request),
        ], { size: "large" });
      }, { variant: "ghost", icon: "eye" }),
      button("生成", async () => {
        const values = manual.values();
        if (!await confirmAction({ title: `总结第 ${values.start}–${values.end} 楼？`, cost: true, confirmLabel: "生成" })) return;
        await ctx.run(`总结 ${values.start}–${values.end}`, () => ctx.summary.runManual(values.start, values.end), () => ctx.summary.stop());
        await ctx.refresh();
      }, { variant: "primary", icon: "play" }))),
    card("最近生成记录", { description: "仅本次页面会话。", actions: history.length ? [button("清空", async () => {
      ctx.summary.clearHistory();
      await ctx.refresh();
    }, { variant: "ghost", small: true })] : [] },
    history.length ? h("div", "ec-stack", ...history.slice().reverse().map((trace) =>
      lazy(`批次 ${trace.batchNumber} · ${TRACE_STATE[trace.state]} · ${formatTime(trace.startedAt, false)}`, () => table([
        { label: "阶段", cell: (stage) => stage.name }, { label: "数量", cell: (stage) => String(stage.count) },
        { label: "时间", cell: (stage) => formatTime(stage.at, false) }, { label: "错误", cell: (stage) => stage.error ?? "" },
      ], trace.stages)))) : muted("本次会话还没有生成记录。")),
    callout("info", "生成规则、提示词和消息清洗在“设置”页调整。"),
  );
}
