import type { MemoryRow } from "../../../../shared/domain";
import { SummaryWorldbookStore, type SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { readMemoryHistory } from "../../../worldbook/memory-history";
import { statusCoordinator } from "../../../status/status-coordinator";
import { h, fill, formatTime, preview } from "../../kit/dom";
import { button, switchControl, selectControl, badge } from "../../kit/controls";
import { callout, empty, lazy, muted, heading } from "../../kit/layout";
import { list, paginate, pager, searchBox, keepSearchFocus } from "../../kit/data";
import { drawer } from "../../kit/drawer";
import type { PageContext } from "../../shell/context";
import { memoryStore, displayValue } from "./row-editor";

const PEOPLE_TEMPLATE = "echoes_people_template";
const RELATION_TEMPLATE = "echoes_relationships_template";

export async function peoplePage(ctx: PageContext): Promise<HTMLElement> {
  const state = await memoryStore.load();
  const ui = ctx.memo("structured-people", () => ({
    typeId: state.catalog.types.find((type) => type.templateId === PEOPLE_TEMPLATE)?.id ?? state.catalog.types[0]?.id ?? "",
    query: "", page: 0, attached: false,
  }));
  if (!state.catalog.types.length) return empty("当前聊天还没有资料表。");
  if (!state.catalog.types.some((type) => type.id === ui.typeId)) ui.typeId = state.catalog.types[0]!.id;
  const entries = await window.TavernHelper!.getWorldbook(state.worldbookName);
  const summaries = entries.some((entry) => entry.extra?.echoes?.kind === "summary_catalog")
    ? await ctx.summary.store.inspect(state.worldbookName) : undefined;
  const status = await statusCoordinator.worldbook.find(state.worldbookName);
  const current = status ? statusCoordinator.current(status)?.snapshot.state ?? status.catalog.profile.initialState : undefined;
  const history = await readMemoryHistory(state.worldbookName);
  const pane = drawer("人物聚合");
  const host = h("div", "ec-stack");
  let version = 0;

  const openEntry = (row: MemoryRow) => {
    ctx.forget("structured-entries");
    ctx.memo("structured-entries", () => ({ typeId: row.typeId, query: "", status: "all", page: 0, selected: new Set<string>(), open: row.id }));
    ctx.navigate("structured/entries");
  };
  const rowBlock = (row: MemoryRow, reason: string) => {
    const type = state.catalog.types.find((item) => item.id === row.typeId)!;
    return lazy(h("span", "", `${type.name} · ${row.dataName} `, reason ? badge(reason) : null), () => h("div", "ec-stack",
      ...type.columns.filter((column) => displayValue(row.values[column.id]) !== "").map((column) =>
        h("div", "ec-field-block", h("h4", "", column.name), h("div", "ec-prose", displayValue(row.values[column.id])))),
      h("div", "ec-row", button("打开条目", () => openEntry(row), { variant: "ghost", small: true, icon: "arrow-up-right-from-square" }))));
  };

  const show = async (person: MemoryRow) => {
    const ticket = ++version;
    const names = [...new Set([person.dataName, ...(person.aliases ?? [])])].filter(Boolean);
    const lowered = names.map((name) => name.toLocaleLowerCase());
    const mention = (value: unknown) => {
      const text = (typeof value === "string" ? value : JSON.stringify(value) ?? "").toLocaleLowerCase();
      if (text.includes(person.id.toLocaleLowerCase())) return "字段含条目 ID";
      const index = lowered.findIndex((name) => text.includes(name));
      return index >= 0 ? `提及「${names[index]}」` : "";
    };
    const duplicates = state.rows.filter((row) => row.id !== person.id && row.typeId === person.typeId
      && [row.dataName, ...(row.aliases ?? [])].some((name) => lowered.includes(name.toLocaleLowerCase())));
    const related = state.rows.filter((row) => row.id !== person.id && mention([row.dataName, row.values]));
    const isRelation = (row: MemoryRow) => state.catalog.types.find((type) => type.id === row.typeId)?.templateId === RELATION_TEMPLATE;
    const sources: SummaryWorldbookState[] = summaries ? [summaries] : [];
    const unavailable: string[] = [];
    if (summaries && ui.attached) {
      const store = new SummaryWorldbookStore();
      const attached = summaries.catalog.attachedRecallSources.filter((source) => source.enabled && source.worldbookName !== state.worldbookName);
      const results = await Promise.allSettled(attached.map((source) => store.inspect(source.worldbookName)));
      results.forEach((result, index) => {
        const expected = attached[index]!;
        if (result.status === "fulfilled" && result.value.catalog.namespaceId === expected.namespaceId
          && result.value.catalog.chatId === expected.chatId) sources.push(result.value);
        else unavailable.push(`${expected.worldbookName}：${result.status === "rejected" ? String(result.reason) : "来源身份已变化"}`);
      });
    }
    if (ctx.signal.aborted || ticket !== version) return;
    const events = sources.flatMap((source) => source.slices.filter((slice) => mention([slice.title, slice.content, slice.tags]))
      .map((slice) => ({ slice, source })));
    const statePaths: Array<{ path: string; value: unknown }> = [];
    const visit = (value: unknown, path: string) => {
      if (!value || typeof value !== "object") { if (mention([path, value])) statePaths.push({ path, value }); return; }
      const pairs = Object.entries(value);
      // An object that names the person in one of its values is shown whole.
      if (path && pairs.some(([, child]) => typeof child === "string" && lowered.includes(child.toLocaleLowerCase()))) {
        statePaths.push({ path, value });
        return;
      }
      for (const [key, child] of pairs) {
        const next = path ? `${path}.${key}` : key;
        if (lowered.includes(key.toLocaleLowerCase())) statePaths.push({ path: next, value: child });
        else visit(child, next);
      }
    };
    if (current) visit(current, "");
    const commitments = statePaths.filter((item) => /commitment|plan|pending|promise|计划|承诺|约定|未解决|待办/i.test(item.path));
    const changes = history.filter((record) => record.rowId === person.id || mention([record.before, record.after]));
    const eventPage = { page: 0 };
    const eventHost = h("div", "ec-stack");
    const drawEvents = () => {
      const page = paginate(events, eventPage, 15);
      eventHost.replaceChildren(...page.items.map(({ slice, source }) => lazy(
        `${slice.timestamp} · ${slice.title} · 批次 ${slice.batch.batchNumber}${source.worldbookName === state.worldbookName ? "" : " · " + source.catalog.chatId}`,
        () => h("div", "ec-prose", slice.content))), ...(page.pages > 1 ? [pager(eventPage, page.pages, events.length, drawEvents, "段")] : []));
    };
    drawEvents();
    await pane.open(person.id, person.dataName, [
      muted(`别名：${person.aliases?.join("、") || "无"}。以下按名称和别名做文本匹配，匹配不代表同一人或知情。`),
      duplicates.length ? callout("warning", `有 ${duplicates.length} 条同名或同别名的人物条目，没有自动合并。`) : null,
      rowBlock(person, "人物条目"),
      heading(`人物关系 · ${related.filter(isRelation).length}`), ...related.filter(isRelation).map((row) => rowBlock(row, mention(row.values))),
      heading(`其他资料 · ${related.filter((row) => !isRelation(row)).length}`),
      ...related.filter((row) => !isRelation(row)).map((row) => rowBlock(row, mention([row.dataName, row.values]))),
      heading(`相关经历 · ${events.length}`), ...unavailable.map((message) => callout("danger", message)),
      events.length ? eventHost : muted("已读取的总结中没有提及此人物的切片。"),
      heading("当前状态"), statePaths.length ? h("div", "ec-stack", ...statePaths.filter((item) => !commitments.includes(item))
        .map((item) => lazy(item.path, item.value))) : muted("当前状态中没有提及此人物。"),
      commitments.length ? heading("计划、承诺与待办") : null, ...commitments.map((item) => lazy(item.path, item.value)),
      heading(`相关变更 · ${changes.length}`), ...changes.slice(0, 30).map((record) =>
        lazy(`${formatTime(record.recordedAt)} · ${record.after?.name ?? record.before?.name ?? record.rowId}`, record)),
    ]);
  };

  const drawList = () => keepSearchFocus(host, () => {
    const query = ui.query.toLocaleLowerCase();
    const people = state.rows.filter((row) => row.typeId === ui.typeId
      && (!query || [row.dataName, ...(row.aliases ?? [])].join("\n").toLocaleLowerCase().includes(query)));
    const page = paginate(people, ui);
    fill(host,
      h("div", "ec-toolbar", h("div", "ec-row",
        selectControl("人物资料表", state.catalog.types.map((type) => [type.id, type.name]), ui.typeId, async (value) => {
          if (!await pane.close()) return;
          ui.typeId = value; ui.page = 0; drawList();
        }),
        searchBox(ui.query, (value) => { ui.query = value; ui.page = 0; drawList(); }, "搜索人物或别名", ctx.signal)),
        h("div", "ec-row ec-toolbar-end", summaries ? switchControl("包含附加的其他聊天总结", ui.attached, (value) => {
          ui.attached = value;
          const open = state.rows.find((row) => row.id === pane.current());
          if (open) return show(open);
        }) : null)),
      list(page.items.map((row) => ({ key: row.id, title: row.dataName, selected: pane.current() === row.id,
        meta: preview(row.aliases?.join("、") ?? "", 40), onOpen: () => show(row) })), "没有匹配的人物"),
      page.pages > 1 ? pager(ui, page.pages, people.length, drawList, "人") : null,
    );
  });
  pane.onChange(() => drawList());
  pane.list.append(host);
  drawList();
  return pane.node;
}
