import type { SummarySlice } from "../../../../shared/domain";
import { sha256Hex } from "../../../../shared/crypto-compat";
import { echoesApi } from "../../../api/client";
import { getSettings } from "../../../state/settings";
import { buildSummaryRetrievalText, summaryRetrievalContentHash, summaryRetrievalDocumentId } from "../../../summary/retrieval-document";
import type { SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { button } from "../../kit/controls";
import { form } from "../../kit/forms";
import { formModal, modal } from "../../kit/overlays";
import { empty, lazy, kv } from "../../kit/layout";
import type { PageContext } from "../../shell/context";

export function editRetrieval(ctx: PageContext, state: SummaryWorldbookState, slice: SummarySlice): void {
  const target = form([
    { key: "body", label: "正文（只读）", type: "textarea", rows: 5, readonly: true, value: slice.content },
    { key: "text", label: "独立检索表示", type: "textarea", rows: 10, value: slice.retrievalText ?? "", hint: "留空则用正文建立索引" },
    { key: "sync", label: "保存后同步索引", type: "switch", value: true, hint: "可能产生向量化费用" },
  ], { className: "is-single" });
  const replace = (text: string) => target.set("text", text);
  formModal(`检索表示 · ${slice.title}`, target, async (values) => {
    ctx.guard();
    await ctx.summary.saveRetrievalTexts(state, new Map([[slice.id, values.text || undefined]]));
    target.commit();
    if (values.sync) await ctx.run("同步检索表示", () => ctx.summary.synchronizeSlices([slice.id]), () => ctx.summary.stop());
    await ctx.refresh();
  }, { size: "large", extra: [
    button("从正文与标签重建", () => replace(buildSummaryRetrievalText(slice)), { variant: "ghost", small: true }),
    button("恢复为用正文", () => replace(""), { variant: "ghost", small: true }),
  ] });
}

export function assignFlags(ctx: PageContext, state: SummaryWorldbookState, slices: SummarySlice[]): void {
  const rules = getSettings().retrieval.recall.flagRules;
  if (!rules.length) {
    const view = modal("设置标志", empty("还没有创建人工标志。", button("去创建", async () => {
      await view.close(true);
      ctx.navigate("recall/sources");
    }, { icon: "flag" })));
    return;
  }
  const single = slices.length === 1;
  const target = form([
    ...(single ? [] : [{ key: "mode", label: "处理方式", type: "select" as const, value: "add",
      options: [["add", "添加所选标志"], ["remove", "移除所选标志"], ["replace", "替换为所选标志"]] as Array<[string, string]> }]),
    ...rules.map((flag) => ({ key: flag.id, label: flag.name, type: "switch" as const,
      value: single && (slices[0]!.recallFlags ?? []).includes(flag.id) })),
  ], { className: "is-single" });
  formModal(single ? `切片标志 · ${slices[0]!.title}` : `批量设置标志 · ${slices.length} 个切片`, target, async (values) => {
    ctx.guard();
    const active = new Set(getSettings().retrieval.recall.flagRules.map((flag) => flag.id));
    const flags = rules.filter((flag) => values[flag.id] && active.has(flag.id)).map((flag) => flag.id);
    await ctx.summary.store.saveSliceFlags(state.worldbookName, slices.map((slice) => slice.id), flags, single ? "replace" : values.mode);
    await ctx.refresh();
  });
}

/** Compares the stored slice with its retrieval index document. */
export async function inspectIndex(ctx: PageContext, slice: SummarySlice): Promise<void> {
  const fresh = await ctx.summary.store.inspect(ctx.worldbook!);
  const current = fresh.slices.find((item) => item.id === slice.id);
  if (!current) throw new Error("切片已不存在。");
  const collection = fresh.catalog.retrievalCollectionId;
  const index = collection ? (await echoesApi.retrievalDocumentStatus([await summaryRetrievalDocumentId(collection, current.id)])).documents[0] : undefined;
  ctx.guard();
  const hash = await summaryRetrievalContentHash(current);
  const body = await sha256Hex(current.content);
  modal(`索引检查 · ${current.title}`, [
    kv([
      ["检索集合", collection ?? "尚未建立"],
      ["检索表示", current.retrievalText ? "独立表示" : "使用正文"],
      ["索引状态", index ? index.vectorState : "未建立索引"],
      ["索引文本", index ? index.contentHash === hash ? "一致" : "不一致，需要重新同步" : "—"],
      ["索引正文", index?.bodyHash ? index.bodyHash === body ? "一致" : "不一致，需要重新同步" : "未记录正文指纹"],
    ]),
    lazy("批次元数据", current.batch),
    lazy("指纹", { expectedContentHash: hash, indexedContentHash: index?.contentHash, expectedBodyHash: body, indexedBodyHash: index?.bodyHash }),
  ]);
}
