import type { JobRecord, SummaryBatchInput, SummaryGenerationRequest, SummaryGenerationResult,
  SummarySliceCandidate, TaskBudgetConfig } from "../../shared/domain";
import { sha256Hex } from "../../shared/crypto-compat";
import { readLocalRecord, updateLocalRecord } from "../state/local-journal";
import type { SummaryWorldbookState } from "../worldbook/summary-worldbook";

export interface SummaryRunDraft {
  version: 1;
  revision?: number;
  worldbookName: string;
  namespaceId: string;
  chatId: string;
  createdAt: string;
  updatedAt: string;
  mode: "create" | "rebuild" | "supplement";
  batch: SummaryBatchInput;
  advanceCheckpoint: boolean;
  checkpoint: string | null;
  nextBatchNumber: number;
  batchSnapshot: string;
  instructions?: string | undefined;
  fingerprint: string;
  // Endpoint secrets are never persisted. The hash above includes their configuration.
  inputs: Array<Pick<SummaryGenerationRequest, "batch" | "messages" | "promptMessages" | "extractAttributes">>;
  parts: Array<{
    slices?: SummarySliceCandidate[] | undefined;
    jobId?: string | undefined;
    submitting?: boolean | undefined;
    resumeAfterEndpointId?: string | undefined;
  }>;
  jobs: Record<string, { status: string; calls: number; characters: number; durationMs: number }>;
  budget: TaskBudgetConfig;
  status: "running" | "ready" | "failed" | "cancelled" | "ambiguous";
  reason: string;
}

function key(state: Pick<SummaryRunDraft, "worldbookName" | "namespaceId" | "chatId">) {
  return `summary-draft:${JSON.stringify([state.chatId, state.worldbookName, state.namespaceId])}`;
}

export function draftScope(state: SummaryWorldbookState) {
  return { worldbookName: state.worldbookName, namespaceId: state.catalog.namespaceId, chatId: state.catalog.chatId };
}

export function readSummaryDraft(state: SummaryWorldbookState) {
  return readLocalRecord<SummaryRunDraft>(key(draftScope(state)));
}

export async function saveSummaryDraft(draft: SummaryRunDraft) {
  draft.updatedAt = new Date().toISOString();
  const revision = draft.revision ?? 0;
  await updateLocalRecord<SummaryRunDraft>(key(draft), (current) => {
    if (current ? current.createdAt !== draft.createdAt || (current.revision ?? 0) !== revision : revision !== 0)
      throw new Error("本地恢复草稿已被另一个操作修改或清理，未继续覆盖。请刷新后核对。");
    return { ...draft, revision: revision + 1 };
  });
  draft.revision = revision + 1;
}

export async function clearSummaryDraft(state: SummaryWorldbookState, expected: SummaryRunDraft | undefined) {
  if (!expected) return;
  await updateLocalRecord<SummaryRunDraft>(key(draftScope(state)), (current) => {
    if (!current) return undefined;
    if (current.createdAt !== expected.createdAt || current.revision !== expected.revision)
      throw new Error("本地恢复草稿已被其他操作修改，未清理新进度。请刷新后核对。");
    return undefined;
  });
}

export function summaryDraftFingerprint(requests: SummaryGenerationRequest[]) {
  return sha256Hex(JSON.stringify(requests));
}

export function recordDraftJob(draft: SummaryRunDraft, index: number, job: JobRecord<SummaryGenerationResult>) {
  draft.parts[index]!.jobId = job.id;
  draft.parts[index]!.submitting = false;
  const old = draft.jobs[job.id];
  draft.jobs[job.id] = {
    status: job.status,
    calls: Math.max(old?.calls ?? 0, job.usage?.providerCalls ?? 0),
    characters: Math.max(old?.characters ?? 0, job.usage?.inputCharacters ?? 0),
    durationMs: Math.max(old?.durationMs ?? 0, Date.parse(job.updatedAt) - Date.parse(job.createdAt)),
  };
  return saveSummaryDraft(draft);
}

export function remainingDraftBudget(draft: SummaryRunDraft, current: TaskBudgetConfig): TaskBudgetConfig {
  const usage = Object.values(draft.jobs).reduce((sum, job) => ({
    calls: sum.calls + job.calls, characters: sum.characters + job.characters, durationMs: sum.durationMs + job.durationMs,
  }), { calls: 0, characters: 0, durationMs: 0 });
  const remaining = (name: keyof TaskBudgetConfig, spent: number) => {
    const limit = Math.min(draft.budget[name] || Infinity, current[name] || Infinity);
    if (spent >= limit) throw new Error("本次总结正文的累计任务预算已用尽。已完成结果保留，恢复不会重置预算。");
    return limit === Infinity ? 0 : Math.max(1, limit - spent);
  };
  return { maxProviderCalls: remaining("maxProviderCalls", usage.calls),
    maxInputCharacters: remaining("maxInputCharacters", usage.characters),
    maxDurationMs: remaining("maxDurationMs", usage.durationMs) };
}
