import { randomUuid } from "../../shared/crypto-compat";
import type { DiscussionRequest, DiscussionResult } from "../../shared/discussion";
import { echoesApi } from "../api/client";
import { getSettings } from "../state/settings";
import { captureDiscussionContext } from "./native-context";

export interface DiscussionRun {
  id: string;
  chatId: string;
  prompt: string;
  text: string;
  status: "preparing" | "generating" | "completed" | "cancelled" | "failed" | "decision_required";
  message: string;
  startedAt: string;
  endpointName?: string | undefined;
  streaming?: boolean | undefined;
  jobId?: string | undefined;
  result?: DiscussionResult | undefined;
  request?: DiscussionRequest | undefined;
}

export class DiscussionCoordinator {
  private active: { run: DiscussionRun; controller: AbortController } | null = null;
  private readonly runs = new Map<string, DiscussionRun[]>();
  private readonly listeners = new Set<() => void>();

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }
  history(chatId: string): readonly DiscussionRun[] { return this.runs.get(chatId) ?? []; }
  get running(): DiscussionRun | null { return this.active?.run ?? null; }
  private emit() { for (const listener of this.listeners) listener(); }

  async start(prompt: string): Promise<void> {
    if (this.active) throw new Error("请先等待或停止正在进行的剧情讨论。");
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("请先选择聊天。");
    if (!prompt.trim()) throw new Error("请输入本次剧情讨论内容。");
    if (prompt.length > 100_000) throw new Error("讨论内容超过 100000 字符。");
    const settings = getSettings();
    const workflow = settings.generationWorkflows.discussion;
    const group = settings.generationGroups.find((item) => item.id === workflow.groupId);
    if (!group?.endpoints.some((endpoint) => endpoint.enabled)) {
      throw new Error("请先在“API 连接 → 工作流分配”配置剧情讨论的生成端点组。");
    }
    const run: DiscussionRun = {
      id: randomUuid(), chatId, prompt, text: "", status: "preparing",
      message: "正在通过酒馆准备完整上下文", startedAt: new Date().toISOString(),
    };
    const history = this.runs.get(chatId) ?? [];
    history.push(run);
    this.runs.set(chatId, history);
    const controller = new AbortController();
    this.active = { run, controller };
    this.emit();
    try {
      const messages = await captureDiscussionContext(controller.signal);
      controller.signal.throwIfAborted();
      if (SillyTavern.getContext().chatId !== chatId) throw new Error("聊天已切换，讨论未发送。");
      run.request = {
        chatId,
        messages: [
          ...messages,
          { role: "system", content: settings.discussion.systemPrompt },
          { role: "user", content: prompt },
        ],
        generationGroup: structuredClone(group),
        failoverPolicy: workflow!.failoverPolicy,
      };
      await this.generate(run, controller.signal);
    } catch (error) {
      this.failed(run, controller.signal, error);
    } finally {
      // Only an explicitly confirmed failover needs to retain a complete request.
      if (run.status !== "decision_required") delete run.request;
      this.active = null;
      this.emit();
    }
  }

  async continue(runId: string): Promise<void> {
    if (this.active) throw new Error("已有剧情讨论正在进行。");
    const chatId = SillyTavern.getContext().chatId ?? "";
    const run = this.runs.get(chatId)?.find((item) => item.id === runId);
    const decision = run?.result?.decisionRequired;
    if (!run?.request || run.status !== "decision_required" || !decision?.nextEndpointId) {
      throw new Error("没有可继续的待确认讨论请求。");
    }
    const controller = new AbortController();
    this.active = { run, controller };
    run.request.resumeAfterEndpointId = decision.failedEndpointId;
    this.emit();
    try { await this.generate(run, controller.signal); }
    catch (error) { this.failed(run, controller.signal, error); }
    finally {
      if (run.status !== "decision_required") delete run.request;
      this.active = null;
      this.emit();
    }
  }

  async stop(): Promise<void> {
    const active = this.active;
    if (!active) return;
    active.run.message = "正在停止；已发送请求仍可能计费";
    active.controller.abort(new DOMException("用户停止剧情讨论。", "AbortError"));
    this.emit();
    if (active.run.jobId) await echoesApi.cancelJob(active.run.jobId);
  }

  chatChanged(): void {
    if (this.active && this.active.run.chatId !== SillyTavern.getContext().chatId) {
      void this.stop().catch((error: unknown) => {
        console.error("[Echoes] Discussion cancellation failed.", error);
      });
    }
  }

  clear(chatId: string): void {
    if (this.active?.run.chatId === chatId) throw new Error("请先停止剧情讨论，再清空结果。");
    this.runs.delete(chatId);
    this.emit();
  }

  private async generate(run: DiscussionRun, signal: AbortSignal): Promise<void> {
    run.status = "generating";
    run.message = "正在提交剧情讨论";
    delete run.jobId;
    delete run.result;
    this.emit();
    const result = await echoesApi.discuss(run.request!, signal, (event) => {
      if (signal.aborted) return;
      if (event.type === "endpoint") {
        run.endpointName = event.name;
        run.streaming = event.streaming;
        run.text = "";
        run.message = event.streaming ? "正在接收流式回复" : "正在等待完整回复";
      } else if (event.type === "delta") {
        run.text += event.text;
      } else if (event.type === "job") {
        run.jobId = event.jobId;
      } else return;
      this.emit();
    });
    signal.throwIfAborted();
    run.result = result;
    if (result.outcome === "completed") {
      run.text = result.text ?? "";
      run.status = "completed";
      run.message = "已完成";
    } else {
      run.status = "decision_required";
      run.message = result.message ?? "端点结果不确定，请确认是否切换；请求可能已计费。";
    }
  }

  private failed(run: DiscussionRun, signal: AbortSignal, error: unknown) {
    const cancelled = signal.aborted || (error instanceof Error && error.name === "AbortError");
    run.status = cancelled ? "cancelled" : "failed";
    run.message = cancelled ? "已停止，保留已接收内容；已发送请求仍可能计费。"
      : error instanceof Error ? error.message : String(error);
    if (!cancelled) console.error("[Echoes] Discussion failed.", error);
  }
}

export const discussionCoordinator = new DiscussionCoordinator();
