import { h, icon, type Child } from "./dom";
import { scope as scopeTag } from "./controls";

export interface CardOptions {
  scope?: "global" | "chat" | undefined;
  description?: string | undefined;
  actions?: Child[] | undefined;
  className?: string | undefined;
}

/** The basic content container. A card without a title has no header. */
export function card(title: string, options: CardOptions = {}, ...children: Child[]): HTMLElement {
  const node = h("section", `ec-card${options.className ? " " + options.className : ""}`);
  if (title || options.actions?.length) {
    const heading = h("div", "ec-card-title", title ? h("h3", "", title) : null,
      options.scope ? scopeTag(options.scope) : null);
    node.append(h("header", "ec-card-head", heading,
      options.actions?.length ? h("div", "ec-row", ...options.actions) : null));
  }
  if (options.description) node.append(h("p", "ec-card-desc", options.description));
  node.append(...children.filter((child): child is Node | string | number => child !== null && child !== undefined && child !== false)
    .map((child) => child instanceof Node ? child : String(child)));
  return node;
}

export function row(...children: Child[]): HTMLElement {
  return h("div", "ec-row", ...children);
}

export function toolbar(start: Child[], end: Child[] = []): HTMLElement {
  return h("div", "ec-toolbar", h("div", "ec-row", ...start), h("div", "ec-row ec-toolbar-end", ...end));
}

export function stack(...children: Child[]): HTMLElement {
  return h("div", "ec-stack", ...children);
}

export function columns(...children: Child[]): HTMLElement {
  return h("div", "ec-columns", ...children);
}

export function muted(text: string): HTMLElement {
  return h("p", "ec-muted", text);
}

export type CalloutTone = "info" | "warning" | "danger" | "success";
export function callout(tone: CalloutTone, content: Child, ...actions: Child[]): HTMLElement {
  const glyph = { info: "circle-info", warning: "triangle-exclamation", danger: "circle-exclamation", success: "circle-check" }[tone];
  return h("div", `ec-callout is-${tone}`, icon(glyph), h("div", "ec-callout-body", content),
    actions.length ? h("div", "ec-row", ...actions) : null);
}

export function empty(text: string, action?: Child): HTMLElement {
  return h("div", "ec-empty", icon("inbox"), h("p", "", text), action);
}

export function stats(items: Array<[string, Child] | [string, Child, string]>): HTMLElement {
  return h("div", "ec-stats", ...items.map(([label, value, note]) =>
    h("div", "ec-stat", h("span", "ec-stat-label", label), h("strong", "ec-stat-value", value),
      note ? h("small", "ec-stat-note", note) : null)));
}

export function kv(pairs: Array<[string, Child]>): HTMLElement {
  const list = h("dl", "ec-kv");
  for (const [label, value] of pairs) list.append(h("dt", "", label), h("dd", "", value === "" ? "—" : value));
  return list;
}

export function code(text: string, className = ""): HTMLElement {
  return h("pre", `ec-code${className ? " " + className : ""}`, text);
}

/** Collapsed disclosure that renders its value only when first opened. */
export function lazy(title: Child, value: unknown | (() => Node)): HTMLDetailsElement {
  const node = h("details", "ec-disclosure", h("summary", "", title));
  let rendered = false;
  node.addEventListener("toggle", () => {
    if (!node.open || rendered) return;
    rendered = true;
    node.append(typeof value === "function" ? (value as () => Node)()
      : code(typeof value === "string" ? value : JSON.stringify(value, null, 2)));
  });
  return node;
}

export function heading(text: string, ...extra: Child[]): HTMLElement {
  return h("div", "ec-heading", h("h4", "", text), ...extra);
}
