import { getSettings, saveSettings } from "../../../state/settings";
import { h } from "../../kit/dom";
import { button } from "../../kit/controls";
import { stack, callout } from "../../kit/layout";
import { form, type FieldSpec } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { FAILOVER_OPTIONS } from "../shared";

const WORKFLOWS = [["extraction", "结构化提取"], ["summary", "总结生成"], ["status", "状态更新"], ["discussion", "剧情讨论"]] as const;

export function assignmentPage(ctx: PageContext): HTMLElement {
  const settings = getSettings();
  const groups: Array<[string, string]> = [["", "未分配"], ...settings.generationGroups.map((group): [string, string] => [group.id, group.name])];
  const generation = form(WORKFLOWS.flatMap(([key, label]): FieldSpec[] => [
    { key: `${key}Group`, label: `${label} · 端点组`, type: "select", value: settings.generationWorkflows[key].groupId, options: groups },
    { key: `${key}Policy`, label: `${label} · 故障切换`, type: "select", value: settings.generationWorkflows[key].failoverPolicy, options: FAILOVER_OPTIONS },
  ]));
  const retrieval = form([
    { key: "embedding", label: "总结向量化 · 端点组", type: "select", value: settings.summary.embeddingGroupId,
      options: [["", "不建立向量（只用 BM25）"], ...settings.retrieval.embeddingGroups.map((group): [string, string] => [group.id, `${group.name} · ${group.dimensions} 维`])],
      hint: "更换向量空间时，当前聊天的总结会迁移到新空间" },
    { key: "batchSize", label: "单次向量化切片数", type: "number", min: 1, max: 100, value: settings.summary.embeddingBatchSize, required: true },
    { key: "rerank", label: "召回重排序 · 端点组", type: "select", value: settings.retrieval.recall.rerankSetId,
      options: [["", "不使用"], ...settings.retrieval.rerankSets.map((set): [string, string] => [set.id, set.name])] },
    { key: "policy", label: "检索 · 故障切换", type: "select", value: settings.retrieval.failoverPolicy, options: FAILOVER_OPTIONS },
  ]);
  const budget = settings.taskBudget;
  const limits = form([
    { key: "calls", label: "单个任务的请求上限", type: "number", min: 0, max: 10000, value: budget.maxProviderCalls, required: true, hint: "0 表示不限" },
    { key: "characters", label: "单个任务的累计请求字符上限", type: "number", min: 0, max: 100000000, value: budget.maxInputCharacters, required: true, hint: "0 表示不限" },
    { key: "duration", label: "单个任务的最长秒数", type: "number", min: 0, max: 86400, value: budget.maxDurationMs / 1000, required: true, hint: "0 表示不限" },
  ]);
  return stack(
    settings.generationGroups.length ? null : callout("warning", "还没有生成端点组。先建立端点组，再在这里分配。",
      button("建立端点组", () => ctx.navigate("api/generation"), { variant: "ghost", small: true, icon: "arrow-right" })),
    formCard("生成任务", generation, (values) => {
      const next = getSettings();
      for (const [key] of WORKFLOWS) next.generationWorkflows[key] = { groupId: values[`${key}Group`], failoverPolicy: values[`${key}Policy`] };
      saveSettings(next);
      ctx.markers();
    }, { scope: "global", description: "每项后台任务使用哪个端点组。组内的端点按顺序尝试。" }),
    formCard("检索任务", retrieval, async (values) => {
      const current = getSettings();
      if (ctx.chatId && values.embedding && values.embedding !== current.summary.embeddingGroupId) {
        ctx.guard();
        const state = await ctx.summary.load();
        if (state.slices.length || state.catalog.retrievalCollectionId) {
          if (!await confirmAction({ title: "把当前聊天的总结迁移到新的向量空间？", cost: true, confirmLabel: "迁移",
            message: "会用新端点组重新向量化全部切片，全部校验成功后才切换；过程中可以停止。" })) throw new Error("没有修改检索设置。");
          await ctx.run("迁移总结向量空间", () => ctx.summary.migrateEmbeddingSpace(values.embedding), () => ctx.summary.stop());
          ctx.guard();
        }
      }
      const next = getSettings();
      next.summary.embeddingGroupId = values.embedding;
      next.summary.embeddingBatchSize = values.batchSize;
      next.retrieval.recall.rerankSetId = values.rerank;
      next.retrieval.failoverPolicy = values.policy;
      saveSettings(next);
    }, { scope: "global" }),
    formCard("用量限制", limits, (values) => {
      const next = getSettings();
      next.taskBudget = { maxProviderCalls: values.calls, maxInputCharacters: values.characters, maxDurationMs: values.duration * 1000 };
      saveSettings(next);
    }, { scope: "global", description: "限制单个后台任务，不是金额上限；已经发出的请求仍可能计费。",
      after: h("div", "ec-row", button("查看任务用量", () => ctx.navigate("system/logs"), { variant: "ghost", small: true, icon: "arrow-right" })) }),
  );
}
