import type { JobListRecord } from "../../../../shared/domain";
import { echoesApi as api } from "../../../api/client";
import { consoleRecords, clearConsoleRecords, subscribeConsole, redactLog } from "../../logs";
import { h, fill, formatTime, download } from "../../kit/dom";
import { button, badge, selectControl } from "../../kit/controls";
import { card, stack, lazy, code, muted, empty, kv } from "../../kit/layout";
import { searchBox, keepSearchFocus, table } from "../../kit/data";
import type { PageContext } from "../../shell/context";
import { stateBadge, attemptsTable } from "../shared";

function jobDetail(job: JobListRecord): HTMLElement {
  const summary = job.resultSummary;
  return h("div", "ec-stack",
    job.error ? h("p", "ec-danger-text", job.error.message) : muted(job.message),
    job.usage ? kv([
      ["请求数", String(job.usage.providerCalls)], ["累计请求字符", String(job.usage.inputCharacters)],
      ["输入 Token 粗估（非账单）", String(job.usage.estimatedInputTokens)], ["上报用量的请求", String(job.usage.reportedCalls)],
      ["上报输入 / 输出 Token", `${job.usage.inputTokens} / ${job.usage.outputTokens}`], ["上报缓存输入 Token", String(job.usage.cachedInputTokens)],
    ]) : null,
    summary ? h("div", "ec-row", badge(`已向量化 ${summary.vectorized ?? 0}`), badge(`失败 ${summary.failed ?? 0}`, summary.failed ? "danger" : "neutral"),
      badge(`待处理 ${summary.pending ?? 0}`), badge(`待确认 ${summary.ambiguous ?? 0}`, summary.ambiguous ? "warning" : "neutral")) : null,
    summary?.attempts?.length ? attemptsTable(summary.attempts) : null,
    job.budget ? lazy("任务预算", job.budget) : null,
    lazy("任务 JSON", job));
}

function jobsCard(ctx: PageContext): HTMLElement {
  const ui = ctx.memo("system-jobs", () => ({ status: "", query: "" }));
  const host = h("div", "ec-stack");
  let jobs: JobListRecord[] = [];
  const draw = () => keepSearchFocus(host, () => {
    const matched = jobs.filter((job) => !ui.query || JSON.stringify(job).toLocaleLowerCase().includes(ui.query.toLocaleLowerCase()));
    fill(host, h("div", "ec-toolbar", h("div", "ec-row",
      searchBox(ui.query, (value) => { ui.query = value; draw(); }, "搜索任务类型、端点或错误", ctx.signal),
      selectControl("任务状态", [["", "全部状态"], ["running", "运行中"], ["queued", "排队中"], ["succeeded", "已完成"], ["failed", "失败"],
        ["ambiguous", "待确认"], ["cancelled", "已取消"]], ui.status, (value) => { ui.status = value; return load(); })),
      h("div", "ec-row ec-toolbar-end", button("刷新", () => load(), { variant: "ghost", small: true, icon: "rotate" }),
        button("导出", () => download("echoes-tasks.json", JSON.stringify(redactLog(jobs), null, 2)), { variant: "ghost", small: true, icon: "download" }))),
    matched.length ? h("div", "ec-stack", ...matched.map((job) => lazy(h("span", "ec-row", stateBadge(job.status), h("strong", "", job.type),
      h("span", "ec-muted", formatTime(job.createdAt)), job.resultSummary?.failed ? badge(`内容失败 ${job.resultSummary.failed}`, "danger") : null), () =>
      h("div", "ec-stack", jobDetail(job), job.status === "running" || job.status === "queued" ? h("div", "ec-row", button("取消任务", async () => {
        if (!(await api.cancelJob(job.id)).cancelled) throw new Error("后台没有确认取消，请刷新后检查。");
        await load();
      }, { variant: "danger", small: true, icon: "stop" })) : null)))) : empty("没有匹配的任务。"));
  });
  const load = async () => {
    jobs = (await api.listJobs({ status: ui.status, limit: 200 })).jobs;
    if (!ctx.signal.aborted) draw();
  };
  void load().catch((error) => fill(host, empty(`读取任务日志失败：${error instanceof Error ? error.message : String(error)}`)));
  return card("服务端任务", { description: "后台执行的模型请求与索引任务，最多显示最近 200 条。" }, host);
}

function consoleCard(ctx: PageContext): HTMLElement {
  const ui = ctx.memo("system-console", () => ({ query: "", level: "all", paused: false }));
  const host = h("div", "ec-stack");
  let snapshot = consoleRecords();
  const draw = () => keepSearchFocus(host, () => {
    if (!ui.paused) snapshot = consoleRecords();
    const items = snapshot.filter((record) => (ui.level === "all" || ui.level === record.level)
      && record.text.toLocaleLowerCase().includes(ui.query.toLocaleLowerCase())).reverse();
    fill(host, h("div", "ec-toolbar", h("div", "ec-row",
      searchBox(ui.query, (value) => { ui.query = value; draw(); }, "搜索日志内容", ctx.signal),
      selectControl("日志级别", [["all", "全部级别"], ["error", "Error"], ["warn", "Warning"], ["info", "Info"], ["log", "Log"], ["debug", "Debug"]],
        ui.level, (value) => { ui.level = value; draw(); })),
      h("div", "ec-row ec-toolbar-end",
        button(ui.paused ? "继续更新" : "暂停更新", () => { ui.paused = !ui.paused; draw(); }, { variant: "ghost", small: true, icon: ui.paused ? "play" : "pause" }),
        button("清空", () => clearConsoleRecords(), { variant: "ghost", small: true, icon: "trash" }),
        button("导出", () => download("echoes-console.json", JSON.stringify(snapshot, null, 2)), { variant: "ghost", small: true, icon: "download" }))),
    table([
      { label: "时间", cell: (record) => formatTime(record.time, false) },
      { label: "级别", cell: (record) => badge(record.level, record.level === "error" ? "danger" : record.level === "warn" ? "warning" : "neutral") },
      { label: "内容", className: "is-grow", cell: (record) => code(record.text, "is-compact") },
    ], items, { empty: "本次页面加载后还没有匹配的 Echoes 日志。", className: "ec-console" }));
  });
  const unsubscribe = subscribeConsole(draw);
  ctx.signal.addEventListener("abort", unsubscribe, { once: true });
  draw();
  return card("浏览器日志", { description: "本次页面加载后 Echoes 输出的浏览器日志（已脱敏，最多 500 条），不包含服务器终端输出。" }, host);
}

export function logsPage(ctx: PageContext): HTMLElement {
  return stack(jobsCard(ctx), consoleCard(ctx));
}
