import { parse, stringify } from "yaml";

import type { MemoryTypeDefinition } from "../../shared/domain";
import { DATA_NAME_KEY, validateMemoryValues } from "../../shared/schemas";

export interface DecodedMemoryContent {
  dataName: string;
  values: Record<string, unknown>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

export function encodeMemoryContent(
  type: Pick<MemoryTypeDefinition, "columns">,
  dataName: string,
  rawValues: Record<string, unknown>,
): string {
  const name = dataName.trim();
  if (!name) throw new Error("Data name cannot be empty.");
  const values = validateMemoryValues(type.columns, rawValues);
  const document: Record<string, unknown> = { [DATA_NAME_KEY]: name };
  for (const column of type.columns) {
    if (Object.hasOwn(values, column.id)) document[column.name] = values[column.id];
  }
  return stringify(document, { lineWidth: 0 }).trimEnd();
}

export function decodeMemoryContent(
  type: Pick<MemoryTypeDefinition, "columns">,
  content: string,
): DecodedMemoryContent {
  let document: unknown;
  try {
    document = parse(content);
  } catch (error) {
    throw new Error(`Invalid memory YAML: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (!isRecord(document)) throw new Error("Memory YAML must contain one mapping object.");

  const dataName = document[DATA_NAME_KEY];
  if (typeof dataName !== "string" || !dataName.trim()) {
    throw new Error(`Memory YAML requires a non-empty ${DATA_NAME_KEY} field.`);
  }

  const columnsByName = new Map(type.columns.map((column) => [column.name, column]));
  const unknownKeys = Object.keys(document).filter(
    (key) => key !== DATA_NAME_KEY && !columnsByName.has(key),
  );
  if (unknownKeys.length > 0) {
    throw new Error(`Memory YAML contains unknown columns: ${unknownKeys.join(", ")}`);
  }

  const values: Record<string, unknown> = {};
  for (const column of type.columns) {
    if (Object.hasOwn(document, column.name)) values[column.id] = document[column.name];
  }
  return {
    dataName: dataName.trim(),
    values: validateMemoryValues(type.columns, values),
  };
}
