import { h, fill, type Child } from "./dom";
import { iconButton } from "./controls";
import { confirmAction } from "./overlays";

export interface Drawer {
  /** The split layout: list on the left, drawer on the right. */
  node: HTMLElement;
  list: HTMLElement;
  current(): string | null;
  open(key: string, title: Child, content: Child[], actions?: Child[]): Promise<boolean>;
  close(): Promise<boolean>;
  onChange(listener: (key: string | null) => void): void;
}

/**
 * A non-modal detail pane beside a list. It becomes a full-screen sheet on
 * narrow screens. Switching or closing asks first when the pane has unsaved
 * edits (any descendant with data-dirty).
 */
export function drawer(label: string): Drawer {
  const list = h("div", "ec-split-list");
  const title = h("h3", "ec-drawer-title");
  const actions = h("div", "ec-row");
  const body = h("div", "ec-drawer-body");
  const pane = h("aside", "ec-drawer", h("header", "ec-drawer-head", title, actions), body);
  pane.setAttribute("aria-label", label);
  pane.tabIndex = -1;
  const node = h("div", "ec-split", list, pane);
  let key: string | null = null;
  const listeners: Array<(key: string | null) => void> = [];
  const guard = async () => !body.querySelector('[data-dirty="true"]')
    || confirmAction({ title: "放弃未保存的修改？", confirmLabel: "放弃修改", danger: true });
  const emit = () => { for (const listener of listeners) listener(key); };
  const api: Drawer = {
    node, list,
    current: () => key,
    async open(nextKey, heading, content, extra = []) {
      if (key !== null && key !== nextKey && !await guard()) return false;
      key = nextKey;
      fill(title, heading);
      fill(actions, ...extra, iconButton("关闭详情", "xmark", () => api.close()));
      fill(body, ...content);
      node.classList.add("is-open");
      body.scrollTop = 0;
      emit();
      return true;
    },
    async close() {
      if (key === null) return true;
      if (!await guard()) return false;
      key = null;
      node.classList.remove("is-open");
      body.replaceChildren();
      emit();
      return true;
    },
    onChange(listener) { listeners.push(listener); },
  };
  pane.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || event.defaultPrevented) return;
    event.preventDefault();
    event.stopPropagation();
    void api.close();
  });
  return api;
}
