import type { RetrievalCollectionStats, RetrievalDocumentInput, RetrievalUpsertResult } from "../../../../shared/domain";
import { retrievalDocumentInputSchema } from "../../../../shared/schemas";
import { echoesApi as api } from "../../../api/client";
import { getSettings } from "../../../state/settings";
import { uid, readTextFile } from "../../kit/dom";
import { button } from "../../kit/controls";
import { form } from "../../kit/forms";
import { formModal, modal, confirmAction, choose } from "../../kit/overlays";
import { lazy } from "../../kit/layout";
import type { PageContext } from "../../shell/context";

const compatibleGroups = (collection: RetrievalCollectionStats) => getSettings().retrieval.embeddingGroups.filter((group) =>
  group.embeddingSpaceId === collection.collection.embeddingSpaceId && group.dimensions === collection.collection.dimensions);

/** Asks before each endpoint switch after an ambiguous result; the switch may bill twice. */
async function continueAfter(message: string): Promise<boolean> {
  return choose({ title: "请求结果不确定", message: `${message}\n切换到下一端点可能重复计费。`, cost: true, cancelValue: false,
    choices: [{ value: false, label: "停止" }, { value: true, label: "切换到下一端点", variant: "primary" }] });
}

export function createCollection(ctx: PageContext): void {
  const groups = getSettings().retrieval.embeddingGroups;
  if (!groups.length) throw new Error("请先配置向量端点组。");
  const target = form([
    { key: "name", label: "名称", required: true },
    { key: "description", label: "说明" },
    { key: "group", label: "向量空间", type: "select", options: groups.map((group) => [group.id, `${group.name} · ${group.dimensions} 维`]) },
  ], { className: "is-single" });
  formModal("新建检索集合", target, async (values) => {
    const group = groups.find((item) => item.id === values.group)!;
    await api.createRetrievalCollection({ id: uid("collection"), name: values.name, description: values.description,
      embeddingSpaceId: group.embeddingSpaceId, dimensions: group.dimensions });
    await ctx.refresh();
  }, { size: "small", saveLabel: "创建" });
}

export function rebuildIndex(ctx: PageContext, collection: RetrievalCollectionStats, repair: boolean): void {
  const groups = compatibleGroups(collection);
  if (!groups.length) throw new Error("没有与这个集合的向量空间和维度匹配的端点组。");
  const target = form([{ key: "group", label: "向量端点组", type: "select", value: groups[0]!.id, options: groups.map((group) => [group.id, group.name]) }], { className: "is-single" });
  formModal(repair ? `修复未就绪的向量 · ${collection.collection.name}` : `重建全部向量 · ${collection.collection.name}`, target, async (values) => {
    if (!await confirmAction({ title: repair ? "重试未就绪的文档？" : "重新向量化全部文档？", cost: true, confirmLabel: "开始" })) return false;
    const settings = getSettings();
    const input = { collectionIds: [collection.collection.id], embeddingGroup: groups.find((group) => group.id === values.group)!,
      failoverPolicy: settings.retrieval.failoverPolicy, embeddingBatchSize: settings.summary.embeddingBatchSize };
    let result = await ctx.job("处理检索索引", () => api.rebuildRetrievalIndex(input, repair));
    while (result.decisionRequired && await continueAfter(result.decisionRequired.message)) {
      const resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
      result = await ctx.job("继续处理索引", () => api.rebuildRetrievalIndex({ ...input, resumeAfterEndpointId }, true));
    }
    modal("索引处理结果", lazy("完整结果", result));
    await ctx.refresh();
  }, { size: "small", saveLabel: "下一步" });
}

export function importDocuments(ctx: PageContext, collection: RetrievalCollectionStats): void {
  const groups = compatibleGroups(collection);
  const target = form([
    { key: "group", label: "向量端点组", type: "select", value: groups[0]?.id ?? "",
      options: [["", "只导入文本，不建立向量"], ...groups.map((group): [string, string] => [group.id, group.name])] },
    { key: "text", label: "文档文本", type: "textarea", rows: 10, hint: "一次导入一篇；批量导入请用 JSONL 文件" },
  ], { className: "is-single" });
  const upload = async (documents: RetrievalDocumentInput[]) => {
    const values = target.values();
    const settings = getSettings();
    const embeddingGroup = groups.find((group) => group.id === values.group);
    if (!documents.length) throw new Error("没有可以导入的文档。");
    if (!await confirmAction({ title: `导入 ${documents.length} 篇文档？`, cost: Boolean(embeddingGroup), confirmLabel: "导入" })) return false;
    const results: RetrievalUpsertResult[] = [];
    for (let offset = 0; offset < documents.length; offset += 100) {
      ctx.guard();
      const input = { documents: documents.slice(offset, offset + 100), embeddingGroup,
        failoverPolicy: settings.retrieval.failoverPolicy, embeddingBatchSize: settings.summary.embeddingBatchSize };
      let result = await ctx.job(`导入文档 ${offset + 1}–${Math.min(documents.length, offset + 100)}`, () => api.upsertRetrievalDocuments(input));
      while (result.decisionRequired && await continueAfter(result.decisionRequired.message)) {
        const resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
        result = await ctx.job("继续向量化文档", () => api.upsertRetrievalDocuments({ ...input, resumeAfterEndpointId }));
      }
      results.push(result);
      if (result.failed || result.ambiguous || result.decisionRequired) break;
    }
    modal("文档导入结果", lazy("完整结果", results));
    await ctx.refresh();
    return true;
  };
  formModal(`导入文档 · ${collection.collection.name}`, target, () => {
    const text = String(target.values().text).trim();
    if (!text) throw new Error("请填写文档文本。");
    return upload([{ collectionId: collection.collection.id, sourceType: "manual", sourceId: uid("source"), text, tags: [], metadata: {} }]);
  }, { saveLabel: "导入文本", extra: [button("导入 JSONL 文件", async () => {
    const file = await readTextFile(".jsonl,.ndjson");
    if (file === null) return;
    const documents = file.split(/\r?\n/).filter((line) => line.trim()).map((line, index) => {
      try {
        const value = JSON.parse(line);
        return retrievalDocumentInputSchema.parse({ ...value, collectionId: collection.collection.id, sourceType: value.sourceType ?? "imported",
          sourceId: value.sourceId ?? uid("source"), tags: value.tags ?? [], metadata: value.metadata ?? {} });
      } catch (error) {
        throw new Error(`第 ${index + 1} 行无效：${error instanceof Error ? error.message : String(error)}`);
      }
    });
    await upload(documents);
  }, { variant: "ghost", icon: "upload" })] });
}
