import { echoesApi } from "../../api/client";
import { getSettings } from "../../state/settings";
import { WorldbookMemoryStore } from "../../worldbook/worldbook-memory";
import { extractionCoordinator } from "../../memory/extraction-coordinator";
import { statusCoordinator } from "../../status/status-coordinator";
import { recallCoordinator } from "../../recall-coordinator";
import { h, icon, errorText } from "../kit/dom";
import { button, switchControl, badge } from "../kit/controls";
import { card, stats, callout, stack, muted } from "../kit/layout";
import { modal } from "../kit/overlays";
import { toast } from "../kit/feedback";
import { attentionItems } from "../shell/attention";
import type { PageContext } from "../shell/context";
import { floorText } from "./shared";
import { traceView } from "./recall/trace";

async function connectionCard(): Promise<HTMLElement> {
  try {
    const status = await echoesApi.systemStatus();
    const ready = status.protocolCompatible && status.bootstrap.state === "ready";
    const bootstrap = { ready: "就绪", degraded: "降级运行", unavailable: "不可用" }[status.bootstrap.state];
    return callout(ready ? "success" : "warning",
      `后端 ${status.build.appVersion} · ${status.protocolCompatible ? "协议兼容" : "协议不兼容"} · ${bootstrap}`);
  } catch (error) {
    return callout("danger", `无法连接 Echoes 后端：${errorText(error)}`);
  }
}

function setupChecklist(credentials: number | null, navigate: (route: string) => void): HTMLElement | null {
  const settings = getSettings();
  const steps: Array<[boolean, string, string]> = [
    [credentials === null || credentials > 0, "添加 API 凭据", "api/credentials"],
    [settings.generationGroups.length > 0, "建立生成端点组", "api/generation"],
    [Boolean(settings.generationWorkflows.summary.groupId), "为各项任务分配端点组", "api/assignment"],
    [Boolean(settings.summary.embeddingGroupId), "（可选）配置总结向量化", "api/assignment"],
  ];
  if (steps.slice(0, 3).every(([done]) => done)) return null;
  return card("首次使用", { description: "完成以下配置后，各项记忆功能才能调用模型。" },
    h("ol", "ec-checklist", ...steps.map(([done, label, route]) => h("li", done ? "is-done" : "",
      icon(done ? "circle-check" : "circle"), h("span", "", label), done ? null
        : button("前往", () => navigate(route), { variant: "ghost", small: true })))));
}

async function structuredMemoryCard(ctx: PageContext): Promise<HTMLElement> {
  const body = await new WorldbookMemoryStore().load().then((memory) => stack(
    stats([["表", String(memory.catalog.types.length)], ["条目", String(memory.rows.length)],
      ["检查点", floorText(memory.catalog.lastProcessedMessageId)]]),
    switchControl("自动提取", memory.catalog.automation.enabled, async (value) => {
      ctx.guard();
      await extractionCoordinator.setAutomationEnabled(value);
    }),
    h("div", "ec-row", button("处理下一批", async () => {
      await ctx.run("结构化记忆提取", () => extractionCoordinator.runManual(), () => extractionCoordinator.stopCurrent());
      await ctx.refresh();
    }, { icon: "play", small: true, disabled: extractionCoordinator.isRunning() }),
      extractionCoordinator.isRunning() ? badge("运行中", "accent") : null),
  ), (error) => callout("danger", errorText(error)));
  return card("结构化记忆", { actions: [button("打开", () => ctx.navigate("structured/entries"), { variant: "ghost", small: true })] }, body);
}

export async function overviewPage(ctx: PageContext): Promise<HTMLElement> {
  const credentials = await echoesApi.listCredentials().then((items) => items.length, () => null);
  const root = stack(await connectionCard());
  const checklist = setupChecklist(credentials, ctx.navigate);
  if (checklist) root.append(checklist);
  if (!ctx.chatId) {
    root.append(card("当前聊天", {}, muted("在 SillyTavern 中打开一个聊天后，这里会显示各记忆模块的状态。")));
    return root;
  }
  const [memoryCard, summary, status] = await Promise.all([
    structuredMemoryCard(ctx), ctx.summary.load(), statusCoordinator.load(),
  ]);
  const attention = attentionItems(ctx.summary);
  const recovery = await ctx.summary.recoveryDraft();
  if (recovery) attention.unshift({ route: "summary/generation", tone: "warning", text: "总结有未提交的恢复草稿", action: "去处理" });
  root.append(card("待处理", {}, attention.length ? h("div", "ec-attention", ...attention.map((item) =>
    h("div", `ec-attention-item is-${item.tone}`, icon(item.tone === "danger" ? "circle-exclamation" : "triangle-exclamation"),
      h("span", "", item.text), button(item.action, () => ctx.navigate(item.route), { variant: "ghost", small: true, icon: "arrow-right" }))))
    : muted("没有需要处理的事项。")));

  const current = statusCoordinator.current(status);
  const chat = SillyTavern.getContext().chat;
  const stale = !current || chat.some((message, index) => index > current.messageIndex && message.is_user !== true
    && message.role !== "user" && Boolean(String(message.mes ?? "").trim()));
  const ready = summary.slices.filter((slice) => slice.batch.state === "ready").length;
  const batches = new Set(summary.slices.map((slice) => slice.batch.id)).size;
  const trace = recallCoordinator.trace;
  root.append(h("div", "ec-grid",
    memoryCard,
    card("总结记忆", { actions: [button("打开", () => ctx.navigate("summary/records"), { variant: "ghost", small: true })] },
      stats([["批次", String(batches)], ["切片", String(summary.slices.length)],
        ["向量就绪", `${ready} / ${summary.slices.length}`], ["检查点", floorText(summary.catalog.lastCommittedMessageId)]]),
      switchControl("自动总结", summary.catalog.autoRun, async (value) => {
        ctx.guard();
        await ctx.summary.setAutoRun(value);
        if (value) void ctx.run("自动总结", () => ctx.summary.runAutomatic(), () => ctx.summary.stop()).catch(() => undefined);
      }),
      h("div", "ec-row", button("检查待处理消息", async () => {
        await ctx.run("自动总结", () => ctx.summary.checkPending(), () => ctx.summary.stop());
        await ctx.refresh();
      }, { icon: "rotate", small: true }))),
    card("状态记忆", { actions: [button("打开", () => ctx.navigate("status/current"), { variant: "ghost", small: true })] },
      stats([["状态", status.catalog.enabled ? "已启用" : "未启用"],
        ["快照来源", current ? `第 ${current.messageIndex} 楼` : "初始状态"], ["同步", stale ? "待同步" : "已同步"]]),
      h("div", "ec-row", button("手动同步", async () => {
        await ctx.run("状态记忆同步", () => statusCoordinator.synchronize());
        const result = statusCoordinator.trace;
        toast(result?.message ?? (result?.outcome === "completed" ? "状态已同步。" : "本次没有写入新的状态快照。"),
          result?.outcome === "completed" || result?.outcome === "unchanged" ? "success" : "warning");
        await ctx.refresh();
      }, { icon: "arrows-rotate", small: true, disabled: !status.catalog.enabled }))),
    card("召回", { actions: [button("打开", () => ctx.navigate("recall/strategy"), { variant: "ghost", small: true })] },
      stats([["总结召回", summary.catalog.recallEnabled ? "已启用" : "未启用"],
        ["上次命中", trace ? String(trace.returned) : "—"], ["上次注入", trace ? String(trace.injected) : "—"]]),
      h("div", "ec-row", button("召回预览", async () => {
        const result = await ctx.run("召回预览", () => recallCoordinator.preview());
        modal("召回预览", traceView(result.trace), { size: "large" });
      }, { icon: "flask", small: true }))),
  ));
  return root;
}
