import { extractionCoordinator as extraction } from "../../../memory/extraction-coordinator";
import { currentExtractionMessages, prepareExtraction } from "../../../memory/extraction-request";
import { getSettings } from "../../../state/settings";
import { extractionProviderMessages } from "../../../../shared/extraction-references";
import { checkpointFloor } from "../../../chat-message-index";
import { h, formatTime } from "../../kit/dom";
import { button, switchControl, badge, type Tone } from "../../kit/controls";
import { card, kv, lazy, muted, stack, code } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formModal, modal, confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { attemptsTable, floorFields, floorText, lastFloor } from "../shared";
import { memoryStore } from "./row-editor";
import { reviewCard } from "./review";

const TRACE: Record<string, [string, Tone]> = {
  running: ["运行中", "accent"], completed: ["已完成", "success"], paused: ["已暂停", "warning"],
  review_required: ["待审核", "warning"], blocked: ["受阻", "danger"], failed: ["失败", "danger"],
};

function requestModal(title: string, messages: Array<{ role: string; content: string }>) {
  modal(title, messages.map((message, index) => lazy(`${index + 1} · ${message.role} · ${message.content.length} 字`, () => code(message.content))), { size: "large" });
}

export async function extractionPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await memoryStore.load();
  const review = extraction.review();
  const statusHost = h("div");
  const drawStatus = () => {
    const trace = extraction.trace();
    const running = extraction.isRunning();
    const [label, tone] = trace ? TRACE[trace.state] ?? [trace.state, "neutral" as Tone] : ["尚未运行", "neutral" as Tone];
    statusHost.replaceChildren(h("div", "ec-stack",
      kv([
        ["状态", running ? badge("正在提取", "accent") : h("span", "", extraction.pauseReason() ?? (review ? "等待审核" : "等待处理"))],
        ["检查点", floorText(state.catalog.lastProcessedMessageId)],
        ["最近一次", trace ? h("span", "ec-row", badge(label, tone), h("span", "ec-muted",
          `${formatTime(trace.completedAt ?? trace.startedAt)} · 写入 ${trace.applied} · 跳过 ${trace.rejected}`)) : "—"],
      ]),
      trace?.message ? muted(trace.message) : null,
      h("div", "ec-row",
        button("处理下一批", async () => {
          await ctx.run("结构化记忆提取", () => extraction.runManual(), () => extraction.stopCurrent());
          await ctx.refresh();
        }, { variant: "primary", icon: "play", disabled: running || Boolean(review) }),
        button("停止", () => extraction.stopCurrent(), { variant: "danger", icon: "stop", disabled: !running }),
        trace && !review ? button("重试上一批", async () => {
          await ctx.run("重试结构化提取", () => extraction.retryCurrent(), () => extraction.stopCurrent());
          await ctx.refresh();
        }, { icon: "rotate", disabled: running }) : null,
        button("预览请求", async () => {
          const prepared = await prepareExtraction(await memoryStore.load(), getSettings(), "manual");
          requestModal("结构化提取请求预览", extractionProviderMessages(prepared.request));
        }, { variant: "ghost", icon: "eye" })),
      trace?.attempts.length ? lazy("端点尝试记录", () => attemptsTable(trace.attempts)) : null,
    ));
  };
  let hadReview = Boolean(review);
  const unsubscribe = extraction.subscribe(() => {
    if (Boolean(extraction.review()) !== hadReview) { hadReview = !hadReview; void ctx.refresh(); return; }
    drawStatus();
  });
  ctx.signal.addEventListener("abort", unsubscribe, { once: true });
  drawStatus();

  const draft = ctx.memo("structured-cleaning", () => ({ start: 0, end: lastFloor(), instructions: "" }));
  const cleaning = form([...floorFields(draft.start, draft.end),
    { key: "instructions", label: "补充要求", type: "textarea", rows: 5, value: draft.instructions,
      hint: "例如：合并“白棠”和“白馆长”两个人物条目；补全第 120–180 楼遗漏的地点信息。" }], { track: false });
  cleaning.node.addEventListener("input", () => {
    draft.instructions = cleaning.control("instructions").value;
    for (const key of ["start", "end"] as const) {
      const value = Number(cleaning.control(key).value);
      if (cleaning.control(key).value !== "" && Number.isFinite(value)) draft[key] = value;
    }
  });
  const cleaningOptions = () => {
    const values = cleaning.values();
    return { startFloor: values.start, endFloor: values.end, instructions: values.instructions };
  };

  return stack(
    card("运行", { scope: "chat", actions: [switchControl("自动提取", state.catalog.automation.enabled, async (value) => {
      ctx.guard();
      await extraction.setAutomationEnabled(value);
    })] }, statusHost),
    review ? reviewCard(ctx, review, state.catalog.types, state.rows) : null,
    card("资料清洗", { description: "从所选楼层和现有条目出发，补全遗漏、更正错误、合并重复。结果进入上方的待审核区，不移动检查点。" },
      cleaning.node, h("div", "ec-row ec-card-foot",
        button("预览清洗请求", async () => {
          ctx.guard();
          const prepared = await extraction.previewCleaning(cleaningOptions());
          requestModal("资料清洗请求预览", extractionProviderMessages(prepared.request));
        }, { variant: "ghost", icon: "eye" }),
        button("开始清洗", async () => {
          const options = cleaningOptions();
          if (!await confirmAction({ title: "开始资料清洗？", message: `会把第 ${options.startFloor}–${options.endFloor} 楼和全部启用表的条目发送给提取端点。`,
            cost: true, confirmLabel: "开始" })) return;
          await ctx.run("结构化资料清洗", () => extraction.runCleaning(options), () => extraction.stopCurrent());
          await ctx.refresh();
        }, { variant: "primary", icon: "wand-magic-sparkles", disabled: Boolean(review) }))),
    card("检查点", { scope: "chat", description: "检查点只决定下一批从哪里开始，修改不会删除已有条目。修改后自动提取会关闭。" },
      h("div", "ec-row",
        button("修改检查点", () => {
          const target = form([{ key: "floor", label: "已处理至楼层", type: "number", min: -1, max: lastFloor(), required: true,
            value: checkpointFloor(state.catalog.lastProcessedMessageId), hint: "-1 表示尚未处理" }], { className: "is-single" });
          formModal("修改结构化检查点", target, async (values) => {
            ctx.guard();
            await extraction.relocateCheckpointToFloor(values.floor);
            await ctx.refresh();
          }, { size: "small", saveLabel: "修改" });
        }, { icon: "pen" }),
        button("移到最新消息", async () => {
          if (!await confirmAction({ title: "把检查点移到最新消息？", message: "尚未处理的消息会被跳过，自动提取会关闭。已有条目保留。", confirmLabel: "移动" })) return;
          ctx.guard();
          await extraction.relocateCheckpoint(currentExtractionMessages().at(-1)?.id ?? null);
          await ctx.refresh();
        }, { icon: "forward" }),
        button("从头开始", async () => {
          if (!await confirmAction({ title: "清除检查点？", message: "下次从第一条消息重新提取，自动提取会关闭。已有条目不会删除。", confirmLabel: "清除" })) return;
          ctx.guard();
          await extraction.relocateCheckpoint(null);
          await ctx.refresh();
        }, { icon: "rotate-left" }))),
  );
}
