import { randomUuid, sha256Hex } from "../../shared/crypto-compat";
import type {
  ChatMessageInput,
  MessageCompressionMarker,
  SummaryBatchMetadata,
  SummarySlice,
} from "../../shared/domain";
import { messageCompressionMarkerSchema } from "../../shared/schemas";
import { echoesApi } from "../api/client";
import {
  SummaryWorldbookStore,
  type SummaryWorldbookState,
} from "../worldbook/summary-worldbook";
import {
  compressionPlan,
  type SummaryBatchCoverage,
} from "./compression-core";
import {
  summaryRetrievalContentHash,
  summaryRetrievalDocumentId,
} from "./retrieval-document";
import { messageWriteCoordinator } from "../chat/message-write-coordinator";
import { indexedChatMessages } from "../chat-message-index";

export interface CompressionBatchStatus {
  batchId: string;
  batchNumber: number;
  covered: number;
  hidden: number;
  pinned: number;
  indexSafe: boolean;
}

export interface CompressionStatus {
  active: boolean;
  hidden: number;
  pinned: number;
  compressible: number;
  indexSafe: boolean;
  unsafeBatchIds: string[];
  staleBatchNumbers: number[];
  batches: CompressionBatchStatus[];
  messageCount: number;
  hideThroughMessageId?: string | undefined;
  blockedReason?: string | undefined;
}

export interface VisibilityChange {
  floor: number;
  sourceHash: string;
  before: { hidden: boolean; marker: MessageCompressionMarker | null };
  after: { hidden: boolean; marker: MessageCompressionMarker | null };
}

interface CompressionSnapshot {
  raw: TavernChatMessage[];
  messages: ChatMessageInput[];
  state: SummaryWorldbookState;
  plan: ReturnType<typeof compressionPlan>;
  safeBatchIds: Set<string>;
  unsafeBatchIds: string[];
  messageIdByFloor: Map<number, string>;
  indexError?: string | undefined;
}

type ChatMessageHelper = TavernHelperApi & Required<
  Pick<TavernHelperApi, "getChatMessages" | "setChatMessages">
>;

function requiredHelper(): ChatMessageHelper {
  if (!window.TavernHelper
    || typeof window.TavernHelper.getChatMessages !== "function"
    || typeof window.TavernHelper.setChatMessages !== "function") {
    throw new Error("Echoes requires TavernHelper chat message APIs for compression.");
  }
  return window.TavernHelper as ChatMessageHelper;
}

function marker(message: TavernChatMessage): MessageCompressionMarker | null {
  const raw = SillyTavern.getContext().chat[message.message_id] as
    | Record<string, any>
    | undefined;
  const candidates = [
    message.extra?.echoes?.compression,
    // TavernHelper surfaces swipe_info entries as `extra`, so a rewritten swipe
    // entry can nest the original extra object one level deeper.
    message.extra?.extra?.echoes?.compression,
    raw?.extra?.echoes?.compression,
  ];
  for (const candidate of candidates) {
    const parsed = messageCompressionMarkerSchema.safeParse(candidate);
    if (parsed.success) return parsed.data;
  }
  return null;
}

function compressionPatch(
  message: TavernChatMessage,
  compression: MessageCompressionMarker | null,
  hidden?: boolean,
) {
  const extra = withMarker(message, compression);
  const raw = SillyTavern.getContext().chat[message.message_id] as Record<string, any> | undefined;
  const swipes = Array.isArray(raw?.swipes) && raw.swipes.length
    ? raw.swipes.map(String)
    : [String(raw?.mes ?? message.message ?? "")];
  const swipesInfo = swipes.map((_, index) => structuredClone(raw?.swipe_info?.[index] ?? {}));
  // TavernHelper only applies `extra` when the patch also carries `message` or
  // `data`. Without this carrier the hide flag is written and the marker is not,
  // which made every later status count read zero.
  const carrier = message.data && typeof message.data === "object" && !Array.isArray(message.data)
    ? { data: message.data }
    : { message: String(message.message ?? "") };
  return {
    message_id: message.message_id,
    ...(hidden === undefined ? {} : { is_hidden: hidden }),
    swipes,
    swipes_info: swipesInfo,
    extra,
    ...carrier,
  };
}

function withMarker(
  message: TavernChatMessage,
  value: MessageCompressionMarker | null,
): Record<string, unknown> {
  if (value === null) {
    const extra = structuredClone(message.extra ?? {});
    if (extra.echoes) delete extra.echoes.compression;
    if (extra.extra?.echoes) delete extra.extra.echoes.compression;
    return extra;
  }
  return {
    ...(message.extra ?? {}),
    echoes: {
      ...(message.extra?.echoes ?? {}),
      compression: value,
    },
  };
}

function nextMarker(
  message: TavernChatMessage,
  namespaceId: string,
  batchId: string,
  changes: Partial<MessageCompressionMarker>,
): MessageCompressionMarker {
  const current = marker(message);
  const now = new Date().toISOString();
  return {
    version: 1,
    stableId: current?.stableId ?? `echoes_message_${randomUuid().replaceAll("-", "")}`,
    namespaceId,
    batchId,
    hiddenByEchoes: current?.hiddenByEchoes ?? false,
    pinnedVisible: current?.pinnedVisible ?? false,
    updatedAt: now,
    ...changes,
  };
}

function uniqueBatches(slices: SummarySlice[]): SummaryBatchMetadata[] {
  return [...new Map(slices.map((slice) => [slice.batch.id, slice.batch])).values()];
}

export class CompressionCoordinator {
  private writing = false;

  constructor(readonly store = new SummaryWorldbookStore()) {}

  get isWriting(): boolean {
    return this.writing;
  }

  inspect(state?: SummaryWorldbookState): Promise<CompressionStatus> {
    return this.serialize(async () => this.statusFromSnapshot(await this.snapshot(state)));
  }

  inspectVisibility(state: SummaryWorldbookState): Promise<Array<Pick<CompressionBatchStatus, "batchId" | "covered" | "hidden" | "pinned">>> {
    return this.serialize(async () => {
      const snapshot = await this.snapshot(state, false);
      return this.statusFromSnapshot(snapshot).batches.map(({ batchId, covered, hidden, pinned }) =>
        ({ batchId, covered, hidden, pinned }));
    });
  }

  reconcile(state?: SummaryWorldbookState, beforeWrite?: (changes: VisibilityChange[]) => Promise<void>): Promise<CompressionStatus> {
    return this.serialize(async () => {
      let snapshot = await this.snapshot(state);
      if (await this.reconcileExternalUnhides(snapshot)) {
        snapshot = await this.snapshot(snapshot.state);
      }
      if (!snapshot.state.catalog.recallEnabled || !snapshot.state.catalog.compression.enabled) {
        return this.statusFromSnapshot(snapshot);
      }
      const safeEnd = this.safeCoverageEnd(snapshot.plan.chain, snapshot.safeBatchIds);
      const targetEnd = Math.min(snapshot.plan.hideThroughIndex, safeEnd);
      const messageIndexById = new Map(snapshot.messages.map((message, index) => [message.id, index]));
      const updates: Parameters<ChatMessageHelper["setChatMessages"]>[0] = [];
      for (const message of snapshot.raw) {
        const id = snapshot.messageIdByFloor.get(message.message_id);
        if (id === undefined) continue;
        const index = messageIndexById.get(id);
        if (index === undefined) continue;
        const item = marker(message);
        const currentOwned = item?.namespaceId === snapshot.state.catalog.namespaceId;
        const targetBatchId = snapshot.plan.batchByMessageId.get(id);
        const shouldHide = index <= targetEnd
          && Boolean(targetBatchId)
          && snapshot.safeBatchIds.has(targetBatchId!)
          && !(currentOwned && item!.pinnedVisible);
        const shouldRestoreForCutoff = index > targetEnd && index <= safeEnd;
        // Also adopt messages that are already hidden inside the current hide
        // range but carry no marker; older versions wrote `is_hidden` without
        // the marker, which left every counter at zero and made restoration
        // impossible.
        if (shouldHide && (!currentOwned || !message.is_hidden)) {
          const compression = nextMarker(
            message,
            snapshot.state.catalog.namespaceId,
            targetBatchId!,
            {
              hiddenByEchoes: true,
              pinnedVisible: false,
              ...(message.is_hidden ? {} : { hiddenAt: new Date().toISOString() }),
            },
          );
          updates.push(compressionPatch(
            message,
            compression,
            message.is_hidden ? undefined : true,
          ));
        } else if (shouldRestoreForCutoff
          && message.is_hidden
          && currentOwned
          && item!.hiddenByEchoes
          && snapshot.plan.coveredMessageIds.has(id)
          && snapshot.plan.chain.some((coverage) => coverage.batch.id === item!.batchId)) {
          const compression = nextMarker(
            message,
            snapshot.state.catalog.namespaceId,
            item!.batchId,
            { hiddenByEchoes: false },
          );
          updates.push(compressionPatch(message, compression, false));
        }
      }
      if (beforeWrite) await beforeWrite(await this.visibilityChanges(snapshot.raw, updates));
      await this.apply(snapshot.state, updates);
      return this.statusFromSnapshot(await this.snapshot(snapshot.state));
    });
  }

  restoreBatch(
    state: SummaryWorldbookState,
    batchIds: string[],
    pinVisible = true,
    beforeWrite?: (changes: VisibilityChange[]) => Promise<void>,
  ): Promise<CompressionStatus> {
    return this.restore(state, (_message, item, _plan, coveredBatchId) => {
      const batchId = item?.batchId ?? coveredBatchId;
      return Boolean(batchId && batchIds.includes(batchId));
    }, pinVisible, false, beforeWrite);
  }

  restoreRange(
    state: SummaryWorldbookState,
    startMessageId: number,
    endMessageId: number,
    pinVisible = true,
  ): Promise<CompressionStatus> {
    const start = Math.min(startMessageId, endMessageId);
    const end = Math.max(startMessageId, endMessageId);
    return this.restore(
      state,
      (message) => message.message_id >= start && message.message_id <= end,
      pinVisible,
    );
  }

  restoreAll(state: SummaryWorldbookState, pinVisible = true): Promise<CompressionStatus> {
    return this.restore(state, (_message, item) => Boolean(item?.hiddenByEchoes), pinVisible, true);
  }

  recompressBatch(
    state: SummaryWorldbookState,
    batchIds: string[],
  ): Promise<CompressionStatus> {
    return this.serialize(async () => {
      const snapshot = await this.snapshot(state);
      const updates: Parameters<ChatMessageHelper["setChatMessages"]>[0] = [];
      for (const message of snapshot.raw) {
        const item = marker(message);
        const batchId = item?.batchId
          ?? snapshot.plan.batchByMessageId.get(snapshot.messageIdByFloor.get(message.message_id) ?? "");
        if (!batchId || !batchIds.includes(batchId) || !item?.pinnedVisible) continue;
        const compression = nextMarker(
          message,
          state.catalog.namespaceId,
          batchId,
          { pinnedVisible: false },
        );
        updates.push(compressionPatch(message, compression));
      }
      await this.apply(state, updates);
      return this.reconcileUnlocked(state);
    });
  }

  hiddenCountForBatches(state: SummaryWorldbookState, batchIds: string[]): Promise<number> {
    return this.serialize(async () => {
      const snapshot = await this.snapshot(state);
      return snapshot.raw.filter((message) => {
        const item = marker(message);
        return message.is_hidden && item?.hiddenByEchoes && batchIds.includes(item.batchId);
      }).length;
    });
  }

  private restore(
    state: SummaryWorldbookState,
    matches: (
      message: TavernChatMessage,
      item: MessageCompressionMarker | null,
      plan: ReturnType<typeof compressionPlan>,
      coveredBatchId: string | undefined,
    ) => boolean,
    pinVisible: boolean,
    includeOtherNamespaces = false,
    beforeWrite?: (changes: VisibilityChange[]) => Promise<void>,
  ): Promise<CompressionStatus> {
    return this.serialize(async () => {
      const snapshot = await this.snapshot(state);
      const updates: Parameters<ChatMessageHelper["setChatMessages"]>[0] = [];
      for (const message of snapshot.raw) {
        const item = marker(message);
        const id = snapshot.messageIdByFloor.get(message.message_id) ?? "";
        const coveredBatchId = snapshot.plan.batchByMessageId.get(id);
        const batchId = item?.batchId
          ?? coveredBatchId;
        if (!batchId || !matches(message, item, snapshot.plan, coveredBatchId)) continue;
        if (item && !includeOtherNamespaces && item.namespaceId !== state.catalog.namespaceId) continue;
        const owned = Boolean(item?.hiddenByEchoes);
        const covered = snapshot.plan.coveredMessageIds.has(id);
        if (!owned && !covered) continue;
        const compression = nextMarker(
          message,
          state.catalog.namespaceId,
          batchId,
          {
            hiddenByEchoes: false,
            pinnedVisible: pinVisible,
          },
        );
        updates.push(compressionPatch(
          message,
          compression,
          owned && message.is_hidden ? false : undefined,
        ));
      }
      if (beforeWrite) {
        await beforeWrite(await this.visibilityChanges(snapshot.raw, updates));
      }
      await this.apply(state, updates);
      return this.statusFromSnapshot(await this.snapshot(state));
    });
  }

  private async reconcileExternalUnhides(snapshot: CompressionSnapshot): Promise<boolean> {
    const updates: Parameters<ChatMessageHelper["setChatMessages"]>[0] = [];
    for (const message of snapshot.raw) {
      const item = marker(message);
      if (!item
        || item.namespaceId !== snapshot.state.catalog.namespaceId
        || !item.hiddenByEchoes
        || message.is_hidden) continue;
      const compression = nextMarker(
        message,
        item.namespaceId,
        item.batchId,
        { hiddenByEchoes: false, pinnedVisible: true },
      );
      updates.push(compressionPatch(message, compression));
    }
    await this.apply(snapshot.state, updates);
    return updates.length > 0;
  }

  private async reconcileUnlocked(state: SummaryWorldbookState): Promise<CompressionStatus> {
    const snapshot = await this.snapshot(state);
    if (!state.catalog.recallEnabled || !state.catalog.compression.enabled) {
      return this.statusFromSnapshot(snapshot);
    }
    const safeEnd = this.safeCoverageEnd(snapshot.plan.chain, snapshot.safeBatchIds);
    const targetEnd = Math.min(snapshot.plan.hideThroughIndex, safeEnd);
    const messageIndexById = new Map(snapshot.messages.map((message, index) => [message.id, index]));
    const updates: Parameters<ChatMessageHelper["setChatMessages"]>[0] = [];
    for (const message of snapshot.raw) {
      const id = snapshot.messageIdByFloor.get(message.message_id) ?? "";
      const index = messageIndexById.get(id);
      if (index === undefined) continue;
      const item = marker(message);
      const batchId = snapshot.plan.batchByMessageId.get(id);
      if (index > targetEnd || !batchId || !snapshot.safeBatchIds.has(batchId)
        || item?.pinnedVisible || message.is_hidden) continue;
      const compression = nextMarker(message, state.catalog.namespaceId, batchId, {
        hiddenByEchoes: true,
        pinnedVisible: false,
        hiddenAt: new Date().toISOString(),
      });
      updates.push(compressionPatch(message, compression, true));
    }
    await this.apply(state, updates);
    return this.statusFromSnapshot(await this.snapshot(state));
  }

  private async snapshot(state?: SummaryWorldbookState, verifyIndex = true): Promise<CompressionSnapshot> {
    const current = state ?? await this.store.load();
    this.assertCurrent(current);
    const raw = requiredHelper().getChatMessages("0-{{lastMessageId}}", {
      include_swipes: false,
      hide_state: "all",
    });
    // Summary IDs may differ from helper floor numbers. Use the same canonical
    // messages (including narrator messages) as summary generation and checkpoints.
    const indexed = indexedChatMessages();
    const messages = indexed.map((entry) => entry.message);
    const messageIdByFloor = new Map(indexed.map((entry) => [entry.floor, entry.message.id]));
    const plan = compressionPlan(
      messages,
      current.slices,
      current.catalog.lastCommittedMessageId,
      current.catalog.compression.keepRecentMessages,
    );
    let safeBatchIds = new Set<string>();
    let unsafeBatchIds = plan.chain.map((coverage) => coverage.batch.id);
    let indexError: string | undefined;
    try {
      if (verifyIndex) ({ safeBatchIds, unsafeBatchIds } = await this.indexSafety(current, plan.chain));
    } catch (error) {
      // Missing diagnostics must block new hiding without changing existing hidden messages.
      indexError = error instanceof Error ? error.message : String(error);
    }
    return { raw, messages, state: current, plan, safeBatchIds, unsafeBatchIds, messageIdByFloor, indexError };
  }

  private async indexSafety(
    state: SummaryWorldbookState,
    chain: SummaryBatchCoverage[],
  ): Promise<{ safeBatchIds: Set<string>; unsafeBatchIds: string[] }> {
    const collectionId = state.catalog.retrievalCollectionId;
    if (!collectionId) {
      return {
        safeBatchIds: new Set(),
        unsafeBatchIds: chain.map((coverage) => coverage.batch.id),
      };
    }
    const expected = await Promise.all(chain.flatMap((coverage) =>
      coverage.slices.map(async (slice) => ({
        batchId: coverage.batch.id,
        documentId: await summaryRetrievalDocumentId(collectionId, slice.id),
        contentHash: await summaryRetrievalContentHash(slice),
      }))));
    const statuses = [];
    for (let offset = 0; offset < expected.length; offset += 100) {
      const page = expected.slice(offset, offset + 100);
      const result = await echoesApi.retrievalDocumentStatus(page.map((item) => item.documentId));
      statuses.push(...result.documents);
    }
    const byId = new Map(statuses.map((item) => [item.documentId, item]));
    const safeBatchIds = new Set<string>();
    const unsafeBatchIds: string[] = [];
    for (const coverage of chain) {
      const batchExpected = expected.filter((item) => item.batchId === coverage.batch.id);
      const safe = batchExpected.length > 0 && batchExpected.every((item) => {
        const status = byId.get(item.documentId);
        return status?.collectionId === collectionId && status.contentHash === item.contentHash;
      });
      if (safe) safeBatchIds.add(coverage.batch.id);
      else unsafeBatchIds.push(coverage.batch.id);
    }
    return { safeBatchIds, unsafeBatchIds };
  }

  private safeCoverageEnd(chain: SummaryBatchCoverage[], safeBatchIds: Set<string>): number {
    let end = -1;
    for (const coverage of chain) {
      if (!safeBatchIds.has(coverage.batch.id)) break;
      end = coverage.endIndex;
    }
    return end;
  }

  private statusFromSnapshot(snapshot: CompressionSnapshot): CompressionStatus {
    const active = snapshot.state.catalog.recallEnabled
      && snapshot.state.catalog.compression.enabled;
    const rawById = new Map(snapshot.raw.map((message) => [snapshot.messageIdByFloor.get(message.message_id), message]));
    const batchStatus = snapshot.plan.chain.map((coverage): CompressionBatchStatus => {
      const messageIds = new Set(coverage.batch.messageIds);
      const messages = [...messageIds].flatMap((id) => {
        const message = rawById.get(id);
        return message ? [message] : [];
      });
      return {
        batchId: coverage.batch.id,
        batchNumber: coverage.batch.batchNumber,
        covered: messages.length,
        hidden: messages.filter((message) => {
          const item = marker(message);
          return message.is_hidden && item?.hiddenByEchoes;
        }).length,
        pinned: messages.filter((message) => marker(message)?.pinnedVisible).length,
        indexSafe: snapshot.safeBatchIds.has(coverage.batch.id),
      };
    });
    const safeEnd = this.safeCoverageEnd(snapshot.plan.chain, snapshot.safeBatchIds);
    const targetEnd = Math.min(snapshot.plan.hideThroughIndex, safeEnd);
    const messageIndexById = new Map(snapshot.messages.map((message, index) => [message.id, index]));
    const hidden = snapshot.raw.filter((message) => {
      const item = marker(message);
      return message.is_hidden && item?.hiddenByEchoes;
    }).length;
    const pinned = snapshot.raw.filter((message) => marker(message)?.pinnedVisible).length;
    const compressible = active
      ? snapshot.raw.filter((message) => {
          const id = snapshot.messageIdByFloor.get(message.message_id) ?? "";
          const index = messageIndexById.get(id);
          const item = marker(message);
          const batchId = snapshot.plan.batchByMessageId.get(id);
          return index !== undefined
            && index <= targetEnd
            && Boolean(batchId)
            && !message.is_hidden
            && !item?.pinnedVisible;
        }).length
      : 0;
    const blockedReason = !snapshot.state.catalog.recallEnabled
      ? "总结召回未启用，已暂停新增隐藏。"
      : !snapshot.state.catalog.compression.enabled
        ? "自动隐藏未启用，请保存隐藏策略后重试。"
        : snapshot.plan.chain.length === 0
          ? "没有从聊天开头连续覆盖到检查点以内的有效总结，请检查批次范围、失效状态和检查点。"
          : snapshot.indexError
            ? `无法校验检索索引：${snapshot.indexError}`
            : snapshot.unsafeBatchIds.length > 0
              ? "部分总结切片的检索索引缺失或内容不一致，已阻止隐藏对应消息及后续消息，请修复索引。"
              : targetEnd < 0
                ? "当前已总结消息均在保留范围内；保留最近原消息数从连续总结终点向前计算。"
                : undefined;
    return {
      active,
      hidden,
      pinned,
      compressible,
      indexSafe: snapshot.unsafeBatchIds.length === 0,
      unsafeBatchIds: snapshot.unsafeBatchIds,
      staleBatchNumbers: uniqueBatches(snapshot.state.slices)
        .filter((batch) => batch.state === "stale")
        .map((batch) => batch.batchNumber),
      batches: batchStatus,
      messageCount: snapshot.messages.length,
      ...(blockedReason ? { blockedReason } : {}),
      ...(targetEnd >= 0
        ? { hideThroughMessageId: snapshot.messages[targetEnd]?.id }
        : {}),
    };
  }

  private async apply(
    state: SummaryWorldbookState,
    updates: Parameters<ChatMessageHelper["setChatMessages"]>[0],
  ): Promise<void> {
    if (updates.length === 0) return;
    this.assertCurrent(state);
    this.writing = true;
    try {
      await requiredHelper().setChatMessages(updates, { refresh: "affected" });
    } finally {
      this.writing = false;
    }
    this.assertCurrent(state);
  }

  private async visibilityChanges(raw: TavernChatMessage[], updates: Parameters<ChatMessageHelper["setChatMessages"]>[0]): Promise<VisibilityChange[]> {
    const byFloor = new Map(raw.map((message) => [message.message_id, message]));
    return Promise.all(updates.map(async (patch) => {
      const message = byFloor.get(patch.message_id)!;
      return { floor: patch.message_id, sourceHash: await sha256Hex(JSON.stringify([message.message, message.swipe_id])),
        before: { hidden: message.is_hidden, marker: marker(message) },
        after: { hidden: patch.is_hidden ?? message.is_hidden, marker: patch.extra?.echoes?.compression ?? null } };
    }));
  }

  async withUndoVisibility<T>(state: SummaryWorldbookState, changes: VisibilityChange[], restoreMemory: () => Promise<T>): Promise<T> {
    return this.serialize(async () => {
      this.assertCurrent(state);
      const raw = requiredHelper().getChatMessages("0-{{lastMessageId}}", { include_swipes: false, hide_state: "all" });
      const updates: Parameters<ChatMessageHelper["setChatMessages"]>[0] = [];
      for (const change of changes) {
        const message = raw.find((message) => message.message_id === change.floor);
        if (!message || await sha256Hex(JSON.stringify([message.message, message.swipe_id])) !== change.sourceHash)
          throw new Error(`第 ${change.floor} 楼原文或回复页已变化，撤销已取消。`);
        const actual = JSON.stringify({ hidden: message.is_hidden, marker: marker(message) });
        if (actual === JSON.stringify(change.before)) continue;
        if (actual !== JSON.stringify(change.after)) throw new Error(`第 ${change.floor} 楼可见性已被后续修改，未覆盖。`);
        updates.push(compressionPatch(message, change.before.marker, change.before.hidden));
      }
      const result = await restoreMemory();
      await this.apply(state, updates);
      return result;
    });
  }

  private assertCurrent(state: SummaryWorldbookState): void {
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
      throw new Error("The active chat changed while Echoes was updating compression.");
    }
  }

  private serialize<T>(operation: () => Promise<T>): Promise<T> {
    return messageWriteCoordinator.run(operation);
  }
}

export const compressionCoordinator = new CompressionCoordinator();
