import { statusCoordinator as coordinator } from "../../../status/status-coordinator";
import { renderStatusYaml } from "../../../status/status-request";
import { getSettings, saveSettings } from "../../../state/settings";
import { h, fill, formatTime } from "../../kit/dom";
import { button, badge, switchControl } from "../../kit/controls";
import { card, stack, kv, lazy, muted, empty } from "../../kit/layout";
import { form } from "../../kit/forms";
import { saveBar } from "../../kit/save";
import { confirmAction } from "../../kit/overlays";
import { toast } from "../../kit/feedback";
import { tabStrip } from "../../kit/tabs";
import type { PageContext } from "../../shell/context";
import { attemptsTable } from "../shared";

/** Renders nested state as labelled groups; leaves as label/value rows. */
export function stateTree(value: unknown): HTMLElement {
  if (!value || typeof value !== "object") return h("p", "ec-muted", String(value ?? "（空）"));
  const entries = Object.entries(value);
  if (!entries.length) return h("p", "ec-muted", "（空）");
  return h("div", "ec-tree", ...entries.map(([key, child]) => child && typeof child === "object"
    ? Object.assign(h("details", "ec-tree-group", h("summary", "", key), stateTree(child)), { open: true })
    : h("div", "ec-tree-leaf", h("span", "ec-tree-key", key), h("span", "ec-tree-value", String(child ?? "")))));
}

const OUTCOME = { completed: "已完成", decision_required: "等待确认", failed: "失败", discarded: "结果已丢弃", unchanged: "无变化", skipped: "未执行" } as const;

export async function statusCurrentPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await coordinator.load();
  const current = coordinator.current(state);
  const value = current?.snapshot.state ?? state.catalog.profile.initialState;
  const token = coordinator.manualStateToken(state);
  const view = ctx.memo("status-view", () => ({ mode: "tree" }));
  const sync = async (force: boolean) => {
    ctx.guard();
    if (force && !await confirmAction({ title: "重新计算当前状态？", cost: true, confirmLabel: "重新计算",
      message: "按当前提示词和上一楼的状态重新计算，会覆盖对当前状态的手动修改或恢复。" })) return;
    const snapshot = await ctx.run(force ? "重新计算状态" : "状态记忆同步", () => force ? coordinator.recompute() : coordinator.synchronize());
    const trace = coordinator.trace;
    if (trace?.outcome === "unchanged") toast(trace.message ?? "当前楼层已有匹配的快照，无需更新。", "info");
    else if (!snapshot || trace?.outcome !== "completed") toast(trace?.message ?? "这次没有写入新的状态快照。", "warning");
    else toast(`状态已同步，快照对应消息 ${snapshot.targetMessageId}。`, "success");
    await ctx.refresh();
  };
  const body = h("div");
  const draw = () => {
    if (view.mode === "tree") { fill(body, stateTree(value)); return; }
    const editor = form([{ key: "yaml", label: "当前状态 YAML", type: "code", rows: 22, value: renderStatusYaml(value) }], { className: "is-single" });
    fill(body, editor.node, saveBar(editor, async (values) => {
      ctx.guard();
      await coordinator.saveManualState(coordinator.parseYaml(values.yaml), "manual", token);
      editor.commit();
      await ctx.refresh();
    }, "校验并保存"));
  };
  const modes = () => tabStrip("状态显示方式", [{ id: "tree", label: "字段" }, { id: "yaml", label: "YAML 编辑" }], view.mode, async (id) => {
    if (body.querySelector('[data-dirty="true"]') && !await confirmAction({ title: "放弃未保存的 YAML 修改？", danger: true, confirmLabel: "放弃" })) return;
    view.mode = id;
    modeHost.replaceChildren(modes());
    draw();
  }, "is-inline");
  const modeHost = h("div", "", modes());
  draw();
  const trace = coordinator.trace;
  return stack(
    card("开关与同步", { scope: "chat" },
      switchControl("启用状态记忆", state.catalog.enabled, async (enabled) => {
        ctx.guard();
        await coordinator.worldbook.saveConfiguration(state.worldbookName, { enabled });
        await ctx.refresh();
      }, { hint: "开启后按剧情更新状态，并在生成时注入当前状态" }),
      switchControl("自动更新", state.catalog.autoUpdate, async (autoUpdate) => {
        ctx.guard();
        await coordinator.worldbook.saveConfiguration(state.worldbookName, { autoUpdate });
      }, { hint: "每次回复生成后自动同步" }),
      switchControl("显示悬浮按钮", getSettings().statusFloatingButton, (enabled) => {
        const next = getSettings();
        next.statusFloatingButton = enabled;
        saveSettings(next);
        window.dispatchEvent(new Event("echoes-status-configuration-changed"));
      }, { hint: "全局设置：在聊天界面显示状态同步按钮" }),
      h("div", "ec-row ec-card-foot",
        button("手动同步", () => sync(false), { variant: "primary", icon: "arrows-rotate", disabled: !state.catalog.enabled }),
        button("重新计算", () => sync(true), { icon: "rotate", disabled: !state.catalog.enabled }),
        button("恢复初始值", async () => {
          if (!await confirmAction({ title: "把当前状态恢复为初始值？", confirmLabel: "恢复" })) return;
          ctx.guard();
          await coordinator.saveManualState(state.catalog.profile.initialState, "manual", token);
          await ctx.refresh();
        }, { variant: "ghost", icon: "rotate-left" }))),
    card("当前状态", { actions: [modeHost],
      description: current ? `快照对应第 ${current.messageIndex} 楼 · ${formatTime(current.snapshot.updatedAt)}` : "还没有快照，显示的是初始状态。" }, body),
    card("最近一次任务", {}, trace ? h("div", "ec-stack",
      kv([["结果", badge(OUTCOME[trace.outcome], trace.outcome === "completed" ? "success" : trace.outcome === "unchanged" ? "neutral" : "warning")],
        ["完成时间", formatTime(trace.completedAt)], ["操作数", String(trace.operationCount)], ["目标消息", trace.targetMessageId]]),
      trace.message ? muted(trace.message) : null,
      trace.attempts.length ? lazy("端点尝试记录", () => attemptsTable(trace.attempts)) : null) : empty("本次会话还没有运行过状态任务。")),
  );
}
