import type { RetrievalTrace } from "../../../../shared/domain";
import { h } from "../../kit/dom";
import { badge, iconButton } from "../../kit/controls";
import { card, code, kv, lazy, stats, callout } from "../../kit/layout";
import { table, paginate, pager } from "../../kit/data";
import { modal } from "../../kit/overlays";

const BRANCH = { succeeded: "成功", failed: "失败", ambiguous: "结果不确定", disabled: "未启用" } as const;
const DECISION = { selected: "通过", minimum_relevance: "低于阈值", result_limit: "超过返回上限" } as const;
const CATEGORY = { status: "状态", batch_overview: "常驻批次总结", recent: "近期总结", semantic: "普通召回", retained: "滞留切片" } as const;

/** Read-only rendering of one recall run: stages, branches, candidates, budget and injected text. */
export function traceView(trace: RetrievalTrace): HTMLElement {
  const root = h("div", "ec-stack");
  root.append(stats([
    ["命中", String(trace.returned)], ["注入", String(trace.injected)],
    ["近期切片", String(trace.recentSliceCount)], ["滞留切片", String(trace.retainedSliceCount ?? 0)],
  ]));
  if (trace.message) root.append(callout("info", trace.message));
  root.append(card("检索分支", {}, kv((["vector", "bm25", "rerank"] as const).map((key) => {
    const branch = trace.branches[key];
    return [{ vector: "向量", bm25: "BM25", rerank: "重排序" }[key],
      h("span", "", `${BRANCH[branch.state]} · ${branch.durationMs} ms${branch.message ? " · " + branch.message : ""}`)];
  })), trace.stages?.length ? table([
    { label: "阶段", cell: (stage) => stage.name }, { label: "数量", cell: (stage) => String(stage.count) },
    { label: "说明", cell: (stage) => stage.note ?? "" },
  ], trace.stages) : null));
  if (trace.injectionBudget) {
    const budget = trace.injectionBudget;
    root.append(card("注入预算（本地估算 Token）", {},
      h("div", "ec-row", badge(`预算 ${budget.limit || "不限"}`), badge(`候选合计 ${budget.requestedTokens}`),
        badge(`本轮注入 ${budget.injectedTokens}`, budget.overflow ? "warning" : "neutral"), budget.blocked ? badge("已中止生成", "danger") : null),
      table([
        { label: "类别", cell: (item) => CATEGORY[item.category] },
        { label: "筛选前", cell: (item) => String(item.requestedTokens) },
        { label: "筛选后", cell: (item) => String(item.injectedTokens) },
      ], budget.categories),
      budget.omitted.length ? lazy(`未注入的内容 · ${budget.omitted.length}`, budget.omitted) : null));
  }
  const candidates = trace.diagnostics?.candidates ?? [];
  if (candidates.length) {
    const host = h("div");
    const state = { page: 0 };
    const draw = () => {
      const page = paginate(candidates, state, 30);
      host.replaceChildren(table([
        { label: "切片", cell: (item) => item.hit.document.sourceId },
        { label: "融合", cell: (item) => item.hit.rrfScore.toFixed(4) },
        { label: "重排", cell: (item) => item.hit.rerankScore?.toFixed(4) ?? "—" },
        { label: "加权后", cell: (item) => item.hit.weightedScore?.toFixed(4) ?? "—" },
        { label: "阈值", cell: (item) => String(item.threshold) },
        { label: "去向", cell: (item) => badge(DECISION[item.decision], item.decision === "selected" ? "success" : "neutral") },
        { label: "", cell: (item) => iconButton("查看分数构成", "eye", () => modal("分数构成", [
          table([
            { label: "权重项", cell: (step) => step.label }, { label: "原始", cell: (step) => String(step.before) },
            { label: "加权重", cell: (step) => String(step.add) }, { label: "乘权重", cell: (step) => String(step.multiply) },
            { label: "结果", cell: (step) => String(step.after) },
          ], item.hit.scoreSteps ?? [], { empty: "没有记录权重步骤" }),
          lazy("分路命中", item.hit.queryMatches ?? []),
        ])) },
      ], page.items), pager(state, page.pages, candidates.length, draw));
    };
    draw();
    root.append(card("候选筛选", { description: trace.diagnostics?.omittedCandidates ? `另有 ${trace.diagnostics.omittedCandidates} 条未展开。` : undefined }, host));
  }
  if (trace.sourceIssues?.length) root.append(card("召回源校验", {}, table([
    { label: "来源", cell: (issue) => issue.chatId ?? issue.collectionId },
    { label: "切片", cell: (issue) => issue.batchNumber !== undefined ? `${issue.batchNumber}.${issue.sliceNumber}` : issue.sliceId },
    { label: "原因", cell: (issue) => issue.reason }, { label: "建议", cell: (issue) => issue.action },
  ], trace.sourceIssues)));
  root.append(
    lazy("实际查询", trace.diagnostics?.queries ?? trace.query),
    lazy("查询编排来源", trace.queryBlocks ?? []),
    lazy("来源集合", trace.sources),
    ...(trace.decisions?.length ? [lazy("前端排除原因", trace.decisions)] : []),
    lazy("注入文本", () => code(trace.injectionText || "（本次没有注入内容）")),
  );
  return root;
}
