import { randomUuid } from "../../shared/crypto-compat";

const OWNER_KEY = "echoes_local_journal_owner";
let database: Promise<IDBDatabase> | undefined;

function owner(): string {
  const context = SillyTavern.getContext();
  let value = context.extensionSettings[OWNER_KEY];
  if (typeof value !== "string" || !value) {
    value = randomUuid();
    context.extensionSettings[OWNER_KEY] = value;
    context.saveSettingsDebounced();
  }
  return value;
}

function open(): Promise<IDBDatabase> {
  if (!database) database = new Promise((resolve, reject) => {
    const request = indexedDB.open("echoes-local-journal", 1);
    request.onupgradeneeded = () => request.result.createObjectStore("records");
    request.onsuccess = () => {
      request.result.onversionchange = () => { request.result.close(); database = undefined; };
      resolve(request.result);
    };
    request.onerror = () => reject(request.error);
    request.onblocked = () => reject(new Error("本地任务记录升级被其他页面阻止，请关闭旧页面后重试。"));
  }).catch((error: unknown) => { database = undefined; throw error; }) as Promise<IDBDatabase>;
  return database;
}

export async function readLocalRecord<T>(key: string): Promise<T | undefined> {
  const scope = owner();
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("records", "readonly");
    const request = tx.objectStore("records").get(`${scope}:${key}`);
    tx.oncomplete = () => resolve(request.result as T | undefined);
    tx.onabort = () => reject(tx.error ?? new Error("读取本地任务记录失败。"));
  });
}

export async function writeLocalRecord<T>(key: string, value: T | undefined): Promise<void> {
  await updateLocalRecord<T>(key, () => value);
}

export async function updateLocalRecord<T>(key: string, update: (current: T | undefined) => T | undefined): Promise<void> {
  const scope = owner();
  const db = await open();
  return new Promise((resolve, reject) => {
    const tx = db.transaction("records", "readwrite");
    const store = tx.objectStore("records");
    const scopedKey = `${scope}:${key}`;
    const request = store.get(scopedKey);
    let failure: unknown;
    request.onsuccess = () => {
      try {
        const value = update(request.result as T | undefined);
        if (value === undefined) store.delete(scopedKey);
        else store.put(structuredClone(value), scopedKey);
      } catch (error) {
        failure = error;
        tx.abort();
      }
    };
    tx.oncomplete = () => resolve();
    tx.onabort = () => reject(failure ?? tx.error ?? new Error("保存本地任务记录失败，操作未继续。"));
  });
}
