import { discussionSettingsSchema, type DiscussionSettings } from "../../../../shared/discussion";
import { discussionCoordinator as coordinator, type DiscussionRun } from "../../../discussion/discussion-coordinator";
import { getSettings, saveSettings } from "../../../state/settings";
import { h, uid, formatTime, copyText } from "../../kit/dom";
import { button, badge, iconButton, selectControl, type Tone } from "../../kit/controls";
import { card, callout, empty, lazy } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formModal, confirmAction } from "../../kit/overlays";
import { toast, reportError } from "../../kit/feedback";
import type { PageContext } from "../../shell/context";
import { attemptsTable } from "../shared";

export function saveDiscussion(change: (settings: DiscussionSettings) => void): void {
  const settings = getSettings();
  const discussion = structuredClone(settings.discussion);
  change(discussion);
  settings.discussion = discussionSettingsSchema.parse(discussion);
  saveSettings(settings);
}

export function editPreset(presetId: string | undefined, content: string, done: () => unknown) {
  const preset = getSettings().discussion.presets.find((item) => item.id === presetId);
  const target = form([
    { key: "name", label: "预设名称", value: preset?.name ?? "", required: true },
    { key: "content", label: "用户提示词", type: "textarea", rows: 12, value: content || preset?.content || "", required: true },
  ], { className: "is-single" });
  return formModal(preset ? `修改预设 · ${preset.name}` : "新增讨论预设", target, async (values) => {
    saveDiscussion((settings) => {
      const next = { id: preset?.id ?? uid("discussion"), name: values.name, content: values.content };
      const index = settings.presets.findIndex((item) => item.id === preset?.id);
      if (preset && index < 0) throw new Error("这个预设已被删除，请刷新后重试。");
      if (index < 0) settings.presets.push(next);
      else settings.presets[index] = next;
    });
    await done();
  }, { size: "large" });
}

const STATUS: Record<DiscussionRun["status"], [string, Tone]> = {
  preparing: ["准备上下文", "accent"], generating: ["生成中", "accent"], completed: ["已完成", "success"],
  cancelled: ["已停止", "neutral"], failed: ["失败", "danger"], decision_required: ["等待确认", "warning"],
};

export function discussionPage(ctx: PageContext): HTMLElement {
  const workflow = getSettings().generationWorkflows.discussion;
  const group = getSettings().generationGroups.find((item) => item.id === workflow.groupId);
  const draft = ctx.memo("discussion-draft", () => ({ text: "", preset: "" }));
  const compose = form([{ key: "prompt", label: "讨论内容", type: "textarea", rows: 10, value: draft.text, required: true,
    placeholder: "例如：接下来三轮，怎样让白棠对旧潮罗盘的秘密起疑？" }], { track: false, className: "is-single" });
  const input = compose.control("prompt") as HTMLTextAreaElement;
  input.maxLength = 100_000;
  input.addEventListener("input", () => { draft.text = input.value; });
  const presetOptions = () => [["", "选择预设…"] as [string, string], ...getSettings().discussion.presets.map((item): [string, string] => [item.id, item.name])];
  const presetHost = h("div", "ec-row");
  const drawPresets = () => presetHost.replaceChildren(selectControl("用户提示词预设", presetOptions(), draft.preset, async (value) => {
    const preset = getSettings().discussion.presets.find((item) => item.id === value);
    if (preset && input.value.trim() && input.value !== preset.content
      && !await confirmAction({ title: "用预设替换当前内容？", confirmLabel: "替换" })) { drawPresets(); return; }
    draft.preset = value;
    if (preset) { input.value = preset.content; draft.text = preset.content; }
  }), iconButton("修改所选预设", "pen", () => {
    if (!draft.preset) throw new Error("请先选择一个预设。");
    return editPreset(draft.preset, input.value, drawPresets);
  }), iconButton("另存为预设", "floppy-disk", () => editPreset(undefined, input.value, drawPresets)));
  drawPresets();
  const send = button("开始讨论", () => {
    ctx.guard();
    compose.values();
    void coordinator.start(input.value).catch(reportError);
  }, { variant: "primary", icon: "paper-plane" });
  const stop = button("停止", () => coordinator.stop(), { variant: "danger", icon: "stop" });
  const results = h("div", "ec-discussion-results");
  const idle = empty("还没有讨论回复。回复只显示在这里，不会写入聊天。");
  const views = new Map<string, { root: HTMLElement; state: HTMLElement; meta: HTMLElement; text: HTMLElement; message: HTMLElement;
    resume: HTMLButtonElement; attempts: HTMLElement; result?: unknown }>();
  const render = () => {
    if (ctx.signal.aborted) return;
    const running = coordinator.running;
    send.disabled = Boolean(running);
    stop.hidden = !running || running.chatId !== ctx.chatId;
    const history = coordinator.history(ctx.chatId);
    idle.hidden = history.length > 0;
    for (const [id, view] of views) if (!history.some((run) => run.id === id)) { view.root.remove(); views.delete(id); }
    for (const run of history) {
      let view = views.get(run.id);
      if (!view) {
        const state = h("span");
        const meta = h("span", "ec-muted");
        const text = h("div", "ec-prose ec-discussion-text");
        const message = h("p", "ec-muted");
        message.setAttribute("role", "status");
        const resume = button("切换到下一端点", async () => {
          ctx.guard();
          if (!await confirmAction({ title: "切换到下一端点？", cost: true, confirmLabel: "切换",
            message: "上一个请求可能已经完成并计费。会用同一份上下文向下一个端点发起新请求。" })) return;
          await coordinator.continue(run.id);
        }, { small: true, icon: "forward" });
        const attempts = h("div");
        const root = h("article", "ec-discussion-item",
          h("header", "ec-row", state, meta, h("span", "ec-grow"), h("time", "ec-muted", formatTime(run.startedAt, false)),
            iconButton("复制回复", "copy", async () => { await copyText(run.text); toast("已复制", "success"); })),
          lazy("本次提问", run.prompt), message, text, attempts, h("div", "ec-row", resume));
        view = { root, state, meta, text, message, resume, attempts };
        views.set(run.id, view);
        results.prepend(root);
      }
      const [label, tone] = STATUS[run.status];
      view.state.replaceChildren(badge(label, tone));
      view.meta.textContent = run.endpointName ? `${run.endpointName} · ${run.streaming ? "流式" : "非流式"}` : "";
      view.message.textContent = run.message;
      if (view.text.textContent !== run.text) view.text.textContent = run.text;
      view.resume.hidden = run.status !== "decision_required" || !run.result?.decisionRequired?.nextEndpointId;
      view.resume.disabled = Boolean(running);
      if (view.result !== run.result) {
        view.result = run.result;
        view.attempts.replaceChildren(...(run.result?.attempts.length ? [lazy("端点尝试记录", () => attemptsTable(run.result!.attempts))] : []));
      }
    }
  };
  let frame: number | undefined;
  const unsubscribe = coordinator.subscribe(() => {
    if (frame === undefined) frame = requestAnimationFrame(() => { frame = undefined; render(); });
  });
  ctx.signal.addEventListener("abort", () => { unsubscribe(); if (frame !== undefined) cancelAnimationFrame(frame); }, { once: true });
  results.append(idle);
  render();
  return h("div", "ec-stack",
    group ? null : callout("warning", "剧情讨论还没有分配端点组。", button("去分配", () => ctx.navigate("api/assignment"), { variant: "ghost", small: true, icon: "arrow-right" })),
    h("div", "ec-discussion",
      card("提问", { description: group ? `端点组：${group.name}` : undefined }, presetHost, compose.node, h("div", "ec-row", send, stop)),
      card("回复", { actions: [iconButton("清空讨论回复", "trash", async () => {
        if (!await confirmAction({ title: "清空讨论回复？", message: "只清除本页显示的回复，不影响聊天和记忆。", confirmLabel: "清空" })) return;
        coordinator.clear(ctx.chatId);
      })] }, results)));
}
