import type { MemoryColumnDefinition, MemoryEntryStatus, MemoryTypeTemplate } from "../../shared/domain";

type Column = [
  id: string, name: string, description: string,
  type?: MemoryColumnDefinition["type"], defaultValue?: string | number,
];

const TEMPLATE_TIME = "2026-10-01T00:00:00.000Z";

function template(
  id: string, name: string, description: string, columns: Column[], guide: string,
  defaultStatus: MemoryEntryStatus = "keyword",
  builtIn = true,
): MemoryTypeTemplate {
  return {
    id, name, description, guide, defaultStatus, builtIn,
    columns: columns.map(([id, name, description, type = "long_text", defaultValue]) => ({
      id, name, description, type, required: false,
      ...(defaultValue === undefined ? {} : { defaultValue }),
    })),
    version: 1, createdAt: TEMPLATE_TIME, updatedAt: TEMPLATE_TIME,
  };
}

