import { getSettings } from "../../../state/settings";
import { nowIso } from "../../kit/dom";
import { card, stack } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import type { PageContext } from "../../shell/context";
import { promptList } from "../prompt-editor";
import { updateRecall } from "./strategy";

export function recallQueryPage(_ctx: PageContext): HTMLElement {
  const preset = getSettings().retrieval.recall.queryPreset;
  const mode = form([
    { key: "mode", label: "查询方式", type: "select", value: preset.mode ?? "combined",
      options: [["combined", "合并为一条查询"], ["multi", "每项单独查询后合并结果"]] },
    { key: "maxQueries", label: "最多查询项", type: "number", min: 1, max: 8, value: preset.maxQueries ?? 4, required: true,
      hint: "按下方顺序取前几项" },
    { key: "maxCharacters", label: "查询总字符预算", type: "number", min: 256, max: 12000, value: preset.maxCharacters ?? 12000, required: true },
  ]);
  return stack(
    formCard("查询方式", mode, (values) => updateRecall((recall) => {
      recall.queryPreset = { ...recall.queryPreset, mode: values.mode, maxQueries: values.maxQueries, maxCharacters: values.maxCharacters, updatedAt: nowIso() };
    }), { scope: "global" }),
    card("查询项", { scope: "global", description: "召回用这些内容作查询文本，去总结中查找相关切片。" },
      promptList("query", preset.items, (items) => updateRecall((recall) => {
        recall.queryPreset = { ...recall.queryPreset, items, updatedAt: nowIso() };
      }))),
  );
}
