import { ECHOES_BUILD_INFO } from "../../../../shared/build-info";
import { echoesApi as api } from "../../../api/client";
import { redactedSettings } from "../../../state/settings";
import { h, download, errorText } from "../../kit/dom";
import { button, badge, type Tone } from "../../kit/controls";
import { card, stack, kv, lazy, callout } from "../../kit/layout";
import type { PageContext } from "../../shell/context";

const SUBSYSTEM: Record<string, [string, Tone]> = { ready: ["就绪", "success"], degraded: ["降级", "warning"], unavailable: ["不可用", "danger"] };

export async function aboutPage(ctx: PageContext): Promise<HTMLElement> {
  const actions = h("div", "ec-row",
    button("导出脱敏配置", () => download("echoes-settings-redacted.json", JSON.stringify(redactedSettings(), null, 2)), { variant: "ghost", icon: "download" }),
    button("运行诊断", () => ctx.navigate("system/diagnostics"), { variant: "ghost", icon: "stethoscope" }));
  try {
    const status = await api.systemStatus();
    const state = (value: string) => { const [label, tone] = SUBSYSTEM[value] ?? [value, "neutral" as Tone]; return badge(label, tone); };
    return stack(
      status.protocolCompatible ? null : callout("danger", "前后端协议不兼容，请把两端更新到配套的版本。"),
      card("版本与连接", {}, kv([
        ["前端版本", ECHOES_BUILD_INFO.appVersion], ["后端版本", status.build.appVersion],
        ["协议", status.protocolCompatible ? badge("兼容", "success") : badge("不兼容", "danger")],
        ["Node.js", `${status.platform.node} · ${status.platform.platform}-${status.platform.arch}${status.platform.supported ? "" : "（不在支持范围内）"}`],
        ["启动状态", state(status.bootstrap.state)], ["凭据服务", state(status.subsystems.credentials)],
        ["任务服务", state(status.subsystems.jobs)], ["检索服务", state(status.subsystems.retrieval)],
      ]), status.bootstrap.message ? h("p", "ec-muted", status.bootstrap.message) : null, lazy("完整系统状态", status), actions),
    );
  } catch (error) {
    return stack(callout("danger", `无法连接 Echoes 后端：${errorText(error)}`), card("版本", {}, kv([["前端版本", ECHOES_BUILD_INFO.appVersion]]), actions));
  }
}
