import { batchOverviewSchema, type BatchOverview } from "../../shared/batch-overview";

export function readBatchOverview(entry: TavernWorldbookEntry): BatchOverview | null {
  if (entry.extra?.echoes?.kind !== "summary_batch_overview") return null;
  return batchOverviewSchema.parse(entry.extra.echoes.overview);
}

export function batchOverviewEntry(overview: BatchOverview): Partial<TavernWorldbookEntry> {
  return {
    name: `批次总结 ${overview.batch.batchNumber}`,
    enabled: overview.enabled && Boolean(overview.content.trim()),
    strategy: { type: "constant", keys: [] },
    position: { type: "after_character_definition", role: "system", depth: 4, order: 80 },
    content: overview.content ? `[批次总结 ${overview.batch.batchNumber}]\n${overview.content}` : "",
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    extra: { echoes: { kind: "summary_batch_overview", version: 1, overview } },
  };
}

export function pruneBatchOverviews(entries: TavernWorldbookEntry[]): TavernWorldbookEntry[] {
  const batchIds = new Set(entries.filter((entry) => entry.extra?.echoes?.kind === "summary_slice")
    .map((entry) => entry.extra!.echoes.batch.id));
  return entries.filter((entry) => entry.extra?.echoes?.kind !== "summary_batch_overview"
    || batchIds.has(entry.extra.echoes.overview.batch.id));
}
