import { h } from "./dom";

const THEME_KEY = "echoes.ui.theme";
export type ThemeChoice = "system" | "dark" | "light";

function stored(): ThemeChoice {
  try {
    const value = localStorage.getItem(THEME_KEY);
    return value === "dark" || value === "light" ? value : "system";
  } catch {
    return "system";
  }
}

let choice: ThemeChoice = stored();
const media = typeof matchMedia === "function" ? matchMedia("(prefers-color-scheme: light)") : null;
const themed = new Set<HTMLElement>();

export function resolvedTheme(): "dark" | "light" {
  if (choice !== "system") return choice;
  return media?.matches ? "light" : "dark";
}

export function themeChoice(): ThemeChoice {
  return choice;
}

function apply(): void {
  const theme = resolvedTheme();
  for (const node of themed) node.dataset.theme = theme;
}

/** Registers a root that carries the design tokens; it follows theme changes. */
export function themeRoot(node: HTMLElement): HTMLElement {
  node.classList.add("ec-theme");
  themed.add(node);
  node.dataset.theme = resolvedTheme();
  return node;
}

export function setThemeChoice(next: ThemeChoice): void {
  choice = next;
  try {
    if (next === "system") localStorage.removeItem(THEME_KEY);
    else localStorage.setItem(THEME_KEY, next);
  } catch {}
  apply();
}

media?.addEventListener("change", apply);

let layerNode: HTMLElement | null = null;

/**
 * Overlays (modals, menus, toasts) live in one body-level layer so they work
 * whether or not the workbench window is open. The window keeps it out of the
 * inert set it applies to the rest of the page.
 */
export function layer(): HTMLElement {
  if (!layerNode) {
    layerNode = themeRoot(h("div", "ec-layer"));
    layerNode.id = "echoes-layer";
  }
  if (!layerNode.isConnected) document.body.append(layerNode);
  return layerNode;
}

/** The topmost open modal, if any; overlays opened from it must render inside it. */
export function topDialog(): HTMLDialogElement | null {
  const open = [...layer().querySelectorAll<HTMLDialogElement>("dialog[open]")];
  return open.at(-1) ?? null;
}

export function overlayHost(): HTMLElement {
  return topDialog() ?? layer();
}
