import type { CredentialMetadata } from "../../../../shared/domain";
import { echoesApi as api } from "../../../api/client";
import { getSettings, legacyCredentialEndpoints, applyCredentialMigration } from "../../../state/settings";
import { h, uid, formatTime } from "../../kit/dom";
import { button, menu } from "../../kit/controls";
import { card, stack, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formModal, confirmAction } from "../../kit/overlays";
import { table } from "../../kit/data";
import type { PageContext } from "../../shell/context";

export async function credentialsPage(ctx: PageContext): Promise<HTMLElement> {
  const credentials = await api.listCredentials();
  const done = () => ctx.refresh();
  const edit = (current?: CredentialMetadata) => {
    const target = form([
      { key: "name", label: "名称", value: current?.name ?? "", required: true },
      { key: "secret", label: current ? "新密钥" : "API 密钥", type: "password", required: !current, hint: current ? "留空则保留原密钥" : undefined },
    ], { className: "is-single" });
    formModal(current ? `修改凭据 · ${current.name}` : "新增凭据", target, async (values) => {
      if (current) await api.updateCredential(current.id, { name: values.name, ...(values.secret ? { secret: values.secret } : {}) });
      else await api.createCredential({ name: values.name, secret: values.secret });
      await done();
    }, { size: "small" });
  };
  const legacy = legacyCredentialEndpoints();
  const endpoints = () => {
    const settings = getSettings();
    return [...settings.generationGroups, ...settings.retrieval.embeddingGroups, ...settings.retrieval.rerankSets].flatMap((group) => group.endpoints);
  };
  return stack(
    legacy.length ? callout("warning", `有 ${legacy.length} 个端点的密钥还以明文保存在浏览器设置中。`, button("迁移到服务端", async () => {
      if (!await confirmAction({ title: "把旧密钥迁移到服务端凭据存储？", confirmLabel: "迁移" })) return;
      const bindings = legacy.map(({ kind, containerId, endpointId }) => ({ kind, containerId, endpointId, credentialId: uid("credential") }));
      await api.migrateCredentials(legacy.map((endpoint, index) => ({ id: bindings[index]!.credentialId, name: endpoint.endpointName, secret: endpoint.apiKey })));
      applyCredentialMigration(bindings);
      await done();
    }, { small: true, icon: "file-import" })) : null,
    card("凭据", { scope: "global", description: "密钥保存在服务端当前 SillyTavern 用户的数据目录，不会写入记忆、提示词或备份。",
      actions: [button("新增凭据", () => edit(), { variant: "primary", small: true, icon: "key" })] },
    table([
      { label: "名称", cell: (item) => h("strong", "", item.name) },
      { label: "创建时间", cell: (item) => formatTime(item.createdAt) },
      { label: "最后使用", cell: (item) => item.lastUsedAt ? formatTime(item.lastUsedAt) : "尚未使用" },
      { label: "使用它的端点", cell: (item) => String(endpoints().filter((endpoint) => endpoint.credentialId === item.id).length) },
      { label: "", className: "is-actions", cell: (item) => menu(`${item.name} 的操作`, [
        { label: "修改", icon: "pen", onSelect: () => edit(item) },
        { label: "删除", icon: "trash", danger: true, onSelect: async () => {
          if (endpoints().some((endpoint) => endpoint.credentialId === item.id)) throw new Error("还有端点在使用这个凭据，请先为这些端点更换凭据。");
          if (!await confirmAction({ title: `删除凭据「${item.name}」？`, irreversible: true, danger: true, confirmLabel: "删除" })) return;
          await api.deleteCredential(item.id);
          await done();
        } },
      ]) },
    ], credentials, { empty: "还没有凭据。" })),
  );
}
