import { h, type Child } from "./dom";
import { button } from "./controls";
import { toast } from "./feedback";
import { card, type CardOptions } from "./layout";
import type { Form } from "./forms";

/**
 * The sticky "unsaved changes" bar for a form. It appears once the form is
 * dirty; a save that races with further edits leaves the bar visible.
 */
export function saveBar(target: Form, save: (values: Record<string, any>) => unknown, label = "保存"): HTMLElement {
  let edits = 0;
  const status = h("span", "ec-savebar-text", "有未保存的修改");
  status.setAttribute("role", "status");
  const discard = button("放弃", () => target.reset(), { variant: "ghost", small: true });
  const submit = button(label, async () => {
    const values = target.values();
    const version = edits;
    await save(values);
    if (version === edits) target.commit();
    toast("已保存", "success");
  }, { variant: "primary", small: true, icon: "floppy-disk" });
  const bar = h("div", "ec-savebar", status, h("div", "ec-row", discard, submit));
  const update = () => { bar.hidden = !target.dirty(); };
  target.node.addEventListener("input", () => { edits++; });
  target.node.addEventListener("change", () => { edits++; });
  target.onChange(update);
  update();
  return bar;
}

/** A card holding a form and its save bar. */
export function formCard(title: string, target: Form, save: (values: Record<string, any>) => unknown,
  options: CardOptions & { saveLabel?: string; after?: Child } = {}): HTMLElement {
  return card(title, options, target.node, options.after, saveBar(target, save, options.saveLabel));
}
