// Batch overviews are injected separately, so they are not summary background.
function summaryWorldbookContent(messages: ChatMessageInput[]): Promise<string> {
  return activatedWorldbookContent(messages.map((message) => message.content),
    window.TavernHelper?.getChatWorldbookName("current"), (kind) => kind === "summary_batch_overview");
}

export { SUMMARY_OUTPUT_PROTOCOL } from "../../shared/summary-protocol";

export interface SummaryPromptBlock {
  id: string;
  title: string;
  role: PromptMessageInput["role"];
  content: string;
}

export interface PreparedSummaryRequest {
  subRequests?: PreparedSummaryRequest[] | undefined;
  ranges?: SummaryPart["ranges"] | undefined;
  batch: SummaryBatchInput;
  originalMessages: ChatMessageInput[];
  cleanedMessages: ChatMessageInput[];
  promptBlocks: SummaryPromptBlock[];
  promptMessages: PromptMessageInput[];
}

export function currentChatMessages(): ChatMessageInput[] {
  return indexedChatMessages().map((entry) => entry.message);
}

export async function summarySourceHash(messages: ChatMessageInput[]): Promise<string> {
  return sourceMessagesHash(messages);
}

export async function automaticSummaryBatch(
  messages: ChatMessageInput[],
  catalog: SummaryCatalog,
  messageCount: number,
): Promise<{ batch: SummaryBatchInput; messages: ChatMessageInput[] } | null> {
  const checkpointIndex = catalog.lastCommittedMessageId
    ? messages.findIndex((message) => message.id === catalog.lastCommittedMessageId)
    : -1;
  if (catalog.lastCommittedMessageId && checkpointIndex < 0) {
    throw new Error("总结检查点消息已不存在，请修改检查点后再继续。");
  }
  const start = checkpointIndex + 1;
  const minimumEnd = start + messageCount - 1;
  if (minimumEnd >= messages.length) return null;
  // Search forward instead of backward: an automatic batch must never fall
  // below the configured threshold just because the boundary happens to land
  // on an unconfirmed assistant reply. Wait for the next user message instead.
  let end = -1;
  for (let index = minimumEnd; index < messages.length; index += 1) {
    if (messages[index]?.role !== "assistant") continue;
    if (!messages.slice(index + 1).some((message) => message.role === "user")) continue;
    end = index;
    break;
  }
  if (end < start) return null;
  const selected = messages.slice(start, end + 1);
  const batchNumber = catalog.nextBatchNumber;
  return {
    messages: selected,
    batch: {
      id: `summary_batch_${batchNumber}`,
      batchNumber,
      startMessageId: selected[0]!.id,
      endMessageId: selected.at(-1)!.id,
      messageIds: selected.map((message) => message.id),
      sourceHash: await summarySourceHash(selected),
    },
  };
}

export async function manualSummaryBatch(
  messages: ChatMessageInput[],
  catalog: SummaryCatalog,
  startIndex: number,
  endIndex: number,
  existingBatch?: SummarySlice["batch"],
): Promise<{ batch: SummaryBatchInput; messages: ChatMessageInput[] }> {
  if (!Number.isInteger(startIndex) || !Number.isInteger(endIndex) || startIndex < 0 || endIndex < startIndex || endIndex >= messages.length) {
    throw new Error("手动总结消息范围无效。");
  }
  const selected = messages.slice(startIndex, endIndex + 1);
  const maximum = existingBatch ? 50_000 : 500;
  if (selected.length === 0 || selected.length > maximum) throw new Error(`总结范围必须包含 1 至 ${maximum} 条消息。`);
  const batchNumber = existingBatch?.batchNumber ?? catalog.nextBatchNumber;
  return {
    messages: selected,
    batch: {
      id: existingBatch?.id ?? `summary_batch_${batchNumber}`,
      ...(existingBatch?.purpose ? { purpose: existingBatch.purpose } : {}),
      batchNumber,
      startMessageId: selected[0]!.id,
      endMessageId: selected.at(-1)!.id,
      messageIds: selected.map((message) => message.id),
      sourceHash: await summarySourceHash(selected),
    },
  };
}

export function summaryAdvancesCheckpoint(batch: SummaryBatchInput, catalog: SummaryCatalog, messages: ChatMessageInput[]): boolean {
  if (batch.purpose === "supplement") return false;
  const checkpoint = catalog.lastCommittedMessageId
    ? messages.findIndex((message) => message.id === catalog.lastCommittedMessageId) : -1;
  if (catalog.lastCommittedMessageId && checkpoint < 0) return false;
  const start = messages.findIndex((message) => message.id === batch.startMessageId);
  const end = messages.findIndex((message) => message.id === batch.endMessageId);
  return start >= 0 && start <= checkpoint + 1 && end > checkpoint;
}

export async function prepareBatchOverviewPrompt(
  messages: ChatMessageInput[], settings: EchoesSettings,
): Promise<PromptMessageInput[]> {
  const cleanedMessages = await preprocessSummaryMessages(messages, settings.summary.preprocessRules);
  if (cleanedMessages.length === 0) throw new Error("消息清洗后没有可生成批次总结的内容。");
  const { character, charName } = promptIdentity();
  const background = [characterCardContent(character, charName),
    await summaryWorldbookContent(cleanedMessages)].filter(Boolean).join("\n\n");
  const result: PromptMessageInput[] = [{ role: "system", content: settings.summary.batchOverviewPrompt }];
  const append = (content: string) => {
    // Split protocol fields, not story coverage: every character remains in the same provider request.
    for (let start = 0; start < content.length; start += 180_000) {
      result.push({ role: "user", content: content.slice(start, start + 180_000) });
    }
  };
  append(`<background>\n${background}\n</background>`);
  append(`<target_messages>\n${cleanedMessages.map((message) =>
    `[${message.id}] ${message.role === "user" ? "主持人" : charName}:\n${message.content}`
  ).join("\n\n")}\n</target_messages>`);
  return result;
}

function renderPreviousSlice(slice: SummarySlice): string {
  return `[${slice.timestamp}] [${slice.title}]\n${slice.content}${slice.continuity ? "\n时间与认知属性：" + JSON.stringify(slice.continuity) : ""}`;
}

function previousSummaryContent(
  item: Extract<SummaryPromptItem, { kind: "previous_summaries" }>,
  slices: SummarySlice[],
): string {
  if (item.count === 0) return "";
  if ((item.unit ?? "slices") === "slices") {
    return slices.slice(-item.count).map(renderPreviousSlice).join("\n\n");
  }
  const batchIds = [...new Map(slices.map((slice) => [slice.batch.id, slice.batch])).values()]
    .sort(createBatchOrder(currentChatMessages()).compare)
    .slice(-item.count)
    .map((batch) => batch.id);
  const selected = new Set(batchIds);
  const grouped = new Map<string, SummarySlice[]>();
  for (const slice of slices) {
    if (!selected.has(slice.batch.id)) continue;
    const batch = grouped.get(slice.batch.id) ?? [];
    batch.push(slice);
    grouped.set(slice.batch.id, batch);
  }
  return [...grouped.values()].map((batch) => {
    const ordered = [...batch].sort((left, right) => left.sliceNumber - right.sliceNumber);
    return `[已有总结 第 ${ordered[0]!.batch.batchNumber} 批]\n${ordered.map(renderPreviousSlice).join("\n\n")}`;
  }).join("\n\n");
}

async function dynamicContent(
  item: SummaryPromptItem,
  cleanedMessages: ChatMessageInput[],
  previousSlices: SummarySlice[],
): Promise<string> {
  const { character, charName, userName, personaDescription } = promptIdentity();
  if (item.kind === "custom") return applyPromptMacros(item.content, charName, userName);
  if (item.kind === "character") return wrapPromptContent("character", characterCardContent(character, charName));
  if (item.kind === "worldbook") return wrapPromptContent("worldbook", await summaryWorldbookContent(cleanedMessages));
  if (item.kind === "persona") {
    const description = personaDescription.trim();
    return wrapPromptContent("persona", description ? `${userName}:\n${description}` : "");
  }
  if (item.kind === "previous_summaries") return wrapPromptContent("previous_summaries", previousSummaryContent(item, previousSlices));
  return wrapPromptContent("recent_messages", cleanedMessages.map((message) => {
    const name = message.role === "user" ? "主持人" : charName;
    return `[${message.id}] ${name}: ${message.content}`;
  }).join("\n\n"));
}

export async function prepareSummaryRequest(options: {
  batch: SummaryBatchInput;
  messages: ChatMessageInput[];
  state: SummaryWorldbookState;
  settings: EchoesSettings;
  cleanedMessages?: ChatMessageInput[];
}): Promise<PreparedSummaryRequest> {
  const cleanedMessages = options.cleanedMessages ?? await preprocessSummaryMessages(options.messages, options.settings.summary.preprocessRules);
  if (cleanedMessages.length === 0) throw new Error("消息清洗后没有可总结内容。");
  if (!options.settings.summary.promptPreset.items.some((item) => item.enabled && item.kind === "messages")) {
    throw new Error("总结预设至少需要一个启用的待总结消息项。");
  }
  const messages = currentChatMessages();
  const order = createBatchOrder(messages);
  const start = order.start(options.batch);
  const previousSlices = options.state.slices.filter((slice) =>
    slice.batch.id !== options.batch.id && slice.batch.state !== "stale"
    && slice.batch.source?.kind !== "imported"
    && (start === null ? false : (() => {
      const index = order.start(slice.batch);
      return index !== null && index + slice.batch.messageIds.length <= start;
    })())).sort((a, b) => order.compare(a.batch, b.batch) || a.sliceNumber - b.sliceNumber);
  const promptBlocks: SummaryPromptBlock[] = [];
  for (const item of options.settings.summary.promptPreset.items) {
    if (!item.enabled) continue;
    const content = (await dynamicContent(item, cleanedMessages, previousSlices)).trim();
    if (content) promptBlocks.push({ id: item.id, title: item.title, role: item.role, content });
  }
  return {
    batch: options.batch,
    originalMessages: structuredClone(options.messages),
    cleanedMessages,
    promptBlocks,
    promptMessages: promptBlocks.map(({ role, content }) => ({ role, content })),
  };
}

export async function prepareSummarySubRequests(options: {
  batch: SummaryBatchInput; messages: ChatMessageInput[]; state: SummaryWorldbookState; settings: EchoesSettings;
}): Promise<PreparedSummaryRequest[]> {
  const cleaned = await preprocessSummaryMessages(options.messages, options.settings.summary.preprocessRules);
  const parts = splitSummaryMessages(cleaned, options.settings.summary.batching);
  if (parts.length === 1 && options.messages.length <= 500) return [await prepareSummaryRequest({ ...options, cleanedMessages: cleaned })];
  const prepared: PreparedSummaryRequest[] = [];
  for (const [index, part] of parts.entries()) {
    const batch: SummaryBatchInput = {
      ...options.batch, id: `${options.batch.id.slice(0, 68)}_part_${index + 1}`,
      messageIds: part.messages.map((message) => message.id),
      startMessageId: part.messages[0]!.id, endMessageId: part.messages.at(-1)!.id,
      sourceHash: await summarySourceHash(part.messages),
    };
    const request = await prepareSummaryRequest({ ...options, batch, messages: part.messages, cleanedMessages: part.messages });
    const guide = {
      role: "system" as const,
      content: summarySubRequestGuide(index + 1, parts.length, part.overlap),
    };
    request.promptMessages.unshift(guide);
    request.ranges = part.ranges;
    prepared.push(request);
  }
  return prepared;
}

export async function firstStaleBatchNumber(
  state: SummaryWorldbookState,
  messages: ChatMessageInput[],
): Promise<number | null> {
  return (await staleSummaryBatches(state, messages)).find((batch) => batch.purpose !== "supplement")?.batchNumber ?? null;
}

export async function staleSummaryBatches(
  state: SummaryWorldbookState, messages: ChatMessageInput[], signal?: AbortSignal,
): Promise<SummarySlice["batch"][]> {
  const byId = new Map(messages.map((message) => [message.id, message]));
  const stale: SummarySlice["batch"][] = [];
  const batches = [...new Map(state.slices.map((slice) => [slice.batch.id, slice.batch])).values()]
    .sort(createBatchOrder(messages).compare);
  for (const batch of batches) {
    signal?.throwIfAborted();
    if (batch.source?.kind === "imported") continue;
    if (batch.state === "stale") { stale.push(batch); continue; }
    const current = batch.messageIds.map((id) => byId.get(id));
    const start = messages.findIndex((message) => message.id === batch.startMessageId);
    if (start < 0 || current.some((message) => !message)
      || messages.slice(start, start + batch.messageIds.length).map((message) => message.id).join("\0") !== batch.messageIds.join("\0")
      || await summarySourceHash(current as ChatMessageInput[]) !== batch.sourceHash) stale.push(batch);
  }
  return stale;
}
