import { h } from "../../kit/dom";

/**
 * Searchable list of the models an endpoint reported. Picking one fills the model input;
 * the input stays free text, so a model ID that isn't listed can still be typed by hand.
 */
export function modelCatalog(model: HTMLInputElement, locked: boolean) {
  let models: string[] = [];
  const filter = h("input", "ec-input ec-search");
  filter.type = "search";
  filter.placeholder = "筛选模型";
  filter.setAttribute("aria-label", "筛选已获取的模型");
  const count = h("span", "ec-muted");
  const list = h("div", "ec-model-list");
  list.setAttribute("role", "listbox");
  list.setAttribute("aria-label", "已获取的模型");
  const node = h("div", "ec-model-catalog", h("div", "ec-row", filter, count), list);
  node.hidden = true;

  const draw = () => {
    const query = filter.value.trim().toLocaleLowerCase();
    const shown = query ? models.filter((name) => name.toLocaleLowerCase().includes(query)) : models;
    count.textContent = query ? `${shown.length} / ${models.length} 个模型` : `${models.length} 个模型`;
    list.replaceChildren(...(shown.length ? shown.map((name) => {
      const option = h("button", "ec-model-option", name);
      option.type = "button";
      option.title = name;
      option.setAttribute("role", "option");
      option.setAttribute("aria-selected", String(name === model.value));
      option.disabled = locked;
      option.addEventListener("click", () => {
        model.value = name;
        model.dispatchEvent(new Event("input", { bubbles: true }));
        sync();
      });
      return option;
    }) : [h("p", "ec-muted", "没有匹配的模型；可以直接在“模型”中手动填写。")]));
  };
  const sync = () => {
    for (const option of list.querySelectorAll<HTMLElement>(".ec-model-option"))
      option.setAttribute("aria-selected", String(option.textContent === model.value));
  };
  filter.addEventListener("input", draw);
  filter.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowDown") return;
    event.preventDefault();
    list.querySelector<HTMLButtonElement>(".ec-model-option:not(:disabled)")?.focus();
  });
  list.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return;
    event.preventDefault();
    const options = [...list.querySelectorAll<HTMLButtonElement>(".ec-model-option")];
    const index = options.indexOf(document.activeElement as HTMLButtonElement);
    const next = options[index + (event.key === "ArrowDown" ? 1 : -1)];
    if (next) next.focus();
    else if (event.key === "ArrowUp") filter.focus();
  });
  model.addEventListener("input", sync);

  return {
    node,
    fill(next: string[]) {
      models = next;
      filter.value = "";
      node.hidden = false;
      draw();
    },
    clear() {
      models = [];
      node.hidden = true;
      list.replaceChildren();
    },
  };
}
