import type { SummarySlice } from "../../../../shared/domain";
import { checkpointFloor } from "../../../chat-message-index";
import { h, fill, icon } from "../../kit/dom";
import { button, badge, menu, selectControl } from "../../kit/controls";
import { empty } from "../../kit/layout";
import { list, paginate, pager, searchBox, checkbox, keepSearchFocus } from "../../kit/data";
import { drawer } from "../../kit/drawer";
import type { PageContext } from "../../shell/context";
import { stateBadge } from "../shared";
import { BATCH_ACTIONS, runBatchAction } from "./batch-actions";
import { bulkOverviews, openBatchOverview, overviewLabel } from "./overview-dialogs";
import { showSlice } from "./slice-detail";
import { assignFlags } from "./slice-tools";

interface RecordsState { query: string; status: string; page: number; selected: Set<string>; expanded: Set<string>; open: string | null }

export async function summaryRecordsPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const ui = ctx.memo<RecordsState>("summary-records", () => ({ query: "", status: "all", page: 0, selected: new Set(), expanded: new Set(), open: null }));
  const known = new Set(state.slices.map((slice) => slice.id));
  for (const id of ui.selected) if (!known.has(id)) ui.selected.delete(id);
  let visibility = new Map<string, { hidden: number; covered: number; pinned: number }>();
  let visibilityError = "";
  try {
    visibility = new Map((await ctx.summary.compression.inspectVisibility(state)).map((item) => [item.batchId, item]));
  } catch (error) {
    visibilityError = error instanceof Error ? error.message : String(error);
  }
  const byBatch = new Map<string, SummarySlice[]>();
  for (const slice of state.slices) byBatch.set(slice.batch.id, [...(byBatch.get(slice.batch.id) ?? []), slice]);
  const groups = [...byBatch.values()].sort((a, b) => b[0]!.batch.batchNumber - a[0]!.batch.batchNumber);
  const overviews = new Map(state.batchOverviews?.map((item) => [item.batch.id, item]));
  const pane = drawer("切片详情");
  pane.onChange((key) => { ui.open = key; draw(); });
  const host = h("div", "ec-stack");
  const matches = (slice: SummarySlice) => (ui.status === "all" || slice.batch.state === ui.status)
    && (!ui.query || [slice.title, slice.content, slice.timestamp, ...slice.tags].join(" ").toLocaleLowerCase().includes(ui.query.toLocaleLowerCase()));
  const act = async (action: Parameters<typeof runBatchAction>[2], slices: SummarySlice[]) => {
    if (!await runBatchAction(ctx, state, action, slices)) return;
    if (action === "delete" || action === "reset") ui.selected.clear();
    await ctx.refresh();
  };

  const batchHead = (slices: SummarySlice[], all: SummarySlice[]) => {
    const batch = all[0]!.batch;
    const seen = visibility.get(batch.id);
    const open = ui.expanded.has(batch.id) || Boolean(ui.query);
    const toggle = h("button", "ec-batch-toggle", icon(open ? "chevron-down" : "chevron-right"), h("strong", "", `批次 ${batch.batchNumber}`));
    toggle.type = "button";
    toggle.setAttribute("aria-expanded", String(open));
    toggle.addEventListener("click", () => { ui.expanded.has(batch.id) ? ui.expanded.delete(batch.id) : ui.expanded.add(batch.id); draw(); });
    const [label, tone] = overviewLabel(overviews.get(batch.id));
    const ready = all.filter((slice) => slice.batch.state === "ready").length;
    const range = batch.source?.kind === "imported" ? "导入批次" : `第 ${checkpointFloor(batch.startMessageId)}–${checkpointFloor(batch.endMessageId)} 楼`;
    const overview = h("button", "ec-badge-button", badge(label, tone));
    overview.type = "button";
    overview.title = "查看批次总结";
    overview.addEventListener("click", () => openBatchOverview(ctx, state, batch));
    return h("div", "ec-batch-head",
      checkbox(`选择批次 ${batch.batchNumber}`, slices.every((slice) => ui.selected.has(slice.id)), (value) => {
        slices.forEach((slice) => value ? ui.selected.add(slice.id) : ui.selected.delete(slice.id));
        draw();
      }),
      toggle,
      h("span", "ec-batch-meta", `${range} · ${all.length} 切片 · 向量 ${ready}/${all.length} · `,
        seen ? `隐藏 ${seen.hidden}/${seen.covered}${seen.pinned ? `（固定可见 ${seen.pinned}）` : ""}` : visibilityError ? "隐藏状态读取失败" : "隐藏状态不可用"),
      batch.state === "stale" ? badge("源消息已变化", "warning") : null,
      overview,
      menu(`批次 ${batch.batchNumber} 的操作`, [
        { label: "批次总结", icon: "file-lines", onSelect: () => openBatchOverview(ctx, state, batch) },
        { label: "重新总结", icon: "rotate", onSelect: () => act("rebuild", all) },
        { label: "恢复原消息", icon: "eye", onSelect: () => act("restore", all) },
        { label: "重新隐藏", icon: "eye-slash", onSelect: () => act("hide", all) },
        { label: "检查覆盖", icon: "magnifying-glass", onSelect: () => {
          ctx.forget("summary-coverage-range");
          ctx.memo("summary-coverage-range", () => ({ start: checkpointFloor(batch.startMessageId), end: checkpointFloor(batch.endMessageId), instructions: "" }));
          ctx.navigate("summary/coverage");
        } },
        { label: "从此批次重置", icon: "rotate-left", danger: true, onSelect: () => act("reset", all) },
      ]));
  };

  const draw = () => keepSearchFocus(host, () => {
    const visible = groups.map((slices) => slices.filter(matches)).filter((slices) => slices.length);
    const page = paginate(visible, ui, 20);
    const selected = state.slices.filter((slice) => ui.selected.has(slice.id));
    fill(host,
      h("div", "ec-toolbar",
        h("div", "ec-row", searchBox(ui.query, (value) => { ui.query = value; ui.page = 0; draw(); }, "搜索标题、正文、时间或标签", ctx.signal),
          selectControl("向量状态", [["all", "全部状态"], ["ready", "向量就绪"], ["pending", "待同步"], ["failed", "失败"], ["ambiguous", "待确认"], ["stale", "源消息已变化"]],
            ui.status, (value) => { ui.status = value; ui.page = 0; draw(); })),
        h("div", "ec-row ec-toolbar-end",
          button("修复索引", async () => {
            await ctx.run("修复总结索引", () => ctx.summary.repairIndex(), () => ctx.summary.stop());
            await ctx.refresh();
          }, { variant: "ghost", small: true, icon: "screwdriver-wrench" }),
          button("批量生成批次总结", () => bulkOverviews(ctx, state, state.slices), { variant: "ghost", small: true, icon: "file-lines" }),
          button("生成总结", () => ctx.navigate("summary/generation"), { variant: "primary", icon: "plus" }))),
      selected.length ? h("div", "ec-selection",
        h("strong", "", `已选 ${selected.length} 个切片 · ${new Set(selected.map((slice) => slice.batch.id)).size} 个批次`),
        button("批次总结", () => bulkOverviews(ctx, state, selected), { small: true, icon: "file-lines" }),
        button("设置标志", () => assignFlags(ctx, state, selected), { small: true, icon: "flag" }),
        menu("批量操作", BATCH_ACTIONS.map((item) => ({ label: item.label, icon: item.icon, danger: item.danger, onSelect: () => act(item.action, selected) })), "list-check"),
        button("取消选择", () => { ui.selected.clear(); draw(); }, { variant: "ghost", small: true })) : null,
      visible.length ? h("div", "ec-batches", ...page.items.map((slices) => {
        const all = byBatch.get(slices[0]!.batch.id)!;
        const open = ui.expanded.has(slices[0]!.batch.id) || Boolean(ui.query);
        return h("section", "ec-batch", batchHead(slices, all), open ? list(slices.map((slice) => ({
          key: slice.id, selected: ui.open === slice.id,
          leading: checkbox(`选择切片 ${slice.sliceNumber}`, ui.selected.has(slice.id), (value) => {
            value ? ui.selected.add(slice.id) : ui.selected.delete(slice.id);
            draw();
          }),
          title: `${slice.batch.batchNumber}.${slice.sliceNumber}  ${slice.title}`,
          meta: slice.timestamp, trailing: stateBadge(slice.batch.state),
          onOpen: () => showSlice(ctx, pane, state, slice),
        }))) : null);
      })) : empty(ui.query || ui.status !== "all" ? "没有匹配的总结" : "还没有总结记录。",
        ui.query ? null : button("生成总结", () => ctx.navigate("summary/generation"), { icon: "plus" })),
      page.pages > 1 ? pager(ui, page.pages, visible.length, draw, "批") : null,
    );
  });
  pane.list.append(host);
  draw();
  const open = state.slices.find((slice) => slice.id === ui.open);
  if (open) await showSlice(ctx, pane, state, open);
  else ui.open = null;
  return pane.node;
}
