import { sha256Hex } from "./crypto-compat";
import type {
  ChatMessageInput,
  MemoryRow,
  MemoryTypeDefinition,
} from "./domain";

function canonical(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record).sort().map((key) =>
    `${JSON.stringify(key)}:${canonical(record[key])}`).join(",")}}`;
}

async function sha256(value: unknown): Promise<string> {
  return sha256Hex(canonical(value));
}

export function structuredExtractionMessageHash(messages: ChatMessageInput[]): Promise<string> {
  return sha256(messages.map(({ id, role, content }) => ({ id, role, content })));
}

export function structuredExtractionContextHash(
  types: MemoryTypeDefinition[],
  rows: MemoryRow[],
): Promise<string> {
  return sha256({
    types: [...types].sort((left, right) => left.id.localeCompare(right.id)).map((type) => ({
      id: type.id,
      templateId: type.templateId,
      name: type.name,
      description: type.description,
      columns: type.columns,
      guide: type.guide,
      defaultStatus: type.defaultStatus,
      enabled: type.enabled,
      version: type.version,
    })),
    rows: [...rows].sort((left, right) => left.id.localeCompare(right.id)).map((row) => ({
      id: row.id,
      typeId: row.typeId,
      dataName: row.dataName,
      keywords: row.keywords,
      status: row.status,
      values: row.values,
      ...(row.aliases ? { aliases: row.aliases } : {}),
      ...(row.continuity ? { continuity: row.continuity } : {}),
      enabled: row.enabled,
      revision: row.revision,
    })),
  });
}
