const CATALOG_ENTRY_NAME = "[Echoes] 结构化长期记忆配置";
const CATALOG_CONTENT = "Echoes structured-memory metadata. This disabled entry is managed by the plugin.";

interface CatalogMetadata {
  kind: "catalog";
  formatVersion: 2;
  catalog: StructuredMemoryCatalog;
}

interface RowMetadata {
  keywords?: string[];
  aliases?: string[] | undefined;
  continuity?: MemoryRow["continuity"];
  kind: "row";
  formatVersion: 1;
  rowId: string;
  typeId: string;
  source: MemoryRow["source"];
  revision: number;
  createdAt: string;
  updatedAt: string;
}

type EchoesMetadata = CatalogMetadata | RowMetadata;

export interface WorldbookMemoryState {
  worldbookName: string;
  catalog: StructuredMemoryCatalog;
  rows: MemoryRow[];
  issues: string[];
}

export interface ApplySummary {
  added: number;
  updated: number;
  deleted: number;
}

export type MigrationPolicy = MemoryImportPolicy;

function uniqueId(prefix: string): string {
  return `${prefix}_${randomUuid().replaceAll("-", "")}`;
}

function requiredHelper(): TavernHelperApi {
  if (!window.TavernHelper) {
    throw new Error("Echoes requires TavernHelper to read and write SillyTavern worldbooks.");
  }
  return window.TavernHelper;
}

function echoesMetadata(entry: TavernWorldbookEntry): EchoesMetadata | null {
  const metadata = entry.extra?.echoes;
  if (!metadata || typeof metadata !== "object") return null;
  if (metadata.kind !== "catalog" && metadata.kind !== "row") return null;
  return metadata as EchoesMetadata;
}

function catalogFromEntries(entries: TavernWorldbookEntry[]): {
  entry: TavernWorldbookEntry;
  catalog: StructuredMemoryCatalog;
} {
  const entry = entries.find((candidate) => echoesMetadata(candidate)?.kind === "catalog");
  if (!entry) throw new Error("The current worldbook has no Echoes memory catalog.");
  const metadata = echoesMetadata(entry) as CatalogMetadata;
  return {
    entry,
    catalog: structuredMemoryCatalogSchema.parse(metadata.catalog),
  };
}

function keywordsFromEntry(entry: TavernWorldbookEntry): string[] {
  return entry.strategy.keys.map((key) => String(key)).filter(Boolean);
}

function statusFromEntry(entry: TavernWorldbookEntry): MemoryEntryStatus {
  if (entry.strategy?.type === "constant") return "permanent";
  if (entry.strategy?.type === "vectorized") return "vectorized";
  return "keyword";
}

function strategyType(status: MemoryEntryStatus): "constant" | "selective" | "vectorized" {
  if (status === "permanent") return "constant";
  if (status === "vectorized") return "vectorized";
  return "selective";
}

function rowFromEntry(
  entry: TavernWorldbookEntry,
  type: MemoryTypeDefinition,
): MemoryRow {
  const metadata = echoesMetadata(entry);
  if (!metadata || metadata.kind !== "row") throw new Error("Entry is not an Echoes memory row.");
  const decoded = decodeMemoryContent(type, entry.content);
  return {
    id: metadata.rowId,
    typeId: metadata.typeId,
    dataName: decoded.dataName,
    keywords: keywordsFromEntry(entry).filter((key) => !(metadata.aliases ?? []).includes(key)
      || metadata.keywords?.includes(key)),
    status: statusFromEntry(entry),
    values: decoded.values,
    enabled: entry.enabled,
    worldbookUid: entry.uid,
    source: structuredClone(metadata.source),
    revision: metadata.revision,
    createdAt: metadata.createdAt,
    updatedAt: metadata.updatedAt,
    ...(metadata.aliases ? { aliases: aliasSchema.parse(metadata.aliases) } : {}),
    ...(metadata.continuity ? { continuity: continuitySchema.parse(metadata.continuity) } : {}),
  };
}

function updateCatalogEntry(
  entry: TavernWorldbookEntry,
  catalog: StructuredMemoryCatalog,
): void {
  entry.name = CATALOG_ENTRY_NAME;
  entry.enabled = false;
  entry.content = CATALOG_CONTENT;
  entry.strategy = { ...entry.strategy, type: "constant", keys: [] };
  entry.extra = {
    ...(entry.extra ?? {}),
    echoes: {
      kind: "catalog",
      formatVersion: 2,
      catalog: structuredClone(catalog),
    } satisfies CatalogMetadata,
  };
}

function catalogEntry(catalog: StructuredMemoryCatalog): Partial<TavernWorldbookEntry> {
  return {
    name: CATALOG_ENTRY_NAME,
    enabled: false,
    strategy: { type: "constant", keys: [] },
    position: { type: "after_character_definition", role: "system", depth: 4, order: 10 },
    content: CATALOG_CONTENT,
    probability: 100,
    extra: {
      echoes: {
        kind: "catalog",
        formatVersion: 2,
        catalog: structuredClone(catalog),
      } satisfies CatalogMetadata,
    },
  };
}

function rowEntry(
  type: MemoryTypeDefinition,
  row: MemoryRow,
): Partial<TavernWorldbookEntry> {
  const keys = [...new Set([...row.keywords, ...(row.aliases ?? [])])];
  const annotations = renderContinuity(row.continuity);
  return {
    name: `${type.name}-${row.dataName}`,
    enabled: type.enabled && currentFact(row.continuity),
    strategy: {
      type: strategyType(row.status),
      keys,
      keys_secondary: { logic: "and_any", keys: [] },
      scan_depth: "same_as_global",
    },
    position: { type: "after_character_definition", role: "system", depth: 4, order: 100 },
    content: encodeMemoryContent(type, row.dataName, row.values)
      + (annotations ? "\n" + annotations.split("\n").map((line) => `# ${line}`).join("\n") : ""),
    probability: 100,
    recursion: { prevent_incoming: false, prevent_outgoing: false, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    extra: {
      echoes: {
        kind: "row",
        formatVersion: 1,
        rowId: row.id,
        typeId: row.typeId,
        source: structuredClone(row.source),
        revision: row.revision,
        createdAt: row.createdAt,
        updatedAt: row.updatedAt,
        keywords: [...row.keywords],
        ...(row.aliases ? { aliases: row.aliases } : {}),
        ...(row.continuity ? { continuity: row.continuity } : {}),
      } satisfies RowMetadata,
    },
  };
}

function applyRowToEntry(
  entry: TavernWorldbookEntry,
  type: MemoryTypeDefinition,
  row: MemoryRow,
): void {
  const replacement = rowEntry(type, row);
  entry.name = replacement.name!;
  entry.enabled = replacement.enabled!;
  entry.strategy = { ...entry.strategy, ...replacement.strategy! };
  entry.content = replacement.content!;
  entry.extra = {
    ...(entry.extra ?? {}),
    ...(replacement.extra ?? {}),
  };
}

function uniqueDataName(
  rows: MemoryRow[],
  typeId: string,
  dataName: string,
  exceptRowId?: string,
): boolean {
  const normalized = dataName.trim().toLocaleLowerCase();
  return !rows.some(
    (row) => row.typeId === typeId
      && row.id !== exceptRowId
      && row.dataName.trim().toLocaleLowerCase() === normalized,
  );
}

function validateAliases(rows: MemoryRow[], row: Pick<MemoryRow, "id" | "typeId" | "dataName" | "aliases">): void {
  const normalize = (name: string) => name.trim().toLocaleLowerCase();
  const names = new Set([row.dataName, ...(row.aliases ?? [])].map(normalize));
  const conflict = rows.find((other) => other.id !== row.id && other.typeId === row.typeId
    && [other.dataName, ...(other.aliases ?? [])].some((name) => names.has(normalize(name))));
  if (conflict) throw new Error(`名称或别名与同表条目「${conflict.dataName}」冲突，请使用可区分的名称；不会自动合并。`);
}

function applyOperationsToEntries(
  entries: TavernWorldbookEntry[],
  catalog: StructuredMemoryCatalog,
  operations: MemoryExtractionOperation[],
  sourceBase: MemoryRow["source"],
): ApplySummary {
  const summary: ApplySummary = { added: 0, updated: 0, deleted: 0 };
  const typeById = new Map(catalog.types.filter((type) => type.enabled).map((type) => [type.id, type]));
  const rows: MemoryRow[] = [];
  const entryByRowId = new Map<string, TavernWorldbookEntry>();
  for (const entry of entries) {
    const metadata = echoesMetadata(entry);
    if (metadata?.kind !== "row") continue;
    const type = typeById.get(metadata.typeId);
    if (!type) continue;
    const row = rowFromEntry(entry, type);
    rows.push(row);
    entryByRowId.set(row.id, entry);
  }

  const initialRows = [...rows];
  const deletedRowIds = new Set(sourceBase.extractionMode === "cleaning"
    ? operations.flatMap((operation) => operation.action === "delete"
      && rows.some((row) => row.id === operation.rowId && row.typeId === operation.typeId)
      ? [operation.rowId] : [])
    : []);
  for (const operation of operations) {
    const type = typeById.get(operation.typeId);
    if (!type) throw new Error(`Operation references an inactive type: ${operation.typeId}`);
    const now = new Date().toISOString();
    const source = structuredClone(sourceBase);
    const identityRows = deletedRowIds.size ? rows.filter((row) => !deletedRowIds.has(row.id)) : rows;
    if (operation.action === "add") {
      if (!uniqueDataName(identityRows, type.id, operation.dataName)) {
        throw new Error(`Duplicate data name in ${type.name}: ${operation.dataName}`);
      }
      const row: MemoryRow = {
        ...(operation.aliases ? { aliases: aliasSchema.parse(operation.aliases) } : {}),
        ...(operation.continuity ? { continuity: continuitySchema.parse(operation.continuity) } : {}),
        id: uniqueId("row"),
        typeId: type.id,
        dataName: operation.dataName,
        keywords: operation.keywords,
        status: operation.status,
        values: validateMemoryValues(type.columns, operation.values),
        enabled: true,
        source,
        revision: 1,
        createdAt: now,
        updatedAt: now,
      };
      validateAliases(identityRows, row);
      row.enabled = type.enabled && currentFact(row.continuity);
      rows.push(row);
      entries.push(rowEntry(type, row) as TavernWorldbookEntry);
      summary.added += 1;
      continue;
    }

    const entry = entryByRowId.get(operation.rowId);
    const rowIndex = rows.findIndex((row) => row.id === operation.rowId);
    const current = rowIndex >= 0 ? rows[rowIndex] : undefined;
    if (!entry || !current || current.typeId !== type.id) {
      throw new Error(unavailableExtractionRowReason(operation.rowId, type.id, initialRows, rows));
    }
    if (operation.action === "delete") {
      const entryIndex = entries.indexOf(entry);
      if (entryIndex >= 0) entries.splice(entryIndex, 1);
      rows.splice(rowIndex, 1);
      entryByRowId.delete(operation.rowId);
      summary.deleted += 1;
      continue;
    }

    const dataName = operation.changes.dataName ?? current.dataName;
    if (!uniqueDataName(identityRows, type.id, dataName, current.id)) {
      throw new Error(`Duplicate data name in ${type.name}: ${dataName}`);
    }
    const updated: MemoryRow = {
      ...current,
      ...(operation.changes.aliases ? { aliases: aliasSchema.parse(operation.changes.aliases) } : {}),
      ...(operation.changes.continuity ? { continuity: continuitySchema.parse({ ...current.continuity, ...operation.changes.continuity }) } : {}),
      dataName,
      keywords: operation.changes.keywords ?? current.keywords,
      status: operation.changes.status ?? current.status,
      values: validateMemoryValues(type.columns, {
        ...current.values,
        ...(operation.changes.values ?? {}),
      }),
      enabled: true,
      source,
      revision: current.revision + 1,
      updatedAt: now,
    };
    validateAliases(identityRows, updated);
    updated.enabled = type.enabled && currentFact(updated.continuity);
    rows[rowIndex] = updated;
    applyRowToEntry(entry, type, updated);
    summary.updated += 1;
  }
  return summary;
}

export class WorldbookMemoryStore {
  listWorldbooks(): string[] {
    return requiredHelper().getWorldbookNames();
  }

  async load(): Promise<WorldbookMemoryState> {
    return this.enqueue(async (target) => {
      const { worldbookName, entries } = await this.ensureCurrentCatalog(target);
      return this.stateFromEntries(worldbookName, entries);
    });
  }

  async inspect(worldbookName: string): Promise<WorldbookMemoryState> {
    return this.readWorldbook(worldbookName);
  }

  async saveType(rawInput: MemoryTypeInput, currentId?: string, expectedVersion?: number): Promise<MemoryTypeDefinition> {
    const input = memoryTypeInputSchema.parse(rawInput);
    if (!currentId && !getSettings().typeTemplates.some((template) => template.id === input.templateId)) {
      throw new Error("A new memory type must be based on an existing type template.");
    }

    let savedId = currentId ?? "";
    await this.mutate((entries, catalog) => {
      const now = new Date().toISOString();
      const current = currentId
        ? catalog.types.find((type) => type.id === currentId)
        : undefined;
      if (currentId && !current) throw new Error("Memory type not found.");
      if (expectedVersion !== undefined && current?.version !== expectedVersion) {
        throw new Error("表结构已被修改，请刷新后重新审核。");
      }
      const nameChanged = !current
        || current.name.toLocaleLowerCase() !== input.name.toLocaleLowerCase();
      if (nameChanged && catalog.types.some(
        (type) => type.id !== currentId && type.name.toLocaleLowerCase() === input.name.toLocaleLowerCase(),
      )) {
        throw new Error("A memory type with this name already exists.");
      }

      const saved: MemoryTypeDefinition = {
        ...input,
        id: current?.id ?? input.id ?? uniqueId("type"),
        version: (current?.version ?? 0) + 1,
        createdAt: current?.createdAt ?? now,
        updatedAt: now,
      };
      savedId = saved.id;

      if (current) {
        const oldRows = new Map(entries.flatMap((entry) => {
          const metadata = echoesMetadata(entry);
          return metadata?.kind === "row" && metadata.typeId === current.id
            ? [[entry.uid, rowFromEntry(entry, current)] as const] : [];
        }));
        checkRequiredColumnBackfill(saved.columns, [...oldRows.values()]);
        for (const entry of entries) {
          const oldRow = oldRows.get(entry.uid);
          if (!oldRow) continue;
          const retainedValues = Object.fromEntries(
            Object.entries(oldRow.values).filter(([columnId]) =>
              saved.columns.some((column) => column.id === columnId),
            ),
          );
          const migratedRow: MemoryRow = {
            ...oldRow,
            values: validateMemoryValues(saved.columns, retainedValues),
            enabled: saved.enabled,
            revision: oldRow.revision + 1,
            updatedAt: now,
          };
          applyRowToEntry(entry, saved, migratedRow);
        }
        const index = catalog.types.findIndex((type) => type.id === current.id);
        catalog.types[index] = saved;
      } else {
        catalog.types.push(saved);
      }
    });

    const state = await this.load();
    return state.catalog.types.find((type) => type.id === savedId)!;
  }

  async deleteType(typeId: string): Promise<void> {
    await this.mutate((entries, catalog) => {
      if (!catalog.types.some((type) => type.id === typeId)) throw new Error("Memory type not found.");
      catalog.types = catalog.types.filter((type) => type.id !== typeId);
      for (let index = entries.length - 1; index >= 0; index -= 1) {
        const metadata = echoesMetadata(entries[index]!);
        if (metadata?.kind === "row" && metadata.typeId === typeId) entries.splice(index, 1);
      }
    });
  }

  async setTypeEnabled(typeId: string, enabled: boolean): Promise<void> {
    await this.mutate((entries, catalog) => {
      const type = catalog.types.find((candidate) => candidate.id === typeId);
      if (!type) throw new Error("Memory type not found.");
      type.enabled = enabled;
      type.version += 1;
      type.updatedAt = new Date().toISOString();
      for (const entry of entries) {
        const metadata = echoesMetadata(entry);
        if (metadata?.kind === "row" && metadata.typeId === typeId) entry.enabled = enabled && currentFact(metadata.continuity);
      }
    });
  }

  async saveRow(typeId: string, rawInput: MemoryRowInput, rowId?: string, expectedRevision?: number): Promise<MemoryRow> {
    const input = memoryRowInputSchema.parse(rawInput);
    return this.enqueue(async (target) => {
      const { worldbookName, entries } = await this.ensureCurrentCatalog(target);
      const state = this.stateFromEntries(worldbookName, entries);
      const type = state.catalog.types.find((candidate) => candidate.id === typeId);
      if (!type) throw new Error("Memory type not found.");
      if (!uniqueDataName(state.rows, typeId, input.dataName, rowId)) {
        throw new Error("Data names must be unique within a memory type.");
      }
      const existing = state.rows.find((row) => row.id === rowId);
      if (expectedRevision !== undefined && existing?.revision !== expectedRevision) throw new Error("条目已被修改，请刷新后重新编辑。");
      validateAliases(state.rows, { id: rowId ?? "", typeId, dataName: input.dataName,
        aliases: input.aliases ?? existing?.aliases });
      const values = validateMemoryValues(type.columns, input.values);
      const now = new Date().toISOString();

      if (!rowId) {
        const row: MemoryRow = {
          ...(input.aliases ? { aliases: input.aliases } : {}),
          ...(input.continuity ? { continuity: input.continuity } : {}),
          id: uniqueId("row"),
          typeId,
          dataName: input.dataName,
          keywords: input.keywords,
          status: input.status,
          values,
          enabled: type.enabled && currentFact(input.continuity),
          source: input.source,
          revision: 1,
          createdAt: now,
          updatedAt: now,
        };
        const result = await requiredHelper().createWorldbookEntries(
          worldbookName,
          [rowEntry(type, row)],
          { render: "debounced" },
        );
        const created = result.new_entries[0];
        return { ...row, ...(created ? { worldbookUid: created.uid } : {}) };
      }

      let saved: MemoryRow | null = null;
      await requiredHelper().updateWorldbookWith(worldbookName, (entries) => {
        const before = structuredClone(entries.filter((entry) => entry.extra?.echoes?.kind === "row"));
        const entry = entries.find((candidate) => {
          const metadata = echoesMetadata(candidate);
          return metadata?.kind === "row" && metadata.rowId === rowId;
        });
        if (!entry) throw new Error("Memory row not found.");
        const current = rowFromEntry(entry, type);
        if (expectedRevision !== undefined && current.revision !== expectedRevision) throw new Error("条目已被修改，请刷新后重新编辑。");
        saved = {
          ...current,
          ...(input.aliases ? { aliases: input.aliases } : {}),
          ...(input.continuity ? { continuity: input.continuity } : {}),
          dataName: input.dataName,
          keywords: input.keywords,
          status: input.status,
          values,
          enabled: type.enabled && currentFact(input.continuity ?? current.continuity),
          source: input.source,
          revision: current.revision + 1,
          updatedAt: now,
        };
        applyRowToEntry(entry, type, saved);
        appendMemoryHistory(before, entries);
        return entries;
      }, { render: "debounced" });
      if (!saved) throw new Error("Memory row was not updated.");
      return saved;
    });
  }

  async reclassifyRow(
    expected: MemoryRow, targetTypeId: string, targetVersion: number,
    content: { dataName: string; values: Record<string, unknown> },
  ): Promise<void> {
    await this.mutate((entries, catalog) => {
      const sourceType = catalog.types.find((type) => type.id === expected.typeId);
      const targetType = catalog.types.find((type) => type.id === targetTypeId);
      if (!sourceType || !targetType || targetType.version !== targetVersion) {
        throw new Error("来源表或目标表结构已改变，请重新审核。");
      }
      if (targetType.id === sourceType.id) throw new Error("请选择不同的目标表。");
      const entry = entries.find((item) => item.extra?.echoes?.kind === "row"
        && item.extra.echoes.rowId === expected.id);
      if (!entry || entry.extra?.echoes?.typeId !== sourceType.id) {
        throw new Error("原条目已不存在或已被迁移。");
      }
      const current = rowFromEntry(entry, sourceType);
      if (current.revision !== expected.revision
        || JSON.stringify(current.values) !== JSON.stringify(expected.values)) {
        throw new Error("原条目已被修改，请重新审核。");
      }
      const row: MemoryRow = {
        ...current, typeId: targetType.id, dataName: content.dataName,
        values: validateMemoryValues(targetType.columns, content.values),
        revision: current.revision + 1, updatedAt: new Date().toISOString(),
      };
      const targetRows = entries.filter((item) => item.extra?.echoes?.kind === "row"
        && item.extra.echoes.typeId === targetType.id).map((item) => rowFromEntry(item, targetType));
      validateAliases(targetRows, row);
      applyRowToEntry(entry, targetType, row);
    });
  }

  async deleteRow(rowId: string): Promise<void> {
    await this.mutate((entries) => {
      const index = entries.findIndex((entry) => {
        const metadata = echoesMetadata(entry);
        return metadata?.kind === "row" && metadata.rowId === rowId;
      });
      if (index < 0) throw new Error("Memory row not found.");
      entries.splice(index, 1);
    });
  }

  async deleteRows(rowIds: string[]): Promise<number> {
    const targets = new Set(rowIds);
    if (targets.size === 0) return 0;
    let deleted = 0;
    await this.mutate((entries) => {
      for (let index = entries.length - 1; index >= 0; index -= 1) {
        const metadata = echoesMetadata(entries[index]!);
        if (metadata?.kind !== "row" || !targets.has(metadata.rowId)) continue;
        entries.splice(index, 1);
        deleted += 1;
      }
      if (deleted === 0) throw new Error("No matching memory rows were found.");
    }, "删除结构化条目");
    return deleted;
  }

  async savePromptPreset(preset: PromptPreset): Promise<void> {
    const parsed = promptPresetSchema.parse(preset);
    await this.mutate((_entries, catalog) => {
      catalog.promptPreset = { ...structuredClone(parsed), updatedAt: new Date().toISOString() };
    });
  }

  async saveCreativePreferences(value: NonNullable<StructuredMemoryCatalog["creativePreferences"]>,
    expected: StructuredMemoryCatalog["creativePreferences"]): Promise<void> {
    await this.mutate((_entries, catalog) => {
      if (JSON.stringify(catalog.creativePreferences) !== JSON.stringify(expected))
        throw new Error("创作偏好已被其他操作修改，请刷新后重新审核。");
      catalog.creativePreferences = structuredClone(value);
    });
  }

  async setCheckpoint(messageId: string): Promise<void> {
    await this.mutate((_entries, catalog) => {
      catalog.lastProcessedMessageId = messageId;
    });
  }

  async setAutomationEnabled(enabled: boolean): Promise<void> {
    await this.mutate((_entries, catalog) => {
      catalog.automation.enabled = enabled;
    });
  }

  async relocateCheckpoint(messageId: string | null): Promise<void> {
    await this.mutate((_entries, catalog) => {
      catalog.automation.enabled = false;
      if (messageId === null) delete catalog.lastProcessedMessageId;
      else catalog.lastProcessedMessageId = messageId;
    });
  }

  async commitExtractionBatch(options: {
    worldbookName: string;
    chatId: string;
    batch: StructuredExtractionBatch;
    expectedCheckpoint: string | null;
    operations: MemoryExtractionOperation[];
    jobId: string;
    signal?: AbortSignal;
  }): Promise<ApplySummary> {
    return worldbookWriteCoordinator.run(options.worldbookName, async () => {
      let committed: ApplySummary | null = null;
      let undoId: string | undefined;
      const written = await requiredHelper().updateWorldbookWith(options.worldbookName, async (entries) => {
        const beforeAll = options.batch.mode === "cleaning" ? structuredClone(entries) : undefined;
        const before = structuredClone(entries.filter((entry) => entry.extra?.echoes?.kind === "row"));
        const { entry: catalogEntryValue, catalog } = catalogFromEntries(entries);
        if (catalog.chatId !== options.chatId) {
          throw new Error("The locked worldbook no longer belongs to the extraction chat.");
        }
        if ((catalog.lastProcessedMessageId ?? null) !== options.expectedCheckpoint) {
          throw new Error("The structured-memory checkpoint changed while extraction was running.");
        }
        const state = this.stateFromEntries(options.worldbookName, entries);
        const types = state.catalog.types.filter((type) => type.enabled);
        const typeIds = new Set(types.map((type) => type.id));
        const rows = state.rows.filter((row) => typeIds.has(row.typeId));
        if (await structuredExtractionContextHash(types, rows) !== options.batch.contextHash) {
          throw new Error("Structured-memory types or rows changed while extraction was running.");
        }
        options.signal?.throwIfAborted();
        committed = applyOperationsToEntries(entries, catalog, options.operations, {
          kind: "extraction",
          messageIds: [...options.batch.messageIds],
          jobId: options.jobId,
          batchId: options.batch.id,
          extractionMode: options.batch.mode,
        });
        if (options.batch.mode !== "cleaning") catalog.lastProcessedMessageId = options.batch.endMessageId;
        catalog.updatedAt = new Date().toISOString();
        updateCatalogEntry(catalogEntryValue, catalog);
        structuredMemoryCatalogSchema.parse(catalog);
        appendMemoryHistory(before, entries);
        if (beforeAll) undoId = await recordMemoryUndo(options.worldbookName, "structured", "应用记忆清洗", beforeAll, entries);
        return entries;
      }, { render: "debounced" });
      if (!committed) throw new Error("The extraction batch was not committed.");
      await completeMemoryUndo(options.worldbookName, options.chatId, undoId, written);
      return committed;
    });
  }

  async applyOperations(
    operations: MemoryExtractionOperation[],
    jobId: string,
  ): Promise<ApplySummary> {
    return this.enqueue(async (target) => {
      const { worldbookName } = await this.ensureCurrentCatalog(target);
      let summary: ApplySummary = { added: 0, updated: 0, deleted: 0 };
      await requiredHelper().updateWorldbookWith(worldbookName, (entries) => {
        const before = structuredClone(entries.filter((entry) => entry.extra?.echoes?.kind === "row"));
        const { catalog } = catalogFromEntries(entries);
        summary = applyOperationsToEntries(entries, catalog, operations, {
          kind: "extraction",
          messageIds: [],
          jobId,
        });
        appendMemoryHistory(before, entries);
        return entries;
      }, { render: "debounced" });

      return summary;
    });
  }

  async migrateFrom(
    sourceWorldbookName: string,
    selectedTypeIds: string[],
    policy: MigrationPolicy,
  ): Promise<ApplySummary> {
    return this.enqueue(async (target) => {
      const source = await this.inspect(sourceWorldbookName);
      const { worldbookName: targetWorldbookName } = await this.ensureCurrentCatalog(target);
      if (sourceWorldbookName === targetWorldbookName) {
        throw new Error("The source and target worldbooks are the same.");
      }
      return this.importIntoWorldbook(targetWorldbookName,
        source.catalog.types.filter((type) => selectedTypeIds.includes(type.id)).map((type) => ({
          type, rows: source.rows.filter((row) => row.typeId === type.id),
        })), policy);
    });
  }

  async importTables(tables: MemoryTableTransfer[], policy: MigrationPolicy): Promise<ApplySummary> {
    return this.enqueue(async (target) => {
      const { worldbookName } = await this.ensureCurrentCatalog(target);
      const now = new Date().toISOString();
      return this.importIntoWorldbook(worldbookName, tables.map(({ type, rows }) => ({
        type: { ...type, version: 1, createdAt: now, updatedAt: now }, rows: rows ?? [],
      })), policy);
    });
  }

  private async importIntoWorldbook(
    worldbookName: string,
    tables: Array<{ type: MemoryTypeDefinition; rows: MemoryRowTransfer[] }>,
    policy: MigrationPolicy,
  ): Promise<ApplySummary> {
    const summary: ApplySummary = { added: 0, updated: 0, deleted: 0 };
    await requiredHelper().updateWorldbookWith(worldbookName, (entries) => {
      const before = structuredClone(entries.filter((entry) => entry.extra?.echoes?.kind === "row"));
      const { entry: catalogEntryValue, catalog } = catalogFromEntries(entries);
      let rows = this.stateFromEntries(worldbookName, entries).rows;
      const now = new Date().toISOString();
      for (const source of tables) {
        const existingType = catalog.types.find((type) => type.id === source.type.id);
        if (existingType && policy === "skip") continue;
        const importedType = structuredClone(source.type);
        if (policy === "copy") {
          importedType.id = uniqueId("type");
          importedType.name = this.availableTypeName(catalog.types, `${importedType.name.slice(0, 116)}（迁移）`);
        } else {
          importedType.name = this.availableTypeName(
            catalog.types.filter((type) => type.id !== importedType.id), importedType.name,
          );
        }
        importedType.updatedAt = now;
        if (existingType && policy === "overwrite") {
          for (let index = entries.length - 1; index >= 0; index -= 1) {
            const metadata = echoesMetadata(entries[index]!);
            if (metadata?.kind !== "row" || metadata.typeId !== existingType.id) continue;
            entries.splice(index, 1);
            summary.deleted += 1;
          }
          rows = rows.filter((row) => row.typeId !== existingType.id);
          catalog.types[catalog.types.indexOf(existingType)] = importedType;
        } else {
          catalog.types.push(importedType);
        }
        for (const sourceRow of source.rows) {
          const { dataName, keywords, status, values, aliases, continuity } = structuredClone(sourceRow);
          const importedRow: MemoryRow = {
            id: uniqueId("row"), typeId: importedType.id,
            dataName, keywords, status, values, aliases, continuity,
            enabled: importedType.enabled && currentFact(continuity),
            source: { kind: "migration", messageIds: [] },
            revision: 1, createdAt: now, updatedAt: now,
          };
          const existingRow = rows.find((row) => row.typeId === importedType.id
            && row.dataName.toLocaleLowerCase() === importedRow.dataName.toLocaleLowerCase());
          if (existingRow && policy === "skip") continue;
          if (existingRow && policy === "copy") {
            const desired = `${importedRow.dataName.slice(0, 236)}（迁移）`;
            importedRow.dataName = desired;
            let suffix = 2;
            while (!uniqueDataName(rows, importedType.id, importedRow.dataName)) {
              const ending = ` ${suffix++}`;
              importedRow.dataName = desired.slice(0, 240 - ending.length) + ending;
            }
          }
          if (existingRow && policy === "overwrite") {
            const index = entries.findIndex((entry) => {
              const metadata = echoesMetadata(entry);
              return metadata?.kind === "row" && metadata.rowId === existingRow.id;
            });
            entries.splice(index, 1);
            rows = rows.filter((row) => row.id !== existingRow.id);
            summary.deleted += 1;
          }
          validateAliases(rows, importedRow);
          rows.push(importedRow);
          entries.push(rowEntry(importedType, importedRow) as TavernWorldbookEntry);
          summary.added += 1;
        }
      }
      catalog.updatedAt = now;
      updateCatalogEntry(catalogEntryValue, catalog);
      structuredMemoryCatalogSchema.parse(catalog);
      appendMemoryHistory(before, entries);
      return entries;
    }, { render: "debounced" });
    return summary;
  }

  private availableTypeName(types: MemoryTypeDefinition[], desired: string): string {
    let candidate = desired;
    let suffix = 2;
    while (types.some((type) => type.name.toLocaleLowerCase() === candidate.toLocaleLowerCase())) {
      const ending = ` ${suffix}`;
      candidate = desired.slice(0, 120 - ending.length) + ending;
      suffix += 1;
    }
    return candidate;
  }

  private assertCurrentChat(chatId: string): void {
    if (SillyTavern.getContext().chatId !== chatId) {
      throw new Error("The active chat changed before the structured-memory operation started.");
    }
  }

  private async ensureCurrentCatalog(target: {
    chatId: string;
    worldbookName: string | null;
  }): Promise<{ worldbookName: string; entries: TavernWorldbookEntry[] }> {
    const helper = requiredHelper();
    this.assertCurrentChat(target.chatId);
    const baseName = target.chatId.replace(/\.(json|jsonl)$/i, "");
    let worldbookName = target.worldbookName;
    if (!worldbookName) {
      this.assertCurrentChat(target.chatId);
      worldbookName = await helper.getOrCreateChatWorldbook("current", `Echoes-${baseName}`);
      this.assertCurrentChat(target.chatId);
    }
    let entries = await helper.getWorldbook(worldbookName);
    const existingCatalogEntry = entries.find(
      (entry) => echoesMetadata(entry)?.kind === "catalog",
    );
    let deleted: LegacyStructuredCounts | undefined;
    if (existingCatalogEntry) {
      const metadata = echoesMetadata(existingCatalogEntry) as CatalogMetadata;
      if (metadata.catalog.formatVersion !== 2) {
        this.assertCurrentChat(target.chatId);
        const cleanup = await deleteLegacyStructured(worldbookName);
        entries = cleanup.entries;
        deleted = cleanup.counts;
      } else if (structuredMemoryCatalogSchema.parse(metadata.catalog).chatId !== target.chatId) {
        const names = new Set(helper.getWorldbookNames());
        let candidate = `Echoes-${baseName}`;
        let suffix = 2;
        while (names.has(candidate)) {
          candidate = `Echoes-${baseName}-${suffix}`;
          suffix += 1;
        }
        await helper.createWorldbook(candidate);
        this.assertCurrentChat(target.chatId);
        await helper.rebindChatWorldbook("current", candidate);
        this.assertCurrentChat(target.chatId);
        worldbookName = candidate;
        entries = [];
      }
    }
    if (!entries.some((entry) => echoesMetadata(entry)?.kind === "catalog")) {
      const created = await helper.createWorldbookEntries(
        worldbookName,
        [catalogEntry(createDefaultCatalog(target.chatId))],
        { render: "debounced" },
      );
      entries = created.worldbook;
    }
    if (deleted) {
      toast(`已删除此聊天 4.0 之前的结构化记忆（目录、${deleted.rows} 条条目、${deleted.history} 条历史记录），已按新方案重新建表。`, "success");
    }
    return { worldbookName, entries };
  }

  private async readWorldbook(worldbookName: string): Promise<WorldbookMemoryState> {
    const entries = await requiredHelper().getWorldbook(worldbookName);
    return this.stateFromEntries(worldbookName, entries);
  }

  private stateFromEntries(
    worldbookName: string,
    entries: TavernWorldbookEntry[],
  ): WorldbookMemoryState {
    const { catalog } = catalogFromEntries(entries);
    const typeById = new Map(catalog.types.map((type) => [type.id, type]));
    const rows: MemoryRow[] = [];
    const issues: string[] = [];
    for (const entry of entries) {
      const metadata = echoesMetadata(entry);
      if (metadata?.kind !== "row") continue;
      const type = typeById.get(metadata.typeId);
      if (!type) {
        issues.push(`${entry.name}: unknown memory type ${metadata.typeId}`);
        continue;
      }
      try {
        rows.push(rowFromEntry(entry, type));
      } catch (error) {
        issues.push(`${entry.name}: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
    return { worldbookName, catalog, rows, issues };
  }

  private async mutate(
    mutator: (
      entries: TavernWorldbookEntry[],
      catalog: StructuredMemoryCatalog,
    ) => void,
    undoLabel?: string,
  ): Promise<void> {
    await this.enqueue(async (target) => {
      const { worldbookName } = await this.ensureCurrentCatalog(target);
      let undoId: string | undefined;
      const written = await requiredHelper().updateWorldbookWith(worldbookName, async (entries) => {
        const beforeAll = undoLabel ? structuredClone(entries) : undefined;
        const before = structuredClone(entries.filter((entry) => entry.extra?.echoes?.kind === "row"));
        const { entry, catalog } = catalogFromEntries(entries);
        mutator(entries, catalog);
        catalog.updatedAt = new Date().toISOString();
        updateCatalogEntry(entry, catalog);
        structuredMemoryCatalogSchema.parse(catalog);
        appendMemoryHistory(before, entries);
        if (beforeAll) undoId = await recordMemoryUndo(worldbookName, "structured", undoLabel!, beforeAll, entries);
        return entries;
      }, { render: "debounced" });
      await completeMemoryUndo(worldbookName, target.chatId, undoId, written);
    });
  }

  async undoOperation(id: string): Promise<void> {
    await this.enqueue(async (target) => {
      if (!target.worldbookName) throw new Error("当前聊天没有世界书。");
      const record = await requireMemoryUndo(target.worldbookName, id);
      if (record.kind !== "structured") throw new Error("撤销记录类型不符。");
      const written = await requiredHelper().updateWorldbookWith(target.worldbookName, async (entries) => {
        const next = applyMemoryUndo(record, entries);
        const restored = this.stateFromEntries(target.worldbookName!, next);
        const affected = new Set(record.changes.map((change) => change.before?.extra?.echoes?.rowId).filter(Boolean));
        for (const row of restored.rows.filter((row) => affected.has(row.id))) validateAliases(restored.rows, row);
        for (const change of record.changes) if (change.before) {
          const type = restored.catalog.types.find((type) => type.id === change.before!.extra!.echoes.typeId)!;
          rowFromEntry(change.before, type);
        }
        appendMemoryHistory(entries, next);
        await prepareMemoryUndoRestore(record, next);
        return next;
      });
      await completeMemoryUndo(target.worldbookName, target.chatId, id, written, true);
      await forgetMemoryUndo(target.worldbookName, target.chatId, id);
    });
  }

  private enqueue<TResult>(
    operation: (target: { chatId: string; worldbookName: string | null }) => Promise<TResult>,
  ): Promise<TResult> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("Open a SillyTavern chat before using structured memory."));
    const worldbookName = requiredHelper().getChatWorldbookName("current");
    const lockKey = worldbookName ?? `chat:${chatId}`;
    return worldbookWriteCoordinator.run(lockKey, async () => {
      this.assertCurrentChat(chatId);
      return operation({ chatId, worldbookName });
    });
  }
}
