import { z } from "zod";
import type { MemoryRow, MemoryTypeDefinition, MemoryTypeTemplate } from "../../shared/domain";
import {
  memoryRowInputSchema, memoryTypeInputSchema, memoryTypeTemplateInputSchema, validateMemoryValues,
} from "../../shared/schemas";

export type MemoryImportPolicy = "copy" | "skip" | "overwrite";

export const memoryTemplatesFileSchema = z.object({
  format: z.literal("echoes-memory-templates", { error: "不是 Echoes 类型模板文件。" }),
  version: z.literal(1, { error: "仅支持版本 1 的类型模板文件。" }),
  exportedAt: z.string().datetime(),
  templates: z.array(memoryTypeTemplateInputSchema.required({ id: true }).strict()),
}).strict();

const memoryTableTransferSchema = z.object({
  type: memoryTypeInputSchema.required({ id: true }).strict(),
  rows: z.array(memoryRowInputSchema.omit({ source: true }).strict()).optional(),
}).strict().transform((table, context) => {
  for (const [index, row] of (table.rows ?? []).entries()) {
    try {
      row.values = validateMemoryValues(table.type.columns, row.values);
    } catch (error) {
      context.addIssue({ code: "custom", path: ["rows", index, "values"],
        message: `表「${table.type.name}」的条目「${row.dataName}」字段值不符合表结构：${(error as Error).message}` });
    }
  }
  return table;
});

export const memoryTablesFileSchema = z.object({
  format: z.literal("echoes-memory-tables", { error: "不是 Echoes 记忆表文件。" }),
  version: z.literal(1, { error: "仅支持版本 1 的记忆表文件。" }),
  exportedAt: z.string().datetime(),
  tables: z.array(memoryTableTransferSchema),
}).strict();

export type MemoryTemplateTransfer = z.infer<typeof memoryTemplatesFileSchema>["templates"][number];
export type MemoryTableTransfer = z.infer<typeof memoryTablesFileSchema>["tables"][number];
export type MemoryRowTransfer = NonNullable<MemoryTableTransfer["rows"]>[number];

function parseFile<T>(text: string, schema: z.ZodType<T>): T {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch (cause) {
    throw new Error("文件不是有效的 JSON。", { cause });
  }
  const result = schema.safeParse(raw);
  if (!result.success) {
    const issue = result.error.issues[0]!;
    const message = (issue.code === "custom" && issue.path.at(-1) === "values")
      || issue.path[0] === "format" || issue.path[0] === "version"
      ? issue.message : `文件内容无效（${issue.path.join(".") || "根对象"}），请检查字段类型、必填项、取值及字段是否重复。`;
    throw new Error(message, { cause: result.error });
  }
  return result.data;
}

export function parseMemoryTemplates(text: string): MemoryTemplateTransfer[] {
  return parseFile(text, memoryTemplatesFileSchema).templates;
}

export function parseMemoryTables(text: string): MemoryTableTransfer[] {
  return parseFile(text, memoryTablesFileSchema).tables;
}

export function serializeMemoryTemplates(templates: MemoryTypeTemplate[]): string {
  return JSON.stringify({
    format: "echoes-memory-templates", version: 1, exportedAt: new Date().toISOString(),
    templates: templates.map(({ id, name, description, columns, guide, defaultStatus }) =>
      ({ id, name, description, columns, guide, defaultStatus })),
  }, null, 2);
}

export function serializeMemoryTables(types: MemoryTypeDefinition[], rows: MemoryRow[], includeRows: boolean): string {
  return JSON.stringify({
    format: "echoes-memory-tables", version: 1, exportedAt: new Date().toISOString(),
    tables: types.map(({ id, templateId, name, description, columns, guide, defaultStatus, enabled }) => ({
      type: { id, templateId, name, description, columns, guide, defaultStatus, enabled },
      ...(includeRows ? { rows: rows.filter((row) => row.typeId === id)
        .map(({ dataName, keywords, status, values, aliases, continuity }) =>
          ({ dataName, keywords, status, values, aliases, continuity })) } : {}),
    })),
  }, null, 2);
}
