import type { MemoryColumnDefinition, MemoryRow, MemoryTypeDefinition } from "../../../../shared/domain";
import { WorldbookMemoryStore } from "../../../worldbook/worldbook-memory";
import { decodeMemoryContent, encodeMemoryContent } from "../../../worldbook/memory-codec";
import { lines } from "../../kit/dom";
import { form, type FieldSpec, type Form } from "../../kit/forms";
import { formModal } from "../../kit/overlays";
import { ACTIVATION_OPTIONS } from "../shared";

export const memoryStore = new WorldbookMemoryStore();

function columnSpec(column: MemoryColumnDefinition, value: unknown): FieldSpec {
  const base = { key: `value:${column.id}`, label: column.name, required: column.required, hint: column.description, value };
  switch (column.type) {
    case "number": return { ...base, type: "number", step: "any" };
    case "boolean": return { ...base, type: "select", value: value === undefined ? "" : String(value),
      options: [["", "未设置"], ["true", "是"], ["false", "否"]] };
    case "enum": return { ...base, type: "select", value: value ?? "",
      options: [["", "未设置"], ...(column.enumValues ?? []).map((item): [string, string] => [item, item])] };
    case "json": return { ...base, type: "json", rows: 6, value: value ?? null };
    case "long_text": return { ...base, type: "textarea", rows: 4 };
    default: return { ...base, type: "text" };
  }
}

/** The editable form for an entry: identity, activation, keywords, then each column. */
export function rowForm(type: MemoryTypeDefinition, row?: MemoryRow): Form {
  return form([
    { key: "dataName", label: "条目名称", value: row?.dataName ?? "", required: true },
    { key: "status", label: "激活方式", type: "select", value: row?.status ?? type.defaultStatus, options: ACTIVATION_OPTIONS },
    { key: "keywords", label: "关键词", type: "textarea", rows: 2, value: row?.keywords.join("\n") ?? "", hint: "每行一项" },
    { key: "aliases", label: "别名", type: "textarea", rows: 2, value: row?.aliases?.join("\n") ?? "", hint: "每行一项；用于查重与人物聚合" },
    ...type.columns.map((column) => columnSpec(column, row?.values[column.id] ?? column.defaultValue)),
  ], { className: "is-single" });
}

export function rowInput(type: MemoryTypeDefinition, values: Record<string, any>) {
  const fields: Record<string, unknown> = {};
  for (const column of type.columns) {
    const value = values[`value:${column.id}`];
    if (value === "" || value === undefined || value === null) continue;
    fields[column.id] = column.type === "boolean" ? value === "true" : value;
  }
  return {
    dataName: String(values.dataName),
    status: values.status,
    keywords: lines(values.keywords),
    aliases: lines(values.aliases),
    values: fields,
  };
}

export function newRowModal(type: MemoryTypeDefinition, guard: () => void, done: () => Promise<void>) {
  const target = rowForm(type);
  return formModal(`新增条目 · ${type.name}`, target, async (values) => {
    guard();
    await memoryStore.saveRow(type.id, rowInput(type, values));
    await done();
  }, { size: "large" });
}

export function yamlModal(type: MemoryTypeDefinition, row: MemoryRow, guard: () => void, done: () => Promise<void>) {
  const target = form([{ key: "yaml", label: "条目 YAML", type: "code", rows: 24, required: true,
    value: encodeMemoryContent(type, row.dataName, row.values) }], { className: "is-single" });
  return formModal(`编辑 YAML · ${row.dataName}`, target, async (values) => {
    guard();
    const content = decodeMemoryContent(type, values.yaml);
    // Aliases and time attributes are kept by the store when omitted.
    await memoryStore.saveRow(type.id, { ...content, status: row.status, keywords: row.keywords }, row.id, row.revision);
    await done();
  }, { size: "large" });
}

export function displayValue(value: unknown): string {
  if (value === undefined || value === null) return "";
  if (typeof value === "boolean") return value ? "是" : "否";
  return typeof value === "string" ? value : JSON.stringify(value, null, 2);
}
