import type { PromptPresetItem, RetrievalQueryPresetItem, StatusPromptItem, SummaryPromptItem } from "../../../shared/domain";
import { uid, h, type Child } from "../kit/dom";
import { form } from "../kit/forms";
import { formModal } from "../kit/overlays";
import { sortable } from "../kit/sortable";

type Prompt = PromptPresetItem | SummaryPromptItem | StatusPromptItem | RetrievalQueryPresetItem;
export type PromptMode = "structured" | "summary" | "status" | "query";

const KIND_NAMES: Record<string, string> = {
  main: "主提示词", custom: "自定义文本", character: "角色卡", worldbook: "世界书", persona: "用户设定",
  previous_summaries: "前文总结", messages: "剧情消息", current_state: "当前状态", current_message: "当前消息",
  recent_messages: "近期消息", scene: "时空状态", participants: "在场角色", commitments: "计划与承诺",
};
const KINDS: Record<PromptMode, string[]> = {
  structured: ["main", "custom"],
  summary: ["custom", "character", "worldbook", "persona", "previous_summaries", "messages"],
  status: ["custom", "character", "worldbook", "persona", "current_state", "messages"],
  query: ["custom", "current_message", "recent_messages", "character", "persona", "scene", "participants", "commitments"],
};
const DESCRIPTIONS: Record<string, string> = {
  character: "插入当前角色卡。", worldbook: "插入本批剧情激活的世界书条目。", persona: "插入用户设定。",
  previous_summaries: "插入最近的已有总结，只用于理解背景。", messages: "插入本次要处理的剧情消息。",
  current_state: "插入当前状态 YAML。", current_message: "以当前消息作查询。", recent_messages: "以此前若干条消息作查询。",
  scene: "以状态中的时空状态作查询。", participants: "以状态中的在场角色作查询。", commitments: "以状态中的计划与承诺作查询。",
};

function editPrompt(mode: PromptMode, item: Prompt | undefined, done: (item: Prompt) => void): void {
  const value = (item ?? {}) as any;
  const target = form([
    { key: "title", label: "标题", value: value.title ?? "", required: true },
    { key: "kind", label: "内容类型", type: "select", value: value.kind ?? "custom",
      options: KINDS[mode].map((kind): [string, string] => [kind, KIND_NAMES[kind]!]) },
    ...(mode === "query" ? [] : [{ key: "role", label: "消息角色", type: "select" as const, value: value.role ?? "system",
      options: [["system", "System"], ["user", "User"], ["assistant", "Assistant"]] as Array<[string, string]> }]),
    { key: "enabled", label: "启用", type: "switch", value: value.enabled ?? true },
    { key: "count", label: "数量", type: "number", min: 0, max: 100, value: value.count ?? 2 },
    { key: "unit", label: "计数单位", type: "select", value: value.unit ?? "batches", options: [["batches", "完整批次"], ["slices", "切片"]] },
    { key: "content", label: "内容", type: "code", rows: 18, value: value.content ?? "" },
  ]);
  const note = h("p", "ec-muted");
  const sync = () => {
    const kind = target.control("kind").value;
    target.show("count", kind === "previous_summaries" || kind === "recent_messages");
    target.show("unit", kind === "previous_summaries");
    target.show("content", kind === "main" || kind === "custom");
    note.textContent = DESCRIPTIONS[kind] ?? "";
    note.hidden = !note.textContent;
  };
  target.control("kind").addEventListener("change", sync);
  sync();
  formModal(item ? `编辑 · ${value.title}` : "添加提示词", target, (values) => {
    const result: any = { id: value.id ?? uid("prompt"), title: values.title, kind: values.kind, enabled: values.enabled };
    if (mode !== "query") result.role = values.role;
    if (values.kind === "custom" || values.kind === "main") result.content = values.content;
    if (values.kind === "previous_summaries" || values.kind === "recent_messages") result.count = values.count;
    if (values.kind === "previous_summaries") result.unit = values.unit;
    done(result);
  }, { size: "large", after: note });
}

/** The ordered prompt editor used by every module. */
export function promptList<T extends Prompt>(mode: PromptMode, items: readonly T[], save: (items: T[]) => unknown,
  extra?: (drafts: () => T[]) => Child[]): HTMLElement {
  return sortable<T>({
    items,
    describe: (item) => ({
      title: item.title,
      tag: KIND_NAMES[item.kind] ?? item.kind,
      note: "content" in item ? `${item.content.length} 字` : "count" in item ? `数量 ${item.count}` : undefined,
    }),
    edit: (item, done) => editPrompt(mode, item, (next) => done(next as T)),
    save,
    toggle: { get: (item) => item.enabled, set: (item, value) => ({ ...item, enabled: value }) },
    addLabel: mode === "query" ? "添加查询项" : "添加提示词",
    ...(extra ? { extra } : {}),
    emptyText: "还没有任何提示词。",
  });
}
