import { getSettings, saveSettings } from "../../../state/settings";
import { recallCoordinator } from "../../../recall-coordinator";
import { summaryOriginalSource } from "../../../summary/summary-original-source";
import { h, fill } from "../../kit/dom";
import { button, badge } from "../../kit/controls";
import { card, stack, lazy, code, muted } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { modal, confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";

export function recallContinuityPage(ctx: PageContext): HTMLElement {
  const config = getSettings().continuity;
  const extraction = form([{ key: "extractAttributes", label: "提取时间与角色认知属性", type: "switch", value: config.extractAttributes,
    hint: "结构化提取和总结生成都会为记录附上事件时间、有效期和角色知情情况" }]);
  const triggers = form([
    { key: "enabled", label: "状态驱动查询", type: "switch", value: config.triggers.enabled, hint: "根据当前状态中的计划与约定追加查询" },
    { key: "maxQueries", label: "追加查询上限", type: "number", min: 1, max: 4, value: config.triggers.maxQueries, required: true },
    { key: "nearDays", label: "约定临近天数", type: "number", min: 0, max: 30, value: config.triggers.nearDays, required: true },
  ]);
  const supplement = form([
    { key: "auto", label: "命中不足时自动补充检索", type: "switch", value: config.supplement.auto },
    { key: "minimumHits", label: "触发补充的命中数", type: "number", min: 0, max: 100, value: config.supplement.minimumHits, required: true,
      hint: "普通召回少于这个数时补充" },
    { key: "maxRequests", label: "最多补充请求", type: "number", min: 0, max: 3, value: config.supplement.maxRequests, required: true },
    { key: "maxItems", label: "补充切片上限", type: "number", min: 1, max: 20, value: config.supplement.maxItems, required: true },
    { key: "maxWaitMs", label: "补充检索总等待（毫秒）", type: "number", min: 1000, max: 120000, value: config.supplement.maxWaitMs, required: true },
    { key: "allowPaid", label: "允许调用向量与重排序端点", type: "switch", value: config.supplement.allowPaid, hint: "关闭时只用 BM25，不产生费用" },
  ]);
  const save = (change: (value: typeof config) => void) => {
    ctx.guard();
    const settings = getSettings();
    const next = structuredClone(settings.continuity);
    change(next);
    settings.continuity = next;
    saveSettings(settings);
  };
  const manual = form([{ key: "query", label: "查询内容", type: "textarea", rows: 3, required: true }], { track: false });
  const results = h("div", "ec-stack");
  return stack(
    formCard("时间与认知", extraction, (values) => save((next) => { next.extractAttributes = values.extractAttributes; }), { scope: "global" }),
    formCard("状态驱动查询", triggers, (values) => save((next) => {
      next.triggers = { enabled: values.enabled, maxQueries: values.maxQueries, nearDays: values.nearDays };
    }), { scope: "global" }),
    formCard("有界补充检索", supplement, (values) => save((next) => {
      next.supplement = { auto: values.auto, maxRequests: values.maxRequests, maxWaitMs: values.maxWaitMs,
        maxItems: values.maxItems, minimumHits: values.minimumHits, allowPaid: values.allowPaid };
    }), { scope: "global", description: "普通召回命中太少时，按限制补充检索一次，结果单独标注。" }),
    card("手动补充检索", { description: "用任意文本试一次补充检索，不注入、不写入任何记忆。" }, manual.node,
      h("div", "ec-row ec-card-foot", button("检索", async () => {
        const { query } = manual.values();
        ctx.guard();
        if (getSettings().continuity.supplement.allowPaid && !await confirmAction({ title: "进行补充检索？", cost: true, confirmLabel: "检索",
          message: "当前设置允许调用向量与重排序端点。" })) return;
        const result = await recallCoordinator.supplementPreview(query, ctx.signal);
        if (ctx.signal.aborted) return;
        fill(results, h("div", "ec-row", badge(`请求 ${result.calls} 次`), badge(`命中 ${result.slices.length} 条`)),
          ...result.messages.map((message) => muted(message)),
          ...result.slices.map(({ slice, worldbookName, chatId }) => lazy(`${slice.timestamp} · ${slice.title} · ${chatId}`, () =>
            h("div", "ec-stack", h("div", "ec-prose", slice.content), h("div", "ec-row", button("查看批次原文", async () => {
              const source = await summaryOriginalSource(slice, { worldbookName, chatId });
              modal("批次原文", [muted(source.scope), ...source.messages.map((message) => card(`${message.role} · ${message.id}`, {}, code(message.content)))], { size: "large" });
            }, { variant: "ghost", small: true }))))));
      }, { variant: "primary", icon: "magnifying-glass" })), results),
  );
}
