import { h, isAbort, errorText, type Child } from "./dom";
import { button, iconButton, badge, type ButtonVariant } from "./controls";
import { layer } from "./theme";
import type { Form } from "./forms";

function messageNode(message: Child): Child {
  return typeof message === "string" ? h("p", "ec-modal-text", message) : message;
}

export interface Choice<T> {
  value: T;
  label: string;
  variant?: ButtonVariant | undefined;
  disabled?: boolean | undefined;
  focus?: boolean | undefined;
}
export interface ChooseOptions<T> {
  title: string;
  message?: Child;
  cost?: boolean | undefined;
  irreversible?: boolean | undefined;
  choices: Array<Choice<T>>;
  cancelValue: T;
}

/** A small modal that resolves to the chosen value; Esc resolves to cancelValue. */
export function choose<T>(options: ChooseOptions<T>): Promise<T> {
  return new Promise((resolve) => {
    const dialog = h("dialog", "ec-modal is-small ec-confirm");
    dialog.setAttribute("aria-label", options.title);
    let settled = false;
    const finish = (value: T) => {
      if (settled) return;
      settled = true;
      dialog.close();
      resolve(value);
    };
    const tags = [options.cost ? badge("可能产生费用", "warning") : null, options.irreversible ? badge("不能撤销", "danger") : null];
    const buttons = options.choices.map((choice) => {
      const node = button(choice.label, () => finish(choice.value), { variant: choice.variant ?? "secondary", disabled: choice.disabled });
      if (choice.focus) node.autofocus = true;
      return node;
    });
    dialog.append(
      h("header", "ec-modal-head", h("h2", "", options.title)),
      h("div", "ec-modal-body", tags.some(Boolean) ? h("div", "ec-row", ...tags) : null,
        options.message === undefined ? null : messageNode(options.message)),
      h("footer", "ec-modal-foot", h("div", "ec-row ec-modal-actions", ...buttons)),
    );
    dialog.addEventListener("cancel", (event) => {
      event.preventDefault();
      finish(options.cancelValue);
    });
    dialog.addEventListener("close", () => {
      dialog.remove();
      if (!settled) { settled = true; resolve(options.cancelValue); }
    }, { once: true });
    layer().append(dialog);
    dialog.showModal();
  });
}

export interface ConfirmOptions {
  title: string;
  message?: Child;
  confirmLabel?: string | undefined;
  cancelLabel?: string | undefined;
  danger?: boolean | undefined;
  cost?: boolean | undefined;
  irreversible?: boolean | undefined;
}

export function confirmAction(options: ConfirmOptions): Promise<boolean> {
  return choose<boolean>({
    title: options.title, message: options.message, cost: options.cost, irreversible: options.irreversible,
    cancelValue: false,
    choices: [
      { value: false, label: options.cancelLabel ?? "取消" },
      { value: true, label: options.confirmLabel ?? "确定", variant: options.danger ? "danger" : "primary", focus: true },
    ],
  });
}

export interface ModalOptions {
  size?: "small" | "medium" | "large" | undefined;
  /** Returns false to keep the modal open. Errors are shown inside the modal. */
  primary?: { label: string; run: () => unknown; danger?: boolean | undefined } | undefined;
  cancelLabel?: string | undefined;
  extra?: Child[] | undefined;
  dirty?: (() => boolean) | undefined;
  onClose?: (() => void) | undefined;
}
export interface Modal {
  node: HTMLDialogElement;
  body: HTMLElement;
  showError(message: string): void;
  close(force?: boolean): Promise<boolean>;
}

export function modal(title: string, content: Child | Child[], options: ModalOptions = {}): Modal {
  const dialog = h("dialog", `ec-modal is-${options.size ?? "medium"}`);
  dialog.setAttribute("aria-label", title);
  const body = h("div", "ec-modal-body", ...(Array.isArray(content) ? content : [content]));
  const error = h("p", "ec-modal-error");
  error.setAttribute("role", "alert");
  error.hidden = true;
  const dirty = options.dirty ?? (() => Boolean(body.querySelector('[data-dirty="true"]')));
  const close = async (force = false) => {
    if (!dialog.open) return true;
    if (!force && dirty() && !await confirmAction({ title: "放弃未保存的修改？", confirmLabel: "放弃修改", danger: true })) return false;
    dialog.close();
    return true;
  };
  const actions: Child[] = [...(options.extra ?? [])];
  if (options.primary) {
    const primary = options.primary;
    actions.push(button(options.cancelLabel ?? "取消", () => close(), { variant: "ghost" }),
      button(primary.label, async () => {
        error.hidden = true;
        try {
          if (await primary.run() !== false) await close(true);
        } catch (cause) {
          if (isAbort(cause)) return;
          error.textContent = errorText(cause);
          error.hidden = false;
        }
      }, { variant: primary.danger ? "danger" : "primary" }));
  }
  dialog.append(h("header", "ec-modal-head", h("h2", "", title), iconButton("关闭", "xmark", () => close())), body);
  if (actions.length) dialog.append(h("footer", "ec-modal-foot", error, h("div", "ec-row ec-modal-actions", ...actions)));
  else body.append(error);
  dialog.addEventListener("cancel", (event) => {
    event.preventDefault();
    void close();
  });
  dialog.addEventListener("close", () => {
    dialog.remove();
    options.onClose?.();
  }, { once: true });
  layer().append(dialog);
  dialog.showModal();
  return {
    node: dialog, body, close,
    showError(message) { error.textContent = message; error.hidden = false; },
  };
}

export function formModal(title: string, target: Form, save: (values: Record<string, any>) => unknown,
  options: Omit<ModalOptions, "primary" | "dirty"> & { saveLabel?: string; before?: Child; after?: Child } = {}): Modal {
  return modal(title, [options.before, target.node, options.after], {
    ...options, dirty: () => target.dirty(),
    primary: { label: options.saveLabel ?? "保存", run: () => save(target.values()) },
  });
}
