import type { SummaryWorldbookState } from "./worldbook/summary-worldbook";
import { indexedChatMessages } from "./chat-message-index";

export function recallSourceFingerprint(state: SummaryWorldbookState): string {
  const { updatedAt: _updated, recallPool: _pool, autoRun: _auto, ...catalog } = state.catalog;
  return JSON.stringify([catalog, state.slices.map(({ worldbookUid: _uid, batch, ...slice }) => [
    slice, { ...batch, state: batch.state === "stale", updatedAt: undefined },
  ])]);
}

export function visibleRecallMessageIds(chat: Array<Record<string, unknown>>): Set<string> {
  const original = SillyTavern.getContext().chat;
  const visible = new Set<string>();
  const byId = new Map<string, Array<Record<string, unknown>>>();
  const byIdentity = new Set(chat.filter((entry) => !entry.is_hidden));
  for (const entry of chat) {
    const rawId = entry.message_id ?? entry.id;
    if (rawId === undefined || entry.is_hidden) continue;
    const id = String(rawId);
    byId.set(id, [...(byId.get(id) ?? []), entry]);
  }
  for (const { floor, message } of indexedChatMessages()) {
    if (original[floor]?.is_hidden) continue;
    const matching = [...new Set([...(byId.get(message.id) ?? []),
      ...(byIdentity.has(original[floor]!) ? [original[floor]!] : [])])];
    if (matching.length === 1
      && String(matching[0]!.mes ?? matching[0]!.message ?? matching[0]!.content ?? "").trim() === message.content) {
      visible.add(message.id);
    }
  }
  return visible;
}

export function excludedRecallSources(
  current: SummaryWorldbookState, sources: SummaryWorldbookState[], visibleIds: Set<string>,
): Set<string> {
  const excluded = new Set<string>();
  for (const source of sources) {
    for (const id of source.catalog.pendingRetrievalDeletes) excluded.add(id);
    const sameChat = source.catalog.chatId === current.catalog.chatId
      && source.catalog.namespaceId === current.catalog.namespaceId && source.worldbookName === current.worldbookName;
    for (const slice of source.slices) {
      if (slice.batch.state === "stale" || slice.continuity?.validity === "superseded"
        || (sameChat && slice.batch.source?.kind !== "imported" && slice.batch.messageIds.length > 0
          && slice.batch.messageIds.every((id) => visibleIds.has(id)))) excluded.add(slice.id);
    }
  }
  return excluded;
}
