import type { ChatMessageInput, SummaryPreprocessRule } from "../../shared/domain";
import { inspectSummaryPreprocess, type CleaningReport } from "./preprocess-core";

export function preprocessSummaryMessages(
  messages: ChatMessageInput[],
  rules: SummaryPreprocessRule[],
  timeoutMs = 2_000,
): Promise<ChatMessageInput[]> {
  return runPreprocess(messages, rules, timeoutMs, false).then((result) => result.messages);
}

export function previewSummaryPreprocess(
  messages: ChatMessageInput[],
  rules: SummaryPreprocessRule[],
  timeoutMs = 2_000,
): Promise<CleaningReport> {
  return runPreprocess(messages, rules, timeoutMs, true);
}

function runPreprocess(messages: ChatMessageInput[], rules: SummaryPreprocessRule[], timeoutMs: number, includeNotes: boolean): Promise<CleaningReport> {
  if (rules.every((rule) => !rule.enabled)) return Promise.resolve({ messages: structuredClone(messages), notes: [] });
  if (typeof Worker === "undefined") return Promise.resolve(inspectSummaryPreprocess(messages, rules, includeNotes));
  const worker = new Worker(new URL("./summary-regex-worker.js", import.meta.url), { type: "module" });
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      worker.terminate();
      reject(new Error("消息清洗规则执行超时，请检查正则表达式。"));
    }, timeoutMs);
    worker.addEventListener("message", (event: MessageEvent<Partial<CleaningReport> & { ok: boolean; error?: string }>) => {
      clearTimeout(timeout);
      worker.terminate();
      if (event.data.ok && event.data.messages) resolve({ messages: event.data.messages, notes: event.data.notes ?? [] });
      else reject(new Error(event.data.error ?? "消息清洗失败。"));
    }, { once: true });
    worker.addEventListener("error", (event) => {
      clearTimeout(timeout);
      worker.terminate();
      reject(new Error(event.message || "消息清洗 Worker 失败。"));
    }, { once: true });
    worker.postMessage({ messages, rules, includeNotes });
  });
}
