import type { ExtractionRequest, MemoryRow } from "./domain";
import { declaredAliases, selectExtractionRows } from "./extraction-context";
import { CONTINUITY_EXTRACTION_GUIDE } from "./continuity";

export const EXTRACTION_CLEANING_GUIDE = `本次是用户发起的资料清洗，不是普通的增量提取。主提示词中“新剧情是新增信息的唯一依据”和有关删除的限制，本次改按以下规则执行：
- rows 包含所有启用表中的全部条目及其完整字段。已保存的条目和所选的历史剧情都是有效依据；用户的补充要求可以确认名称不同的条目是同一对象。
- 按用户的要求补全遗漏、更正错误或整理重复。整理旧资料不需要新剧情作为理由。
- 合并重复条目时，保留一条（优先保留用户指定的那条），用 update 把其他条目中仍然有效的信息整合进去，再用 delete 删除多余的条目。被删除条目的名称和别名，可以在同一批操作中转给保留的条目。
- 每个更新的字段都是完整替换，要同时包含原有内容和并入的内容，保留出处、先后顺序和不确定性。
- 按身份判断是否重复，不只看名称。相关的条目不一定重复；身份无法确认时保持原状。
- 不能用历史剧情中较早的状态，改回之后已知的状态。与要求无关的条目不要改动。
- 确实没有需要处理的内容时，返回 {"operations":[]}。结果会交给用户审核，不影响普通提取的进度。`;

export function extractionProviderMessages(request: ExtractionRequest) {
  return [
    ...request.promptMessages,
    ...request.backgroundMessages,
    ...(request.extractAttributes ? [{ role: "system" as const, content: CONTINUITY_EXTRACTION_GUIDE }] : []),
    ...(request.batch.mode === "cleaning" ? [{ role: "system" as const, content: EXTRACTION_CLEANING_GUIDE }] : []),
    { role: "user" as const, content: JSON.stringify(extractionRuntimeInput(request)) },
    ...(request.additionalInstructions?.trim()
      ? [{ role: "system" as const, content: request.additionalInstructions.trim() }] : []),
  ];
}

export function extractionRowReferences(rows: MemoryRow[]): Map<string, string> {
  const storedIds = new Set(rows.map((row) => row.id));
  const references = new Map<string, string>();
  let index = 1;
  for (const row of rows) {
    while (storedIds.has(`R${index}`)) index += 1;
    references.set(`R${index++}`, row.id);
  }
  return references;
}

type ExtractionContextInput = Pick<ExtractionRequest, "types" | "rows" | "messages" | "contextPolicy" | "batch">;

export function extractionContextRows(request: ExtractionContextInput) {
  // Cleaning compares existing records, so it must not inherit incremental relevance filtering.
  return selectExtractionRows(request.rows, request.types,
    request.messages.map((message) => message.content).join("\n"),
    request.batch.mode === "cleaning" ? undefined : request.contextPolicy);
}

export function extractionRuntimeInput(request: ExtractionContextInput) {
  const referenceById = new Map([...extractionRowReferences(request.rows)].map(([ref, id]) => [id, ref]));
  const selected = extractionContextRows(request);
  return {
    tables: request.types.map((type) => ({
      id: type.id,
      name: type.name,
      purpose: type.description,
      defaultStatus: type.defaultStatus,
      guide: type.guide,
      columns: type.columns.map((column) => ({
        id: column.id, name: column.name, type: column.type, required: column.required,
        description: column.description ?? "",
        ...(column.enumValues?.length ? { enumValues: column.enumValues } : {}),
        ...(column.defaultValue === undefined ? {} : { defaultValue: column.defaultValue }),
      })),
    })),
    ...(request.contextPolicy?.enabled && request.batch.mode !== "cleaning" ? {
      directory: request.rows.map((row) => ({
        rowId: referenceById.get(row.id)!, typeId: row.typeId, dataName: row.dataName,
        aliases: declaredAliases(row, request.types),
      })),
    } : {}),
    rows: selected.rows.map((row) => ({
      rowId: referenceById.get(row.id)!, typeId: row.typeId, dataName: row.dataName,
      keywords: row.keywords, status: row.status, values: row.values,
      ...(row.aliases ? { aliases: row.aliases } : {}),
      ...(row.continuity ? { continuity: row.continuity } : {}),
    })),
    newMessages: request.messages,
  };
}

export function unavailableExtractionRowReason(
  rowId: string,
  typeId: string,
  initialRows: MemoryRow[],
  currentRows: MemoryRow[],
): string {
  const initial = initialRows.find((row) => row.id === rowId);
  const prefix = `Operation references an unavailable row: ${rowId}. `;
  if (!initial) return prefix + "该引用不在本次请求的 rows 中；新增记录应使用 add，不能自行生成 rowId。";
  if (initial.typeId !== typeId) {
    return prefix + `记录“${initial.dataName}”属于 ${initial.typeId}，操作却指定了 ${typeId}；rowId 与 typeId 必须来自同一条记录。`;
  }
  if (!currentRows.some((row) => row.id === rowId)) {
    return prefix + `记录“${initial.dataName}”已被本批更早的操作删除；请合并对同一条记录的修改。`;
  }
  return prefix + "当前记录已不可用，请刷新记录后重试。";
}
