import { stringify } from "yaml";
import type { MemoryRow, MemoryTypeDefinition, MemoryTypeTemplate } from "../../../../shared/domain";
import { getSettings } from "../../../state/settings";
import { decodeMemoryContent, encodeMemoryContent } from "../../../worldbook/memory-codec";
import { h } from "../../kit/dom";
import { form } from "../../kit/forms";
import { formModal } from "../../kit/overlays";
import { table } from "../../kit/data";
import { callout, code, lazy, muted } from "../../kit/layout";
import { memoryStore } from "./row-editor";

/** Template columns first (matched by name), then the table's own leftover columns. */
function additiveColumns(current: MemoryTypeDefinition, template: MemoryTypeTemplate) {
  const retained = new Set<string>();
  const used = new Set(current.columns.map((column) => column.id));
  const columns = template.columns.map((column) => {
    const existing = current.columns.find((item) => item.name === column.name);
    if (existing) {
      if (existing.type !== column.type) throw new Error(`同名字段“${column.name}”的类型不同，请先手动调整；已有值不会自动转换。`);
      retained.add(existing.id);
      return structuredClone(existing);
    }
    let id = column.id;
    let suffix = 2;
    while (used.has(id)) id = `${column.id}_${suffix++}`;
    used.add(id);
    return { ...structuredClone(column), id };
  });
  const legacy = current.columns.filter((column) => !retained.has(column.id));
  return { columns: [...columns, ...structuredClone(legacy)], legacy };
}

export function upgradeFromTemplate(current: MemoryTypeDefinition, rowCount: number, guard: () => void, done: () => Promise<void>) {
  const templates = getSettings().typeTemplates;
  const target = form([
    { key: "template", label: "目标模板", type: "select", options: templates.map((item) => [item.id, item.name]),
      value: templates.some((item) => item.id === current.templateId) ? current.templateId : templates[0]?.id },
    { key: "replaceGuide", label: "同时采用模板的用途与记录说明", type: "switch", value: false },
  ], { className: "is-single" });
  const preview = h("div", "ec-stack");
  const render = () => {
    const template = templates.find((item) => item.id === target.control("template").value)!;
    try {
      const merged = additiveColumns(current, template);
      preview.replaceChildren(
        muted(`已有条目 ${rowCount} 条。旧字段全部保留；新增字段只写入模板中明确的默认值。`),
        table([
          { label: "字段", cell: (column) => column.name },
          { label: "类型", cell: (column) => column.type },
          { label: "处理", cell: (column) => !current.columns.some((item) => item.id === column.id) ? "新增"
            : merged.legacy.some((item) => item.id === column.id) ? "保留旧字段，待手动整理" : "保留原字段" },
        ], merged.columns),
        lazy("原记录说明", current.guide), lazy("模板记录说明", template.guide),
      );
    } catch (error) {
      preview.replaceChildren(callout("danger", error instanceof Error ? error.message : String(error)));
    }
  };
  target.control("template").addEventListener("change", render);
  render();
  return formModal(`从模板更新 · ${current.name}`, target, async (values) => {
    guard();
    const template = templates.find((item) => item.id === values.template)!;
    const merged = additiveColumns(current, template);
    await memoryStore.saveType({
      ...current, templateId: template.id, columns: merged.columns,
      description: values.replaceGuide ? template.description : current.description,
      guide: values.replaceGuide ? template.guide : current.guide,
    }, current.id, current.version);
    await done();
  }, { size: "large", after: preview, saveLabel: "更新表结构" });
}

export function reclassifyRow(types: MemoryTypeDefinition[], row: MemoryRow, guard: () => void, done: () => Promise<void>) {
  const source = types.find((type) => type.id === row.typeId)!;
  const targets = types.filter((type) => type.id !== row.typeId);
  if (!targets.length) throw new Error("请先创建目标表。");
  const drafts = new Map<string, string>();
  const target = form([
    { key: "target", label: "目标表", type: "select", value: targets[0]!.id, options: targets.map((type) => [type.id, type.name]) },
    { key: "yaml", label: "迁移后的字段 YAML", type: "code", rows: 18 },
    { key: "reviewed", label: "我已逐项核对原字段，有效信息都已保留", type: "switch", value: false },
  ], { className: "is-single" });
  const definitions = h("div");
  let selected = "";
  const select = () => {
    if (selected) drafts.set(selected, target.control("yaml").value);
    selected = target.control("target").value;
    const next = targets.find((type) => type.id === selected)!;
    const byName = new Map(source.columns.map((column) => [column.name, row.values[column.id]]));
    target.control("yaml").value = drafts.get(selected) ?? stringify({
      数据名: row.dataName,
      ...Object.fromEntries(next.columns.flatMap((column) => {
        const value = byName.get(column.name) ?? column.defaultValue;
        if (value !== undefined) return [[column.name, value]];
        return ["text", "long_text", "date"].includes(column.type) ? [[column.name, ""]] : [];
      })),
    }, { lineWidth: 0 });
    (target.control("reviewed") as HTMLInputElement).checked = false;
    definitions.replaceChildren(lazy("目标表字段说明", next.columns));
  };
  target.control("target").addEventListener("change", select);
  select();
  return formModal(`重新分类 · ${row.dataName}`, target, async (values) => {
    guard();
    if (!values.reviewed) throw new Error("请先核对原字段并确认有效信息都已保留。");
    const next = targets.find((type) => type.id === values.target)!;
    await memoryStore.reclassifyRow(row, next.id, next.version, decodeMemoryContent(next, values.yaml));
    await done();
  }, { size: "large", saveLabel: "移动到目标表",
    before: lazy("原条目完整内容", () => code(encodeMemoryContent(source, row.dataName, row.values))), after: definitions });
}
