import type { SummarySlice } from "../../../../shared/domain";
import { createBatchOrder, summarySuffix } from "../../../summary/batch-order";
import { currentChatMessages } from "../../../summary/summary-request";
import { buildSummaryRetrievalText } from "../../../summary/retrieval-document";
import type { SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { confirmAction, choose } from "../../kit/overlays";
import { toast } from "../../kit/feedback";
import type { PageContext } from "../../shell/context";

export type BatchAction = "rebuild" | "representation" | "sync" | "restore" | "hide" | "reset" | "delete";

/** Runs a maintenance action over the batches that own the given slices. */
export async function runBatchAction(ctx: PageContext, state: SummaryWorldbookState, action: BatchAction, slices: SummarySlice[]): Promise<boolean> {
  ctx.guard();
  if (!slices.length) return false;
  const coordinator = ctx.summary;
  const batches = [...new Map(slices.map((slice) => [slice.batch.id, slice.batch])).values()]
    .sort(createBatchOrder(currentChatMessages()).compare);
  const batchIds = batches.map((batch) => batch.id);
  switch (action) {
    case "rebuild": {
      if (batches.some((batch) => batch.source?.kind === "imported")) throw new Error("导入的批次没有原聊天消息，不能重新总结。");
      if (!await confirmAction({ title: `重新总结 ${batches.length} 个批次？`, message: "生成成功后替换这些批次的切片，并重新生成批次总结。",
        cost: true, confirmLabel: "重新总结" })) return false;
      await ctx.run("重新总结批次", () => coordinator.rebuildBatches(batches.map((batch) => batch.batchNumber)), () => coordinator.stop());
      break;
    }
    case "representation": {
      if (!await confirmAction({ title: `重建 ${slices.length} 个切片的检索表示？`, message: "从正文与标签重新生成，会覆盖自定义的检索表示；正文不变。随后同步索引。",
        cost: true, confirmLabel: "重建并同步" })) return false;
      let stopped = false;
      await ctx.run("重建检索表示并同步", async () => {
        const saved = await coordinator.saveRetrievalTexts(state, new Map(slices.map((slice) => [slice.id, buildSummaryRetrievalText(slice)])));
        if (stopped) throw new DOMException("已停止；检索表示已保存，索引未同步。", "AbortError");
        ctx.guard();
        const ids = new Set(slices.map((slice) => slice.id));
        const active = saved.slices.filter((slice) => ids.has(slice.id) && slice.batch.state !== "stale").map((slice) => slice.id);
        if (active.length) await coordinator.synchronizeSlices(active);
      }, async () => { stopped = true; await coordinator.stop(); });
      break;
    }
    case "sync": {
      if (!await confirmAction({ title: `同步 ${slices.length} 个切片的索引？`, cost: true, confirmLabel: "同步" })) return false;
      await ctx.run("同步切片索引", () => coordinator.synchronizeSlices(slices.map((slice) => slice.id)), () => coordinator.stop());
      break;
    }
    case "restore":
      await coordinator.compression.restoreBatch(state, batchIds);
      toast("已恢复这些批次的原消息。", "success");
      break;
    case "hide": {
      const result = await coordinator.compression.recompressBatch(state, batchIds);
      toast(result.blockedReason ?? `已重新隐藏：隐藏 ${result.hidden} 条，固定可见 ${result.pinned} 条。`, result.blockedReason ? "warning" : "success");
      break;
    }
    case "reset": {
      const start = batches[0]!.batchNumber;
      const affected = summarySuffix(state.slices, start, currentChatMessages());
      if (!await confirmAction({ title: `从批次 ${start} 开始重置？`, irreversible: true, danger: true, confirmLabel: "重置",
        message: `会删除此后的 ${affected.length} 个切片及其批次总结，恢复对应原消息，检查点退回到批次 ${start} 之前。` })) return false;
      ctx.guard();
      await coordinator.compression.restoreBatch(state, [...new Set(affected.map((slice) => slice.batch.id))]);
      ctx.guard();
      await coordinator.resetFrom(start);
      break;
    }
    case "delete": {
      if (!await confirmAction({ title: `删除 ${slices.length} 个切片？`, danger: true, confirmLabel: "删除",
        message: `涉及 ${batches.length} 个批次。整个批次被清空时，它的批次总结也会删除。可在“系统维护 → 备份与撤销”中撤销。` })) return false;
      const policy = state.catalog.compression.deletionPolicy;
      const restore = policy === "restore_first" || (policy === "confirm_restore" && await choose({
        title: "同时恢复这些批次的原消息？", cancelValue: false,
        choices: [{ value: false, label: "保持隐藏" }, { value: true, label: "恢复原消息", variant: "primary", focus: true }],
      }));
      ctx.guard();
      await ctx.run("删除总结切片", () => coordinator.deleteSlices(slices.map((slice) => slice.id), restore));
      break;
    }
  }
  return true;
}

export const BATCH_ACTIONS: Array<{ action: BatchAction; label: string; icon: string; danger?: boolean }> = [
  { action: "rebuild", label: "重新总结", icon: "rotate" },
  { action: "representation", label: "重建检索表示", icon: "file-lines" },
  { action: "sync", label: "同步索引", icon: "arrows-rotate" },
  { action: "restore", label: "恢复原消息", icon: "eye" },
  { action: "hide", label: "重新隐藏", icon: "eye-slash" },
  { action: "reset", label: "从最早批次重置", icon: "rotate-left", danger: true },
  { action: "delete", label: "删除切片", icon: "trash", danger: true },
];
