import type { MemoryRow, MemoryTypeDefinition } from "../../../../shared/domain";
import { renderContinuity } from "../../../../shared/continuity";
import { h, formatTime } from "../../kit/dom";
import { button, menu } from "../../kit/controls";
import { kv, muted, code } from "../../kit/layout";
import { saveBar } from "../../kit/save";
import { confirmAction } from "../../kit/overlays";
import type { Drawer } from "../../kit/drawer";
import type { PageContext } from "../../shell/context";
import { editContinuity, stateBadge } from "../shared";
import { memoryStore, rowForm, rowInput, yamlModal, displayValue } from "./row-editor";
import { reclassifyRow } from "./type-actions";

const SOURCE = { manual: "手动", extraction: "模型提取", migration: "导入或迁移" } as const;

/** Opens an entry in the drawer, read-only first; "编辑" swaps in the form in place. */
export function showRow(ctx: PageContext, pane: Drawer, types: MemoryTypeDefinition[], type: MemoryTypeDefinition,
  row: MemoryRow, editing = false): Promise<boolean> {
  const done = () => ctx.refresh();
  const actions = [
    editing ? null : button("编辑", () => showRow(ctx, pane, types, type, row, true), { icon: "pen", small: true }),
    menu(`${row.dataName} 的更多操作`, [
      { label: "编辑 YAML", icon: "code", onSelect: () => yamlModal(type, row, ctx.guard, done) },
      { label: "时间与认知", icon: "clock", onSelect: () => editContinuity(`${row.dataName} · 时间与认知`, row.continuity,
        async (continuity) => { ctx.guard(); await memoryStore.saveRow(type.id, { ...row, continuity }, row.id, row.revision); await done(); }) },
      { label: "重新分类到其他表", icon: "arrow-right-arrow-left", onSelect: () => reclassifyRow(types, row, ctx.guard, done) },
      { label: "删除条目", icon: "trash", danger: true, onSelect: async () => {
        if (!await confirmAction({ title: `删除条目「${row.dataName}」？`, message: "条目会从世界书移除，修改记录仍可在“历史”中查看。",
          confirmLabel: "删除", danger: true })) return;
        ctx.guard();
        await memoryStore.deleteRow(row.id);
        await pane.close();
        await done();
      } },
    ]),
  ];
  if (editing) {
    const target = rowForm(type, row);
    // Discarding (from the save bar or this button) returns to the read-only view.
    target.node.addEventListener("ec-reset", () => void showRow(ctx, pane, types, type, row));
    const cancel = button("取消编辑", () => target.dirty() ? target.reset() : showRow(ctx, pane, types, type, row),
      { variant: "ghost", small: true });
    return pane.open(row.id, row.dataName, [target.node, h("div", "ec-row", cancel), saveBar(target, async (values) => {
      ctx.guard();
      await memoryStore.saveRow(type.id, rowInput(type, values), row.id, row.revision);
      target.commit();
      await done();
    })], actions);
  }
  const filled = type.columns.filter((column) => displayValue(row.values[column.id]) !== "");
  const unfilled = type.columns.filter((column) => displayValue(row.values[column.id]) === "");
  const continuity = renderContinuity(row.continuity);
  return pane.open(row.id, row.dataName, [
    kv([
      ["表", type.name], ["激活方式", stateBadge(row.status)],
      ["关键词", row.keywords.join("、") || "—"], ["别名", row.aliases?.join("、") || "—"],
      ["来源", SOURCE[row.source.kind]], ["修订", `第 ${row.revision} 版 · ${formatTime(row.updatedAt)}`],
      ...(row.enabled ? [] : [["世界书条目", "已停用（表停用或内容非当前事实）"] as [string, string]]),
    ]),
    continuity ? h("div", "ec-field-block", h("h4", "", "时间与认知"), code(continuity)) : null,
    ...filled.map((column) => h("div", "ec-field-block", h("h4", "", column.name), h("div", "ec-prose", displayValue(row.values[column.id])))),
    filled.length ? null : muted("这个条目还没有填写任何字段。"),
    unfilled.length ? h("details", "ec-disclosure", h("summary", "", `未填写的 ${unfilled.length} 个字段`),
      h("p", "ec-muted", unfilled.map((column) => column.name).join("、"))) : null,
  ], actions);
}
