import type { SummarySlice } from "../../../../shared/domain";
import type { SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { h, isAbort, errorText } from "../../kit/dom";
import { button, badge, switchControl } from "../../kit/controls";
import { callout, empty, muted } from "../../kit/layout";
import { form } from "../../kit/forms";
import { modal, formModal, confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";

type Overview = NonNullable<SummaryWorldbookState["batchOverviews"]>[number];

export function overviewLabel(overview: Overview | undefined): [string, "neutral" | "success" | "warning" | "danger"] {
  if (!overview) return ["批次总结未生成", "neutral"];
  if (overview.state === "failed") return ["批次总结失败", "danger"];
  if (overview.state === "pending") return ["批次总结待生成", "warning"];
  return overview.enabled ? ["批次总结常驻", "success"] : ["批次总结已关闭", "neutral"];
}

/** View, toggle, edit or regenerate one batch's overview. */
export function openBatchOverview(ctx: PageContext, state: SummaryWorldbookState, batch: SummarySlice["batch"]): void {
  const overview = state.batchOverviews?.find((item) => item.batch.id === batch.id);
  const [label, tone] = overviewLabel(overview);
  const stale = batch.state === "stale" || (overview !== undefined && overview.batch.sourceHash !== batch.sourceHash);
  const view = modal(`批次 ${batch.batchNumber} 的批次总结`, [
    h("div", "ec-row", badge(label, tone), overview ? switchControl("常驻注入", overview.enabled, async (enabled) => {
      ctx.guard();
      await ctx.summary.store.saveBatchOverview(state, batch.id, { enabled });
      await ctx.refresh();
    }) : null),
    overview?.error ? callout("danger", overview.error) : null,
    stale ? callout("warning", "原消息已变化；这里仍保留旧的批次总结，请核对后重建批次。") : null,
    overview?.content && overview.state !== "ready" ? callout("info", "当前显示的是上一次成功生成的正文。") : null,
    overview?.content ? h("div", "ec-prose", overview.content) : empty("还没有批次总结正文。"),
  ], { size: "large", extra: [
    button("编辑", () => {
      const target = form([{ key: "content", label: "正文", type: "textarea", rows: 18, value: overview?.content ?? "", required: true }], { className: "is-single" });
      formModal(`编辑批次 ${batch.batchNumber} 的批次总结`, target, async (values) => {
        ctx.guard();
        await ctx.summary.store.saveBatchOverview(state, batch.id, { content: values.content.trim(), state: "ready" });
        await view.close(true);
        await ctx.refresh();
      }, { size: "large" });
    }, { icon: "pen" }),
    button(overview?.content ? "重新生成" : "生成", async () => {
      if (!await confirmAction({ title: "生成批次总结？", message: "单独调用总结端点，不会重新生成切片。", cost: true, confirmLabel: "生成" })) return;
      await view.close(true);
      await ctx.run("生成批次总结", () => ctx.summary.regenerateBatchOverview(batch.id), () => ctx.summary.stop());
      await ctx.refresh();
    }, { variant: "primary", icon: "rotate" }),
  ] });
}

/** Generates overviews for many batches one by one, with live progress and stop. */
export function bulkOverviews(ctx: PageContext, state: SummaryWorldbookState, slices: SummarySlice[]): void {
  const batchIds = [...new Set(slices.map((slice) => slice.batch.id))];
  const target = form([{ key: "mode", label: "生成范围", type: "select", value: "missing",
    options: [["missing", "只补全缺失、待生成或失败的"], ["all", "重新生成全部所选批次"]] }], { track: false, className: "is-single" });
  const count = muted("");
  const progress = h("p", "ec-muted");
  progress.setAttribute("role", "status");
  let control: AbortController | undefined;
  const targets = () => ctx.summary.batchOverviewTargets(state, batchIds, target.control("mode").value === "missing");
  const update = () => {
    const eligible = targets().length;
    count.textContent = `所选 ${batchIds.length} 个批次，将生成 ${eligible} 个，跳过 ${batchIds.length - eligible} 个。`;
    start.disabled = Boolean(control) || eligible === 0;
  };
  const stop = button("停止", () => control?.abort(), { variant: "danger", icon: "stop", disabled: true });
  const start = button("开始生成", async () => {
    const selected = targets();
    const onlyMissing = target.control("mode").value === "missing";
    if (!await confirmAction({ title: `为 ${selected.length} 个批次生成批次总结？`, cost: true, confirmLabel: "开始",
      message: `逐批调用总结端点，失败时停止后续批次。${onlyMissing ? "" : "已有正文会在生成成功后被替换。"}` })) return;
    const cancellation = new AbortController();
    control = cancellation;
    target.control("mode").disabled = true;
    stop.disabled = false;
    update();
    try {
      await ctx.run(`批量生成批次总结 · ${selected.length} 个`, () => ctx.summary.regenerateBatchOverviews(selected.map((batch) => batch.id), {
        onlyMissing, signal: cancellation.signal,
        onProgress: (done, total, number) => { progress.textContent = done === total ? `已完成 ${done} / ${total}` : `已完成 ${done} / ${total}，正在处理批次 ${number}`; },
      }), async () => cancellation.abort());
      progress.textContent += "。";
    } catch (error) {
      progress.textContent = cancellation.signal.aborted || isAbort(error) ? "已停止；已完成的批次总结保留。" : errorText(error);
    } finally {
      control = undefined;
      target.control("mode").disabled = false;
      stop.disabled = true;
      update();
    }
  }, { variant: "primary", icon: "play" });
  target.control("mode").addEventListener("change", update);
  update();
  modal("批量生成批次总结", [target.node, count, progress], { extra: [stop, start], onClose: () => void ctx.refresh() });
}
