class RecallRunSupersededError extends Error {
  constructor() {
    super("Recall request was superseded by a newer run.");
    this.name = "RecallRunSupersededError";
  }
}

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);
const GENERATION_TYPES = new Set(["chat", "normal", "continue", "regenerate", "swipe", "impersonate"]);

type RecallDecision = "continue" | "degraded" | "abort";

interface ResolvedSource {
  state: SummaryWorldbookState;
  collectionId: string;
  trace: RetrievalTraceSource;
}

export interface RecallResult {
  retainedSlices?: SummarySlice[] | undefined;
  hits: RetrievalHit[];
  recentSlices: SummarySlice[];
  trace: RetrievalTrace;
}

const DISABLED_BRANCHES: RetrievalQueryResult["branches"] = {
  vector: { state: "disabled", durationMs: 0, attempts: [] },
  bm25: { state: "disabled", durationMs: 0, attempts: [] },
  rerank: { state: "disabled", durationMs: 0, attempts: [] },
};

function renderRecentSummaries(slices: SummarySlice[]): string {
  const batches = new Map<string, SummarySlice[]>();
  for (const slice of slices) {
    const current = batches.get(slice.batch.id) ?? [];
    current.push(slice);
    batches.set(slice.batch.id, current);
  }
  return [...batches.values()].map((items) => {
    const sorted = [...items].sort((left, right) => left.sliceNumber - right.sliceNumber);
    return `[近期总结 第 ${sorted[0]!.batch.batchNumber} 批]\n${sorted
      .map((slice) => `[${slice.timestamp}] [${slice.title}]\n${renderSummaryBody(slice)}`)
      .join("\n\n")}`;
  }).join("\n\n");
}

export function renderInjectionTemplate(
  template: string,
  recentSummaries: string,
  memories: string,
): string {
  let rendered = template;
  const hasRecentPlaceholder = rendered.includes("{{recent_summaries}}");
  const hasMemoriesPlaceholder = rendered.includes("{{memories}}");
  rendered = rendered
    .replaceAll("{{recent_summaries}}", recentSummaries)
    .replaceAll("{{memories}}", memories);
  if (recentSummaries && !hasRecentPlaceholder) {
    rendered = `近期剧情总结：\n${recentSummaries}\n\n${rendered}`;
  }
  if (memories && !hasMemoriesPlaceholder) rendered = `${rendered}\n\n${memories}`;
  return rendered.trim();
}

function sleep(durationMs: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, durationMs));
}

async function waitForJob<TResult>(
  initial: JobRecord<TResult>,
  maxWaitMs: number,
): Promise<JobRecord<TResult> | null> {
  let job = initial;
  const deadline = Date.now() + maxWaitMs;
  while (!TERMINAL_STATES.has(job.status) && Date.now() < deadline) {
    await sleep(400);
    job = await echoesApi.getJob<TResult>(job.id);
  }
  if (!TERMINAL_STATES.has(job.status)) {
    await echoesApi.cancelJob(job.id).catch(() => undefined);
    return null;
  }
  if (job.status !== "succeeded" || !job.result) {
    throw new Error(job.error?.message ?? job.message);
  }
  return job;
}

function openDecisionDialog(options: {
  message: string;
  canContinue: boolean;
  degradedLabel?: string;
}): Promise<RecallDecision> {
  return choose<RecallDecision>({
    title: "召回请求结果不确定",
    message: options.message === "The provider may have completed and billed this request. Continue with the next endpoint only after confirmation."
      ? "供应商可能已完成本次请求并计费，但未能确认返回结果。切换下一端点会重新发起请求。"
      : options.message,
    cost: true,
    cancelValue: "degraded",
    choices: [
      { value: "abort", label: "中止生成", variant: "danger" },
      { value: "continue", label: "切换下一端点", disabled: !options.canContinue },
      { value: "degraded", label: options.degradedLabel ?? "使用已有 BM25/RRF 结果", variant: "primary", focus: true },
    ],
  });
}

function generationIdentity() {
  const context = SillyTavern.getContext();
  const character = context.characters?.[context.characterId ?? -1] ?? {};
  return {
    characterName: String(character.name ?? "Character"),
    characterDescription: String(character.description ?? ""),
    userName: String(context.powerUserSettings?.persona_name ?? context.name1 ?? "User"),
    personaDescription: String(context.powerUserSettings?.persona_description ?? ""),
  };
}

function sourcePreference(
  state: SummaryWorldbookState,
  attached?: AttachedRecallSource,
): Pick<RetrievalTraceSource, "weight" | "order" | "addWeight"> {
  return attached
    ? { weight: attached.weight, addWeight: attached.addWeight ?? 0, order: attached.order }
    : {
        weight: state.catalog.recallSourceWeight,
        addWeight: state.catalog.recallSourceAddWeight ?? 0,
        order: state.catalog.recallSourceOrder,
      };
}

function recallFloorKey(generationType: string): string {
  const chat = SillyTavern.getContext().chat;
  const tail = chat.at(-1);
  const replacesAssistant = ["regenerate", "swipe", "continue"].includes(generationType)
    && tail && tail.is_user !== true && tail.role !== "user";
  // Regeneration/continuation targets the existing assistant floor, even before ST removes it.
  const length = chat.length - (replacesAssistant ? 1 : 0);
  const preceding = chat[length - 1];
  return `${length}:${String(preceding?.message_id ?? preceding?.id ?? "")}`;
}

export class RecallCoordinator {
  readonly summaryStore = new SummaryWorldbookStore();
  readonly injectionStore = new RecallWorldbookStore();
  private runSequence = 0;
  private activeJobId: string | null = null;
  private previewSequence = 0;
  private previewJobId: string | null = null;
  private lastTrace: RetrievalTrace | null = null;
  private readonly traces: RetrievalTrace[] = [];
  private lastInjection: { worldbookName: string; token: symbol } | null = null;

  private unwatch: (() => void) | undefined;
  private watchSources(current: SummaryWorldbookState): void {
    this.unwatch?.();
    const names = new Set([current.worldbookName, ...current.catalog.attachedRecallSources
      .filter((source) => source.enabled).map((source) => source.worldbookName)]);
    this.unwatch = onRecallInvalidated((name) => {
      if (name && !names.has(name)) return;
      void this.clear().catch((error) => console.warn("[Echoes] 清理过期召回失败", error));
    });
  }

  get trace(): RetrievalTrace | null {
    return this.lastTrace ? structuredClone(this.lastTrace) : null;
  }

  history(): RetrievalTrace[] {
    return structuredClone(this.traces.filter((trace) => trace.chatId === SillyTavern.getContext().chatId));
  }

  clearHistory(): void {
    this.traces.length = 0;
    this.lastTrace = null;
  }

  async sourceOverview(): Promise<{
    current: SummaryWorldbookState;
    available: SummaryWorldbookState[];
    sources: RetrievalTraceSource[];
  }> {
    const current = await this.summaryStore.load();
    const available = await this.summaryStore.listAvailableSources();
    const settings = getSettings();
    const group = this.embeddingGroup();
    const collections = await echoesApi.listRetrievalCollections();
    const collectionMap = new Map(collections.map((item) => [item.collection.id, item.collection]));
    const { traces } = await this.resolveSources(current, available, collectionMap, group, settings.retrieval.recall.vectorEnabled);
    return { current, available, sources: traces };
  }

  async runInterceptor(
    chat: Array<Record<string, unknown>>,
    type: string | undefined,
    abort?: (() => void) | undefined,
  ): Promise<void> {
    const generationType = type ?? "normal";
    if (!GENERATION_TYPES.has(generationType)) {
      try {
        await this.clear();
      } catch (error) {
        console.error("[Echoes] 清理召回注入失败", error);
        toastr.warning(error instanceof Error ? error.message : String(error), "Echoes 旧召回注入清理失败");
      }
      return;
    }
    const sequence = ++this.runSequence;
    this.previewSequence += 1;
    const previewJobId = this.previewJobId;
    if (previewJobId) {
      this.previewJobId = null;
      await echoesApi.cancelJob(previewJobId).catch(() => undefined);
    }
    if (sequence !== this.runSequence) return;
    const activeJobId = this.activeJobId;
    if (activeJobId) {
      this.activeJobId = null;
      await echoesApi.cancelJob(activeJobId).catch(() => undefined);
    }
    if (sequence !== this.runSequence) return;
    try {
      await this.retrieve(chat, generationType, sequence, true, abort);
    } catch (error) {
      if (error instanceof RecallRunSupersededError || sequence !== this.runSequence) return;
      let clearFailure = "";
      try {
        await this.clear();
      } catch (clearError) {
        console.error("[Echoes] 清理召回注入失败", clearError);
        clearFailure = `；旧召回注入清理失败：${clearError instanceof Error ? clearError.message : String(clearError)}`;
      }
      if (this.runSequence !== sequence + 1) return;
      const message = (error instanceof Error ? error.message : String(error)) + clearFailure;
      const decision = await openDecisionDialog({
        message,
        canContinue: false,
        degradedLabel: "无记忆继续",
      });
      if (decision === "abort") abort?.();
      else toastr.warning(message, "Echoes 召回已降级");
    }
  }

  async preview(chat = SillyTavern.getContext().chat, queryOverride?: string): Promise<RecallResult> {
    if (this.activeJobId) throw new Error("主生成召回正在运行，请稍后再预览。");
    const sequence = ++this.previewSequence;
    const previewJobId = this.previewJobId;
    if (previewJobId) {
      this.previewJobId = null;
      await echoesApi.cancelJob(previewJobId).catch(() => undefined);
    }
    if (sequence !== this.previewSequence) throw new RecallRunSupersededError();
    return queryOverride === undefined
      ? this.retrieve(chat, "preview", sequence, false)
      : this.retrieve(chat, "preview", sequence, false, undefined, queryOverride);
  }

  async supplementPreview(query: string, signal?: AbortSignal): Promise<{
    slices: Array<{ slice: SummarySlice; worldbookName: string; chatId: string }>;
    calls: number; messages: string[];
  }> {
    if (this.activeJobId) throw new Error("主生成召回正在运行，请稍后再补充检索。");
    const sequence = ++this.previewSequence;
    if (this.previewJobId) await echoesApi.cancelJob(this.previewJobId).catch(() => undefined);
    const worldbookName = window.TavernHelper?.getChatWorldbookName("current");
    if (!worldbookName) throw new Error("请先建立总结记忆。");
    const chatId = SillyTavern.getContext().chatId;
    const guard = () => {
      signal?.throwIfAborted();
      if (sequence !== this.previewSequence || chatId !== SillyTavern.getContext().chatId
        || window.TavernHelper?.getChatWorldbookName("current") !== worldbookName) throw new RecallRunSupersededError();
    };
    guard();
    const settings = getSettings(), recall = settings.retrieval.recall;
    const config = settings.continuity.supplement;
    const current = await this.summaryStore.inspect(worldbookName);
    this.watchSources(current);
    const available = await this.summaryStore.attachedSources(current);
    const collections = await echoesApi.listRetrievalCollections();
    const group = this.embeddingGroup();
    const resolved = await this.resolveSources(current, available,
      new Map(collections.map((item) => [item.collection.id, item.collection])), group, recall.vectorEnabled);
    guard();
    if (!resolved.active.length) throw new Error("没有可检索的总结集合。");
    const expected = new Map([current, ...resolved.active.map((source) => source.state)]
      .map((state) => [state.worldbookName, recallSourceFingerprint(state)]));
    const checkSources = async () => {
      for (const [name, fingerprint] of expected) {
        const state = await this.summaryStore.inspect(name);
        if (recallSourceFingerprint(state) !== fingerprint) throw new RecallRunSupersededError();
      }
    };
    const vectorCollectionIds = resolved.active.filter((source) => source.trace.mode === "vector_bm25").map((source) => source.collectionId);
    const rerankSet = settings.retrieval.rerankSets.find((set) => set.id === recall.rerankSetId);
    const rerankEnabled = recall.rerankEnabled && Boolean(rerankSet);
    const result = await boundedSupplement({
      queries: [balancedQueryText(query.trim(), 12000)], config, guard,
      ...(signal ? { signal } : {}),
      track: (id) => { if (sequence === this.previewSequence) this.previewJobId = id; },
      request: {
        query: balancedQueryText(query.trim(), 12000),
        collectionIds: resolved.active.map((source) => source.collectionId), vectorCollectionIds,
        sourceWeights: resolved.active.map((source) => ({ collectionId: source.collectionId,
          weight: source.trace.weight, addWeight: source.trace.addWeight ?? 0, order: source.trace.order })),
        excludeSourceIds: [...new Set(resolved.active.flatMap((source) => [
          ...source.state.catalog.pendingRetrievalDeletes,
          ...source.state.slices.filter((slice) => slice.batch.state === "stale" || slice.continuity?.validity === "superseded").map((slice) => slice.id),
        ]))],
        flagRules: recall.flagRules,
        flagAssignments: resolved.active.flatMap((source) => source.state.slices.filter((slice) => slice.recallFlags?.length)
          .map((slice) => ({ collectionId: source.collectionId, sourceId: slice.id, flags: slice.recallFlags! }))),
        minimumRelevance: recall.relevanceProfiles?.[rerankEnabled ? `rerank:${recall.rerankSetId}` : "rrf"] ?? recall.minimumRelevance,
        fallbackMinimumRelevance: recall.relevanceProfiles?.rrf ?? recall.minimumRelevance,
        vectorEnabled: recall.vectorEnabled && Boolean(group) && vectorCollectionIds.length > 0,
        bm25Enabled: true, rerankEnabled,
        vectorTopK: recall.vectorTopK, bm25TopK: recall.bm25TopK, rerankTopK: recall.rerankTopK,
        finalTopK: config.maxItems, failoverPolicy: "confirm_ambiguous",
        ...(group ? { embeddingGroup: group } : {}), ...(rerankSet ? { rerankSet } : {}),
      },
    });
    guard();
    await checkSources();
    const authoritative = await authoritativeRecallHits(result.hits,
      resolved.active.map((source) => ({ collectionId: source.collectionId, slices: source.state.slices,
        worldbookName: source.state.worldbookName, chatId: source.state.catalog.chatId })));
    await checkSources();
    guard();
    if (authoritative.issues.length) console.warn("[Echoes] 补充召回源校验排除", authoritative.issues);
    return { calls: result.calls, messages: [...result.messages, ...authoritative.issues.map((issue) =>
      `${issue.chatId ?? issue.collectionId} / ${issue.title ?? issue.sliceId}：${issue.reason}；${issue.action}。`)],
      slices: authoritative.hits.map((hit) => {
        const source = resolved.active.find((source) => source.collectionId === hit.document.collectionId)!;
        return { slice: source.state.slices.find((slice) => slice.id === hit.document.sourceId)!,
          worldbookName: source.state.worldbookName, chatId: source.state.catalog.chatId };
      }) };
  }

  async clear(): Promise<void> {
    this.unwatch?.();
    this.unwatch = undefined;
    this.runSequence += 1;
    this.previewSequence += 1;
    const ownership = this.lastInjection;
    const activeJobId = this.activeJobId;
    if (activeJobId) {
      this.activeJobId = null;
      await echoesApi.cancelJob(activeJobId).catch(() => undefined);
    }
    const previewJobId = this.previewJobId;
    if (previewJobId) {
      this.previewJobId = null;
      await echoesApi.cancelJob(previewJobId).catch(() => undefined);
    }
    const worldbookName = ownership?.worldbookName
      ?? window.TavernHelper?.getChatWorldbookName("current")
      ?? null;
    // A failed clear keeps ownership so the next clear retries the same worldbook.
    if (worldbookName) await this.injectionStore.clear(worldbookName);
    if (this.lastInjection === ownership) this.lastInjection = null;
  }

  private async retrieve(
    chat: Array<Record<string, unknown>>,
    generationType: string,
    sequence: number,
    inject: boolean,
    abort?: (() => void) | undefined,
    queryOverride?: string,
  ): Promise<RecallResult> {
    const startedAt = new Date().toISOString();
    const floorKey = recallFloorKey(generationType);
    const sourceSnapshots = new Map<string, string>();
    const settingsSnapshot = JSON.stringify([getSettings().retrieval, getSettings().continuity, getSettings().summary.embeddingGroupId]);
    const assertFresh = async () => {
      if (sequence !== (generationType === "preview" ? this.previewSequence : this.runSequence)
        || settingsSnapshot !== JSON.stringify([getSettings().retrieval, getSettings().continuity, getSettings().summary.embeddingGroupId])) {
        throw new RecallRunSupersededError();
      }
      for (const [name, expected] of sourceSnapshots) {
        const fresh = await this.summaryStore.inspect(name);
        if (recallSourceFingerprint(fresh) !== expected) throw new RecallRunSupersededError();
      }
      if (sequence !== (generationType === "preview" ? this.previewSequence : this.runSequence)) throw new RecallRunSupersededError();
    };
    const remember = (state: SummaryWorldbookState) => {
      sourceSnapshots.set(state.worldbookName, recallSourceFingerprint(state));
    };
    const finalize = (options: Parameters<RecallCoordinator["finalizeRecall"]>[0]) =>
      this.finalizeRecall({ ...options, floorKey, queryBlocks: prepared.blocks, abort, assertFresh });
    const settings = getSettings();
    const recall = settings.retrieval.recall;
    const continuity = settings.continuity;
    const existingWorldbook = window.TavernHelper?.getChatWorldbookName("current");
    if (!inject && !existingWorldbook) throw new Error("请先建立当前聊天的总结记忆。");
    const current = inject ? await this.summaryStore.load() : await this.summaryStore.inspect(existingWorldbook!);
    remember(current);
    this.watchSources(current);
    const lockedWorldbookName = current.worldbookName;
    if (inject) {
      await this.injectionStore.cleanupStale(lockedWorldbookName);
      await this.injectionStore.clear(lockedWorldbookName);
    }
    if (inject) this.lastInjection = { worldbookName: lockedWorldbookName, token: Symbol() };

    let queryState: Record<string, unknown> | undefined;
    if (!queryOverride && (continuity.triggers.enabled || recall.queryPreset.items.some((item) => item.enabled && ["scene", "participants", "commitments"].includes(item.kind)))) {
      const state = await statusCoordinator.worldbook.find(current.worldbookName);
      queryState = state ? await statusCoordinator.generationState(state, generationType) : undefined;
    }
    const prepared = prepareRecallQuery({
      state: queryState,
      chat,
      preset: queryOverride === undefined ? recall.queryPreset : {
        ...recall.queryPreset, mode: "combined",
        items: [{ id: "evaluation", kind: "custom", title: "测试查询", enabled: true, content: queryOverride }],
      },
      ...generationIdentity(),
    });
    if (!queryOverride && continuity.triggers.enabled) {
      const triggers = statusTriggerQueries(queryState, continuity.triggers.nearDays)
        .filter((trigger) => !prepared.queries.some((query) => query.text.includes(trigger.text)))
        .slice(0, Math.min(continuity.triggers.maxQueries, 8 - prepared.queries.length));
      prepared.queries.push(...triggers);
      const budget = recall.queryPreset.maxCharacters ?? 12000;
      const perQuery = Math.max(1, Math.floor((budget - Math.max(0, prepared.queries.length - 1) * 2) / Math.max(1, prepared.queries.length)));
      prepared.queries = prepared.queries.map((query) => ({ ...query, text: balancedQueryText(query.text, perQuery) }));
      prepared.query = prepared.queries.map((query) => query.text).join("\n\n");
      if (triggers.length) {
        prepared.messageIds = [];
        prepared.blocks = prepared.queries.map((query) => ({ id: query.id, title: query.id.startsWith("trigger_") ? "状态触发" : "查询", content: query.text }));
      }
    }
    const compressionActive = current.catalog.recallEnabled
      && current.catalog.compression.enabled;
    const recentBatches = compressionActive
      ? recentSummaryBatches(current.slices, current.catalog.compression.recentBatchCount, currentChatMessages())
      : [];
    const recentSlices = recentBatches.flatMap((coverage) => coverage.slices).filter((slice) => slice.continuity?.validity !== "superseded");
    if (!current.catalog.recallEnabled || !prepared.query) {
      return finalize({
        current,
        sequence,
        inject,
        generationType,
        startedAt,
        query: prepared.query,
        sources: [],
        branches: DISABLED_BRANCHES,
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices: current.catalog.recallEnabled ? recentSlices : [],
        message: current.catalog.recallEnabled ? "Recall query is empty." : "Recall is disabled.",
      });
    }

    const group = this.embeddingGroup();
    const rerankSet = settings.retrieval.rerankSets.find((set) => set.id === recall.rerankSetId);
    const available = await this.summaryStore.attachedSources(current);
    let collectionStats;
    try {
      collectionStats = await echoesApi.listRetrievalCollections();
    } catch (error) {
      if (recentSlices.length === 0 && !current.catalog.recallPool?.entries.length
        && !current.catalog.recallPool?.replay.length) throw error;
      const message = error instanceof Error ? error.message : String(error);
      toastr.warning(message, "Echoes 语义召回失败");
      return finalize({
        current,
        sequence,
        inject,
        generationType,
        startedAt,
        query: prepared.query,
        sources: [],
        branches: {
          vector: { state: "failed", durationMs: 0, attempts: [], message },
          bm25: { state: "failed", durationMs: 0, attempts: [], message },
          rerank: { state: "disabled", durationMs: 0, attempts: [] },
        },
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message,
      });
    }
    const collectionMap = new Map(collectionStats.map((item) => [item.collection.id, item.collection]));
    const resolved = await this.resolveSources(
      current,
      available,
      collectionMap,
      group,
      recall.vectorEnabled,
    );
    if (resolved.active.length === 0) {
      return finalize({
        current,
        sequence,
        inject,
        generationType,
        startedAt,
        query: prepared.query,
        sources: resolved.traces,
        branches: DISABLED_BRANCHES,
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message: "No attached summary source has an available retrieval collection.",
      });
    }

    const vectorCollectionIds = resolved.active
      .filter((source) => source.trace.mode === "vector_bm25")
      .map((source) => source.collectionId);
    for (const source of resolved.active) remember(source.state);
    await assertFresh();
    const visibleIds = visibleRecallMessageIds(chat);
    const recentIds = new Set(prepared.messageIds.filter((id) => visibleIds.has(id)));
    const excludeSourceIds = excludedRecallSources(current, resolved.active.map((source) => source.state), recentIds);
    // Budget selection may omit a recent slice; do not exclude it before actual injection planning.

    const vectorEnabled = recall.vectorEnabled && Boolean(group) && vectorCollectionIds.length > 0;
    if (!vectorEnabled && !recall.bm25Enabled) {
      return finalize({
        current,
        sequence,
        inject,
        generationType,
        startedAt,
        query: prepared.query,
        sources: resolved.traces,
        branches: DISABLED_BRANCHES,
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message: "No enabled semantic retrieval branch can query the selected sources.",
      });
    }
    if (recall.rerankEnabled && !rerankSet) {
      return finalize({
        current,
        sequence,
        inject,
        generationType,
        startedAt,
        query: prepared.query,
        sources: resolved.traces,
        branches: DISABLED_BRANCHES,
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message: "Recall reranking is enabled but no rerank endpoint set is selected.",
      });
    }
    const candidateTopK = Math.min(100, Math.max(recall.finalTopK, recall.finalTopK * 3));
    const isSuperseded = () => inject
      ? sequence !== this.runSequence
      : sequence !== this.previewSequence;
    let trackedJobId: string | null = null;
    const trackJob = (jobId: string) => {
      trackedJobId = jobId;
      if (inject) this.activeJobId = jobId;
      else this.previewJobId = jobId;
    };
    const clearTrackedJob = () => {
      if (trackedJobId) {
        if (inject && this.activeJobId === trackedJobId) this.activeJobId = null;
        if (!inject && this.previewJobId === trackedJobId) this.previewJobId = null;
      }
      trackedJobId = null;
    };
    let job: JobRecord<RetrievalQueryResult>;
    let completed: JobRecord<RetrievalQueryResult> | null;
    let queryRequest: RetrievalQueryRequest;
    try {
      queryRequest = {
        collectionIds: resolved.active.map((source) => source.collectionId),
        vectorCollectionIds,
        sourceWeights: resolved.active.map((source) => ({
          collectionId: source.collectionId,
          weight: source.trace.weight,
          addWeight: source.trace.addWeight ?? 0,
          order: source.trace.order,
        })),
        excludeSourceIds: [...excludeSourceIds],
        minimumRelevance: recall.relevanceProfiles?.[recall.rerankEnabled ? `rerank:${recall.rerankSetId}` : "rrf"]
          ?? recall.minimumRelevance,
        fallbackMinimumRelevance: recall.relevanceProfiles?.rrf ?? recall.minimumRelevance,
        flagRules: recall.flagRules,
        flagAssignments: resolved.active.flatMap((source) => source.state.slices
          .filter((slice) => (slice.recallFlags?.length ?? 0) > 0 && !excludeSourceIds.has(slice.id))
          .map((slice) => ({ collectionId: source.collectionId, sourceId: slice.id, flags: slice.recallFlags! }))),
        query: prepared.query,
        queries: prepared.queries,
        vectorEnabled,
        bm25Enabled: recall.bm25Enabled,
        rerankEnabled: recall.rerankEnabled,
        vectorTopK: recall.vectorTopK,
        bm25TopK: recall.bm25TopK,
        finalTopK: candidateTopK,
        rerankTopK: recall.rerankTopK,
        failoverPolicy: settings.retrieval.failoverPolicy,
        ...(vectorEnabled && group ? { embeddingGroup: group } : {}),
        ...(recall.rerankEnabled && rerankSet ? { rerankSet } : {}),
      };
      job = await echoesApi.queryRetrieval(queryRequest);
      if (isSuperseded()) {
        await echoesApi.cancelJob(job.id).catch(() => undefined);
        throw new RecallRunSupersededError();
      }
      trackJob(job.id);
      completed = await waitForJob(job, recall.injection.maxWaitMs);
    } catch (error) {
      clearTrackedJob();
      if (error instanceof RecallRunSupersededError || isSuperseded()) throw new RecallRunSupersededError();
      if (recentSlices.length === 0 && !current.catalog.recallPool?.entries.length
        && !current.catalog.recallPool?.replay.length) throw error;
      const message = error instanceof Error ? error.message : String(error);
      toastr.warning(message, "Echoes 语义召回失败");
      return finalize({
        current,
        sequence,
        inject,
        generationType,
        startedAt,
        query: prepared.query,
        sources: resolved.traces,
        branches: {
          vector: { state: "failed", durationMs: 0, attempts: [], message },
          bm25: { state: "failed", durationMs: 0, attempts: [], message },
          rerank: { state: "disabled", durationMs: 0, attempts: [] },
        },
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message,
      });
    }
    if (isSuperseded()) throw new RecallRunSupersededError();
    if (!completed) {
      clearTrackedJob();
      const decision = inject
        ? await openDecisionDialog({
            message: `主检索任务等待超过 ${Math.round(recall.injection.maxWaitMs / 1_000)} 秒，Echoes 已取消本地任务，且不会自动轮换端点。`,
            canContinue: false,
            degradedLabel: "无记忆继续",
          })
        : "degraded";
      if (decision === "abort") abort?.();
      return finalize({
        current,
        sequence,
        inject: inject && decision !== "abort",
        generationType,
        startedAt,
        query: prepared.query,
        sources: resolved.traces,
        branches: {
          vector: { state: "failed", durationMs: 0, attempts: [], message: "Retrieval timed out." },
          bm25: { state: "failed", durationMs: 0, attempts: [], message: "Retrieval timed out." },
          rerank: { state: "disabled", durationMs: 0, attempts: [] },
        },
        rawReturned: 0,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message: "Retrieval timed out.",
      });
    }

    let result = completed.result!;
    while (result.decisionRequired) {
      if (isSuperseded()) throw new RecallRunSupersededError();
      const decision = inject
        ? await openDecisionDialog({
            message: result.decisionRequired.message,
            canContinue: Boolean(result.continuation),
          })
        : "degraded";
      if (isSuperseded()) throw new RecallRunSupersededError();
      if (decision === "abort") {
        abort?.();
        await this.injectionStore.clear(lockedWorldbookName);
        return finalize({
          current,
          sequence,
          inject: false,
          generationType,
          startedAt,
          query: prepared.query,
          sources: resolved.traces,
          branches: result.branches,
          diagnostics: result.diagnostics,
          rawReturned: result.hits.length,
          semanticHits: [],
          semanticSliceByDocumentId: new Map(),
          recentSlices,
          message: "Generation aborted after an ambiguous retrieval result.",
        });
      }
      if (decision === "degraded" || !result.continuation) break;
      try {
        job = await echoesApi.continueRetrievalQuery({
          token: result.continuation.token,
          failoverPolicy: settings.retrieval.failoverPolicy,
          ...(group ? { embeddingGroup: group } : {}),
          ...(rerankSet ? { rerankSet } : {}),
        });
        if (isSuperseded()) {
          await echoesApi.cancelJob(job.id).catch(() => undefined);
          throw new RecallRunSupersededError();
        }
        trackJob(job.id);
        completed = await waitForJob(job, recall.injection.maxWaitMs);
        if (!completed) break;
        result = completed.result!;
      } catch (error) {
        if (error instanceof RecallRunSupersededError || isSuperseded()) throw new RecallRunSupersededError();
        const message = error instanceof Error ? error.message : String(error);
        toastr.warning(message, "Echoes 召回续接失败");
        break;
      }
    }
    clearTrackedJob();

    const enabledBranches = [
      vectorEnabled ? result.branches.vector : null,
      recall.bm25Enabled ? result.branches.bm25 : null,
    ].filter((branch): branch is RetrievalQueryResult["branches"]["vector"] => Boolean(branch));
    if (result.hits.length === 0
      && enabledBranches.length > 0
      && enabledBranches.every((branch) => branch.state === "failed" || branch.state === "ambiguous")) {
      const decision = inject
        ? await openDecisionDialog({
            message: "向量和 BM25 分支均未返回可用结果。",
            canContinue: false,
            degradedLabel: "无记忆继续",
          })
        : "degraded";
      if (decision === "abort") abort?.();
      return finalize({
        current,
        sequence,
        inject: inject && decision !== "abort",
        generationType,
        startedAt,
        query: prepared.query,
        sources: resolved.traces,
        branches: result.branches,
        diagnostics: result.diagnostics,
        rawReturned: result.hits.length,
        semanticHits: [],
        semanticSliceByDocumentId: new Map(),
        recentSlices,
        message: "All retrieval branches failed.",
      });
    }

    await assertFresh();
    let authoritative = await authoritativeRecallHits(
      result.hits,
      resolved.active.map((source) => ({
        collectionId: source.collectionId,
        slices: source.state.slices,
        worldbookName: source.state.worldbookName,
        chatId: source.state.catalog.chatId,
      })),
    );
    const supplementMessages: string[] = [];
    if (continuity.supplement.auto && authoritative.hits.length < continuity.supplement.minimumHits && !result.decisionRequired) {
      const supplemental = await boundedSupplement({
        request: { ...queryRequest!, excludeSourceIds: [...excludeSourceIds, ...authoritative.hits.map((hit) => hit.document.sourceId)] },
        queries: supplementQueryVariants(prepared.queries.map((query) => query.text)),
        config: continuity.supplement,
        guard: () => {
          if (isSuperseded() || SillyTavern.getContext().chatId !== current.catalog.chatId
            || window.TavernHelper?.getChatWorldbookName("current") !== lockedWorldbookName) throw new RecallRunSupersededError();
        },
        track: (id) => id ? trackJob(id) : clearTrackedJob(),
      });
      supplementMessages.push(`补充请求 ${supplemental.calls} 次，候选 ${supplemental.hits.length} 条。`, ...supplemental.messages);
      const extra = await authoritativeRecallHits(supplemental.hits, resolved.active.map((source) => ({
        collectionId: source.collectionId, slices: source.state.slices,
        worldbookName: source.state.worldbookName, chatId: source.state.catalog.chatId,
      })));
      authoritative = { hits: [...authoritative.hits, ...extra.hits], dropped: [...authoritative.dropped, ...extra.dropped],
        issues: [...authoritative.issues, ...extra.issues],
        sliceByDocumentId: new Map([...authoritative.sliceByDocumentId, ...extra.sliceByDocumentId]) };
    }
    const hits = authoritative.hits.slice(0, recall.finalTopK);
    if (authoritative.issues.length > 0) {
      console.warn("[Echoes] 召回源校验排除", authoritative.issues);
      const reasons = [...new Set(authoritative.issues.map((issue) => issue.reason))].join("；");
      toastr.warning(`已跳过 ${authoritative.issues.length} 条召回索引：${reasons}。具体来源与处理建议见召回诊断和控制台日志。`, "Echoes");
    }
    return finalize({
      current,
      sequence,
      inject,
      generationType,
      startedAt,
      query: prepared.query,
      sources: resolved.traces,
      branches: result.branches,
      rawReturned: result.hits.length,
      semanticHits: hits,
      semanticSliceByDocumentId: authoritative.sliceByDocumentId,
      recentSlices,
      droppedSourceIds: authoritative.dropped,
      sourceIssues: authoritative.issues,
      diagnostics: result.diagnostics,
      ...(supplementMessages.length ? { message: supplementMessages.join("\n") } : {}),
      decisions: [
        ...authoritative.issues.map((issue) => ({ sliceId: issue.sliceId, reason: `${issue.reason}；${issue.action}` })),
        ...authoritative.hits.slice(recall.finalTopK).map((hit) => ({ sliceId: hit.document.sourceId, reason: "超过最终结果数" })),
        ...[...excludeSourceIds].slice(0, 500).map((sliceId) => ({ sliceId, reason: "近期已包含、待删除或已失效" })),
      ],
    });
  }

  private embeddingGroup(): EmbeddingEndpointGroup | undefined {
    const settings = getSettings();
    return settings.retrieval.embeddingGroups.find((group) =>
      group.id === settings.summary.embeddingGroupId);
  }

  private async resolveSources(
    current: SummaryWorldbookState,
    available: SummaryWorldbookState[],
    collectionMap: Map<string, { embeddingSpaceId: string; dimensions: number }>,
    group: EmbeddingEndpointGroup | undefined,
    vectorEnabled: boolean,
  ): Promise<{ active: ResolvedSource[]; traces: RetrievalTraceSource[] }> {
    const byWorldbook = new Map(available.map((state) => [state.worldbookName, state]));
    byWorldbook.set(current.worldbookName, current);
    const configured = [
      { state: current, attached: undefined },
      ...current.catalog.attachedRecallSources.map((attached) => ({
        state: byWorldbook.get(attached.worldbookName),
        attached,
      })),
    ];
    const traces: RetrievalTraceSource[] = [];
    const active: ResolvedSource[] = [];
    for (const configuredSource of configured) {
      const attached = configuredSource.attached;
      const state = configuredSource.state;
      const preference = state
        ? sourcePreference(state, attached)
        : { weight: attached?.weight ?? 1, order: attached?.order ?? 0 };
      const base = {
        chatId: state?.catalog.chatId ?? attached?.chatId ?? "",
        namespaceId: state?.catalog.namespaceId ?? attached?.namespaceId ?? "",
        worldbookName: state?.worldbookName ?? attached?.worldbookName ?? "",
        ...preference,
      };
      if (attached && !attached.enabled) {
        traces.push({ ...base, mode: "unavailable", message: "Source is disabled." });
        continue;
      }
      if (!state
        || (attached && (state.catalog.namespaceId !== attached.namespaceId
          || state.catalog.chatId !== attached.chatId))) {
        traces.push({ ...base, mode: "unavailable", message: "Summary worldbook is missing or changed." });
        continue;
      }
      const collectionId = state.catalog.retrievalCollectionId;
      const collection = collectionId ? collectionMap.get(collectionId) : undefined;
      if (!collectionId || !collection) {
        traces.push({ ...base, mode: "unavailable", message: "Summary retrieval collection is unavailable." });
        continue;
      }
      const compatible = vectorEnabled
        && Boolean(group)
        && collection.embeddingSpaceId === group!.embeddingSpaceId
        && collection.dimensions === group!.dimensions;
      const trace: RetrievalTraceSource = {
        ...base,
        collectionId,
        mode: compatible ? "vector_bm25" : "bm25_only",
      };
      traces.push(trace);
      active.push({ state, collectionId, trace });
    }
    active.sort((left, right) => left.trace.order - right.trace.order
      || left.trace.namespaceId.localeCompare(right.trace.namespaceId));
    return { active, traces };
  }

  private async finalizeRecall(options: {
    assertFresh?: () => Promise<void>;
    abort?: (() => void) | undefined;
    diagnostics?: RetrievalQueryResult["diagnostics"];
    queryBlocks?: RetrievalTrace["queryBlocks"];
    decisions?: RetrievalTrace["decisions"];
    sourceIssues?: RetrievalTrace["sourceIssues"];
    floorKey?: string;
    current: SummaryWorldbookState;
    sequence: number;
    inject: boolean;
    generationType: string;
    startedAt: string;
    query: string;
    sources: RetrievalTraceSource[];
    branches: RetrievalQueryResult["branches"];
    rawReturned: number;
    semanticHits: RetrievalHit[];
    semanticSliceByDocumentId: Map<string, SummarySlice>;
    recentSlices: SummarySlice[];
    droppedSourceIds?: string[];
    message?: string;
  }): Promise<RecallResult> {
    await options.assertFresh?.();
    const sequenceMatches = options.generationType === "preview"
      ? options.sequence === this.previewSequence
      : options.sequence === this.runSequence;
    const locked = sequenceMatches
      && SillyTavern.getContext().chatId === options.current.catalog.chatId
      && window.TavernHelper?.getChatWorldbookName("current") === options.current.worldbookName
      && (!options.floorKey || options.floorKey === recallFloorKey(options.generationType));
    const recall = getSettings().retrieval.recall;
    let retained: RetainableSlice[] = [];
    let retentionPool = options.current.catalog.recallPool;
    if (locked && options.current.catalog.recallEnabled
      && (options.current.catalog.recallPool || recall.flagRules?.some((flag) => flag.retentionTurns > 0))) {
      const current = await this.summaryStore.inspect(options.current.worldbookName);
      const availableSources = await this.summaryStore.attachedSources(current);
      const sources = [current, ...availableSources.filter((source) =>
        source.catalog.namespaceId !== current.catalog.namespaceId
        && current.catalog.attachedRecallSources.some((attached) => attached.enabled
          && attached.namespaceId === source.catalog.namespaceId && attached.worldbookName === source.worldbookName))];
      const available: RetainableSlice[] = sources.flatMap((source) => source.slices
        .filter((slice) => slice.batch.state !== "stale" && slice.continuity?.validity !== "superseded" && !source.catalog.pendingRetrievalDeletes.includes(slice.id))
        .map((slice) => ({ namespaceId: source.catalog.namespaceId, sliceId: slice.id, slice })));
      const selected = options.semanticHits.flatMap((hit) => {
        const source = sources.find((item) => item.catalog.retrievalCollectionId === hit.document.collectionId);
        return source ? [{ namespaceId: source.catalog.namespaceId, sliceId: hit.document.sourceId }] : [];
      });
      const result = advanceRecallPool({
        previous: current.catalog.recallPool,
        floorKey: options.floorKey ?? recallFloorKey(options.generationType), available, selected,
        alreadyIncluded: options.recentSlices.map((slice) => ({ namespaceId: current.catalog.namespaceId, sliceId: slice.id })),
        flags: recall.flagRules, maximum: recall.retentionMaxSlices,
      });
      retained = result.extras;
      retentionPool = result.pool;
    }
    const guard = () => {
      if (options.sequence !== (options.generationType === "preview" ? this.previewSequence : this.runSequence)
        || SillyTavern.getContext().chatId !== options.current.catalog.chatId
        || window.TavernHelper?.getChatWorldbookName("current") !== options.current.worldbookName
        || (options.floorKey && options.floorKey !== recallFloorKey(options.generationType))) throw new RecallRunSupersededError();
    };
    if (locked) guard();
    let injected = 0;
    let injectionText = "";
    let selectedRecent = options.recentSlices;
    let selectedHits = options.semanticHits;
    let selectedRetained = retained;
    let injectionBudget: RetrievalTrace["injectionBudget"];
    if (locked) {
      const worldbookEntries = await window.TavernHelper!.getWorldbook(options.current.worldbookName);
      const statusText = options.inject
        ? worldbookEntries
          .filter((entry) => entry.enabled && entry.extra?.echoes?.kind === "status_injection")
          .map((entry) => entry.content).join("\n\n")
        : await statusCoordinator.previewInjection();
      const batchOverviews = worldbookEntries.filter((entry) =>
        entry.enabled && entry.extra?.echoes?.kind === "summary_batch_overview" && entry.content.trim());
      const template = recall.injection.template;
      const repeatCount = (placeholder: string) => Math.max(1, template.split(placeholder).length - 1);
      const items: InjectionItem[] = [
        ...(statusText ? [{ id: "__status", title: "当前状态", category: "status" as const, text: statusText }] : []),
        ...batchOverviews.map((entry) => ({ id: `batch_overview:${entry.uid}`, title: entry.name,
          category: "batch_overview" as const, text: entry.content })),
        ...options.recentSlices.map((slice) => ({ id: `recent:${slice.id}`, title: slice.title,
          category: "recent" as const, text: renderRecentSummaries([slice]), repetitions: repeatCount("{{recent_summaries}}") })),
        ...options.semanticHits.map((hit, index) => {
          const slice = options.semanticSliceByDocumentId.get(hit.document.documentId)!;
          return { id: `semantic:${hit.document.documentId}`, title: slice.title, category: "semantic" as const,
            text: `[记忆 ${index + 1}：${slice.timestamp} · ${slice.title}]\n${renderSummaryBody(slice)}`,
            repetitions: repeatCount("{{memories}}") };
        }),
        ...retained.map(({ slice, namespaceId }) => ({ id: `retained:${namespaceId}:${slice.id}`, title: slice.title,
          category: "retained" as const, text: `[滞留记忆：${slice.timestamp} · ${slice.title}]\n${renderSummaryBody(slice)}` })),
      ];
      const overhead = renderInjectionTemplate(template, "", "");
      const recentPlan = planInjectionBudget(items.filter((item) => item.category !== "semantic"),
        overhead, recall.budget?.overflow === "abort" ? { ...recall.budget, maxTokens: 0 } : recall.budget);
      const duplicateSemanticIds = new Set(options.semanticHits.filter((hit) =>
        hit.document.collectionId === options.current.catalog.retrievalCollectionId
        && recentPlan.selected.has(`recent:${hit.document.sourceId}`))
        .map((hit) => `semantic:${hit.document.documentId}`));
      const uniqueItems = items.filter((item) => !duplicateSemanticIds.has(item.id));
      const plan = planInjectionBudget(uniqueItems, overhead, recall.budget);
      injectionBudget = plan.report;
      selectedRecent = options.recentSlices.filter((slice) => plan.selected.has(`recent:${slice.id}`));
      selectedHits = options.semanticHits.filter((hit) => plan.selected.has(`semantic:${hit.document.documentId}`)
        && !selectedRecent.some((slice) => slice.id === hit.document.sourceId && hit.document.collectionId === options.current.catalog.retrievalCollectionId));
      selectedRetained = retained.filter(({ slice, namespaceId }) => plan.selected.has(`retained:${namespaceId}:${slice.id}`));
      const recent = renderRecentSummaries(selectedRecent);
      const memories = selectedHits.map((hit, index) => {
        const slice = options.semanticSliceByDocumentId.get(hit.document.documentId)!;
        return `[记忆 ${index + 1}：${slice.timestamp} · ${slice.title}]\n${renderSummaryBody(slice)}`;
      }).join("\n\n");
      const retainedText = selectedRetained.map(({ slice }) => `[滞留记忆：${slice.timestamp} · ${slice.title}]\n${renderSummaryBody(slice)}`).join("\n\n");
      let content = !recent && !memories && !retainedText ? "" : [retainedText, renderInjectionTemplate(
        getSettings().retrieval.recall.injection.template,
        recent,
        memories,
      )].filter(Boolean).join("\n\n");
      // Batch overviews are already constant worldbook entries; count them without injecting a second copy.
      const actualEstimate = estimateInjectionTokens([content, statusText, ...batchOverviews.map((entry) => entry.content)]
        .filter(Boolean).join("\n\n"));
      if (recall.budget?.maxTokens && recall.budget.overflow !== "preserve_protected"
        && actualEstimate > recall.budget.maxTokens) {
        injectionBudget.blocked = true;
        injectionBudget.omitted = uniqueItems.map(({ id, title, category }) => ({ id, title, category, reason: "常驻内容与模板开销超出预算，本轮生成中止" }));
      }
      if (injectionBudget.blocked) {
        content = "";
        selectedRecent = [];
        selectedHits = [];
        selectedRetained = [];
        injectionBudget.injectedTokens = 0;
        injectionBudget.overflow = false;
        for (const category of injectionBudget.categories) category.injectedTokens = 0;
        if (options.inject) {
          guard();
          await statusCoordinator.clearInjection();
          guard();
          options.abort?.();
          toastr.warning("记忆注入预算不足，本轮生成已中止；正文与检查点保持不变。", "Echoes");
        }
      } else {
        injectionBudget.injectedTokens = actualEstimate;
        injectionBudget.overflow = Boolean(injectionBudget.limit && actualEstimate > injectionBudget.limit);
        if (options.inject && injectionBudget.overflow) {
          toastr.warning("记忆注入超出预算；按当前策略保留状态、批次总结、近期与滞留内容，普通召回已按预算筛选。", "Echoes");
        }
      }
      await options.assertFresh?.();
      guard();
      injectionText = content;
      if (content && options.inject) {
        await this.injectionStore.write({
          worldbookName: options.current.worldbookName,
          chatId: options.current.catalog.chatId,
          namespaceId: options.current.catalog.namespaceId,
          content,
          config: getSettings().retrieval.recall.injection,
          guard: async () => { guard(); await options.assertFresh?.(); guard(); },
        });
        injected = selectedRecent.length + selectedHits.length + selectedRetained.length;
      }
    }
    if (options.inject && locked && !injectionBudget?.blocked && options.current.catalog.recallEnabled && retentionPool) {
      await this.summaryStore.saveRecallPool(options.current.worldbookName, retentionPool, guard);
    }
    const recentBatchIds = [...new Set(options.recentSlices.map((slice) => slice.batch.id))];
    const trace: RetrievalTrace = {
      injectionBudget,
      diagnostics: options.diagnostics,
      queryBlocks: options.queryBlocks,
      decisions: options.decisions,
      sourceIssues: options.sourceIssues,
      injectionText,
      stages: [
        { name: "查询编排", count: options.queryBlocks?.length ?? 0 },
        { name: "向量候选", count: options.diagnostics?.counts.vector ?? 0 },
        { name: "BM25 候选", count: options.diagnostics?.counts.bm25 ?? 0 },
        { name: "融合候选", count: options.diagnostics?.counts.fused ?? 0 },
        { name: "后端筛选结果", count: options.rawReturned },
        { name: "源校验后的最终结果", count: options.semanticHits.length },
        { name: "近期总结", count: options.recentSlices.length },
        { name: "额外滞留", count: retained.length },
        { name: "预算排除切片", count: injectionBudget?.omitted.filter((item) =>
          item.category !== "status" && item.category !== "batch_overview").length ?? 0 },
        { name: options.inject ? "实际注入" : "预览注入（未写入）",
          count: options.inject ? injected : selectedHits.length + selectedRecent.length + selectedRetained.length },
      ],
      chatId: options.current.catalog.chatId,
      query: options.query,
      generationType: options.generationType,
      startedAt: options.startedAt,
      completedAt: new Date().toISOString(),
      sources: options.sources,
      branches: options.branches,
      returned: options.rawReturned,
      injected,
      semanticReturned: options.semanticHits.length,
      retainedSliceCount: retained.length,
      ...(retentionPool ? { retentionPool } : {}),
      recentBatchIds,
      recentSliceCount: options.recentSlices.length,
      compressionActive: options.current.catalog.recallEnabled
        && options.current.catalog.compression.enabled,
      droppedSourceIds: options.droppedSourceIds ?? [],
      ...(!locked
        ? { message: "Chat changed before retrieval completed; result was discarded." }
        : options.message
          ? { message: options.message }
          : {}),
    };
    if (options.generationType !== "preview") this.lastTrace = trace;
    if (locked) {
      this.traces.unshift(trace);
      this.traces.splice(10);
    }
    return {
      hits: selectedHits,
      retainedSlices: selectedRetained.map((item) => item.slice),
      recentSlices: structuredClone(selectedRecent),
      trace,
    };
  }

}

export const recallCoordinator = new RecallCoordinator();

export function installRecallInterceptor(): void {
  globalThis.EchoesRecallInterceptor = async (
    chat: Array<Record<string, unknown>>,
    _contextSize: number,
    abort: (() => void) | undefined,
    type: string | undefined,
  ) => {
    try {
      await prepareCreativePreferences(type);
    } catch (error) {
      abort?.();
      throw error;
    }
    try {
      await statusCoordinator.prepareInjection(type);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      try {
        await statusCoordinator.clearInjection();
        toastr.warning(message, "Echoes 状态注入已降级");
      } catch (clearError) {
        console.error("[Echoes] 清理状态注入失败", clearError);
        toastr.error(`${message}；旧状态注入清理失败：${clearError instanceof Error ? clearError.message : String(clearError)}`,
          "Echoes 状态注入已降级");
      }
    }
    await recallCoordinator.runInterceptor(chat, type, abort);
  };
}
