import { randomUuid, sha256Hex as sha256 } from "../../shared/crypto-compat";
import { batchOverviewSchema } from "../../shared/batch-overview";
import { batchOverviewEntry } from "../worldbook/batch-overview";
import type {
  ChatMessageInput,
  EchoesBackupMessageSwipe,
  EchoesBackupV1,
  EchoesBackupWorldbookEntry,
  RestoreMode,
  RestorePlan,
  RestoreResult,
  StatusSnapshot,
} from "../../shared/domain";
import { ECHOES_BUILD_INFO } from "../../shared/build-info";
import { sourceMessagesHash } from "../../shared/source-hash";
import {
  echoesBackupV1Schema,
  identifierSchema,
  memoryRowSourceSchema,
  statusCatalogSchema,
  statusSnapshotSchema,
  structuredMemoryCatalogSchema,
  summaryCatalogSchema,
  summarySliceSchema,
} from "../../shared/schemas";
import {
  getSettings,
  parseImportedSettings,
  redactedSettings,
  saveSettings,
  type EchoesSettings,
} from "../state/settings";
import { worldbookWriteCoordinator } from "../worldbook/worldbook-write-coordinator";
import { messageWriteCoordinator } from "../chat/message-write-coordinator";
import { aliasSchema, continuitySchema, currentFact } from "../../shared/continuity";
import { memoryHistorySchema } from "../worldbook/memory-history";
import { invalidateRecall } from "../recall-invalidation";

const MAX_BACKUP_BYTES = 100 * 1024 * 1024;
const TEMPORARY_KINDS = new Set(["retrieval_injection", "status_injection", "creative_preferences_injection"]);
const PERSISTENT_KINDS = new Set(["catalog", "row", "summary_catalog", "summary_slice", "summary_batch_overview", "status_catalog", "memory_history"]);

interface ChatDescriptor {
  index: number;
  stableId: string;
  role: EchoesBackupMessageSwipe["role"];
  swipeHashes: string[];
  selectedSwipe: number;
  message: Record<string, any>;
}

interface ChatMessagePatch {
  message_id: number;
  is_hidden: boolean;
  swipe_id: number;
  swipes: string[];
  swipes_data: Array<Record<string, any>>;
  swipes_info: Array<Record<string, any>>;
}

function helper(): TavernHelperApi & Required<Pick<TavernHelperApi, "setChatMessages">> {
  if (!window.TavernHelper?.setChatMessages) {
    throw new Error("Echoes backup restore requires TavernHelper message write APIs.");
  }
  return window.TavernHelper as TavernHelperApi & Required<Pick<TavernHelperApi, "setChatMessages">>;
}

function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, item]) => `${JSON.stringify(key)}:${stableJson(item)}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function transcriptShape(messages: EchoesBackupMessageSwipe[]): Array<Pick<EchoesBackupMessageSwipe, "role" | "swipeHashes">> {
  return messages.map(({ role: messageRole, swipeHashes }) => ({ role: messageRole, swipeHashes }));
}

function targetTranscriptShape(messages: ChatDescriptor[]): Array<{
  stableId: string;
  role: EchoesBackupMessageSwipe["role"];
  swipeHashes: string[];
  selectedSwipe: number;
}> {
  return messages.map(({ stableId: messageId, role: messageRole, swipeHashes, selectedSwipe }) => ({
    stableId: messageId,
    role: messageRole,
    swipeHashes,
    selectedSwipe,
  }));
}

async function targetTranscriptFingerprint(messages: ChatDescriptor[]): Promise<string> {
  return sha256(stableJson(targetTranscriptShape(messages)));
}

function role(message: Record<string, unknown>): EchoesBackupMessageSwipe["role"] {
  if (message.is_user === true || message.role === "user") return "user";
  if (message.role === "system") return "system";
  return "assistant";
}

function stableId(message: Record<string, unknown>, index: number): string {
  return String(message.message_id ?? message.id ?? index);
}

function swipeTexts(message: Record<string, any>): string[] {
  const swipes = Array.isArray(message.swipes) ? message.swipes.map(String) : [];
  if (swipes.length > 0) return swipes;
  return [String(message.mes ?? message.message ?? "")];
}

async function describeChat(chat = SillyTavern.getContext().chat): Promise<ChatDescriptor[]> {
  return Promise.all(chat.map(async (message, index) => ({
    index,
    stableId: stableId(message, index),
    role: role(message),
    swipeHashes: await Promise.all(swipeTexts(message).map(sha256)),
    selectedSwipe: Math.max(0, Number(message.swipe_id ?? 0) || 0),
    message,
  })));
}

function variablesForSwipe(message: Record<string, any>, swipeId: number): Record<string, unknown> {
  if (Array.isArray(message.variables)) return message.variables[swipeId] ?? {};
  if (message.variables && typeof message.variables === "object") return message.variables[swipeId] ?? {};
  const data = Array.isArray(message.swipes_data) ? message.swipes_data[swipeId] : undefined;
  return data?.variables && typeof data.variables === "object" ? data.variables : {};
}

function snapshots(descriptor: ChatDescriptor): EchoesBackupMessageSwipe["statusSnapshots"] {
  return descriptor.swipeHashes.flatMap((_, swipeId) => {
    const parsed = statusSnapshotSchema.safeParse(variablesForSwipe(descriptor.message, swipeId).echoes_status);
    return parsed.success ? [{ swipeId, value: parsed.data }] : [];
  });
}

function compression(message: Record<string, any>): EchoesBackupMessageSwipe["compression"] {
  const value = message.extra?.echoes?.compression;
  return value && typeof value === "object" ? structuredClone(value) : undefined;
}

function restoreEchoesStatusValues(
  current: Array<Record<string, any>> | Record<number, Record<string, any>>,
  original: Array<Record<string, any>> | Record<number, Record<string, any>>,
): void {
  for (const value of Object.values(current)) {
    if (value && typeof value === "object") delete value.echoes_status;
  }
  for (const [swipeId, value] of Object.entries(original)) {
    if (!value || typeof value !== "object" || !Object.hasOwn(value, "echoes_status")) continue;
    const index = Number(swipeId);
    current[index] = {
      ...(current[index] ?? {}),
      echoes_status: structuredClone(value.echoes_status),
    };
  }
}

function messagePatch(
  descriptor: ChatDescriptor,
  variables: Array<Record<string, any>> | Record<number, Record<string, any>>,
  extra: Record<string, any>,
  hidden: boolean,
): ChatMessagePatch {
  const swipes = swipeTexts(descriptor.message);
  const swipesInfo = swipes.map((_, index) =>
    structuredClone(descriptor.message.swipe_info?.[index] ?? {}));
  swipesInfo[descriptor.selectedSwipe] = extra;
  // The helper's swiped-message API maps these fields to raw variables/swipe_info.
  return {
    message_id: descriptor.index,
    is_hidden: hidden,
    swipe_id: descriptor.selectedSwipe,
    swipes,
    swipes_data: swipes.map((_, index) => structuredClone(variables[index] ?? {})),
    swipes_info: swipesInfo,
  };
}

function rollbackMessagePatch(
  current: ChatDescriptor,
  original: Record<string, any>,
  expectedHidden: boolean,
): ChatMessagePatch {
  const variables = structuredClone(current.message.variables ?? []) as
    Array<Record<string, any>> | Record<number, Record<string, any>>;
  const originalVariables = structuredClone(original.variables ?? []) as
    Array<Record<string, any>> | Record<number, Record<string, any>>;
  restoreEchoesStatusValues(variables, originalVariables);

  const extra = structuredClone(current.message.extra ?? {}) as Record<string, any>;
  if (extra.echoes?.compression) delete extra.echoes.compression;
  const originalCompression = original.extra?.echoes?.compression;
  if (originalCompression) {
    extra.echoes = {
      ...(extra.echoes ?? {}),
      compression: structuredClone(originalCompression),
    };
  }
  const currentHidden = Boolean(current.message.is_system ?? current.message.is_hidden);
  return messagePatch(
    current,
    variables,
    extra,
    currentHidden === expectedHidden ? Boolean(original.is_system ?? original.is_hidden) : currentHidden,
  );
}

function echoesKind(entry: TavernWorldbookEntry): string | null {
  const kind = entry.extra?.echoes?.kind;
  return typeof kind === "string" ? kind : null;
}

export function rollbackWorldbookEntries(current: TavernWorldbookEntry[], before: TavernWorldbookEntry[], written: TavernWorldbookEntry[]): TavernWorldbookEntry[] {
  const owned = (entries: TavernWorldbookEntry[]) => entries.filter((entry) => echoesKind(entry));
  if (stableJson(owned(current)) !== stableJson(owned(written))) {
    throw new Error("恢复期间 Echoes 世界书数据被其他操作修改，未覆盖这些新数据；请使用安全备份核对。");
  }
  return [...current.filter((entry) => !echoesKind(entry)), ...structuredClone(owned(before))];
}

export function persistentEchoesEntry(entry: TavernWorldbookEntry): boolean {
  const kind = echoesKind(entry);
  return Boolean(kind && PERSISTENT_KINDS.has(kind) && !TEMPORARY_KINDS.has(kind));
}

function validatePortableEntry(entry: EchoesBackupWorldbookEntry): void {
  const echoes = entry.extra.echoes as Record<string, any> | undefined;
  const kind = typeof echoes?.kind === "string" ? echoes.kind : "";
  if (!PERSISTENT_KINDS.has(kind)) throw new Error(`Unsupported Echoes worldbook entry kind: ${kind || "missing"}.`);
  if (kind === "catalog") {
    if (echoes!.catalog.formatVersion !== 2) {
      throw new Error("此备份的结构化记忆目录是 4.0 之前的格式，与当前版本不兼容，无法导入或恢复。");
    }
    structuredMemoryCatalogSchema.parse(echoes!.catalog);
  } else if (kind === "row") {
    identifierSchema.parse(echoes!.rowId);
    identifierSchema.parse(echoes!.typeId);
    memoryRowSourceSchema.parse(echoes!.source);
    if (echoes!.aliases) aliasSchema.parse(echoes!.aliases);
    if (echoes!.continuity) continuitySchema.parse(echoes!.continuity);
  } else if (kind === "summary_catalog") summaryCatalogSchema.parse(echoes!.catalog);
  else if (kind === "summary_slice") {
    summarySliceSchema.parse({
      id: echoes!.summaryId,
      timestamp: echoes!.timestamp,
      title: echoes!.title,
      content: entry.content,
      tags: echoes!.tags,
      batch: echoes!.batch,
      sliceNumber: echoes!.sliceNumber,
      ...(echoes!.continuity ? { continuity: echoes!.continuity } : {}),
    });
  } else if (kind === "summary_batch_overview") batchOverviewSchema.parse(echoes!.overview);
  else if (kind === "status_catalog") statusCatalogSchema.parse(echoes!.catalog);
  else if (kind === "memory_history") memoryHistorySchema.parse(echoes!.record);
}

function portableEntry(entry: TavernWorldbookEntry): EchoesBackupWorldbookEntry {
  return {
    sourceUid: entry.uid,
    name: entry.name,
    enabled: entry.enabled,
    strategy: structuredClone(entry.strategy) as unknown as Record<string, unknown>,
    ...(entry.position ? { position: structuredClone(entry.position) as unknown as Record<string, unknown> } : {}),
    content: entry.content,
    ...(entry.probability !== undefined ? { probability: entry.probability } : {}),
    ...(entry.recursion ? { recursion: structuredClone(entry.recursion) } : {}),
    ...(entry.effect ? { effect: structuredClone(entry.effect) } : {}),
    extra: structuredClone(entry.extra ?? {}),
  };
}

function withoutIntegrity(backup: EchoesBackupV1): Omit<EchoesBackupV1, "integrity"> {
  const { integrity: _integrity, ...value } = backup;
  return value;
}

export async function finalizeBackup(value: Omit<EchoesBackupV1, "integrity">): Promise<EchoesBackupV1> {
  return {
    ...value,
    integrity: { algorithm: "sha256", digest: await sha256(stableJson(value)) },
  };
}

function uniqueId(prefix: string): string {
  return `${prefix}_${randomUuid().replaceAll("-", "")}`;
}

function currentWorldbook(): { chatId: string; worldbookName: string } {
  const context = SillyTavern.getContext();
  const chatId = context.chatId;
  const worldbookName = window.TavernHelper?.getChatWorldbookName("current");
  if (!chatId || !worldbookName) throw new Error("Open a chat with an attached worldbook before using backup.");
  return { chatId, worldbookName };
}

function exactMapping(source: EchoesBackupMessageSwipe[], target: ChatDescriptor[]): RestorePlan["mappedMessages"] | null {
  const targetById = new Map<string, ChatDescriptor[]>();
  for (const item of target) {
    const values = targetById.get(item.stableId) ?? [];
    values.push(item);
    targetById.set(item.stableId, values);
  }
  const mapping: RestorePlan["mappedMessages"] = [];
  const sourceIds = new Set<string>();
  const targetIndexes = new Set<number>();
  for (const item of source) {
    if (sourceIds.has(item.stableId)) return null;
    sourceIds.add(item.stableId);
    const candidates = (targetById.get(item.stableId) ?? []).filter((candidate) =>
      candidate.role === item.role && stableJson(candidate.swipeHashes) === stableJson(item.swipeHashes));
    if (candidates.length !== 1 || targetIndexes.has(candidates[0]!.index)) return null;
    targetIndexes.add(candidates[0]!.index);
    mapping.push({
      sourceStableId: item.stableId,
      targetIndex: candidates[0]!.index,
      targetStableId: candidates[0]!.stableId,
    });
  }
  return mapping;
}

function monotonicMapping(source: EchoesBackupMessageSwipe[], target: ChatDescriptor[]): RestorePlan["mappedMessages"] | null {
  const mapping: RestorePlan["mappedMessages"] = [];
  const sourceIds = new Set<string>();
  let targetIndex = 0;
  for (const item of source) {
    if (sourceIds.has(item.stableId)) return null;
    sourceIds.add(item.stableId);
    const candidates = target.slice(targetIndex).filter((candidate) =>
      candidate.role === item.role && stableJson(candidate.swipeHashes) === stableJson(item.swipeHashes));
    if (candidates.length !== 1) return null;
    const candidate = candidates[0]!;
    mapping.push({ sourceStableId: item.stableId, targetIndex: candidate.index, targetStableId: candidate.stableId });
    targetIndex = candidate.index + 1;
  }
  return mapping;
}

function replacement(value: unknown, replacements: Map<string, string>): unknown {
  return typeof value === "string" ? replacements.get(value) ?? value : value;
}

function replacementList(value: unknown, replacements: Map<string, string>): unknown {
  return Array.isArray(value) ? value.map((item) => replacement(item, replacements)) : value;
}

function descriptorMessage(
  descriptor: ChatDescriptor,
  swipeId = descriptor.selectedSwipe,
): ChatMessageInput {
  const content = String(swipeTexts(descriptor.message)[swipeId] ?? "").trim();
  if (!content) throw new Error(`Mapped message ${descriptor.stableId} has no usable selected swipe content.`);
  return {
    id: descriptor.stableId,
    role: descriptor.role === "user" ? "user" : "assistant",
    content,
  };
}

function mappedMessages(
  messageIds: string[],
  targetById: Map<string, ChatDescriptor>,
  targetSwipe?: { messageId: string; swipeId: number },
): ChatMessageInput[] {
  return messageIds.map((messageId) => {
    const descriptor = targetById.get(messageId);
    if (!descriptor) throw new Error(`Mapped source message is missing from the target chat: ${messageId}.`);
    return descriptorMessage(
      descriptor,
      targetSwipe?.messageId === messageId ? targetSwipe.swipeId : descriptor.selectedSwipe,
    );
  });
}

async function rewriteSnapshotReferences(
  snapshot: StatusSnapshot,
  replacements: Map<string, string>,
  targetById: Map<string, ChatDescriptor>,
): Promise<StatusSnapshot> {
  const rewritten = structuredClone(snapshot);
  rewritten.namespaceId = String(replacement(rewritten.namespaceId, replacements));
  rewritten.snapshotId = String(replacement(rewritten.snapshotId, replacements));
  rewritten.targetMessageId = String(replacement(rewritten.targetMessageId, replacements));
  rewritten.sourceMessageIds = replacementList(rewritten.sourceMessageIds, replacements) as string[];
  if (rewritten.parentSnapshotId) {
    rewritten.parentSnapshotId = String(replacement(rewritten.parentSnapshotId, replacements));
  }
  rewritten.sourceHash = await sourceMessagesHash(mappedMessages(
    rewritten.sourceMessageIds,
    targetById,
    { messageId: rewritten.targetMessageId, swipeId: rewritten.targetSwipeId },
  ));
  return rewritten;
}

function rewriteCompressionReferences(
  marker: NonNullable<EchoesBackupMessageSwipe["compression"]>,
  replacements: Map<string, string>,
): NonNullable<EchoesBackupMessageSwipe["compression"]> {
  const rewritten = structuredClone(marker);
  rewritten.stableId = String(replacement(rewritten.stableId, replacements));
  rewritten.namespaceId = String(replacement(rewritten.namespaceId, replacements));
  rewritten.batchId = String(replacement(rewritten.batchId, replacements));
  return rewritten;
}

function worldbookNamespaceReplacements(
  backup: EchoesBackupV1,
  targetChatId: string,
): Map<string, string> {
  const replacements = new Map<string, string>([[backup.source.chatId, targetChatId]]);
  for (const entry of backup.worldbookEntries) {
    const echoes = entry.extra.echoes as Record<string, any> | undefined;
    const catalog = echoes?.catalog as { namespaceId?: unknown } | undefined;
    if (typeof catalog?.namespaceId !== "string" || replacements.has(catalog.namespaceId)) continue;
    const prefix = catalog.namespaceId.startsWith("summary_") ? "summary_namespace"
      : catalog.namespaceId.startsWith("status_") ? "status_namespace" : "memory_namespace";
    replacements.set(catalog.namespaceId, uniqueId(prefix));
  }
  for (const entry of backup.worldbookEntries) {
    const echoes = entry.extra.echoes as Record<string, any> | undefined;
    for (const [value, prefix] of [
      [echoes?.summaryId, "summary"],
      [echoes?.batch?.id, "summary_batch"],
      [echoes?.overview?.batch?.id, "summary_batch"],
      [echoes?.rowId, "row"],
      [echoes?.kind === "memory_history" ? echoes.record?.rowId : undefined, "row"],
    ] as Array<[unknown, string]>) {
      if (typeof value === "string" && !replacements.has(value)) replacements.set(value, uniqueId(prefix));
    }
  }
  for (const message of backup.messages) {
    for (const { value } of message.statusSnapshots) {
      if (!replacements.has(value.snapshotId)) replacements.set(value.snapshotId, uniqueId("status_snapshot"));
    }
  }
  return replacements;
}

async function rewriteEntry(
  entry: EchoesBackupWorldbookEntry,
  mode: RestoreMode,
  backup: EchoesBackupV1,
  targetChatId: string,
  replacements: Map<string, string>,
  targetById: Map<string, ChatDescriptor>,
): Promise<Partial<TavernWorldbookEntry>> {
  const rewritten = structuredClone(entry);
  const echoes = rewritten.extra.echoes as Record<string, any>;
  const kind = String(echoes.kind ?? "");
  if (kind === "summary_catalog") {
    echoes.version = 2;
    echoes.catalog.formatVersion = 2;
    echoes.catalog.chatId = targetChatId;
    echoes.catalog.namespaceId = replacement(echoes.catalog.namespaceId, replacements);
    echoes.catalog.lastCommittedMessageId = replacement(echoes.catalog.lastCommittedMessageId, replacements);
    echoes.catalog.checkpointAnchorMessageId = replacement(echoes.catalog.checkpointAnchorMessageId, replacements);
    echoes.catalog.automaticStopMessageId = replacement(echoes.catalog.automaticStopMessageId, replacements);
    delete echoes.catalog.recallPool;
    echoes.catalog.pendingRetrievalDeletes = replacementList(echoes.catalog.pendingRetrievalDeletes, replacements);
    delete echoes.catalog.retrievalCollectionId;
    delete echoes.catalog.retrievalEmbeddingSpaceId;
    echoes.catalog.pendingRetrievalDeletes = [];
    if (mode === "seed_memories") {
      echoes.catalog.autoRun = false;
      echoes.catalog.recallEnabled = false;
      echoes.catalog.attachedRecallSources = [];
      echoes.catalog.compression = { ...echoes.catalog.compression, enabled: false };
      delete echoes.catalog.lastCommittedMessageId;
      delete echoes.catalog.checkpointAnchorMessageId;
      delete echoes.catalog.automaticStopMessageId;
    }
  } else if (kind === "summary_batch_overview") {
    const overview = batchOverviewSchema.parse(echoes.overview);
    const original = structuredClone(overview.batch);
    overview.batch.id = replacements.get(overview.batch.id) ?? overview.batch.id;
    overview.batch.startMessageId = replacements.get(overview.batch.startMessageId) ?? overview.batch.startMessageId;
    overview.batch.endMessageId = replacements.get(overview.batch.endMessageId) ?? overview.batch.endMessageId;
    overview.batch.messageIds = overview.batch.messageIds.map((id) => replacements.get(id) ?? id);
    if (mode === "seed_memories") {
      overview.batch.source = { kind: "imported", backupId: backup.backupId, sourceChatId: backup.source.chatId };
    } else if (mode === "equivalent_chat" && overview.batch.source?.kind !== "imported") {
      try {
        const current = mappedMessages(overview.batch.messageIds, targetById);
        const oldIdentity = current.map((message, index) => ({ ...message, id: original.messageIds[index]! }));
        const positions = overview.batch.messageIds.map((id) => targetById.get(id)?.index);
        if (original.state === "stale" || !positions.every((index, offset) => index !== undefined && index === positions[0]! + offset)
          || await sourceMessagesHash(oldIdentity) !== original.sourceHash) overview.batch.state = "stale";
        else overview.batch.sourceHash = await sourceMessagesHash(current);
      } catch { overview.batch.state = "stale"; }
    }
    return batchOverviewEntry(overview);
  } else if (kind === "summary_slice") {
    const originalBatch = (entry.extra.echoes as Record<string, any>).batch;
    echoes.version = 2;
    echoes.summaryId = replacement(echoes.summaryId, replacements);
    echoes.batch.id = replacement(echoes.batch.id, replacements);
    echoes.batch.startMessageId = replacement(echoes.batch.startMessageId, replacements);
    echoes.batch.endMessageId = replacement(echoes.batch.endMessageId, replacements);
    echoes.batch.messageIds = replacementList(echoes.batch.messageIds, replacements);
    echoes.batch.state = originalBatch.state === "stale" ? "stale" : "pending";
    if (mode === "seed_memories") {
      echoes.batch.source = {
        kind: "imported",
        backupId: backup.backupId,
        sourceChatId: backup.source.chatId,
      };
    } else if (!echoes.batch.source) {
      echoes.batch.source = { kind: "chat_messages" };
    }
    if (mode === "equivalent_chat" && echoes.batch.source.kind === "chat_messages") {
      try {
        const current = mappedMessages(echoes.batch.messageIds.map(String), targetById);
        const originalIdentity = current.map((message, index) => ({ ...message, id: String(originalBatch.messageIds[index]) }));
        const positions = echoes.batch.messageIds.map((id: string) => targetById.get(id)?.index);
        const contiguous = positions.every((index: number | undefined, offset: number) =>
          index !== undefined && index === positions[0] + offset);
        if (originalBatch.state !== "stale" && contiguous
          && await sourceMessagesHash(originalIdentity) === originalBatch.sourceHash) {
          echoes.batch.sourceHash = await sourceMessagesHash(current);
        } else {
          echoes.batch.state = "stale";
        }
      } catch {
        // Unverifiable bodies retain their original hash and must not be reactivated by reindexing.
        echoes.batch.state = "stale";
      }
    }
  } else if (kind === "catalog") {
    echoes.catalog.chatId = targetChatId;
    echoes.catalog.namespaceId = replacement(echoes.catalog.namespaceId, replacements);
    echoes.catalog.lastProcessedMessageId = replacement(echoes.catalog.lastProcessedMessageId, replacements);
    if (mode === "seed_memories") {
      echoes.catalog.automation = { enabled: false };
      if (echoes.catalog.creativePreferences) echoes.catalog.creativePreferences.enabled = false;
      delete echoes.catalog.lastProcessedMessageId;
    }
  } else if (kind === "row" && mode === "seed_memories") {
    echoes.source = { kind: "migration", messageIds: [] };
    echoes.rowId = replacement(echoes.rowId, replacements);
  } else if (kind === "row") {
    echoes.rowId = replacement(echoes.rowId, replacements);
    echoes.source.messageIds = replacementList(echoes.source?.messageIds, replacements);
    echoes.source.batchId = replacement(echoes.source?.batchId, replacements);
  } else if (kind === "status_catalog") {
    echoes.catalog.chatId = targetChatId;
    echoes.catalog.namespaceId = replacement(echoes.catalog.namespaceId, replacements);
    if (mode === "seed_memories") {
      echoes.catalog.enabled = false;
      echoes.catalog.autoUpdate = false;
    }
  }
  if (kind === "memory_history") {
    echoes.record.id = uniqueId("history");
    echoes.record.rowId = replacement(echoes.record.rowId, replacements);
    for (const snapshot of [echoes.record.before, echoes.record.after]) {
      if (!snapshot) continue;
      snapshot.metadata.rowId = replacement(snapshot.metadata.rowId, replacements);
      if (snapshot.metadata.source) {
        snapshot.metadata.source = mode === "seed_memories" ? { kind: "migration", messageIds: [] }
          : { ...snapshot.metadata.source, messageIds: replacementList(snapshot.metadata.source.messageIds, replacements) };
      }
    }
    rewritten.enabled = false;
  }
  if (kind === "row" && !currentFact(echoes.continuity)) rewritten.enabled = false;
  const result: Partial<TavernWorldbookEntry> = {
    name: rewritten.name,
    enabled: rewritten.enabled,
    strategy: rewritten.strategy as unknown as TavernWorldbookEntry["strategy"],
    content: rewritten.content,
    extra: rewritten.extra,
  };
  if (rewritten.position) result.position = rewritten.position as NonNullable<TavernWorldbookEntry["position"]>;
  if (rewritten.probability !== undefined) result.probability = rewritten.probability;
  if (rewritten.recursion) result.recursion = rewritten.recursion;
  if (rewritten.effect) result.effect = rewritten.effect;
  return result;
}

function disableMissingCredentialEndpoints(settings: EchoesSettings, available: Set<string>): void {
  const apply = (endpoint: { credentialId?: string | undefined; enabled: boolean }): void => {
    if (endpoint.credentialId && !available.has(endpoint.credentialId)) endpoint.enabled = false;
  };
  settings.generationGroups.forEach((group) => group.endpoints.forEach(apply));
  settings.retrieval.embeddingGroups.forEach((group) => group.endpoints.forEach(apply));
  settings.retrieval.rerankSets.forEach((set) => set.endpoints.forEach(apply));
}

export class EchoesBackupManager {
  async create(includeGlobalSettings = false): Promise<EchoesBackupV1> {
    const { chatId, worldbookName } = currentWorldbook();
    const api = helper();
    const [entries, chat] = await Promise.all([
      api.getWorldbook(worldbookName),
      describeChat(),
    ]);
    if (SillyTavern.getContext().chatId !== chatId) throw new Error("The active chat changed during backup.");
    const messages: EchoesBackupMessageSwipe[] = chat.map((item) => ({
      index: item.index,
      stableId: item.stableId,
      role: item.role,
      swipeHashes: item.swipeHashes,
      selectedSwipe: item.selectedSwipe,
      statusSnapshots: snapshots(item),
      ...(compression(item.message) ? { compression: compression(item.message) } : {}),
    }));
    const worldbookEntries = entries.filter(persistentEchoesEntry).map(portableEntry);
    worldbookEntries.forEach(validatePortableEntry);
    const value: Omit<EchoesBackupV1, "integrity"> = {
      formatVersion: 1,
      appVersion: ECHOES_BUILD_INFO.appVersion,
      backupId: uniqueId("backup"),
      createdAt: new Date().toISOString(),
      source: {
        chatId,
        worldbookName,
        transcriptFingerprint: await sha256(stableJson(transcriptShape(messages))),
      },
      ...(includeGlobalSettings ? { globalSettings: redactedSettings() } : {}),
      worldbookEntries,
      messages,
    };
    return echoesBackupV1Schema.parse(await finalizeBackup(value));
  }

  async parse(text: string): Promise<EchoesBackupV1> {
    if (new TextEncoder().encode(text).byteLength > MAX_BACKUP_BYTES) {
      throw new Error("Echoes backup exceeds the 100 MB uncompressed limit.");
    }
    const backup = echoesBackupV1Schema.parse(JSON.parse(text));
    const digest = await sha256(stableJson(withoutIntegrity(backup)));
    if (digest !== backup.integrity.digest) throw new Error("Echoes backup integrity verification failed.");
    const transcriptFingerprint = await sha256(stableJson(transcriptShape(backup.messages)));
    if (transcriptFingerprint !== backup.source.transcriptFingerprint) {
      throw new Error("Echoes backup transcript fingerprint is inconsistent.");
    }
    backup.worldbookEntries.forEach(validatePortableEntry);
    if (backup.globalSettings) parseImportedSettings(backup.globalSettings);
    return backup;
  }

  async plan(backup: EchoesBackupV1, mode: RestoreMode, restoreGlobalSettings = false): Promise<RestorePlan> {
    if (restoreGlobalSettings && backup.globalSettings) parseImportedSettings(backup.globalSettings);
    const { chatId, worldbookName } = currentWorldbook();
    const target = await describeChat();
    const mappedMessages = mode === "equivalent_chat"
      ? exactMapping(backup.messages, target) ?? monotonicMapping(backup.messages, target)
      : [];
    if (mode === "equivalent_chat" && (!mappedMessages || mappedMessages.length !== backup.messages.length)) {
      throw new Error("The target transcript is missing messages or contains ambiguous swipe matches.");
    }
    const entries = await helper().getWorldbook(worldbookName);
    return {
      mode,
      targetChatId: chatId,
      targetWorldbookName: worldbookName,
      targetTranscriptFingerprint: await targetTranscriptFingerprint(target),
      restoreGlobalSettings: restoreGlobalSettings && Boolean(backup.globalSettings),
      mappedMessages: mappedMessages ?? [],
      echoesEntriesToReplace: entries.filter((entry) => Boolean(echoesKind(entry))).length,
      statusSnapshotsToReplace: backup.messages.reduce((sum, item) => sum + item.statusSnapshots.length, 0),
      compressionMarkersToReplace: backup.messages.filter((item) => item.compression).length,
      warnings: [
        "Existing Echoes-owned target data will be replaced after a safety backup is created.",
        "Derived retrieval collections are not restored and must be rebuilt.",
        "Stale or unverifiable summaries remain stale; indexing cannot validate their bodies.",
      ],
    };
  }

  restore(
    backup: EchoesBackupV1,
    plan: RestorePlan,
    onSafetyBackup?: ((backup: EchoesBackupV1) => void) | undefined,
  ): Promise<{ result: RestoreResult; safetyBackup: EchoesBackupV1 }> {
    return messageWriteCoordinator.run(() => this.restoreLocked(backup, plan, onSafetyBackup));
  }

  private async assertRestoreTarget(
    backup: EchoesBackupV1,
    plan: RestorePlan,
  ): Promise<ChatDescriptor[]> {
    const current = currentWorldbook();
    if (current.chatId !== plan.targetChatId || current.worldbookName !== plan.targetWorldbookName) {
      throw new Error("The target chat changed after restore preview.");
    }
    const target = await describeChat();
    if (await targetTranscriptFingerprint(target) !== plan.targetTranscriptFingerprint) {
      throw new Error("The target transcript changed after restore preview.");
    }
    if (plan.mode === "equivalent_chat") {
      const mappedMessages = exactMapping(backup.messages, target) ?? monotonicMapping(backup.messages, target);
      if (!mappedMessages || stableJson(mappedMessages) !== stableJson(plan.mappedMessages)) {
        throw new Error("The target transcript mapping changed after restore preview.");
      }
    }
    return target;
  }

  private async restoreLocked(
    backup: EchoesBackupV1,
    plan: RestorePlan,
    onSafetyBackup?: ((backup: EchoesBackupV1) => void) | undefined,
  ): Promise<{ result: RestoreResult; safetyBackup: EchoesBackupV1 }> {
    const current = currentWorldbook();
    await this.assertRestoreTarget(backup, plan);
    const api = helper();
    const safetyBackup = await this.create(plan.restoreGlobalSettings);
    onSafetyBackup?.(safetyBackup);
    return worldbookWriteCoordinator.run(current.worldbookName, async () => {
    const baselineTarget = await this.assertRestoreTarget(backup, plan);
    const originalEntries = structuredClone(await api.getWorldbook(current.worldbookName));
    const originalChat = new Map(baselineTarget.map((item) => [
      item.stableId,
      structuredClone(item.message),
    ]));
    const replacements = worldbookNamespaceReplacements(backup, current.chatId);
    const mapping = new Map(plan.mappedMessages.map((item) => [item.sourceStableId, item.targetStableId]));
    for (const [source, target] of mapping) replacements.set(source, target);
    const targetById = new Map(baselineTarget.map((item) => [item.stableId, item]));
    const incoming = await Promise.all(backup.worldbookEntries.map((entry) =>
      rewriteEntry(entry, plan.mode, backup, current.chatId, replacements, targetById)));
    const rewrittenSnapshots = new Map<string, StatusSnapshot>();
    const validSummaryBatches = new Set(incoming.filter((entry) =>
      entry.extra?.echoes?.kind === "summary_slice" && entry.extra.echoes.batch.state !== "stale")
      .map((entry) => entry.extra!.echoes.batch.id));
    if (plan.mode === "equivalent_chat") {
      for (const message of backup.messages) {
        const targetMessageId = mapping.get(message.stableId);
        if (!targetMessageId) throw new Error(`Missing target mapping for message ${message.stableId}.`);
        for (const stored of message.statusSnapshots) {
          rewrittenSnapshots.set(
            `${targetMessageId}\0${stored.swipeId}`,
            await rewriteSnapshotReferences(stored.value, replacements, targetById),
          );
        }
      }
    }
    const originalSettings = plan.restoreGlobalSettings ? structuredClone(getSettings()) : null;
    const expectedHidden = new Map<string, boolean>();
    let messagesWritten = false;
    let settingsWritten = false;
    let worldbookWriteStarted = false;
    let writtenEntries: TavernWorldbookEntry[] | undefined;
    try {
        invalidateRecall(current.worldbookName);
        await this.assertRestoreTarget(backup, plan);
        await api.updateWorldbookWith(current.worldbookName, (entries) => {
          if (stableJson(entries) !== stableJson(originalEntries)) throw new Error("世界书已变化，未执行恢复，请重新预览。");
          worldbookWriteStarted = true;
          return [...entries.filter((entry) => !echoesKind(entry)), ...incoming] as TavernWorldbookEntry[];
        });
        writtenEntries = structuredClone(await api.getWorldbook(current.worldbookName));
        const targetMessages = await this.assertRestoreTarget(backup, plan);
        const sourceByTarget = new Map<number, EchoesBackupMessageSwipe>();
        if (plan.mode === "equivalent_chat") {
          const sourceById = new Map(backup.messages.map((item) => [item.stableId, item]));
          for (const item of plan.mappedMessages) sourceByTarget.set(item.targetIndex, sourceById.get(item.sourceStableId)!);
        }
        const patches = targetMessages.map((descriptor, index) => {
          if (descriptor.index !== index) throw new Error("The target transcript indexes changed during restore.");
          const target = descriptor.message;
          const source = sourceByTarget.get(index);
          const variables: Array<Record<string, any>> | Record<number, Record<string, any>> =
            structuredClone(target.variables ?? []) as Array<Record<string, any>> | Record<number, Record<string, any>>;
          for (const value of Object.values(variables)) {
            if (value && typeof value === "object") delete value.echoes_status;
          }
          for (const stored of source?.statusSnapshots ?? []) {
            const value = rewrittenSnapshots.get(`${descriptor.stableId}\0${stored.swipeId}`);
            if (!value) throw new Error("A restored status snapshot was not prepared for the mapped message.");
            variables[stored.swipeId] = { ...(variables[stored.swipeId] ?? {}), echoes_status: value };
          }
          const extra: Record<string, any> = structuredClone(target.extra ?? {});
          const wasEchoesHidden = Boolean(extra.echoes?.compression?.hiddenByEchoes);
          if (extra.echoes?.compression) delete extra.echoes.compression;
          const validCompression = source?.compression
            && validSummaryBatches.has(String(replacement(source.compression.batchId, replacements)));
          if (validCompression) {
            extra.echoes = {
              ...(extra.echoes ?? {}),
              compression: rewriteCompressionReferences(source!.compression!, replacements),
            };
          }
          const hidden = validCompression && source?.compression?.hiddenByEchoes
            ? true
            : wasEchoesHidden ? false : Boolean(target.is_system ?? target.is_hidden);
          expectedHidden.set(descriptor.stableId, hidden);
          return messagePatch(descriptor, variables, extra, hidden);
        });
        messagesWritten = true;
        await api.setChatMessages(patches, { refresh: "affected" });
        if (plan.mode === "seed_memories") {
          const latest = [...backup.messages].reverse().map((message) =>
            message.statusSnapshots.find((item) => item.swipeId === message.selectedSwipe)?.value)
            .find((snapshot): snapshot is StatusSnapshot => Boolean(snapshot));
          if (latest) {
            await api.updateWorldbookWith(current.worldbookName, (entries) => entries.map((entry) => {
              const echoes = entry.extra?.echoes;
              if (echoes?.kind !== "status_catalog") return entry;
              const rewritten = structuredClone(entry);
              rewritten.extra!.echoes.catalog.profile.initialState = structuredClone(latest.state);
              rewritten.extra!.echoes.catalog.enabled = false;
              rewritten.extra!.echoes.catalog.autoUpdate = false;
              return rewritten;
            }));
            writtenEntries = structuredClone(await api.getWorldbook(current.worldbookName));
          }
        }
      if (plan.restoreGlobalSettings && backup.globalSettings) {
        const restored = parseImportedSettings(backup.globalSettings);
        const credentials = await import("../api/client").then(({ echoesApi }) => echoesApi.listCredentials());
        disableMissingCredentialEndpoints(restored, new Set(credentials.map((credential) => credential.id)));
        saveSettings(restored);
        settingsWritten = true;
      }
    } catch (error) {
      try {
        if (worldbookWriteStarted) {
          await api.updateWorldbookWith(current.worldbookName, (entries) => {
            if (!writtenEntries) {
              if (stableJson(entries) === stableJson(originalEntries)) return entries;
              throw new Error("无法确认失败恢复操作的世界书写入结果，已保留现状；请使用安全备份核对。");
            }
            return rollbackWorldbookEntries(entries, originalEntries, writtenEntries);
          });
        }
        if (messagesWritten) {
          const rollbackTarget = await this.assertRestoreTarget(backup, plan);
          const rollbackPatches = rollbackTarget.map((descriptor) => {
            const original = originalChat.get(descriptor.stableId);
            if (!original) throw new Error("The target transcript cannot be mapped for rollback.");
            return rollbackMessagePatch(
              descriptor,
              original,
              expectedHidden.get(descriptor.stableId) ?? Boolean(descriptor.message.is_system ?? descriptor.message.is_hidden),
            );
          });
          await api.setChatMessages(rollbackPatches, { refresh: "all" });
        }
        if (settingsWritten && originalSettings) saveSettings(originalSettings);
      } catch (rollbackError) {
        throw new AggregateError([error, rollbackError], "Restore and compensating rollback both failed.");
      }
      throw error;
    }
    return {
      safetyBackup,
      result: {
        backupId: backup.backupId,
        safetyBackupId: safetyBackup.backupId,
        mode: plan.mode,
        worldbookEntries: incoming.length,
        statusSnapshots: plan.mode === "equivalent_chat" ? plan.statusSnapshotsToReplace : 0,
        compressionMarkers: plan.mode === "equivalent_chat" ? plan.compressionMarkersToReplace : 0,
        retrievalRebuildRequired: incoming.some((entry) => entry.extra?.echoes?.kind === "summary_slice"),
        globalSettingsRestored: plan.restoreGlobalSettings,
      },
    };
    });
  }
}

export function serializeBackup(backup: EchoesBackupV1): string {
  return JSON.stringify(backup, null, 2);
}
