import { randomUuid } from "../../shared/crypto-compat";
import type {
  AttachedRecallSource,
  SummaryBatchInput,
  SummaryCatalog,
  SummarySlice,
  SummarySliceCandidate,
  SummarySyncState,
  RecallPoolState,
} from "../../shared/domain";
import {
  summaryCatalogSchema,
  summarySliceCandidateSchema,
  summarySliceSchema,
} from "../../shared/schemas";
import { worldbookWriteCoordinator } from "./worldbook-write-coordinator";
import { invalidateRecall } from "../recall-invalidation";
import { indexedChatMessages } from "../chat-message-index";
import { createBatchOrder, summarySuffix } from "../summary/batch-order";
import { summaryPropositionKey } from "../summary/adaptive-batches";
import { batchOverviewSchema, type BatchOverview } from "../../shared/batch-overview";
import { batchOverviewEntry, readBatchOverview, pruneBatchOverviews } from "./batch-overview";
import { recordMemoryUndo, amendMemoryUndo, completeMemoryUndo, prepareMemoryUndoRestore,
  requireMemoryUndo, applyMemoryUndo, undoFingerprint } from "../maintenance/operation-undo";
import type { VisibilityChange } from "../summary/compression-coordinator";

interface SummaryCatalogMetadata {
  kind: "summary_catalog";
  version: 1 | 2;
  catalog: SummaryCatalog;
}

interface SummarySliceMetadata {
  continuity?: SummarySlice["continuity"];
  retrievalText?: string | undefined;
  recallFlags?: string[] | undefined;
  kind: "summary_slice";
  version: 2;
  summaryId: string;
  timestamp: string;
  title: string;
  tags: string[];
  batch: SummarySlice["batch"];
  sliceNumber: number;
}

export interface SummaryWorldbookState {
  undoOperationId?: string | undefined;
  batchOverviews?: BatchOverview[];
  worldbookName: string;
  catalog: SummaryCatalog;
  slices: SummarySlice[];
}

export function summaryMigrationFingerprint(state: SummaryWorldbookState): string {
  return JSON.stringify({
    namespace: state.catalog.namespaceId,
    collection: state.catalog.retrievalCollectionId,
    pendingDeletes: state.catalog.pendingRetrievalDeletes,
    slices: state.slices.map((s) => [s.id, s.timestamp, s.title, s.content, s.tags, s.retrievalText,
      s.batch.id, s.batch.revision, s.batch.state === "stale"]),
  });
}

export function summaryBatchSnapshot(slices: SummarySlice[], batchId: string): string {
  return JSON.stringify(slices.filter((slice) => slice.batch.id === batchId)
    .map(({ worldbookUid: _uid, ...slice }) => slice).sort((a, b) => a.id.localeCompare(b.id)));
}

function chatMessages() {
  return indexedChatMessages().map((entry) => entry.message);
}

function prunePool(catalog: SummaryCatalog, removed: Set<string>): SummaryCatalog {
  if (!catalog.recallPool) return catalog;
  const keep = (ref: { namespaceId: string; sliceId: string }) =>
    ref.namespaceId !== catalog.namespaceId || !removed.has(ref.sliceId);
  return { ...catalog, recallPool: { ...catalog.recallPool,
    entries: catalog.recallPool.entries.filter(keep), replay: catalog.recallPool.replay.filter(keep) } };
}

function helper(): TavernHelperApi {
  if (!window.TavernHelper) throw new Error("Echoes requires TavernHelper for summary storage.");
  return window.TavernHelper;
}

function uniqueId(prefix: string): string {
  return `${prefix}_${randomUuid().replaceAll("-", "")}`;
}

function metadata(entry: TavernWorldbookEntry): SummaryCatalogMetadata | SummarySliceMetadata | null {
  const value = entry.extra?.echoes as { version?: unknown; kind?: unknown } | undefined;
  if (!value) return null;
  if (value.kind === "summary_catalog") {
    if (value.version !== 1 && value.version !== 2) return null;
    return value as SummaryCatalogMetadata;
  }
  if (value.kind === "summary_slice") {
    if (value.version !== 2) {
      throw new Error("Echoes summary slices must use metadata version 2 with a required timestamp.");
    }
    return value as SummarySliceMetadata;
  }
  return null;
}

function createCatalog(chatId: string): SummaryCatalog {
  return {
    formatVersion: 2,
    chatId,
    namespaceId: uniqueId("summary_namespace"),
    autoRun: false,
    recallEnabled: false,
    recallSourceWeight: 0,
    recallSourceAddWeight: 0,
    recallSourceOrder: 0,
    attachedRecallSources: [],
    compression: {
      enabled: false,
      keepRecentMessages: 30,
      recentBatchCount: 2,
      deletionPolicy: "confirm_restore",
    },
    nextBatchNumber: 1,
    pendingRetrievalDeletes: [],
    updatedAt: new Date().toISOString(),
  };
}

function catalogEntry(catalog: SummaryCatalog): Partial<TavernWorldbookEntry> {
  return {
    name: "Echoes Summary Catalog",
    enabled: false,
    strategy: { type: "constant", keys: [] },
    content: "Echoes summary catalog. Managed by the Echoes extension.",
    extra: { echoes: { kind: "summary_catalog", version: 2, catalog } satisfies SummaryCatalogMetadata },
  };
}

function nextUnusedBatchNumber(used: Set<number>, start: number): number {
  let candidate = Math.max(1, Math.floor(start));
  while (used.has(candidate)) candidate += 1;
  return candidate;
}

function sliceEntry(slice: SummarySlice): Partial<TavernWorldbookEntry> {
  return {
    name: `总结 ${slice.batch.batchNumber}.${slice.sliceNumber} [${slice.timestamp}] - ${slice.title}`,
    enabled: false,
    strategy: { type: "selective", keys: slice.tags },
    content: slice.content,
    extra: {
      echoes: {
        kind: "summary_slice",
        version: 2,
        summaryId: slice.id,
        timestamp: slice.timestamp,
        title: slice.title,
        tags: slice.tags,
        ...(slice.continuity ? { continuity: slice.continuity } : {}),
        recallFlags: slice.recallFlags ?? [],
        ...(slice.retrievalText ? { retrievalText: slice.retrievalText } : {}),
        batch: slice.batch,
        sliceNumber: slice.sliceNumber,
      } satisfies SummarySliceMetadata,
    },
  };
}

function readState(worldbookName: string, entries: TavernWorldbookEntry[]): SummaryWorldbookState | null {
  const catalogWorldbookEntry = entries.find((entry) => metadata(entry)?.kind === "summary_catalog");
  if (!catalogWorldbookEntry) return null;
  const catalogMetadata = metadata(catalogWorldbookEntry) as SummaryCatalogMetadata;
  const catalog = summaryCatalogSchema.parse(catalogMetadata.catalog);
  const slices = entries.flatMap((entry): SummarySlice[] => {
    const item = metadata(entry);
    if (!item || item.kind !== "summary_slice") return [];
    return [summarySliceSchema.parse({
      id: item.summaryId,
      timestamp: item.timestamp,
      title: item.title,
      content: entry.content,
      tags: item.tags,
      ...(item.continuity ? { continuity: item.continuity } : {}),
      recallFlags: item.recallFlags ?? [],
      ...(item.retrievalText ? { retrievalText: item.retrievalText } : {}),
      batch: item.batch,
      sliceNumber: item.sliceNumber,
      worldbookUid: entry.uid,
    })];
  });
  const messages = catalog.chatId === SillyTavern.getContext().chatId ? chatMessages() : [];
  const { compare } = createBatchOrder(messages);
  slices.sort((left, right) => compare(left.batch, right.batch)
    || (left.batch.id === right.batch.id ? left.sliceNumber - right.sliceNumber : 0));
  const batchOverviews = entries.flatMap((entry) => {
    const overview = readBatchOverview(entry);
    return overview ? [overview] : [];
  });
  return { worldbookName, catalog, slices, batchOverviews };
}

function structuredCatalogChatId(entries: TavernWorldbookEntry[]): string | null {
  for (const entry of entries) {
    const echoes = entry.extra?.echoes as { kind?: unknown; catalog?: { chatId?: unknown } } | undefined;
    if (echoes?.kind === "catalog" && typeof echoes.catalog?.chatId === "string") return echoes.catalog.chatId;
  }
  return null;
}

export class SummaryWorldbookStore {
  async load(): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("Open a SillyTavern chat before using summaries.");
    const api = helper();
    const boundWorldbookName = api.getChatWorldbookName("current");
    return worldbookWriteCoordinator.run(boundWorldbookName ?? `chat:${chatId}`, async () => {
      if (SillyTavern.getContext().chatId !== chatId) {
        throw new Error("The active chat changed before the summary operation started.");
      }
      const baseName = chatId.replace(/\.(json|jsonl)$/i, "");
      let worldbookName = boundWorldbookName;
      if (!worldbookName) {
        worldbookName = await api.getOrCreateChatWorldbook("current", `Echoes-${baseName}`);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed while the summary worldbook was being created.");
        }
      }
      let entries = await api.getWorldbook(worldbookName);
      let state = readState(worldbookName, entries);
      if ((state && state.catalog.chatId !== chatId)
        || (!state && structuredCatalogChatId(entries) && structuredCatalogChatId(entries) !== chatId)) {
        const names = new Set(api.getWorldbookNames());
        let candidate = `Echoes-${baseName}`;
        let suffix = 2;
        while (names.has(candidate)) candidate = `Echoes-${baseName}-${suffix++}`;
        await api.createWorldbook(candidate);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed before the summary worldbook could be rebound.");
        }
        await api.rebindChatWorldbook("current", candidate);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed while the summary worldbook was being rebound.");
        }
        worldbookName = candidate;
        entries = [];
        state = null;
      }
      if (!state) {
        await api.createWorldbookEntries(worldbookName, [catalogEntry(createCatalog(chatId))]);
        entries = await api.getWorldbook(worldbookName);
        state = readState(worldbookName, entries);
      }
      if (!state) throw new Error("Failed to initialize the Echoes summary catalog.");
      return state;
    });
  }

  inspect(worldbookName: string): Promise<SummaryWorldbookState> {
    return helper().getWorldbook(worldbookName).then((entries) => {
      const state = readState(worldbookName, entries);
      if (!state) throw new Error("The worldbook has no Echoes summary catalog.");
      return state;
    });
  }

  async listAvailableSources(): Promise<SummaryWorldbookState[]> {
    const inspected = await Promise.allSettled(
      helper().getWorldbookNames().map((worldbookName) => this.inspect(worldbookName)),
    );
    return inspected.flatMap((result) => result.status === "fulfilled" ? [result.value] : []);
  }

  async attachedSources(current: SummaryWorldbookState): Promise<SummaryWorldbookState[]> {
    const configured = current.catalog.attachedRecallSources.filter((source) => source.enabled
      && source.worldbookName !== current.worldbookName);
    const names = [...new Set(configured.map((source) => source.worldbookName))];
    const inspected = await Promise.allSettled(names.map((name) => this.inspect(name)));
    // Unreadable sources are reported as unavailable in the recall trace; keep the cause visible too.
    inspected.forEach((result, index) => {
      if (result.status === "rejected") console.warn(`[Echoes] 附加总结来源 ${names[index]} 读取失败`, result.reason);
    });
    return inspected.flatMap((result) => result.status === "fulfilled"
      && configured.some((source) => source.worldbookName === result.value.worldbookName
        && source.namespaceId === result.value.catalog.namespaceId && source.chatId === result.value.catalog.chatId)
      ? [result.value] : []);
  }

  commitBatch(options: {
    worldbookName: string;
    catalog: SummaryCatalog;
    batch: SummaryBatchInput;
    candidates: SummarySliceCandidate[];
    writeMode?: "create" | "rebuild" | undefined;
    advanceCheckpoint?: boolean | undefined;
    expectedCheckpoint?: string | null | undefined;
    expectedNextBatchNumber?: number | undefined;
    expectedBatchSnapshot?: string | undefined;
    signal?: AbortSignal | undefined;
  }): Promise<SummaryWorldbookState> {
    return this.serialize(options.worldbookName, async () => {
      options.signal?.throwIfAborted();
      const api = helper();
      const now = new Date().toISOString();
      let undoId: string | undefined;
      const written = await api.updateWorldbookWith(options.worldbookName, async (entries) => {
        options.signal?.throwIfAborted();
        const currentState = readState(options.worldbookName, entries);
        if (!currentState || currentState.catalog.namespaceId !== options.catalog.namespaceId) {
          throw new Error("The summary worldbook changed while the generation task was running.");
        }
        const writeMode = options.writeMode ?? "create";
        const existing = currentState.slices.filter((slice) => slice.batch.id === options.batch.id);
        const numberCollisions = currentState.slices.filter((slice) =>
          slice.batch.batchNumber === options.batch.batchNumber && slice.batch.id !== options.batch.id);
        if (writeMode === "rebuild" && existing.length === 0) {
          throw new Error("The summary batch selected for rebuilding no longer exists.");
        }
        if (numberCollisions.length > 0) {
          throw new Error("The summary batch ID and batch number refer to different existing batches.");
        }
        if (options.expectedCheckpoint !== undefined
          && (currentState.catalog.lastCommittedMessageId ?? null) !== options.expectedCheckpoint) {
          throw new Error("The summary checkpoint changed while the generation task was running.");
        }
        if (options.expectedNextBatchNumber !== undefined
          && currentState.catalog.nextBatchNumber !== options.expectedNextBatchNumber) {
          throw new Error("The summary batch sequence changed while the generation task was running.");
        }
        if (writeMode === "create" && (existing.length > 0 || numberCollisions.length > 0)) {
          throw new Error("The summary batch number was occupied before the new batch could be written.");
        }
        if (options.expectedBatchSnapshot !== undefined
          && summaryBatchSnapshot(currentState.slices, options.batch.id) !== options.expectedBatchSnapshot) {
          throw new Error("总结批次已被编辑、增加或删除，未覆盖新内容。");
        }
        const revision = Math.max(0, ...existing.map((slice) => slice.batch.revision)) + 1;
        const createdAt = existing[0]?.batch.createdAt ?? now;
        const parsed = options.candidates.map((candidate) => summarySliceCandidateSchema.parse(candidate));
        const oldByKey = new Map<string, SummarySlice[]>();
        for (const slice of existing) {
          const key = summaryPropositionKey(slice);
          oldByKey.set(key, [...(oldByKey.get(key) ?? []), slice]);
        }
        const keys = parsed.map(summaryPropositionKey);
        const counts = new Map<string, number>();
        for (const key of keys) counts.set(key, (counts.get(key) ?? 0) + 1);
        // Reuse identities only for an unambiguous exact proposition, never its output position.
        const slices: SummarySlice[] = parsed.map((candidate, index) => {
          const key = keys[index]!;
          const matches = oldByKey.get(key) ?? [];
          const previous = matches.length === 1 && counts.get(key) === 1
            ? matches[0] : undefined;
          return summarySliceSchema.parse({
            ...candidate,
            id: previous?.id ?? uniqueId("summary"),
            ...(previous?.recallFlags ? { recallFlags: previous.recallFlags } : {}),
            ...(previous?.retrievalText ? { retrievalText: previous.retrievalText } : {}),
            sliceNumber: index + 1,
            batch: {
              ...options.batch,
              source: { kind: "chat_messages" },
              state: "pending",
              revision,
              createdAt,
              updatedAt: now,
            },
          });
        });
        const desiredIds = new Set(slices.map((slice) => slice.id));
        const removedIds = existing.map((slice) => slice.id).filter((id) => !desiredIds.has(id));
        const existingIds = new Set(existing.map((slice) => slice.id));
        const usedBatchNumbers = new Set(currentState.slices
          .filter((slice) => slice.batch.id !== options.batch.id)
          .map((slice) => slice.batch.batchNumber));
        usedBatchNumbers.add(options.batch.batchNumber);
        const nextCatalog = summaryCatalogSchema.parse({
          ...prunePool(currentState.catalog, new Set(removedIds)),
          ...(options.advanceCheckpoint !== false && options.batch.purpose !== "supplement"
            ? { lastCommittedMessageId: options.batch.endMessageId }
            : {}),
          nextBatchNumber: writeMode === "create"
            ? nextUnusedBatchNumber(usedBatchNumbers, options.batch.batchNumber + 1)
            : currentState.catalog.nextBatchNumber,
          pendingRetrievalDeletes: [...new Set([
            ...currentState.catalog.pendingRetrievalDeletes,
            ...removedIds,
          ])].filter((id) => !desiredIds.has(id)),
          updatedAt: now,
        });
        const nextEntries = entries.flatMap((entry) => {
          const item = metadata(entry);
          if (item?.kind === "summary_catalog") {
            return [{ ...entry, ...catalogEntry(nextCatalog) }];
          }
          if (item?.kind === "summary_slice" && item.batch.id === options.batch.id) {
            const replacement = slices.find((slice) => slice.id === item.summaryId);
            return replacement ? [{ ...entry, ...sliceEntry(replacement) }] : [];
          }
          return [entry];
        });
        nextEntries.push(...slices
          .filter((slice) => !existingIds.has(slice.id))
          .map((slice) => sliceEntry(slice) as TavernWorldbookEntry));
        const previousOverview = currentState.batchOverviews?.find((item) => item.batch.id === options.batch.id);
        const overview = batchOverviewSchema.parse({
          batch: slices[0]!.batch, enabled: previousOverview?.enabled ?? true,
          content: previousOverview?.content ?? "", state: "pending",
          revision: (previousOverview?.revision ?? 0) + 1, updatedAt: now,
        });
        const overviewIndex = nextEntries.findIndex((entry) => readBatchOverview(entry)?.batch.id === options.batch.id);
        if (overviewIndex < 0) nextEntries.push(batchOverviewEntry(overview) as TavernWorldbookEntry);
        else nextEntries[overviewIndex] = { ...nextEntries[overviewIndex]!, ...batchOverviewEntry(overview) };
        if (writeMode === "rebuild") undoId = await recordMemoryUndo(options.worldbookName, "summary",
          `替换总结批次 ${options.batch.batchNumber}`, entries, nextEntries);
        return nextEntries;
      });
      await completeMemoryUndo(options.worldbookName, options.catalog.chatId, undoId, written);
      return { ...await this.inspect(options.worldbookName), undoOperationId: undoId };
    });
  }

  setAutoRun(worldbookName: string, enabled: boolean): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({ ...catalog, autoRun: enabled }));
  }

  setAutomaticStop(worldbookName: string, messageId: string | null): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => {
      if (messageId === null) delete catalog.automaticStopMessageId;
      else catalog.automaticStopMessageId = messageId;
      return catalog;
    });
  }

  saveBatchOverview(expected: SummaryWorldbookState, batchId: string,
    patch: Partial<Pick<BatchOverview, "content" | "enabled" | "state" | "error">>,
    signal?: AbortSignal, undoId?: string): Promise<SummaryWorldbookState> {
    return this.serialize(expected.worldbookName, async () => {
      const written = await helper().updateWorldbookWith(expected.worldbookName, async (entries) => {
        signal?.throwIfAborted();
        const current = readState(expected.worldbookName, entries);
        if (!current || current.catalog.namespaceId !== expected.catalog.namespaceId
          || current.catalog.chatId !== SillyTavern.getContext().chatId
          || helper().getChatWorldbookName("current") !== expected.worldbookName) {
          throw new Error("聊天或总结目录已变化，未保存批次总结。");
        }
        const batch = current.slices.find((slice) => slice.batch.id === batchId)?.batch;
        const old = current.batchOverviews?.find((item) => item.batch.id === batchId);
        const before = expected.batchOverviews?.find((item) => item.batch.id === batchId);
        if (!batch || batch.sourceHash !== expected.slices.find((slice) => slice.batch.id === batchId)?.batch.sourceHash
          || old?.revision !== before?.revision) throw new Error("批次总结已变化或批次已删除，请刷新后重试。");
        const overview = batchOverviewSchema.parse({
          batch, content: "", enabled: true, state: "pending", ...old, ...patch,
          revision: (old?.revision ?? 0) + 1, updatedAt: new Date().toISOString(),
        });
        if (patch.state === "ready" || patch.state === "pending") delete overview.error;
        const index = entries.findIndex((entry) => readBatchOverview(entry)?.batch.id === batchId);
        const beforeEntry = index < 0 ? undefined : structuredClone(entries[index]);
        if (index < 0) entries.push(batchOverviewEntry(overview) as TavernWorldbookEntry);
        else entries[index] = { ...entries[index]!, ...batchOverviewEntry(overview) };
        await amendMemoryUndo(expected.worldbookName, expected.catalog.chatId, undoId, (record) => {
          const change = record.changes.find((change) => change.key === `overview:${batchId}`);
          if (!change || undoFingerprint(change.after) !== undoFingerprint(beforeEntry))
            throw new Error("批次总结的撤销基线已变化，未覆盖新内容。");
          change.pendingAfter = structuredClone(entries.find((entry) => readBatchOverview(entry)?.batch.id === batchId)!);
        });
        return entries;
      });
      if (undoId) await amendMemoryUndo(expected.worldbookName, expected.catalog.chatId, undoId, (record) => {
        const change = record.changes.find((change) => change.key === `overview:${batchId}`)!;
        change.after = structuredClone(written.find((entry) => readBatchOverview(entry)?.batch.id === batchId));
        delete change.pendingAfter;
      });
      return this.inspect(expected.worldbookName);
    });
  }

  saveCompressionConfiguration(
    worldbookName: string,
    compression: SummaryCatalog["compression"],
  ): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      compression: structuredClone(compression),
    }));
  }

  saveRecallConfiguration(
    worldbookName: string,
    configuration: {
      enabled: boolean;
      weight: number;
      addWeight?: number | undefined;
      order: number;
      attachedSources: AttachedRecallSource[];
    },
  ): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => {
      const allowed = new Set([catalog.namespaceId, ...configuration.attachedSources
        .filter((source) => source.enabled).map((source) => source.namespaceId)]);
      if (!configuration.enabled) delete catalog.recallPool;
      else if (catalog.recallPool) catalog.recallPool = {
        ...catalog.recallPool,
        entries: catalog.recallPool.entries.filter((ref) => allowed.has(ref.namespaceId)),
        replay: catalog.recallPool.replay.filter((ref) => allowed.has(ref.namespaceId)),
      };
      return {
        ...catalog,
        recallEnabled: configuration.enabled,
        recallSourceWeight: configuration.weight,
        recallSourceAddWeight: configuration.addWeight ?? catalog.recallSourceAddWeight ?? 0,
        recallSourceOrder: configuration.order,
        attachedRecallSources: structuredClone(configuration.attachedSources),
      };
    });
  }

  setRetrievalBinding(
    worldbookName: string,
    collectionId: string,
    embeddingSpaceId: string,
  ): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      retrievalCollectionId: collectionId,
      retrievalEmbeddingSpaceId: embeddingSpaceId,
    }));
  }

  markBatchState(
    worldbookName: string,
    batchId: string,
    state: SummarySyncState,
    sliceIds?: string[],
  ): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const api = helper();
      const now = new Date().toISOString();
      const targets = sliceIds ? new Set(sliceIds) : null;
      await api.updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
        const item = metadata(entry);
        if (item?.kind !== "summary_slice" || item.batch.id !== batchId) return entry;
        if (targets && !targets.has(item.summaryId)) return entry;
        return {
          ...entry,
          extra: {
            ...entry.extra,
            echoes: { ...item, batch: { ...item.batch, state, updatedAt: now } },
          },
        };
      }));
      return this.inspect(worldbookName);
    }, state === "stale");
  }

  markSliceSyncState(expected: SummaryWorldbookState, slice: SummarySlice, syncState: SummarySyncState): Promise<SummaryWorldbookState> {
    return this.serialize(expected.worldbookName, async () => {
      await helper().updateWorldbookWith(expected.worldbookName, (entries) => {
        const current = readState(expected.worldbookName, entries);
        const fresh = current?.slices.find((candidate) => candidate.id === slice.id);
        if (!current || current.catalog.namespaceId !== expected.catalog.namespaceId
          || current.catalog.retrievalCollectionId !== expected.catalog.retrievalCollectionId
          || current.catalog.retrievalEmbeddingSpaceId !== expected.catalog.retrievalEmbeddingSpaceId
          || !fresh || fresh.batch.state === "stale" || slice.batch.state === "stale"
          || summaryBatchSnapshot([fresh], fresh.batch.id) !== summaryBatchSnapshot([slice], slice.batch.id)) return entries;
        return entries.map((entry) => {
          const item = metadata(entry);
          return item?.kind === "summary_slice" && item.summaryId === slice.id
            ? { ...entry, extra: { ...entry.extra, echoes: { ...item,
              batch: { ...item.batch, state: syncState, updatedAt: new Date().toISOString() } } } } : entry;
        });
      });
      return this.inspect(expected.worldbookName);
    }, false);
  }

  relocateCheckpoint(worldbookName: string, chatId: string, messageId: string | null): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => {
      if (catalog.chatId !== chatId || SillyTavern.getContext().chatId !== chatId
        || helper().getChatWorldbookName("current") !== worldbookName) throw new Error("聊天已切换，未修改检查点。");
      catalog.autoRun = false;
      if (messageId === null) {
        delete catalog.lastCommittedMessageId;
        delete catalog.checkpointAnchorMessageId;
      } else {
        catalog.lastCommittedMessageId = messageId;
        catalog.checkpointAnchorMessageId = messageId;
      }
      return catalog;
    });
  }

  activateRetrievalMigration(
    expected: SummaryWorldbookState,
    collectionId: string,
    embeddingSpaceId: string,
    signal: AbortSignal,
  ): Promise<SummaryWorldbookState> {
    return this.serialize(expected.worldbookName, async () => {
      signal.throwIfAborted();
      await helper().updateWorldbookWith(expected.worldbookName, (entries) => {
        signal.throwIfAborted();
        const current = readState(expected.worldbookName, entries);
        if (!current || summaryMigrationFingerprint(current) !== summaryMigrationFingerprint(expected)) {
          throw new Error("迁移期间总结内容或绑定已变化，请重试迁移。");
        }
        if (SillyTavern.getContext().chatId !== current.catalog.chatId
          || helper().getChatWorldbookName("current") !== expected.worldbookName) {
          throw new Error("迁移期间聊天已切换，原索引绑定保持不变。");
        }
        const catalog = summaryCatalogSchema.parse({ ...current.catalog,
          retrievalCollectionId: collectionId, retrievalEmbeddingSpaceId: embeddingSpaceId,
          pendingRetrievalDeletes: [], updatedAt: new Date().toISOString(),
        });
        return entries.map((entry) => {
          const item = metadata(entry);
          if (item?.kind === "summary_catalog") return { ...entry, ...catalogEntry(catalog) };
          if (item?.kind === "summary_slice" && item.batch.state !== "stale") {
            return { ...entry, extra: { ...entry.extra, echoes: { ...item,
              batch: { ...item.batch, state: "ready", updatedAt: catalog.updatedAt },
            } } };
          }
          return entry;
        });
      });
      return this.inspect(expected.worldbookName);
    });
  }

  async markStaleFrom(worldbookName: string, batchNumber: number): Promise<SummaryWorldbookState> {
    const state = await this.inspect(worldbookName);
    return this.invalidateBatches(state, [...new Set(summarySuffix(state.slices, batchNumber, chatMessages()).map((slice) => slice.batch.id))]);
  }

  invalidateBatches(expected: SummaryWorldbookState, batchIds: string[], signal?: AbortSignal): Promise<SummaryWorldbookState> {
    const worldbookName = expected.worldbookName;
    return this.serialize(worldbookName, async () => {
      const now = new Date().toISOString();
      await helper().updateWorldbookWith(worldbookName, (entries) => {
        signal?.throwIfAborted();
        const state = readState(worldbookName, entries);
        if (!state || state.catalog.namespaceId !== expected.catalog.namespaceId) throw new Error("总结目录已变化，请重试完整性检查。");
        for (const id of batchIds) {
          if (summaryBatchSnapshot(state.slices, id) !== summaryBatchSnapshot(expected.slices, id))
            throw new Error("总结已变化，请重试完整性检查。");
        }
        const ids = new Set(batchIds);
        const affected = state.slices.filter((slice) => ids.has(slice.batch.id) && slice.batch.source?.kind !== "imported");
        const catalog = prunePool(state.catalog, new Set(affected.map((slice) => slice.id)));
        const messages = chatMessages();
        const checkpoint = messages.findIndex((message) => message.id === catalog.lastCommittedMessageId);
        const anchor = messages.findIndex((message) => message.id === catalog.checkpointAnchorMessageId);
        const { start } = createBatchOrder(messages);
        const starts = affected.filter((slice) => slice.batch.purpose !== "supplement")
          .map((slice) => start(slice.batch) ?? 0);
        if (starts.length && catalog.lastCommittedMessageId) {
          const rollback = Math.max(anchor, Math.min(...starts) - 1);
          if (checkpoint < 0 || rollback < checkpoint) {
            if (rollback >= 0) catalog.lastCommittedMessageId = messages[rollback]!.id;
            else delete catalog.lastCommittedMessageId;
          }
        }
        catalog.pendingRetrievalDeletes = [...new Set([...catalog.pendingRetrievalDeletes, ...affected.map((slice) => slice.id)])];
        catalog.updatedAt = now;
        return entries.map((entry) => {
          const item = metadata(entry);
          if (item?.kind === "summary_catalog") return { ...entry, ...catalogEntry(summaryCatalogSchema.parse(catalog)) };
          if (item?.kind !== "summary_slice" || !ids.has(item.batch.id) || item.batch.source?.kind === "imported") return entry;
          return { ...entry, extra: { ...entry.extra,
            echoes: { ...item, batch: { ...item.batch, state: "stale", updatedAt: now } } } };
        });
      });
      return this.inspect(worldbookName);
    });
  }

  saveSlice(worldbookName: string, sliceId: string, candidate: SummarySliceCandidate, expectedRevision?: number): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const api = helper();
      const parsed = summarySliceCandidateSchema.parse(candidate);
      const now = new Date().toISOString();
      await api.updateWorldbookWith(worldbookName, (entries) => {
        if (!entries.some((entry) => metadata(entry)?.kind === "summary_slice" && entry.extra?.echoes?.summaryId === sliceId))
          throw new Error("切片已删除，请刷新后重试。");
        return entries.map((entry) => {
        const item = metadata(entry);
        if (item?.kind !== "summary_slice" || item.summaryId !== sliceId) return entry;
        if (expectedRevision !== undefined && item.batch.revision !== expectedRevision) throw new Error("切片已变化，请刷新后重新编辑。");
        const updated: SummarySlice = {
          ...parsed,
          ...(!parsed.continuity && item.continuity ? { continuity: item.continuity } : {}),
          ...(item.retrievalText ? { retrievalText: item.retrievalText } : {}),
          recallFlags: item.recallFlags ?? [],
          id: item.summaryId,
          sliceNumber: item.sliceNumber,
          worldbookUid: entry.uid,
          batch: {
            ...item.batch,
            state: "pending",
            revision: item.batch.revision + 1,
            updatedAt: now,
          },
        };
        return { ...entry, ...sliceEntry(updated) };
      }); });
      return this.inspect(worldbookName);
    });
  }

  saveSliceFlags(worldbookName: string, sliceIds: string[], flags: string[], mode: "add" | "remove" | "replace"):
    Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const targets = new Set(sliceIds);
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
        const item = metadata(entry);
        if (item?.kind !== "summary_slice" || !targets.has(item.summaryId)) return entry;
        const previous = item.recallFlags ?? [];
        const next = mode === "replace" ? flags : mode === "add" ? [...previous, ...flags]
          : previous.filter((id) => !flags.includes(id));
        const recallFlags = summarySliceSchema.shape.recallFlags.parse([...new Set(next)]);
        return { ...entry, extra: { ...entry.extra, echoes: { ...item, recallFlags } } };
      }));
      return this.inspect(worldbookName);
    });
  }

  saveRetrievalTexts(expected: SummaryWorldbookState, values: Map<string, string | undefined>): Promise<SummaryWorldbookState> {
    return this.serialize(expected.worldbookName, async () => {
      await helper().updateWorldbookWith(expected.worldbookName, (entries) => {
        const current = readState(expected.worldbookName, entries);
        if (!current || current.catalog.chatId !== SillyTavern.getContext().chatId
          || helper().getChatWorldbookName("current") !== expected.worldbookName) throw new Error("聊天已切换，未保存检索表示。");
        for (const id of values.keys()) {
          const before = expected.slices.find((slice) => slice.id === id);
          const after = current.slices.find((slice) => slice.id === id);
          if (!before || !after || before.batch.revision !== after.batch.revision
            || before.content !== after.content || before.retrievalText !== after.retrievalText) {
            throw new Error("切片已改变，请重新打开检索表示编辑器。");
          }
        }
        return entries.map((entry) => {
          const item = metadata(entry);
          if (item?.kind !== "summary_slice" || !values.has(item.summaryId)) return entry;
          const value = values.get(item.summaryId)?.trim() || undefined;
          const retrievalText = summarySliceSchema.shape.retrievalText.parse(value);
          if (retrievalText === item.retrievalText) return entry;
          const updated = { ...item };
          if (retrievalText) updated.retrievalText = retrievalText;
          else delete updated.retrievalText;
          updated.batch = { ...item.batch, revision: item.batch.revision + 1,
            state: item.batch.state === "stale" ? "stale" : "pending", updatedAt: new Date().toISOString() };
          return { ...entry, extra: { ...entry.extra, echoes: updated } };
        });
      });
      return this.inspect(expected.worldbookName);
    });
  }

  saveRecallPool(worldbookName: string, pool: RecallPoolState, guard: () => void): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => {
      guard();
      return { ...catalog, recallPool: structuredClone(pool) };
    }, false);
  }

  deleteSlice(worldbookName: string, sliceId: string): Promise<SummaryWorldbookState> {
    return this.deleteSlices(worldbookName, [sliceId]);
  }

  deleteSlices(worldbookName: string, sliceIds: string[], visibility: VisibilityChange[] = []): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const removed = new Set(sliceIds);
      let undoId: string | undefined;
      const chatId = SillyTavern.getContext().chatId!;
      const written = await helper().updateWorldbookWith(worldbookName, async (entries) => {
        const state = readState(worldbookName, entries);
        if (!state || state.catalog.chatId !== chatId || helper().getChatWorldbookName("current") !== worldbookName)
          throw new Error("聊天或世界书已变化。");
        const existingIds = state.slices.filter((slice) => removed.has(slice.id)).map((slice) => slice.id);
        if (existingIds.length !== removed.size) throw new Error("部分切片已删除，请刷新后重新选择。");
        const catalog = { ...prunePool(state.catalog, removed),
          pendingRetrievalDeletes: [...new Set([...state.catalog.pendingRetrievalDeletes, ...existingIds])],
          updatedAt: new Date().toISOString() };
        const next = pruneBatchOverviews(entries.flatMap((entry) => {
          const item = metadata(entry);
          if (item?.kind === "summary_slice" && removed.has(item.summaryId)) return [];
          return [item?.kind === "summary_catalog" ? { ...entry, ...catalogEntry(catalog) } : entry];
        }));
        undoId = await recordMemoryUndo(worldbookName, "summary", `删除 ${existingIds.length} 个总结切片`, entries, next, visibility);
        return next;
      });
      await completeMemoryUndo(worldbookName, chatId, undoId, written);
      return { ...await this.inspect(worldbookName), undoOperationId: undoId };
    });
  }

  undoOperation(worldbookName: string, id: string): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const record = await requireMemoryUndo(worldbookName, id);
      if (record.kind !== "summary") throw new Error("撤销记录类型不符。");
      const written = await helper().updateWorldbookWith(worldbookName, async (entries) => {
        const next = applyMemoryUndo(record, entries);
        readState(worldbookName, next);
        await prepareMemoryUndoRestore(record, next);
        return next;
      });
      await completeMemoryUndo(worldbookName, record.chatId, id, written, true);
      return this.inspect(worldbookName);
    });
  }

  setNextBatchNumber(worldbookName: string, batchNumber: number): Promise<SummaryWorldbookState> {
    if (!Number.isInteger(batchNumber) || batchNumber < 1) {
      return Promise.reject(new Error("总结批次编号必须是大于 0 的整数。"));
    }
    return this.serialize(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      if (state.slices.some((slice) => slice.batch.batchNumber === batchNumber)) {
        throw new Error("该批次编号已经存在，请先重建、重置或删除对应批次。");
      }
      await this.updateCatalog(worldbookName, {
        ...state.catalog,
        nextBatchNumber: batchNumber,
        updatedAt: new Date().toISOString(),
      });
      return this.inspect(worldbookName);
    });
  }

  resetFrom(worldbookName: string, batchNumber: number): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      const removed = summarySuffix(state.slices, batchNumber, chatMessages());
      const removedIds = new Set(removed.map((slice) => slice.id));
      const retained = state.slices.filter((slice) => slice.batch.source?.kind !== "imported"
        && !removedIds.has(slice.id));
      const previous = retained.filter((slice) => slice.batch.purpose !== "supplement").at(-1)?.batch;
      await helper().updateWorldbookWith(worldbookName, (entries) => pruneBatchOverviews(entries.filter((entry) => {
        const item = metadata(entry);
        return item?.kind !== "summary_slice"
          || !removedIds.has(item.summaryId);
      })));
      const nextCatalog: SummaryCatalog = {
        ...prunePool(state.catalog, removedIds),
        nextBatchNumber: batchNumber,
        pendingRetrievalDeletes: [...new Set([
          ...state.catalog.pendingRetrievalDeletes,
          ...removed.map((slice) => slice.id),
        ])],
        updatedAt: new Date().toISOString(),
      };
      if (previous) nextCatalog.lastCommittedMessageId = previous.endMessageId;
      else delete nextCatalog.lastCommittedMessageId;
      delete nextCatalog.checkpointAnchorMessageId;
      await this.updateCatalog(worldbookName, nextCatalog);
      return this.inspect(worldbookName);
    });
  }

  clearPendingDeletes(worldbookName: string, deletedIds: string[]): Promise<SummaryWorldbookState> {
    const removed = new Set(deletedIds);
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      pendingRetrievalDeletes: catalog.pendingRetrievalDeletes.filter((id) => !removed.has(id)),
    }));
  }

  private updateState(
    worldbookName: string,
    updater: (catalog: SummaryCatalog) => SummaryCatalog,
    invalidate = true,
  ): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      const catalog = {
        ...updater(structuredClone(state.catalog)),
        updatedAt: new Date().toISOString(),
      };
      await this.updateCatalog(worldbookName, catalog);
      return this.inspect(worldbookName);
    }, invalidate);
  }

  private async updateCatalog(worldbookName: string, catalog: SummaryCatalog): Promise<void> {
    const parsed = summaryCatalogSchema.parse(catalog);
    await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
      const item = metadata(entry);
      return item?.kind === "summary_catalog" ? { ...entry, ...catalogEntry(parsed) } : entry;
    }));
  }

  private serialize<T>(worldbookName: string, operation: () => Promise<T>, invalidate = true): Promise<T> {
    return worldbookWriteCoordinator.run(worldbookName, async () => {
      if (invalidate) invalidateRecall(worldbookName);
      const result = await operation();
      if (invalidate) invalidateRecall(worldbookName);
      return result;
    });
  }
}
