import { statusCoordinator as coordinator } from "../../../status/status-coordinator";
import type { StatusSnapshotRecord } from "../../../status/status-snapshots";
import { fieldDifferences, displayValue } from "../../diff";
import { h, formatTime } from "../../kit/dom";
import { button, badge } from "../../kit/controls";
import { lazy, muted } from "../../kit/layout";
import { list, table, paginate, pager } from "../../kit/data";
import { drawer } from "../../kit/drawer";
import { confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { stateTree } from "./current";

const ORIGIN = { auto: "自动", manual: "手动", restored: "恢复" } as const;

export async function statusSnapshotsPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await coordinator.load();
  const history = coordinator.history(state);
  const current = coordinator.current(state);
  const baseline = current?.snapshot.state ?? state.catalog.profile.initialState;
  const ui = ctx.memo("status-snapshots", () => ({ page: 0 }));
  const pane = drawer("快照详情");
  const host = h("div", "ec-stack");
  const open = (record: StatusSnapshotRecord) => {
    const changes = fieldDifferences(record.snapshot.state, baseline);
    return pane.open(record.snapshot.snapshotId, `第 ${record.messageIndex} 楼 · 分支 ${record.swipeId}`, [
      h("div", "ec-row", badge(ORIGIN[record.snapshot.origin]), record.selected ? badge("当前分支", "accent") : null,
        h("span", "ec-muted", formatTime(record.snapshot.updatedAt))),
      h("h4", "", `与当前状态的差异 · ${changes.length}`),
      changes.length ? table([
        { label: "字段", cell: (change) => change.path.join(" / ") },
        { label: "此快照", cell: (change) => displayValue(change.before) },
        { label: "当前状态", cell: (change) => displayValue(change.after) },
      ], changes) : muted("与当前状态完全相同。"),
      h("h4", "", "快照内容"), stateTree(record.snapshot.state),
      lazy("快照元数据", record.snapshot),
    ], [button("恢复此快照", async () => {
      if (!await confirmAction({ title: "把这个快照恢复为当前状态？", confirmLabel: "恢复" })) return;
      ctx.guard();
      await coordinator.restoreSnapshot(record.snapshot);
      await ctx.refresh();
    }, { small: true, icon: "rotate-left" })]);
  };
  const draw = () => {
    const page = paginate(history, ui);
    host.replaceChildren(list(page.items.map((record) => ({
      key: record.snapshot.snapshotId, selected: pane.current() === record.snapshot.snapshotId,
      title: `第 ${record.messageIndex} 楼 · 分支 ${record.swipeId}`,
      meta: formatTime(record.snapshot.updatedAt),
      trailing: h("span", "ec-row", record.selected ? badge("当前分支", "accent") : null, badge(ORIGIN[record.snapshot.origin])),
      onOpen: () => open(record),
    })), "还没有状态快照。"));
    if (page.pages > 1) host.append(pager(ui, page.pages, history.length, draw, "个"));
  };
  pane.onChange(() => draw());
  pane.list.append(host);
  draw();
  return pane.node;
}
