import { creativePreferencesSchema, EMPTY_CREATIVE_PREFERENCES, renderCreativePreferences } from "../../shared/creative-preferences";
import { getSettings } from "../state/settings";
import { WorldbookMemoryStore } from "../worldbook/worldbook-memory";
import { worldbookWriteCoordinator } from "../worldbook/worldbook-write-coordinator";
import { randomUuid } from "../../shared/crypto-compat";

let lastInjection: { worldbookName: string; id: string } | undefined;

export async function clearCreativePreferences(): Promise<void> {
  const ownership = lastInjection;
  lastInjection = undefined;
  const name = ownership?.worldbookName ?? window.TavernHelper?.getChatWorldbookName("current");
  if (!name || !window.TavernHelper) return;
  await worldbookWriteCoordinator.run(name, () => window.TavernHelper!.updateWorldbookWith(name, (entries) =>
    entries.map((entry) => {
      const metadata = entry.extra?.echoes;
      if (metadata?.kind !== "creative_preferences_injection"
        || ownership && metadata.generationId !== ownership.id) return entry;
      return { ...entry, enabled: false, content: "" };
    })));
}

export async function prepareCreativePreferences(type = "normal"): Promise<void> {
  await clearCreativePreferences();
  const context = SillyTavern.getContext();
  const chatId = context.chatId;
  const api = window.TavernHelper;
  if (!chatId || !api || !["chat", "normal", "regenerate", "swipe", "continue"].includes(type)) return;
  let worldbook = api.getChatWorldbookName("current");
  const global = getSettings().creativePreferences;
  if (!worldbook) {
    if (!global.enabled || !global.rules.some((rule) => rule.enabled && rule.confirmed)) return;
    worldbook = (await new WorldbookMemoryStore().load()).worldbookName;
  }
  const name = worldbook;
  const ownership = { worldbookName: name, id: randomUuid() };
  lastInjection = ownership;
  await worldbookWriteCoordinator.run(name, async () => {
    const guard = () => {
      if (lastInjection !== ownership || SillyTavern.getContext().chatId !== chatId || api.getChatWorldbookName("current") !== name)
        throw new Error("聊天已切换，未更新创作偏好注入。");
    };
    guard();
    await api.updateWorldbookWith(name, (entries) => {
      guard();
      const catalog = entries.find((entry) => entry.extra?.echoes?.kind === "catalog")?.extra!.echoes.catalog;
      const local = catalog?.chatId === chatId
        ? creativePreferencesSchema.parse(catalog.creativePreferences ?? EMPTY_CREATIVE_PREFERENCES) : EMPTY_CREATIVE_PREFERENCES;
      const content = renderCreativePreferences(global, local);
      const index = entries.findIndex((entry) => entry.extra?.echoes?.kind === "creative_preferences_injection");
      if (index < 0 && !content) return entries;
      const entry: Partial<TavernWorldbookEntry> = { name: "[Echoes] 创作偏好", enabled: Boolean(content),
        content, strategy: { type: "constant", keys: [] },
        position: { type: "after_character_definition", role: "system", depth: 4, order: 75 },
        recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
        extra: { echoes: { kind: "creative_preferences_injection", version: 1, chatId,
          generationId: ownership.id, updatedAt: new Date().toISOString() } } };
      if (index < 0) entries.push(entry as TavernWorldbookEntry);
      else entries[index] = { ...entries[index]!, ...entry };
      return entries;
    });
  });
}
