import {
  evaluateStatusVariables, formatStatusVariableNumber, renderStatusVariables, replaceStatusVariable,
  type StatusVariable, type StatusVariableValue,
} from "../../../../shared/status-variables";
import { statusCoordinator } from "../../../status/status-coordinator";
import type { StatusWorldbookState } from "../../../worldbook/status-worldbook";
import { h, fill, uid, errorText } from "../../kit/dom";
import { button, badge, menu } from "../../kit/controls";
import { card, stack, code, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formModal, confirmAction } from "../../kit/overlays";
import { table } from "../../kit/data";
import type { PageContext } from "../../shell/context";

const FORMULA_HINT = "支持 + - * / % ^、括号及 abs / min / max / floor / ceil / round / sqrt；引用写作 base(\"变量名\") 或 final(\"变量名\")。";

export async function statusVariablesPage(ctx: PageContext): Promise<HTMLElement> {
  let state: StatusWorldbookState = await statusCoordinator.load();
  const host = h("div", "ec-stack");
  const edit = (variable?: StatusVariable) => {
    const expected = structuredClone(state.catalog.customVariables);
    const id = variable?.id ?? uid("status_variable");
    const fixed = expected.filter((item) => item.type === "fixed" && item.id !== id);
    const target = form([
      { key: "name", label: "变量名", value: variable?.name ?? "", required: true },
      { key: "type", label: "类型", type: "select", value: variable?.type ?? "fixed", options: [["fixed", "固定变量"], ["computed", "变化变量（公式计算）"]] },
      { key: "baseNumber", label: "基础值", type: "number", step: "any", required: true, value: variable?.base.kind === "number" ? variable.base.value : 0 },
      { key: "baseFormula", label: "基础公式", type: "code", rows: 3, required: true, value: variable?.base.kind === "formula" ? variable.base.value : "", hint: FORMULA_HINT },
      { key: "extraKind", label: "额外值", type: "select", value: variable?.extra.kind ?? "number", options: [["number", "固定数值"], ["formula", "公式"]] },
      { key: "extraNumber", label: "额外数值", type: "number", step: "any", required: true, value: variable?.extra.kind === "number" ? variable.extra.value : 0 },
      { key: "extraFormula", label: "额外公式", type: "code", rows: 3, required: true, value: variable?.extra.kind === "formula" ? variable.extra.value : "", hint: FORMULA_HINT },
      { key: "refVariable", label: "插入引用：变量", type: "select", options: fixed.map((item) => [item.name, item.name]) },
      { key: "refPart", label: "插入引用：取值", type: "select", options: [["base", "基础值"], ["final", "最终值"]] },
    ]);
    const sync = () => {
      const computed = target.control("type").value === "computed";
      const formulaExtra = target.control("extraKind").value === "formula";
      target.show("baseNumber", !computed);
      target.show("baseFormula", computed);
      target.show("extraNumber", !formulaExtra);
      target.show("extraFormula", formulaExtra);
      target.show("refVariable", (computed || formulaExtra) && fixed.length > 0);
      target.show("refPart", (computed || formulaExtra) && fixed.length > 0);
    };
    target.control("type").addEventListener("change", sync);
    target.control("extraKind").addEventListener("change", sync);
    sync();
    let lastFormula: HTMLTextAreaElement | null = null;
    for (const key of ["baseFormula", "extraFormula"]) target.control(key).addEventListener("focus", (event) => { lastFormula = event.target as HTMLTextAreaElement; });
    const candidate = () => {
      const values = target.values();
      const base: StatusVariableValue = values.type === "fixed" ? { kind: "number", value: values.baseNumber } : { kind: "formula", value: values.baseFormula };
      const extra: StatusVariableValue = values.extraKind === "number" ? { kind: "number", value: values.extraNumber } : { kind: "formula", value: values.extraFormula };
      return replaceStatusVariable(expected, { id, name: values.name, type: values.type, base, extra });
    };
    const trial = h("div");
    formModal(variable ? `编辑变量 · ${variable.name}` : "新增变量", target, async () => {
      ctx.guard();
      state = await statusCoordinator.worldbook.saveVariables(state.worldbookName, candidate(), expected, ctx.guard);
      draw();
    }, { size: "large", after: trial, extra: [
      button("插入引用", () => {
        const control = lastFormula ?? (target.control("type").value === "computed" ? target.control("baseFormula") : target.control("extraFormula")) as HTMLTextAreaElement;
        const name = target.control("refVariable").value;
        if (!name) throw new Error("当前没有可引用的其他固定变量。");
        control.setRangeText(`${target.control("refPart").value}(${JSON.stringify(name)})`, control.selectionStart, control.selectionEnd, "end");
        control.dispatchEvent(new Event("input", { bubbles: true }));
        control.focus();
      }, { variant: "ghost", icon: "arrow-turn-down" }),
      button("试算", () => {
        try { fill(trial, code(renderStatusVariables(candidate()))); }
        catch (error) { fill(trial, callout("danger", errorText(error))); }
      }, { variant: "ghost", icon: "calculator" }),
    ] });
  };
  const valueCell = (value: number, source: StatusVariableValue) => h("div", "ec-cell-stack",
    h("span", "", formatStatusVariableNumber(value)), source.kind === "formula" ? h("code", "ec-muted", source.value) : null);
  const draw = () => {
    const variables = state.catalog.customVariables;
    let evaluated: ReturnType<typeof evaluateStatusVariables> | null = null;
    let problem = "";
    try { evaluated = evaluateStatusVariables(variables); } catch (error) { problem = errorText(error); }
    fill(host,
      problem ? callout("danger", problem) : null,
      table([
        { label: "变量", cell: (variable) => h("strong", "", variable.name) },
        { label: "类型", cell: (variable) => badge(variable.type === "fixed" ? "固定" : "变化", variable.type === "fixed" ? "neutral" : "accent") },
        { label: "基础值", cell: (variable, index) => evaluated ? valueCell(evaluated[index]!.base, variable.base) : "—" },
        { label: "额外值", cell: (variable, index) => evaluated ? valueCell(evaluated[index]!.extra, variable.extra) : "—" },
        { label: "最终值", cell: (_variable, index) => evaluated ? h("strong", "", formatStatusVariableNumber(evaluated[index]!.final)) : "—" },
        { label: "", className: "is-actions", cell: (variable) => menu(`${variable.name} 的操作`, [
          { label: "编辑", icon: "pen", onSelect: () => edit(variable) },
          { label: "删除", icon: "trash", danger: true, onSelect: async () => {
            if (!await confirmAction({ title: `删除变量「${variable.name}」？`, danger: true, confirmLabel: "删除" })) return;
            ctx.guard();
            const next = state.catalog.customVariables.filter((item) => item.id !== variable.id);
            evaluateStatusVariables(next);
            state = await statusCoordinator.worldbook.saveVariables(state.worldbookName, next, state.catalog.customVariables, ctx.guard);
            draw();
          } },
        ]) },
      ], variables, { empty: "还没有自定义变量。" }),
      variables.length && evaluated ? card("注入内容", { description: "随状态一起注入主模型。" }, code(renderStatusVariables(variables))) : null,
    );
  };
  draw();
  return stack(
    card("自定义变量", { scope: "chat", description: "在本地计算的数值，不调用模型。", actions: [
      state.catalog.enabled ? badge("状态注入已启用", "success") : badge("状态注入未启用，变量不会注入", "warning"),
      button("新增变量", () => edit(), { variant: "primary", icon: "plus", small: true }),
    ] }, host),
  );
}
