import { discussionMessageSchema, type DiscussionMessage } from "../../shared/discussion";
import { recallCoordinator } from "../recall-coordinator";
import { statusCoordinator } from "../status/status-coordinator";
import { clearCreativePreferences } from "../memory/creative-preferences";

interface NativeEvents {
  makeFirst(name: string, listener: (...args: any[]) => void): void;
  makeLast(name: string, listener: (...args: any[]) => void): void;
  removeListener(name: string, listener: (...args: any[]) => void): void;
}

interface NativeScript {
  main_api: string;
  online_status: string;
  is_send_press: boolean;
  eventSource: NativeEvents;
  Generate(type: string, options: Record<string, unknown>, dryRun: boolean): Promise<unknown>;
  setExternalAbortController(controller: AbortController): void;
  stopGeneration(): boolean;
  characters: Array<{ avatar: string }>;
}

interface NativeGroups {
  is_group_generating: boolean;
  groups: Array<{ id: string; members: string[]; disabled_members: string[] }>;
  generateGroupWrapper(auto: boolean, type: string, options: Record<string, unknown>): Promise<unknown>;
}

let preparing = false;
export const isPreparingDiscussionContext = () => preparing;

/**
 * Run the real, non-dry-run pipeline, but abort at SETTINGS_READY before native fetch.
 * depth=1 skips composer submission/deletion. Both native streaming and non-streaming
 * senders obtain their response before creating a reply, so this never adds a reply.
 */
export async function captureDiscussionContext(signal: AbortSignal): Promise<DiscussionMessage[]> {
  if (preparing) throw new Error("另一个剧情讨论正在准备上下文。");
  const scriptUrl = new URL("script.js", document.baseURI).href;
  const groupsUrl = new URL("scripts/group-chats.js", document.baseURI).href;
  const native = await import(/* @vite-ignore */ scriptUrl) as NativeScript;
  const groups = await import(/* @vite-ignore */ groupsUrl) as NativeGroups;
  const context = SillyTavern.getContext();
  const chatId = context.chatId;
  const worldbook = window.TavernHelper?.getChatWorldbookName("current");
  if (!chatId) throw new Error("请先选择聊天。");
  if (preparing || native.is_send_press || groups.is_group_generating) {
    throw new Error("请等待酒馆当前生成结束，再开始剧情讨论。");
  }
  if (native.main_api !== "openai") {
    throw new Error("剧情讨论需要酒馆使用 Chat Completion 模式，才能原样保留消息角色及全部深度注入。");
  }
  if (native.online_status === "no_connection") {
    throw new Error("请先连接酒馆主 API，使酒馆允许正常组装请求；讨论正文仅由 Echoes 分配的端点生成。");
  }
  const events = native.eventSource;
  if (typeof native.Generate !== "function" || typeof native.setExternalAbortController !== "function"
    || typeof native.stopGeneration !== "function" || typeof events?.makeFirst !== "function"
    || typeof events.makeLast !== "function" || typeof events.removeListener !== "function") {
    throw new Error("当前酒馆缺少剧情讨论所需的原生生成/中止接口，未发送请求。");
  }
  let characterId = context.characterId === undefined ? undefined : Number(context.characterId);
  if (characterId !== undefined && (!Number.isInteger(characterId) || characterId < 0)) characterId = undefined;
  if (context.groupId) {
    const group = groups.groups.find((item) => String(item.id) === String(context.groupId));
    const enabled = group?.members.filter((avatar) => !group.disabled_members.includes(avatar)) ?? [];
    if (characterId === undefined || !enabled.includes(native.characters[characterId]?.avatar ?? "")) {
      characterId = native.characters.findIndex((character) => enabled.includes(character.avatar));
    }
    if (characterId < 0 || typeof groups.generateGroupWrapper !== "function") {
      throw new Error("当前群聊没有可用人物，无法准备讨论上下文。");
    }
  }
  signal.throwIfAborted();
  preparing = true;
  const controller = new AbortController();
  const origin = Symbol("echoes-discussion-context");
  const frames: Array<{
    owned: boolean; helper: boolean; type: string; signal?: AbortSignal | undefined; commands: boolean;
  }> = [];
  const tagged: Array<Record<symbol, unknown>> = [];
  const helperGenerations = new Set<string>();
  const ownedRequests = new WeakSet<object>();
  let captured: { messages: unknown[] } | undefined;
  let captureError: Error | undefined;
  let entered = false;
  let interceptingRequest = false;
  let externallyStopped = false;
  const guard = () => {
    signal.throwIfAborted();
    if (externallyStopped) throw new DOMException("酒馆已停止生成，未发送剧情讨论请求。", "AbortError");
    if (SillyTavern.getContext().chatId !== chatId
      || (worldbook != null && window.TavernHelper?.getChatWorldbookName("current") !== worldbook)) {
      throw new Error("聊天或世界书已切换，剧情讨论已停止。");
    }
  };
  const onStart = (type: string, options: { signal?: AbortSignal } = {}) => {
    const owned = options.signal === controller.signal;
    if (owned) entered = true;
    frames.push({ owned, helper: false, type, signal: options.signal, commands: false });
  };
  const onCommands = (type: string, options: { signal?: AbortSignal } = {}) => {
    const frame = frames.at(-1);
    if (frame && !frame.commands && frame.type === type && frame.signal === options.signal) {
      frame.commands = true;
    } else {
      // TavernHelper emits AFTER_COMMANDS without a native STARTED event.
      frames.push({ owned: false, helper: true, type, signal: options.signal, commands: true });
    }
  };
  const onData = (data: { prompt?: unknown }, dryRun: boolean) => {
    const frame = frames.pop();
    if (dryRun || !Array.isArray(data.prompt)) return;
    // Symbols survive native object spreads without becoming request JSON fields.
    for (const message of data.prompt) {
      if (!message || typeof message !== "object") continue;
      Object.defineProperty(message, origin, { value: frame, enumerable: true, configurable: true });
      tagged.push(message);
    }
  };
  const beforeSettings = (data: { type?: string; messages?: unknown[] }) => {
    if (!entered) return;
    const source = data.messages?.find((message) => message && typeof message === "object" && origin in message);
    const frame = source ? (source as Record<symbol, unknown>)[origin] as typeof frames[number] | undefined : undefined;
    if (frame?.helper && helperGenerations.size > 0) return;
    if (frame && !frame.owned && frame.type === "quiet" && data.type === "quiet") return;
    if (!source && data.type === "quiet") return;
    // Fail closed if another ordinary generation interleaves with this one.
    // stopGeneration aborts BOTH the regular controller and StreamingProcessor's controller.
    interceptingRequest = true;
    native.stopGeneration();
    controller.abort();
    try {
      guard();
      if (!frame?.owned || !Array.isArray(data.messages)) {
        throw new Error("无法确认最终请求属于本次剧情讨论，已在酒馆发送前停止。请检查并发生成或改写请求的插件。");
      }
      ownedRequests.add(data);
    } catch (error) {
      captureError = error instanceof Error ? error : new Error(String(error));
    }
  };
  const afterSettings = (data: { messages?: unknown[] }) => {
    // Keep the shared payload until emit resolves so all other plugins finish their edits.
    if (ownedRequests.has(data)) captured = data as { messages: unknown[] };
  };
  const helperStarted = (generationId: string) => { helperGenerations.add(generationId); };
  const helperEnded = (_message: unknown, generationId: string) => { helperGenerations.delete(generationId); };
  const onStopped = () => {
    if (!interceptingRequest) externallyStopped = true;
  };
  const abort = () => {
    controller.abort(signal.reason);
    if (entered) native.stopGeneration();
  };
  const bindings: Array<[string, (...args: any[]) => void]> = [
    ["generation_started", onStart],
    ["generation_after_commands", onCommands],
    ["generate_after_data", onData],
    ["chat_completion_settings_ready", beforeSettings],
    ["chat_completion_settings_ready", afterSettings],
    ["js_generation_started", helperStarted],
    ["js_generation_ended", helperEnded],
    ["generation_stopped", onStopped],
  ];
  let nativeError: unknown;
  try {
    events.makeFirst("generation_started", onStart);
    events.makeFirst("generation_after_commands", onCommands);
    events.makeLast("generate_after_data", onData);
    events.makeFirst("chat_completion_settings_ready", beforeSettings);
    events.makeLast("chat_completion_settings_ready", afterSettings);
    events.makeFirst("js_generation_started", helperStarted);
    events.makeFirst("js_generation_ended", helperEnded);
    events.makeFirst("generation_stopped", onStopped);
    signal.addEventListener("abort", abort, { once: true });
    native.setExternalAbortController(controller);
    const options = { depth: 1, signal: controller.signal, ...(characterId === undefined ? {} : { force_chid: characterId }) };
    try {
      if (context.groupId) await groups.generateGroupWrapper(true, "normal", options);
      else await native.Generate("normal", options, false);
    } catch (error) {
      nativeError = error;
    }
    guard();
    if (captureError) throw captureError;
    if (!captured) throw nativeError ?? new Error("酒馆未完成剧情讨论上下文的组装，未调用讨论 API。");
    return captured.messages.map((message) => discussionMessageSchema.parse(structuredClone(message)));
  } finally {
    for (const [name, handler] of bindings) events.removeListener(name, handler);
    signal.removeEventListener("abort", abort);
    for (const message of tagged) Reflect.deleteProperty(message, origin);
    try {
      // Run every cleanup even if one fails, then report the failures without discarding the captured context.
      const failures: string[] = [];
      for (const [label, clear] of [["召回", () => recallCoordinator.clear()],
        ["状态", () => statusCoordinator.clearInjection()], ["创作偏好", clearCreativePreferences]] as const) {
        try { await clear(); }
        catch (error) {
          console.error(`[Echoes] 剧情讨论结束后${label}临时注入清理失败`, error);
          failures.push(`${label}：${error instanceof Error ? error.message : String(error)}`);
        }
      }
      if (failures.length) toastr.error(failures.join("；"), "Echoes 临时注入清理失败");
    } finally {
      preparing = false;
    }
  }
}
