export interface SummarySupplementDraft {
  state: SummaryWorldbookState;
  batch: SummaryBatchInput;
  candidates: SummarySliceCandidate[];
  comparisons: ReturnType<typeof compareSummaryCandidates>;
}

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);

function abortable<T>(promise: Promise<T>, signal?: AbortSignal): Promise<T> {
  if (!signal) return promise;
  return new Promise<T>((resolve, reject) => {
    const abort = () => reject(new DOMException("Summary stopped.", "AbortError"));
    signal.addEventListener("abort", abort, { once: true });
    void promise.then(resolve, reject).finally(() => signal.removeEventListener("abort", abort));
    if (signal.aborted) abort();
  });
}

export type AmbiguousDecisionHandler = (decision: FailoverDecisionRequired) => Promise<boolean>;
type SummaryStage = (name: string, count: number, error?: string) => void;

export interface SummaryPipelineTrace {
  chatId: string;
  batchId: string;
  batchNumber: number;
  startedAt: string;
  state: "running" | "succeeded" | "incomplete" | "failed" | "cancelled";
  stages: Array<{ name: string; count: number; at: string; error?: string }>;
  error?: string;
}

export interface SummaryCoverageReview {
  worldbookName: string;
  namespaceId: string;
  checkedAt: string;
  sourceHash: string;
  startFloor: number;
  endFloor: number;
  findings: Array<{ messageId: string; start: number; end: number; text: string; reason: string }>;
}

async function waitForJob<TResult>(
  job: JobRecord<TResult>,
  signal?: AbortSignal,
  observe?: (job: JobRecord<TResult>) => Promise<void>,
): Promise<JobRecord<TResult>> {
  const deadline = Date.now() + 2 * 60 * 60_000;
  let current = job;
  await observe?.(current);
  while (!TERMINAL_STATES.has(current.status) && Date.now() < deadline) {
    await abortable(new Promise((resolve) => setTimeout(resolve, 1_000)), signal);
    current = await abortable(echoesApi.getJob<TResult>(current.id), signal);
    await observe?.(current);
  }
  if (!TERMINAL_STATES.has(current.status)) throw new Error("等待后台任务超时。");
  if (current.status !== "succeeded" || !current.result) {
    throw new Error(current.error?.message ?? current.message);
  }
  return current;
}

function defaultDecision(decision: FailoverDecisionRequired): Promise<boolean> {
  if (!decision.nextEndpointId) return Promise.resolve(false);
  return confirmAction({
    title: "总结请求结果不确定", message: `${decision.message}\n继续会向下一个端点创建新请求。`, cost: true,
    confirmLabel: "切换到下一端点", cancelLabel: "停止",
  });
}

export class SummaryCoordinator {
  readonly store = new SummaryWorldbookStore();
  readonly compression = new CompressionCoordinator(this.store);
  private readonly activeRuns = new Map<string, Promise<SummaryWorldbookState | null>>();
  private readonly rerunAutomatic = new Set<string>();
  private readonly controls = new Map<string, AbortController>();
  private readonly pausedAutomatic = new Set<string>();
  private readonly progressListeners = new Set<(state: SummaryWorldbookState) => void>();
  private readonly pipelineTraces: SummaryPipelineTrace[] = [];
  private readonly supplements = new Map<string, SummarySupplementDraft>();
  private readonly resumingDrafts = new Set<string>();
  private readonly finishCurrent = new Set<string>();
  private readonly rebuildConflicts = new Map<string, { state: SummaryWorldbookState; batch: SummaryBatchInput; candidates: SummarySliceCandidate[] }>();
  private readonly coverageReviews = new Map<string, SummaryCoverageReview>();

  coverageReview(state: SummaryWorldbookState): SummaryCoverageReview | null {
    const review = this.coverageReviews.get(state.catalog.chatId);
    return review?.worldbookName === state.worldbookName && review.namespaceId === state.catalog.namespaceId
      ? structuredClone(review) : null;
  }

  supplementDraft(): SummarySupplementDraft | null {
    const draft = this.supplements.get(SillyTavern.getContext().chatId ?? "");
    return draft ? structuredClone(draft) : null;
  }

  async discardSupplement(): Promise<void> {
    await this.discardRecovery();
  }

  rebuildDrafts() {
    return [...this.rebuildConflicts.values()].filter((draft) =>
      draft.state.catalog.chatId === SillyTavern.getContext().chatId
      && draft.state.worldbookName === window.TavernHelper?.getChatWorldbookName("current"))
      .map((draft) => structuredClone(draft));
  }

  async discardRebuildDraft(batchId: string): Promise<void> {
    const draft = this.rebuildDrafts().find((item) => item.batch.id === batchId);
    if (!draft) return;
    const saved = await readSummaryDraft(draft.state);
    if (saved?.mode === "rebuild" && saved.batch.id === batchId && !await this.discardRecovery()) return;
    this.rebuildConflicts.delete(`${draft.state.catalog.namespaceId}:${batchId}`);
  }

  commitRebuildDraft(batchId: string, expectedSnapshot: string): Promise<SummaryWorldbookState | null> {
    const draft = this.rebuildDrafts().find((item) => item.batch.id === batchId);
    if (!draft) return Promise.reject(new Error("重建候选不存在。"));
    return this.startRun(draft.state.catalog.chatId, async (signal) => {
      await this.assertCurrentSourceUnchanged(draft.state, draft.batch);
      const state = await this.store.inspect(draft.state.worldbookName);
      if (state.catalog.namespaceId !== draft.state.catalog.namespaceId) throw new Error("记忆目录已变化。");
      const recovery = await readSummaryDraft(state);
      if (recovery && (recovery.mode !== "rebuild" || recovery.batch.id !== batchId))
        throw new Error("本地恢复草稿已属于另一操作，请先核对后再提交候选。");
      const committed = await this.store.commitBatch({
        worldbookName: state.worldbookName, catalog: state.catalog,
        batch: draft.batch, candidates: draft.candidates, writeMode: "rebuild",
        advanceCheckpoint: summaryAdvancesCheckpoint(draft.batch, state.catalog, currentChatMessages()),
        expectedBatchSnapshot: expectedSnapshot, expectedCheckpoint: state.catalog.lastCommittedMessageId ?? null, signal,
      });
      this.rebuildConflicts.delete(`${state.catalog.namespaceId}:${batchId}`);
      await clearSummaryDraft(state, recovery);
      // Slice candidates are reused; only the independent batch overview calls the model.
      const byId = new Map(currentChatMessages().map((message) => [message.id, message]));
      return this.finishCommittedBatch(committed, batchId,
        draft.batch.messageIds.map((id) => byId.get(id)!), defaultDecision, signal);
    }, defaultDecision);
  }

  history(): SummaryPipelineTrace[] {
    return structuredClone(this.pipelineTraces.filter((trace) => trace.chatId === SillyTavern.getContext().chatId));
  }

  clearHistory(): void {
    this.pipelineTraces.length = 0;
  }

  subscribeProgress(listener: (state: SummaryWorldbookState) => void): () => void {
    this.progressListeners.add(listener);
    return () => { this.progressListeners.delete(listener); };
  }

  private emitProgress(state: SummaryWorldbookState): void {
    for (const listener of this.progressListeners) listener(state);
  }

  async relocateCheckpointToFloor(floor: number): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("请先选择聊天。");
    if (this.isRunning(chatId)) throw new Error("请先停止正在运行的总结任务，再修改检查点。");
    const messageId = checkpointMessageAtFloor(floor);
    this.rerunAutomatic.delete(chatId);
    this.pausedAutomatic.add(chatId);
    return (await this.startRun(chatId, async (signal) => {
      const state = await this.load();
      signal.throwIfAborted();
      if (checkpointMessageAtFloor(floor) !== messageId) throw new Error("修改期间消息楼层已变化，请重试。");
      const updated = await this.store.relocateCheckpoint(state.worldbookName, chatId, messageId);
      await this.compression.reconcile(updated);
      this.emitProgress(updated);
      return updated;
    }, defaultDecision))!;
  }

  isRunning(chatId = SillyTavern.getContext().chatId): boolean {
    return Boolean(chatId && this.activeRuns.has(chatId));
  }

  private startRun(
    chatId: string,
    work: (signal: AbortSignal) => Promise<SummaryWorldbookState | null>,
    decide: AmbiguousDecisionHandler,
  ): Promise<SummaryWorldbookState | null> {
    if (this.activeRuns.has(chatId)) return Promise.reject(new Error("请先停止当前总结任务。"));
    const control = new AbortController();
    this.finishCurrent.delete(chatId);
    this.controls.set(chatId, control);
    const operation = work(control.signal).catch((error: unknown) => {
      this.rerunAutomatic.delete(chatId);
      if (control.signal.aborted) throw error;
      this.pausedAutomatic.add(chatId);
      throw error;
    }).finally(() => {
      if (this.controls.get(chatId) === control) this.controls.delete(chatId);
      this.finishRun(chatId, operation, decide);
    });
    this.activeRuns.set(chatId, operation);
    return operation;
  }

  private async trackedJob<TResult>(
    chatId: string,
    start: () => Promise<JobRecord<TResult>>,
    signal: AbortSignal,
    observe?: (job: JobRecord<TResult>) => Promise<void>,
  ): Promise<JobRecord<TResult>> {
    signal.throwIfAborted();
    let job: JobRecord<TResult> | undefined;
    let cancellation: Promise<void> | undefined;
    const cancel = () => {
      if (!job || cancellation || TERMINAL_STATES.has(job.status)) return;
      cancellation = echoesApi.cancelJob(job.id).then((result) => {
        if (!result.cancelled) throw new Error("后台未确认取消总结请求，请检查任务日志。");
      });
      void cancellation.catch(() => undefined);
    };
    signal.addEventListener("abort", cancel, { once: true });
    const accepted = start().then(async (value) => {
        job = value;
        await observe?.(value);
        if (signal.aborted) cancel();
        return value;
      });
    try {
      return await waitForJob(await abortable(accepted, signal), signal, async (value) => {
        job = value;
        await observe?.(value);
      });
    } catch (error) {
      if (signal.aborted) {
        try {
          try { await accepted; } finally { cancel(); }
          await cancellation;
          if (job) await observe?.(await echoesApi.getJob<TResult>(job.id));
        } catch (cancelError) {
          throw new Error("后台取消失败：" + (cancelError instanceof Error ? cancelError.message : String(cancelError)));
        }
      } else if (observe && job && !TERMINAL_STATES.has(job.status)) {
        cancel();
        try { await cancellation; } catch (cancelError) {
          throw new Error(`${error instanceof Error ? error.message : String(error)}；后台取消未确认：${cancelError instanceof Error ? cancelError.message : String(cancelError)}`);
        }
      }
      throw error;
    } finally {
      signal.removeEventListener("abort", cancel);
    }
  }

  async stop(): Promise<SummaryWorldbookState> {
    return this.setAutoRun(false);
  }

  async stopAfterCurrentBatch(): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("请先选择聊天。");
    this.finishCurrent.add(chatId);
    this.pausedAutomatic.add(chatId);
    this.rerunAutomatic.delete(chatId);
    const state = await this.load();
    if (state.catalog.chatId !== chatId) throw new Error("聊天已切换。");
    const updated = await this.store.setAutoRun(state.worldbookName, false);
    this.emitProgress(updated);
    return updated;
  }

  async setAutomaticStopFloor(floor: number): Promise<void> {
    const messageId = checkpointMessageAtFloor(floor);
    const state = await this.load();
    await this.store.setAutomaticStop(state.worldbookName, messageId);
  }

  async pendingStatus(state: SummaryWorldbookState) {
    const indexed = indexedChatMessages();
    const messages = indexed.map((item) => item.message);
    const checkpoint = state.catalog.lastCommittedMessageId
      ? messages.findIndex((message) => message.id === state.catalog.lastCommittedMessageId) : -1;
    const pending = indexed.slice(checkpoint + 1);
    const draft = await readSummaryDraft(state);
    let reason = "";
    if (this.finishCurrent.has(state.catalog.chatId) && this.isRunning()) reason = "当前批次完成后停止（包括计划中的索引同步与独立批次总结）";
    else if (this.isRunning()) reason = "当前总结任务运行中";
    else if (draft) reason = `存在恢复草稿，等待明确继续或放弃：${draft.reason || draft.status}`;
    else if (!state.catalog.autoRun) reason = "自动总结已关闭";
    else if (this.pausedAutomatic.has(state.catalog.chatId)) reason = "上次任务未完成或已暂停，等待手动检查";
    else if (state.slices.some((slice) => slice.batch.state === "stale" && slice.batch.source?.kind !== "imported"
      && slice.batch.purpose !== "supplement")) reason = "存在失效批次，等待处理";
    const ranges: Array<{ start: number; end: number; count: number }> = [];
    if (state.catalog.lastCommittedMessageId && checkpoint < 0) reason = "检查点消息已不存在";
    else {
      const previewCatalog = structuredClone(state.catalog);
      for (let index = 0; index < 3; index++) {
        const next = await automaticSummaryBatch(messages, previewCatalog, getSettings().summary.messageCount);
        if (!next) break;
        const start = indexed.find((item) => item.message.id === next.batch.startMessageId)!.floor;
        const end = indexed.find((item) => item.message.id === next.batch.endMessageId)!.floor;
        ranges.push({ start, end, count: next.messages.length });
        previewCatalog.lastCommittedMessageId = next.batch.endMessageId;
        previewCatalog.nextBatchNumber++;
      }
      if (!reason) reason = ranges.length ? "等待生成时机或手动检查"
        : pending.length < getSettings().summary.messageCount ? "待处理消息未达阈值"
        : "等待后续用户消息确认批次末尾的助手回复";
    }
    const stop = state.catalog.automaticStopMessageId ? checkpointFloor(state.catalog.automaticStopMessageId) : null;
    if (stop === -1) reason = "停止点消息已不存在，请重新设置或取消停止点";
    else if (stop !== null && ranges[0] && ranges[0].end > stop) reason = "下一完整批次将越过停止点，不会截短或启动该批次";
    return { reason, ranges, pendingCount: pending.length, start: pending[0]?.floor, end: pending.at(-1)?.floor, stop, draft };
  }

  load(): Promise<SummaryWorldbookState> {
    return this.store.load();
  }

  async recoveryDraft(): Promise<SummaryRunDraft | undefined> {
    return readSummaryDraft(await this.load());
  }

  async discardRecovery(): Promise<boolean> {
    if (this.isRunning()) throw new Error("请先停止正在运行的总结。");
    const state = await this.load();
    const draft = await readSummaryDraft(state);
    const uncertainties: string[] = [];
    for (const part of draft?.parts ?? []) {
      if (!part.jobId) {
        if (part.submitting) uncertainties.push("有一次提交未取得后台任务编号。");
        continue;
      }
      try {
        const job = await echoesApi.getJob(part.jobId);
        if (!TERMINAL_STATES.has(job.status)) {
          const result = await echoesApi.cancelJob(job.id);
          if (!result.cancelled) uncertainties.push(`任务 ${job.id} 未确认停止。`);
        }
      } catch (error) {
        uncertainties.push(`任务 ${part.jobId} 无法查询或取消：${error instanceof Error ? error.message : String(error)}`);
      }
    }
    if (uncertainties.length && !await confirmAction({
      title: "放弃本地恢复记录？", danger: true, confirmLabel: "仍然放弃",
      message: `${uncertainties.join("\n")}\n后台可能仍在运行或已经计费。仅清理本地草稿不能确认任务取消，新任务也可能重复计费。`,
    })) return false;
    if (this.isRunning()) throw new Error("总结任务已开始，未清理正在使用的草稿。");
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) throw new Error("聊天已变化，未清理恢复草稿。");
    this.pausedAutomatic.add(state.catalog.chatId);
    this.rerunAutomatic.delete(state.catalog.chatId);
    await this.store.setAutoRun(state.worldbookName, false);
    await clearSummaryDraft(state, draft);
    this.supplements.delete(state.catalog.chatId);
    if (draft?.mode === "rebuild") this.rebuildConflicts.delete(`${state.catalog.namespaceId}:${draft.batch.id}`);
    return true;
  }

  resumeRecovery(): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    return this.startRun(chatId, async (signal) => {
      const state = await this.load();
      const draft = await readSummaryDraft(state);
      if (!draft) throw new Error("没有可恢复的总结记录。");
      await this.assertCurrentSourceUnchanged(state, draft.batch);
      if ((state.catalog.lastCommittedMessageId ?? null) !== draft.checkpoint
        || state.catalog.nextBatchNumber !== draft.nextBatchNumber
        || summaryBatchSnapshot(state.slices, draft.batch.id) !== draft.batchSnapshot) {
        throw new Error("检查点、批次编号或目标批次已变化，不能沿用旧任务写入。请先核对已保存内容。");
      }
      this.pausedAutomatic.add(chatId);
      this.rerunAutomatic.delete(chatId);
      this.resumingDrafts.add(chatId);
      try {
        const byId = new Map(currentChatMessages().map((message) => [message.id, message]));
        const messages = draft.batch.messageIds.map((id) => byId.get(id)!);
        if (draft.mode === "supplement") {
          const candidates = await this.generateCandidates(state, draft.batch, messages, defaultDecision, signal,
            () => {}, draft.instructions, "supplement", false);
          if (candidates) this.supplements.set(chatId, { state, batch: draft.batch, candidates,
            comparisons: compareSummaryCandidates(candidates, state.slices.filter((slice) => slice.batch.state !== "stale")) });
          return state;
        }
        return await this.generate(state, draft.batch, messages, defaultDecision, draft.advanceCheckpoint, draft.mode, signal);
      } finally {
        this.resumingDrafts.delete(chatId);
      }
    }, defaultDecision);
  }

  async checkIntegrity(currentState?: SummaryWorldbookState, signal?: AbortSignal): Promise<SummaryWorldbookState> {
    const state = currentState ?? await this.load();
    signal?.throwIfAborted();
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
      return state;
    }
    const stale = await staleSummaryBatches(state, currentChatMessages(), signal);
    signal?.throwIfAborted();
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
      return state;
    }
    const changed = stale.filter((batch) => state.slices.some((slice) =>
      slice.batch.id === batch.id && slice.batch.state !== "stale")).map((batch) => batch.id);
    if (!changed.length) return state;
    const marked = await this.store.invalidateBatches(state, changed, signal);
    signal?.throwIfAborted();
    await this.compression.restoreBatch(marked, changed, false);
    // Integrity maintenance is local only. Paid index repair runs explicitly under a cancellable task.
    return marked;
  }

  async setAutoRun(enabled: boolean): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("Open a SillyTavern chat before changing summary automation.");
    const running = this.activeRuns.get(chatId);
    if (!enabled) {
      this.pausedAutomatic.add(chatId);
      this.rerunAutomatic.delete(chatId);
      this.controls.get(chatId)?.abort();
    }
    const state = await this.load();
    if (state.catalog.chatId !== chatId) throw new Error("The active chat changed.");
    const updated = await this.store.setAutoRun(state.worldbookName, enabled);
    if (!enabled) {
      await running?.catch((error: unknown) => {
        if (!(error instanceof Error) || error.name !== "AbortError") throw error;
      });
    }
    if (enabled) this.pausedAutomatic.delete(chatId);
    return updated;
  }

  async setRecallEnabled(enabled: boolean): Promise<SummaryWorldbookState> {
    const state = await this.load();
    return this.store.saveRecallConfiguration(state.worldbookName, {
      enabled,
      weight: state.catalog.recallSourceWeight,
      order: state.catalog.recallSourceOrder,
      attachedSources: state.catalog.attachedRecallSources,
    });
  }

  async saveCompression(
    compression: SummaryCompressionConfig,
  ): Promise<{ state: SummaryWorldbookState; status: CompressionStatus }> {
    const state = await this.load();
    const updated = await this.store.saveCompressionConfiguration(
      state.worldbookName,
      compression,
    );
    const status = await this.compression.reconcile(updated);
    return { state: updated, status };
  }

  runAutomatic(
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const lockedChatId = SillyTavern.getContext().chatId;
    if (!lockedChatId || this.supplements.has(lockedChatId)) return Promise.resolve(null);
    const existing = this.activeRuns.get(lockedChatId);
    if (existing) {
      this.rerunAutomatic.add(lockedChatId);
      return existing;
    }
    return this.startRun(
      lockedChatId,
      (signal) => this.performAutomatic(lockedChatId, decide, signal),
      decide,
    );
  }

  checkPending(
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    if (this.supplements.has(chatId)) return Promise.reject(new Error("请先处理待确认的总结补全结果。"));
    return this.startRun(chatId, (signal) => this.performAutomatic(chatId, decide, signal, true), decide);
  }

  private async performAutomatic(
    lockedChatId: string,
    decide: AmbiguousDecisionHandler,
    signal: AbortSignal,
    explicitCheck = false,
  ): Promise<SummaryWorldbookState | null> {
    if (SillyTavern.getContext().chatId !== lockedChatId) return null;
    let state = await this.checkIntegrity(undefined, signal);
    if (state.catalog.chatId !== lockedChatId) {
      throw new Error("The summary catalog does not belong to the locked chat.");
    }
    if (explicitCheck) {
      signal.throwIfAborted();
      if (SillyTavern.getContext().chatId !== lockedChatId
        || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
        throw new Error("聊天或世界书已切换，请重新检查。");
      }
      if (!state.catalog.autoRun) throw new Error("自动总结已关闭，请先开启自动总结，或使用手动总结。");
      if (await readSummaryDraft(state)) throw new Error("存在未完成的总结草稿，请明确选择恢复或放弃；没有启动新请求。");
      if (state.slices.some((slice) => slice.batch.state === "stale"
        && slice.batch.source?.kind !== "imported" && slice.batch.purpose !== "supplement")) {
        throw new Error("存在源消息已变化的失效批次，请先重建或处理失效批次，再检查待处理消息。");
      }
      this.pausedAutomatic.delete(lockedChatId);
    }
    // Pausing generation must not disable visibility maintenance of existing summaries.
    if (!state.catalog.autoRun || this.pausedAutomatic.has(lockedChatId)
      || await readSummaryDraft(state)
      || state.slices.some((slice) => slice.batch.state === "stale"
        && slice.batch.source?.kind !== "imported" && slice.batch.purpose !== "supplement")) {
      await this.compression.reconcile(state);
      return state;
    }
    let completedBatches = 0;
    while (SillyTavern.getContext().chatId === lockedChatId) {
      signal.throwIfAborted();
      state = await this.store.inspect(state.worldbookName);
      if (!state.catalog.autoRun || this.pausedAutomatic.has(lockedChatId)) break;
      const candidate = await automaticSummaryBatch(
        currentChatMessages(),
        state.catalog,
        getSettings().summary.messageCount,
      );
      if (!candidate) break;
      if (state.catalog.automaticStopMessageId) {
        const stop = checkpointFloor(state.catalog.automaticStopMessageId);
        if (stop < 0) throw new Error("自动总结停止点已不存在，请重新设置。");
        if (checkpointFloor(candidate.batch.endMessageId) > stop) {
          this.pausedAutomatic.add(lockedChatId);
          this.rerunAutomatic.delete(lockedChatId);
          state = await this.store.setAutoRun(state.worldbookName, false);
          this.emitProgress(state);
          break;
        }
      }
      const limit = getSettings().automaticBatchLimit;
      if (limit > 0 && completedBatches >= limit) {
        this.pausedAutomatic.add(lockedChatId);
        this.rerunAutomatic.delete(lockedChatId);
        state = await this.store.setAutoRun(state.worldbookName, false);
        toastr.warning("已达到自动总结批次上限，自动总结已关闭。已完成的内容和检查点保留。", "Echoes");
        break;
      }
      const next = await this.generate(
        state,
        candidate.batch,
        candidate.messages,
        decide,
        true,
        "create",
        signal,
      );
      if (!next) {
        this.pausedAutomatic.add(lockedChatId);
        this.rerunAutomatic.delete(lockedChatId);
        break;
      }
      state = next;
      completedBatches += 1;
    }
    await this.compression.reconcile(state);
    if (explicitCheck && completedBatches === 0 && !this.pausedAutomatic.has(lockedChatId)) {
      toastr.info("暂无符合自动总结条件的消息：需达到消息阈值，并由后续用户消息确认助手回复。", "Echoes");
    }
    return state;
  }

  runManual(
    startIndex: number,
    endIndex: number,
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const lockedChatId = SillyTavern.getContext().chatId;
    if (!lockedChatId) return Promise.resolve(null);
    if (this.activeRuns.has(lockedChatId)) {
      return Promise.reject(new Error("This chat already has a summary task running."));
    }
    return this.startRun(
      lockedChatId,
      (signal) => this.performManual(lockedChatId, startIndex, endIndex, decide, signal),
      defaultDecision,
    );
  }

  private async performManual(
    lockedChatId: string,
    startIndex: number,
    endIndex: number,
    decide: AmbiguousDecisionHandler,
    signal: AbortSignal,
  ): Promise<SummaryWorldbookState | null> {
    if (SillyTavern.getContext().chatId !== lockedChatId) return null;
    const state = await this.checkIntegrity(undefined, signal);
    if (state.catalog.chatId !== lockedChatId) {
      throw new Error("The summary catalog does not belong to the locked chat.");
    }
    const messages = currentChatMessages();
    const range = messageRangeByFloor(startIndex, endIndex);
    const candidate = await manualSummaryBatch(
      messages,
      state.catalog,
      range.startIndex,
      range.endIndex,
    );
    const checkpointIndex = state.catalog.lastCommittedMessageId
      ? messages.findIndex((message) => message.id === state.catalog.lastCommittedMessageId)
      : -1;
    if (state.catalog.lastCommittedMessageId && checkpointIndex < 0) {
      throw new Error("总结检查点消息已不存在，请先修改检查点。");
    }
    const advancesCheckpoint = range.startIndex <= checkpointIndex + 1 && range.endIndex > checkpointIndex;
    return this.generate(
      state,
      candidate.batch,
      candidate.messages,
      decide,
      advancesCheckpoint,
      "create",
      signal,
    );
  }

  rebuildBatch(
    batchNumber: number,
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const lockedChatId = SillyTavern.getContext().chatId;
    if (!lockedChatId) return Promise.resolve(null);
    if (this.activeRuns.has(lockedChatId)) {
      return Promise.reject(new Error("This chat already has a summary task running."));
    }
    return this.startRun(
      lockedChatId,
      (signal) => this.performRebuild(lockedChatId, batchNumber, decide, signal),
      defaultDecision,
    );
  }

  rebuildBatches(
    batchNumbers: number[],
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.resolve(null);
    if (this.activeRuns.has(chatId)) return Promise.reject(new Error("This chat already has a summary task running."));
    return this.startRun(chatId, async (signal) => {
      let state: SummaryWorldbookState | null = null;
      for (const batchNumber of [...new Set(batchNumbers)]) {
        signal.throwIfAborted();
        if (SillyTavern.getContext().chatId !== chatId) throw new DOMException("聊天已切换，批量总结已停止。", "AbortError");
        state = await this.performRebuild(chatId, batchNumber, decide, signal);
        if (!state || this.finishCurrent.has(chatId)) break;
      }
      return state;
    }, decide);
  }

  private async performRebuild(
    lockedChatId: string,
    batchNumber: number,
    decide: AmbiguousDecisionHandler,
    signal: AbortSignal,
  ): Promise<SummaryWorldbookState | null> {
    if (SillyTavern.getContext().chatId !== lockedChatId) return null;
    const state = await this.load();
    if (state.catalog.chatId !== lockedChatId) {
      throw new Error("The summary catalog does not belong to the locked chat.");
    }
    const existing = state.slices.find((slice) => slice.batch.batchNumber === batchNumber)?.batch;
    if (!existing) throw new Error("总结批次不存在。");
    const messages = currentChatMessages();
    const start = messages.findIndex((message) => message.id === existing.startMessageId);
    const end = messages.findIndex((message) => message.id === existing.endMessageId);
    if (start < 0 || end < start) throw new Error("原消息范围已不存在，请从该批次重置后重新总结。");
    const candidate = await manualSummaryBatch(messages, state.catalog, start, end, existing);
    return this.generate(state, candidate.batch, candidate.messages, decide,
      summaryAdvancesCheckpoint(candidate.batch, state.catalog, messages), "rebuild", signal);
  }

  async previewManual(startIndex: number, endIndex: number): Promise<PreparedSummaryRequest> {
    const state = await this.load();
    const range = messageRangeByFloor(startIndex, endIndex);
    const candidate = await manualSummaryBatch(
      currentChatMessages(),
      state.catalog,
      range.startIndex,
      range.endIndex,
    );
    const requests = await prepareSummarySubRequests({
      batch: candidate.batch,
      messages: candidate.messages,
      state,
      settings: getSettings(),
    });
    return { ...requests[0]!, ...(requests.length > 1 ? { subRequests: requests } : {}) };
  }

  checkCoverage(startFloor: number, endFloor: number): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    return this.startRun(chatId, async (signal) => {
      const state = await this.load();
      const settings = getSettings();
      const workflow = settings.generationWorkflows.summary;
      const group = settings.generationGroups.find((item) => item.id === workflow.groupId);
      if (!group) throw new Error("请先配置总结生成端点组。");
      const range = messageRangeByFloor(startFloor, endFloor);
      const selected = await manualSummaryBatch(currentChatMessages(), state.catalog, range.startIndex, range.endIndex);
      const prepared = await prepareSummarySubRequests({ ...selected, state, settings });
      const ids = new Set(selected.batch.messageIds);
      const existingSlices = state.slices.filter((slice) => slice.batch.state !== "stale"
        && slice.batch.source?.kind !== "imported" && slice.batch.messageIds.some((id) => ids.has(id)))
        .map(({ timestamp, title, content, tags }) => ({ timestamp, title, content, tags }));
      const backgroundIds = new Set(settings.summary.promptPreset.items
        .filter((item) => ["character", "worldbook", "persona"].includes(item.kind)).map((item) => item.id));
      const requests: SummaryCoverageRequest[] = [];
      for (const part of prepared) {
        const messages = part.cleanedMessages;
        requests.push(summaryCoverageRequestSchema.parse({
          chatId, batch: { ...part.batch, messageIds: messages.map((message) => message.id),
            startMessageId: messages[0]!.id, endMessageId: messages.at(-1)!.id, sourceHash: await summarySourceHash(messages) },
          messages, existingSlices, generationGroup: group, failoverPolicy: workflow.failoverPolicy,
          promptMessages: [{ role: "system", content: SUMMARY_COVERAGE_BACKGROUND_NOTE },
            ...part.promptBlocks.filter((block) => backgroundIds.has(block.id)).map(({ role, content }) => ({ role, content }))],
        }));
      }
      const review: SummaryCoverageReview = {
        worldbookName: state.worldbookName, namespaceId: state.catalog.namespaceId,
        checkedAt: new Date().toISOString(), sourceHash: selected.batch.sourceHash, startFloor, endFloor, findings: [],
      };
      for (const [index, initial] of requests.entries()) {
        await this.assertCurrentSourceUnchanged(state, selected.batch);
        signal.throwIfAborted();
        let request = initial;
        let result: SummaryCoverageResult;
        while (true) {
          result = (await this.trackedJob(chatId, () => echoesApi.checkSummaryCoverage(request), signal)).result!;
          if (!result.decisionRequired) break;
          if (!await abortable(defaultDecision(result.decisionRequired), signal)) return null;
          request = { ...initial, resumeAfterEndpointId: result.decisionRequired.failedEndpointId };
        }
        for (const finding of result.findings) {
          const message = initial.messages[finding.region - 1];
          if (!message) throw new Error("覆盖检查返回了不存在的内容区域。");
          const partRange = prepared[index]!.ranges?.[finding.region - 1];
          review.findings.push({ messageId: message.id, start: partRange?.start ?? 0,
            end: partRange?.end ?? message.content.length, text: message.content, reason: finding.reason });
        }
      }
      await this.assertCurrentSourceUnchanged(state, selected.batch);
      signal.throwIfAborted();
      this.coverageReviews.set(chatId, review);
      return state;
    }, defaultDecision);
  }

  generateSupplement(startFloor: number, endFloor: number, instructions: string): Promise<SummaryWorldbookState | null> {
    if (instructions.length > 20000) return Promise.reject(new Error("补充要求最多 20000 字符。"));
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    if (this.supplements.has(chatId)) return Promise.reject(new Error("请先提交或丢弃已有补全候选。"));
    return this.startRun(chatId, async (signal) => {
      const state = await this.load();
      const range = messageRangeByFloor(startFloor, endFloor);
      const selected = await manualSummaryBatch(currentChatMessages(), state.catalog, range.startIndex, range.endIndex);
      selected.batch.purpose = "supplement";
      const candidates = await this.generateCandidates(state, selected.batch, selected.messages, defaultDecision, signal,
        () => {}, instructions, "supplement", false);
      if (!candidates) return null;
      await this.assertCurrentSourceUnchanged(state, selected.batch);
      signal.throwIfAborted();
      const valid = state.slices.filter((slice) => slice.batch.state !== "stale");
      this.supplements.set(chatId, { state, batch: selected.batch, candidates,
        comparisons: compareSummaryCandidates(candidates, valid) });
      return state;
    }, defaultDecision);
  }

  commitSupplement(indexes: number[]): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId ?? "";
    const draft = this.supplements.get(chatId);
    if (!draft) return Promise.reject(new Error("没有待提交的补全候选。"));
    return this.startRun(chatId, async (signal) => {
      if (indexes.some((index) => !Number.isInteger(index) || index < 0 || index >= draft.candidates.length)) {
        throw new Error("补全选择包含无效切片。");
      }
      await this.assertCurrentSourceUnchanged(draft.state, draft.batch);
      const state = await this.store.inspect(draft.state.worldbookName);
      if (state.catalog.namespaceId !== draft.state.catalog.namespaceId || state.catalog.chatId !== chatId) {
        throw new Error("记忆目录已被替换，请丢弃候选并重新生成。");
      }
      const existing = new Set(state.slices.filter((slice) => slice.batch.state !== "stale").map(summaryPropositionKey));
      const candidates = mergeSummaryCandidates([...new Set(indexes)].map((index) => draft.candidates[index]!))
        .filter((candidate) => !existing.has(summaryPropositionKey(candidate)));
      if (!candidates.length) throw new Error("没有选中新内容；完全重复的正文和时间戳不会再次写入。");
      const recovery = await readSummaryDraft(state);
      if (recovery && (recovery.mode !== "supplement" || recovery.batch.id !== draft.batch.id))
        throw new Error("本地恢复草稿已属于另一操作，请先核对后再提交候选。");
      const batch = { ...draft.batch, batchNumber: state.catalog.nextBatchNumber, id: `summary_batch_${state.catalog.nextBatchNumber}` };
      const committed = await this.store.commitBatch({ worldbookName: state.worldbookName, catalog: state.catalog,
        batch, candidates, advanceCheckpoint: false, expectedCheckpoint: state.catalog.lastCommittedMessageId ?? null,
        expectedNextBatchNumber: state.catalog.nextBatchNumber, signal });
      this.supplements.delete(chatId);
      await clearSummaryDraft(state, recovery);
      const byId = new Map(currentChatMessages().map((message) => [message.id, message]));
      return this.finishCommittedBatch(committed, batch.id, batch.messageIds.map((id) => byId.get(id)!), defaultDecision, signal);
    }, defaultDecision);
  }

  async editSlice(sliceId: string, candidate: SummarySliceCandidate, expectedRevision?: number): Promise<SummaryWorldbookState> {
    const state = await this.load();
    const updated = await this.store.saveSlice(state.worldbookName, sliceId, candidate, expectedRevision);
    const slice = updated.slices.find((item) => item.id === sliceId);
    if (!slice) throw new Error("总结切片不存在。");
    const synced = await this.syncSlices(updated, [slice], updated.catalog.pendingRetrievalDeletes);
    await this.compression.reconcile(synced);
    return synced;
  }

  async deleteSlice(sliceId: string): Promise<SummaryWorldbookState> {
    return this.deleteSlices([sliceId]);
  }

  async deleteSlices(sliceIds: string[], restoreOriginal = false): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("请先选择聊天。");
    return (await this.startRun(chatId, async (signal) => {
      const state = await this.load();
      let updated: SummaryWorldbookState;
      if (restoreOriginal) {
        const batchIds = [...new Set(state.slices.filter((slice) => sliceIds.includes(slice.id)).map((slice) => slice.batch.id))];
        await this.compression.restoreBatch(state, batchIds, false, async (changes) => {
          updated = await this.store.deleteSlices(state.worldbookName, sliceIds, changes);
        });
      } else updated = await this.store.deleteSlices(state.worldbookName, sliceIds);
      return this.syncSlices(updated!, [], updated!.catalog.pendingRetrievalDeletes, defaultDecision, signal, true);
    }, defaultDecision))!;
  }

  async undoOperation(id: string): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("请先选择聊天。");
    return this.startRun(chatId, async (signal) => {
      const state = await this.load();
      const record = await requireMemoryUndo(state.worldbookName, id);
      const restored = await this.compression.withUndoVisibility(state, record.visibility,
        () => this.store.undoOperation(state.worldbookName, id));
      await forgetMemoryUndo(state.worldbookName, chatId, id);
      const restoredIds = new Set(record.changes.flatMap((change) =>
        change.before?.extra?.echoes?.kind === "summary_slice" ? [change.before.extra.echoes.summaryId] : []));
      this.pausedAutomatic.add(chatId);
      this.rerunAutomatic.delete(chatId);
      try {
        return await this.syncSlices(restored, restored.slices.filter((slice) => restoredIds.has(slice.id) && slice.batch.state !== "stale"),
          restored.catalog.pendingRetrievalDeletes, defaultDecision, signal, true);
      } catch (error) {
        throw new Error(`记忆与本操作的可见性已恢复，文本索引同步未完成；可另行修复索引。${error instanceof Error ? error.message : String(error)}`);
      }
    }, defaultDecision);
  }

  async setNextBatchNumber(batchNumber: number): Promise<SummaryWorldbookState> {
    const state = await this.load();
    return this.store.setNextBatchNumber(state.worldbookName, batchNumber);
  }

  async resetFrom(batchNumber: number): Promise<SummaryWorldbookState> {
    const state = await this.load();
    const updated = await this.store.resetFrom(state.worldbookName, batchNumber);
    return this.syncSlices(updated, [], updated.catalog.pendingRetrievalDeletes);
  }

  async repairIndex(decide: AmbiguousDecisionHandler = defaultDecision): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("请先选择聊天。");
    if (this.activeRuns.has(chatId)) throw new Error("请先停止当前总结任务。");
    return (await this.startRun(chatId, (signal) => this.performRepairIndex(decide, signal), decide))!;
  }

  async saveRetrievalTexts(expected: SummaryWorldbookState, values: Map<string, string | undefined>): Promise<SummaryWorldbookState> {
    if (this.isRunning()) throw new Error("请先停止当前总结任务，再修改检索表示。");
    return this.store.saveRetrievalTexts(expected, values);
  }

  synchronizeSlices(sliceIds: string[]): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    return this.startRun(chatId, async (signal) => {
      const state = await this.load();
      const ids = new Set(sliceIds);
      const slices = state.slices.filter((slice) => ids.has(slice.id) && slice.batch.state !== "stale");
      if (slices.length !== ids.size) throw new Error("部分选中切片已删除或源消息已变化，请刷新并重新选择。");
      return this.syncSlices(state, slices, state.catalog.pendingRetrievalDeletes, defaultDecision, signal);
    }, defaultDecision);
  }

  private async performRepairIndex(decide: AmbiguousDecisionHandler, signal: AbortSignal): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    let state = await this.load();
    if (chatId && state.catalog.chatId === chatId) this.pausedAutomatic.delete(chatId);
    const assertUnchanged = async () => {
      signal.throwIfAborted();
      if (SillyTavern.getContext().chatId !== state.catalog.chatId
        || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
        throw new Error("聊天已切换，索引修复已停止。");
      }
      const fresh = await this.store.inspect(state.worldbookName);
      if (summaryMigrationFingerprint(fresh) !== summaryMigrationFingerprint(state)) {
        throw new Error("总结内容或索引绑定已变化，请重新修复索引。");
      }
      signal.throwIfAborted();
    };
    const active = state.slices.filter((slice) => slice.batch.state !== "stale");
    const collectionId = state.catalog.retrievalCollectionId;
    let removed = 0;
    if (collectionId) {
      const expectedIds = new Set(await Promise.all(active.map((slice) => summaryRetrievalDocumentId(collectionId, slice.id))));
      let afterDocumentId: string | undefined;
      do {
        await assertUnchanged();
        const page = await echoesApi.retrievalDocumentManifest(collectionId, afterDocumentId, signal);
        const obsolete = page.documents.filter((document) =>
          document.sourceType === "chat_summary" && !expectedIds.has(document.documentId));
        if (obsolete.length) {
          await assertUnchanged();
          const result = await this.trackedJob(state.catalog.chatId, () => echoesApi.syncRetrievalDocuments({
            documents: [], deleteDocumentIds: obsolete.map((document) => document.documentId),
            failoverPolicy: getSettings().retrieval.failoverPolicy,
          }), signal);
          removed += result.result!.deleted;
        }
        afterDocumentId = page.nextAfterDocumentId;
      } while (afterDocumentId);
    }
    await assertUnchanged();
    if (state.catalog.pendingRetrievalDeletes.length > 0) {
      state = await this.syncSlices(state, [], state.catalog.pendingRetrievalDeletes, decide, signal);
    }
    for (let offset = 0; offset < active.length; offset += 50) {
      await assertUnchanged();
      state = await this.syncSlices(
        state,
        active.slice(offset, offset + 50),
        [],
        decide,
        signal,
      );
    }
    await this.compression.reconcile(state);
    this.emitProgress(state);
    console.info("[Echoes] 总结索引修复完成", {
      worldbookName: state.worldbookName, collectionId: state.catalog.retrievalCollectionId,
      slices: active.length, removed,
    });
    return state;
  }

  private async generate(
    state: SummaryWorldbookState,
    batch: SummaryBatchInput,
    messages: SummaryGenerationRequest["messages"],
    decide: AmbiguousDecisionHandler,
    advanceCheckpoint: boolean,
    writeMode: "create" | "rebuild",
    signal: AbortSignal,
  ): Promise<SummaryWorldbookState | null> {
    const trace: SummaryPipelineTrace = {
      chatId: state.catalog.chatId, batchId: batch.id, batchNumber: batch.batchNumber,
      startedAt: new Date().toISOString(), state: "running", stages: [],
    };
    this.pipelineTraces.unshift(trace);
    this.pipelineTraces.splice(20);
    try {
      const result = await this.performGenerate(state, batch, messages, decide, advanceCheckpoint, writeMode, signal,
        (name, count, error) => trace.stages.push({ name, count, at: new Date().toISOString(), ...(error ? { error } : {}) }));
      const slices = result?.slices.filter((slice) => slice.batch.id === batch.id);
      trace.state = slices?.length && slices.every((slice) => slice.batch.state === "ready") ? "succeeded" : "incomplete";
      return result;
    } catch (error) {
      trace.state = signal.aborted || error instanceof Error && error.name === "AbortError" ? "cancelled" : "failed";
      trace.error = (error instanceof Error ? error.message : String(error)).slice(0, 2000);
      throw error;
    }
  }

  private async performGenerate(
    state: SummaryWorldbookState,
    batch: SummaryBatchInput,
    messages: SummaryGenerationRequest["messages"],
    decide: AmbiguousDecisionHandler,
    advanceCheckpoint: boolean,
    writeMode: "create" | "rebuild",
    signal: AbortSignal,
    stage: SummaryStage,
  ): Promise<SummaryWorldbookState | null> {
    stage("原消息数", messages.length);
    stage("原消息字符", messages.reduce((sum, message) => sum + message.content.length, 0));
    const candidates = await this.generateCandidates(state, batch, messages, decide, signal, stage,
      undefined, writeMode, advanceCheckpoint);
    if (!candidates) return null;
    stage("解析通过切片", candidates.length);
    await this.assertCurrentSourceUnchanged(state, batch);
    signal.throwIfAborted();
    const draftKey = `${state.catalog.namespaceId}:${batch.id}`;
    const recovery = await readSummaryDraft(state);
    if (!recovery || recovery.mode !== writeMode || recovery.batch.id !== batch.id || recovery.status !== "ready")
      throw new Error("本地恢复草稿已变化，未提交旧候选。请刷新后核对。");
    const committed = await this.store.commitBatch({
      worldbookName: state.worldbookName,
      catalog: state.catalog,
      batch,
      candidates,
      writeMode,
      advanceCheckpoint,
      expectedCheckpoint: state.catalog.lastCommittedMessageId ?? null,
      expectedNextBatchNumber: state.catalog.nextBatchNumber,
      expectedBatchSnapshot: summaryBatchSnapshot(state.slices, batch.id),
      signal,
    }).catch((error: unknown) => {
      if (writeMode === "rebuild" && !signal.aborted) {
        this.rebuildConflicts.set(draftKey, structuredClone({ state, batch, candidates }));
        if (this.rebuildConflicts.size > 20) this.rebuildConflicts.delete(this.rebuildConflicts.keys().next().value!);
        throw new Error(`${error instanceof Error ? error.message : String(error)} 生成结果已保留，可在总结记录的重建候选中核对。`);
      }
      throw error;
    });
    this.rebuildConflicts.delete(draftKey);
    await clearSummaryDraft(state, recovery);
    return this.finishCommittedBatch(committed, batch.id, messages, decide, signal, stage);
  }

  private async finishCommittedBatch(
    committed: SummaryWorldbookState, batchId: string, messages: SummaryGenerationRequest["messages"],
    decide: AmbiguousDecisionHandler, signal: AbortSignal, stage: SummaryStage = () => {},
  ): Promise<SummaryWorldbookState> {
    const slices = committed.slices.filter((slice) => slice.batch.id === batchId);
    stage("世界书写入切片", slices.length);
    this.emitProgress(committed);
    let state = committed;
    const failures: string[] = [];
    const recordFailure = (name: string, error: unknown) => {
      if (signal.aborted || error instanceof Error && error.name === "AbortError") throw error;
      const message = error instanceof Error ? error.message : String(error);
      stage(name, 0, message);
      failures.push(`${name}：${message}`);
      console.error(`[Echoes] ${name}`, error);
    };
    // Both follow-up stages use the committed slices; a failure in one must not skip the other.
    try {
      state = await this.syncSlices(state, slices, state.catalog.pendingRetrievalDeletes, decide, signal);
      stage("向量就绪切片", state.slices.filter((slice) => slice.batch.id === batchId && slice.batch.state === "ready").length);
      this.emitProgress(state);
    } catch (error) {
      recordFailure("索引同步失败", error);
      state = await this.store.inspect(committed.worldbookName);
      this.emitProgress(state);
    }
    signal.throwIfAborted();
    try {
      state = await this.generateBatchOverview(state, batchId, messages, decide, signal, committed.undoOperationId);
      stage("批次总结字符", state.batchOverviews?.find((item) => item.batch.id === batchId)?.content.length ?? 0);
    } catch (error) {
      recordFailure("批次总结失败", error);
      state = await this.store.inspect(committed.worldbookName);
    }
    signal.throwIfAborted();
    try {
      await this.compression.reconcile(state, committed.undoOperationId ? async (changes) => {
        await amendMemoryUndo(committed.worldbookName, committed.catalog.chatId, committed.undoOperationId,
          (record) => { record.visibility.push(...changes); });
      } : undefined);
    } catch (error) {
      recordFailure("上下文隐藏更新失败", error);
    }
    signal.throwIfAborted();
    this.emitProgress(state);
    if (failures.length) {
      throw new Error(`切片已保存，检查点保留；后续自动批次已暂停。索引可用“修复索引”重试，批次总结可单独重试，无需重新生成切片。\n${failures.join("\n")}`);
    }
    return state;
  }

  regenerateBatchOverview(batchId: string): Promise<SummaryWorldbookState | null> {
    return this.regenerateBatchOverviews([batchId], { onlyMissing: false });
  }

  batchOverviewTargets(state: SummaryWorldbookState, batchIds: string[], onlyMissing = true): SummarySlice["batch"][] {
    const selected = new Set(batchIds);
    const overviews = new Map(state.batchOverviews?.map((overview) => [overview.batch.id, overview]));
    return [...new Map(state.slices.map((slice) => [slice.batch.id, slice.batch])).values()]
      .filter((batch) => {
        if (!selected.has(batch.id) || batch.source?.kind === "imported" || batch.state === "stale") return false;
        const overview = overviews.get(batch.id);
        return !onlyMissing || !overview?.content.trim() || overview.state !== "ready"
          || overview.batch.sourceHash !== batch.sourceHash;
      })
      .sort(createBatchOrder(currentChatMessages()).compare);
  }

  regenerateBatchOverviews(batchIds: string[], options: {
    onlyMissing?: boolean;
    signal?: AbortSignal;
    onProgress?: (completed: number, total: number, batchNumber: number) => void;
  } = {}): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    return this.startRun(chatId, async (signal) => {
      const cancel = () => this.controls.get(chatId)?.abort();
      options.signal?.addEventListener("abort", cancel, { once: true });
      let completed = 0;
      let currentBatchNumber: number | undefined;
      try {
        if (options.signal?.aborted) cancel();
        signal.throwIfAborted();
        let state = await this.load();
        const existingIds = new Set(state.slices.map((slice) => slice.batch.id));
        if (batchIds.some((id) => !existingIds.has(id))) throw new Error("选中的批次已删除，请刷新后重新选择。");
        const batches = this.batchOverviewTargets(state, batchIds, options.onlyMissing ?? true);
        if (!batches.length) throw new Error("没有需要生成的批次总结；已跳过完成项、导入批次和原消息已变化的批次。");
        for (const batch of batches) {
          signal.throwIfAborted();
          currentBatchNumber = batch.batchNumber;
          options.onProgress?.(completed, batches.length, batch.batchNumber);
          await this.assertCurrentSourceUnchanged(state, batch);
          const byId = new Map(currentChatMessages().map((message) => [message.id, message]));
          state = await this.generateBatchOverview(state, batch.id,
            batch.messageIds.map((id) => byId.get(id)!), defaultDecision, signal);
          completed += 1;
          options.onProgress?.(completed, batches.length, batch.batchNumber);
          if (this.finishCurrent.has(chatId)) break;
        }
        return state;
      } catch (error) {
        if (signal.aborted || error instanceof Error && error.name === "AbortError") throw error;
        if (currentBatchNumber === undefined) throw error;
        throw new Error(`批次 ${currentBatchNumber} 生成失败，已停止后续调用；此前完成的 ${completed} 个批次总结已保留。${error instanceof Error ? error.message : String(error)}`);
      } finally {
        options.signal?.removeEventListener("abort", cancel);
      }
    }, defaultDecision);
  }

  private async generateBatchOverview(
    initial: SummaryWorldbookState, batchId: string, messages: SummaryGenerationRequest["messages"],
    decide: AmbiguousDecisionHandler, signal: AbortSignal, undoId?: string,
  ): Promise<SummaryWorldbookState> {
    signal.throwIfAborted();
    const batch = initial.slices.find((slice) => slice.batch.id === batchId)!.batch;
    await this.assertCurrentSourceUnchanged(initial, batch);
    const state = await this.store.saveBatchOverview(initial, batchId, { state: "pending" }, signal, undoId);
    this.emitProgress(state);
    try {
      const settings = getSettings();
      const workflow = settings.generationWorkflows.summary;
      const group = settings.generationGroups.find((candidate) => candidate.id === workflow.groupId);
      if (!group) throw new Error("请先配置总结生成端点组。");
      const initialRequest = batchOverviewRequestSchema.parse({
        chatId: state.catalog.chatId, batch, messages,
        promptMessages: await prepareBatchOverviewPrompt(messages, settings),
        generationGroup: group, failoverPolicy: workflow.failoverPolicy,
      });
      await this.assertCurrentSourceUnchanged(state, batch);
      let request = initialRequest;
      let result: BatchOverviewResult;
      while (true) {
        signal.throwIfAborted();
        result = (await this.trackedJob(state.catalog.chatId, () => echoesApi.startBatchOverview(request), signal)).result!;
        if (!result.decisionRequired) break;
        if (!await abortable(decide(result.decisionRequired), signal)) throw new DOMException("批次总结已停止。", "AbortError");
        await this.assertCurrentSourceUnchanged(state, batch);
        request = { ...initialRequest, resumeAfterEndpointId: result.decisionRequired.failedEndpointId };
      }
      if (result.outcome !== "completed" || !result.content?.trim()) throw new Error("批次总结未返回正文。");
      signal.throwIfAborted();
      await this.assertCurrentSourceUnchanged(state, batch);
      const updated = await this.store.saveBatchOverview(state, batchId, { content: result.content, state: "ready" }, signal, undoId);
      this.emitProgress(updated);
      return updated;
    } catch (error) {
      const message = signal.aborted ? "批次总结已停止；已完成切片保留。" :
        `批次总结失败；已完成切片保留，可单独重试。${error instanceof Error ? error.message : String(error)}`;
      try {
        this.emitProgress(await this.store.saveBatchOverview(state, batchId, { state: "failed", error: message.slice(0, 2000) }, undefined, undoId));
      } catch (saveError) { console.warn("[Echoes] Could not save batch summary failure state.", saveError); }
      if (signal.aborted || error instanceof DOMException && error.name === "AbortError") throw error;
      throw new Error(message);
    }
  }

  private async generateCandidates(
    state: SummaryWorldbookState, batch: SummaryBatchInput, messages: SummaryGenerationRequest["messages"],
    decide: AmbiguousDecisionHandler, signal: AbortSignal, stage: (name: string, count: number) => void,
    instructions?: string,
    mode: SummaryRunDraft["mode"] = "create",
    advanceCheckpoint = false,
  ): Promise<SummarySliceCandidate[] | null> {
    const settings = getSettings();
    summaryBatchMetadataSchema.parse({ ...batch, state: "pending", revision: 1,
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() });
    if (new Set(batch.messageIds).size !== batch.messageIds.length
      || batch.messageIds.join("\0") !== messages.map((message) => message.id).join("\0")
      || batch.startMessageId !== messages[0]?.id || batch.endMessageId !== messages.at(-1)?.id) throw new Error("总结批次范围无效，尚未调用模型。");
    const workflow = settings.generationWorkflows.summary;
    const group = settings.generationGroups.find((candidate) => candidate.id === workflow.groupId);
    if (!group) throw new Error("请先配置总结生成端点组。");
    const prepared = await prepareSummarySubRequests({ batch, messages, state, settings });
    const requests = prepared.map((part) => {
      const request: SummaryGenerationRequest = { chatId: state.catalog.chatId, batch: part.batch,
        extractAttributes: settings.continuity.extractAttributes,
        messages: part.originalMessages, promptMessages: [...part.promptMessages],
        generationGroup: group, failoverPolicy: workflow.failoverPolicy };
      if (batch.purpose === "supplement") request.promptMessages.push({
        role: "system", content: summarySupplementGuide(instructions?.trim() ?? ""),
      });
      return summaryGenerationRequestSchema.parse(request);
    });
    stage("预检通过子请求", requests.length);
    const fingerprint = await summaryDraftFingerprint(requests);
    let draft = await readSummaryDraft(state);
    if (draft) {
      if (!this.resumingDrafts.has(state.catalog.chatId)) throw new Error("存在未完成的总结记录，请在总结任务页明确选择继续或放弃。");
      if (draft.fingerprint !== fingerprint || draft.batch.sourceHash !== batch.sourceHash || draft.mode !== mode) {
        throw new Error("提示词、背景、清洗规则、端点配置或原文已变化，已完成结果不能与新输入混用。恢复草稿仍保留。");
      }
    } else {
      draft = { version: 1, ...draftScope(state), createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
        mode, batch, advanceCheckpoint, checkpoint: state.catalog.lastCommittedMessageId ?? null,
        nextBatchNumber: state.catalog.nextBatchNumber, batchSnapshot: summaryBatchSnapshot(state.slices, batch.id),
        instructions, fingerprint, inputs: requests.map(({ batch, messages, promptMessages, extractAttributes }) =>
          ({ batch, messages, promptMessages, extractAttributes })), parts: requests.map(() => ({})), jobs: {},
        budget: structuredClone(settings.taskBudget),
        status: "running", reason: "" };
    }
    draft.status = "running";
    draft.reason = "";
    await saveSummaryDraft(draft);
    this.emitProgress(state);
    const candidates: SummarySliceCandidate[] = [];
    try {
    for (const [index, initial] of requests.entries()) {
      signal.throwIfAborted();
      if (SillyTavern.getContext().chatId !== state.catalog.chatId
        || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) throw new Error("聊天已切换，未提交下一子请求。");
      stage(`子请求 ${index + 1} 输入字符`, initial.promptMessages.reduce((sum, item) => sum + item.content.length, 0));
      await this.assertCurrentSourceUnchanged(state, batch);
      const part = draft.parts[index]!;
      let slices = part.slices;
      if (!slices) {
        let result: SummaryGenerationResult;
        while (true) {
          signal.throwIfAborted();
          if (part.submitting && !part.jobId) throw new Error("上次提交未取得任务编号，结果与费用不确定。请先检查后台任务；不得直接重发。可导出已完成结果后明确放弃此草稿。");
          if (part.jobId && this.resumingDrafts.has(state.catalog.chatId)) {
            const previous = await echoesApi.getJob<SummaryGenerationResult>(part.jobId);
            await recordDraftJob(draft, index, previous);
            if (["failed", "cancelled", "ambiguous"].includes(previous.status)) {
              if (!await confirmAction({
                title: `重试子请求 ${index + 1}？`, cost: true, confirmLabel: "重试",
                message: `这个子请求的后台任务状态为 ${previous.status}。\n${previous.error?.message ?? previous.message}\n已发生的费用不会撤销，重新请求仍计入原预算。`,
              })) return null;
              if (!previous.usage) throw new Error("后台未提供原任务用量，不能无依据重置原预算。请核对任务后处理恢复草稿。");
              delete part.jobId;
              await saveSummaryDraft(draft);
            }
          }
          const remaining = part.jobId ? undefined : remainingDraftBudget(draft, getSettings().taskBudget);
          const request = { ...initial, ...(part.resumeAfterEndpointId ? { resumeAfterEndpointId: part.resumeAfterEndpointId } : {}) };
          if (!part.jobId) {
            part.submitting = true;
            await saveSummaryDraft(draft);
          }
          const knownId = part.jobId;
          const job = await this.trackedJob(state.catalog.chatId,
            () => knownId ? echoesApi.getJob<SummaryGenerationResult>(knownId) : echoesApi.startSummary(request, remaining),
            signal, (job) => recordDraftJob(draft!, index, job));
          result = job.result!;
          if (!result.decisionRequired) break;
          draft.status = "ambiguous";
          draft.reason = result.decisionRequired.message;
          await saveSummaryDraft(draft);
          if (!await abortable(decide(result.decisionRequired), signal)) return null;
          part.resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
          delete part.jobId;
          await saveSummaryDraft(draft);
        }
        if (result.outcome !== "completed" || !result.slices.length) throw new Error("总结正文未返回可用切片。");
        slices = result.slices;
        part.slices = structuredClone(slices);
        await saveSummaryDraft(draft);
        this.emitProgress(state);
      } else stage(`子请求 ${index + 1} 复用持久结果`, slices.length);
      candidates.push(...slices);
    }
    draft.status = "ready";
    draft.reason = "正文子请求全部完成，尚未正式提交。";
    await saveSummaryDraft(draft);
    return mergeSummaryCandidates(candidates);
    } catch (error) {
      draft.status = signal.aborted ? "cancelled" : "failed";
      draft.reason = error instanceof Error ? error.message : String(error);
      await saveSummaryDraft(draft);
      throw error;
    }
  }

  private async assertCurrentSourceUnchanged(
    state: SummaryWorldbookState,
    batch: SummaryBatchInput,
  ): Promise<void> {
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
      throw new Error("聊天或世界书已变化，未提交总结结果。");
    }
    const current = currentChatMessages();
    const start = current.findIndex((message) => message.id === batch.startMessageId);
    const end = current.findIndex((message) => message.id === batch.endMessageId);
    const selected = start >= 0 && end >= start ? current.slice(start, end + 1) : [];
    if (selected.length !== batch.messageIds.length
      || selected.some((message, index) => message.id !== batch.messageIds[index])
      || await summarySourceHash(selected) !== batch.sourceHash) {
      throw new Error("The summary source messages changed while the generation task was running.");
    }
  }

  private finishRun(
    chatId: string,
    operation: Promise<SummaryWorldbookState | null>,
    decide: AmbiguousDecisionHandler,
  ): void {
    if (this.activeRuns.get(chatId) === operation) this.activeRuns.delete(chatId);
    if (!this.rerunAutomatic.delete(chatId)
      || this.pausedAutomatic.has(chatId)
      || SillyTavern.getContext().chatId !== chatId) return;
    queueMicrotask(() => {
      void this.runAutomatic(decide).catch((error) => {
        console.error("[Echoes] Deferred summary automation failed.", error);
      });
    });
  }

  private async syncSlices(
    initialState: SummaryWorldbookState,
    slices: SummarySlice[],
    deletedSliceIds: string[],
    decide: AmbiguousDecisionHandler = defaultDecision,
    signal?: AbortSignal,
    textOnly = false,
  ): Promise<SummaryWorldbookState> {
    const settings = getSettings();
    signal?.throwIfAborted();
    const embeddingGroup = textOnly ? undefined : settings.retrieval.embeddingGroups.find((group) =>
      group.id === settings.summary.embeddingGroupId);
    if (!embeddingGroup && !initialState.catalog.retrievalCollectionId) {
      let state = initialState;
      for (const slice of slices) {
        state = await this.store.markSliceSyncState(initialState, slice, "pending");
      }
      return state;
    }
    const previousCollectionId = initialState.catalog.retrievalCollectionId;
    const ensured = embeddingGroup
      ? await this.ensureCollection(initialState, embeddingGroup.id, decide, signal)
      : { state: initialState, recreated: false };
    let state = ensured.state;
    const collectionId = state.catalog.retrievalCollectionId!;
    const collectionChanged = collectionId !== previousCollectionId;
    if (collectionChanged && previousCollectionId) return state;
    const targetSlices = collectionChanged || ensured.recreated
      ? state.slices.filter((slice) => slice.batch.state !== "stale")
      : slices;
    if (targetSlices.length > 100 || deletedSliceIds.length > 1_000) {
      const batches = Math.max(
        Math.ceil(targetSlices.length / 100),
        Math.ceil(deletedSliceIds.length / 1_000),
      );
      for (let index = 0; index < batches; index += 1) {
        signal?.throwIfAborted();
        state = await this.syncSlices(
          state,
          targetSlices.slice(index * 100, (index + 1) * 100),
          deletedSliceIds.slice(index * 1_000, (index + 1) * 1_000),
          decide,
          signal,
          textOnly,
        );
      }
      return state;
    }
    const documents = await Promise.all(targetSlices.map((slice) =>
      summaryRetrievalDocument(collectionId, slice, state.catalog.chatId)));
    const contentHashes = await Promise.all(targetSlices.map(summaryRetrievalContentHash));
    const syncBaseline = state;
    const deleteDocumentIds = await Promise.all(deletedSliceIds.map((id) =>
      summaryRetrievalDocumentId(collectionId, id)));
    let resumeAfterEndpointId: string | undefined;
    let result: RetrievalDocumentSyncResult;
    try {
      while (true) {
        signal?.throwIfAborted();
        const start = () => echoesApi.syncRetrievalDocuments({
          documents,
          deleteDocumentIds,
          embeddingGroup,
          failoverPolicy: settings.retrieval.failoverPolicy,
          embeddingBatchSize: settings.summary.embeddingBatchSize,
          ...(resumeAfterEndpointId ? { resumeAfterEndpointId } : {}),
        });
        result = (await (signal
          ? this.trackedJob(state.catalog.chatId, start, signal)
          : waitForJob(await start()))).result!;
        if (!result.decisionRequired) break;
        if (!await abortable(decide(result.decisionRequired), signal)) break;
        resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
      }
    } catch (error) {
      if (signal?.aborted) throw error;
      for (const slice of targetSlices) {
        state = await this.store.markSliceSyncState(syncBaseline, slice, "failed");
      }
      throw error;
    }
    if (documents.length > 0) {
      const statuses = await echoesApi.retrievalDocumentStatus(documents.map((document) => document.documentId!));
      const statusById = new Map(statuses.documents.map((document) => [document.documentId, document]));
      for (const [index, slice] of targetSlices.entries()) {
        const document = documents[index]!;
        const actual = statusById.get(document.documentId!);
        const syncState: SummarySyncState = actual && actual.contentHash === contentHashes[index]
          && actual.bodyHash === document.metadata.bodyHash
          && actual.collectionId === collectionId ? actual.vectorState : "pending";
        state = await this.store.markSliceSyncState(syncBaseline, slice, syncState);
      }
    }
    if (deletedSliceIds.length > 0) {
      state = await this.store.clearPendingDeletes(state.worldbookName, deletedSliceIds);
    }
    if (result.decisionRequired || result.ambiguous > 0) {
      throw new DOMException("向量同步已暂停：结果不确定，已保留完成部分，后续批次未提交。", "AbortError");
    }
    const incomplete = targetSlices.filter((slice) =>
      state.slices.find((item) => item.id === slice.id)?.batch.state !== "ready");
    if (embeddingGroup && incomplete.length) {
      const reason = result.attempts.filter((attempt) => attempt.outcome !== "succeeded").at(-1)?.message;
      throw new Error(`索引同步未完成：${incomplete.length}/${targetSlices.length} 个切片未就绪。${reason ?? "请查看向量任务日志。"} 已保存的切片保留。`);
    }
    return state;
  }

  private async ensureCollection(
    state: SummaryWorldbookState,
    embeddingGroupId: string,
    decide: AmbiguousDecisionHandler = defaultDecision,
    signal?: AbortSignal,
  ): Promise<{ state: SummaryWorldbookState; recreated: boolean }> {
    const group = getSettings().retrieval.embeddingGroups.find((candidate) => candidate.id === embeddingGroupId)!;
    let missingBoundCollection = false;
    if (state.catalog.retrievalCollectionId && state.catalog.retrievalEmbeddingSpaceId === group.embeddingSpaceId) {
      const existing = (await echoesApi.listRetrievalCollections()).find((c) => c.collection.id === state.catalog.retrievalCollectionId);
      if (existing && (existing.collection.dimensions !== group.dimensions || existing.collection.embeddingSpaceId !== group.embeddingSpaceId)) {
        throw new Error("向量空间或维度与已有总结集合不一致，请创建新向量空间并迁移。");
      }
      if (existing) return { state, recreated: false };
      missingBoundCollection = true;
    }
    if (state.catalog.retrievalCollectionId && !missingBoundCollection) {
      return { state: await this.migrateState(state, group, decide, signal ?? new AbortController().signal), recreated: false };
    }
    const digest = await hashIdentifier(`${state.catalog.namespaceId}\0${group.embeddingSpaceId}`);
    const collectionId = state.catalog.retrievalCollectionId ?? `summary_${digest.slice(0, 48)}`;
    const collections = await echoesApi.listRetrievalCollections();
    const validateCollection = (collection: { dimensions: number; embeddingSpaceId: string }) => {
      if (collection.dimensions !== group.dimensions || collection.embeddingSpaceId !== group.embeddingSpaceId) {
        throw new Error("向量空间或维度与已有总结集合不一致，请创建新向量空间并迁移。");
      }
    };
    const existing = collections.find((item) => item.collection.id === collectionId);
    if (existing) validateCollection(existing.collection);
    if (!collections.some((item) => item.collection.id === collectionId)) {
      try {
        signal?.throwIfAborted();
        await echoesApi.createRetrievalCollection({
          id: collectionId,
          name: `聊天总结 - ${state.catalog.chatId}`.slice(0, 120),
          description: "Echoes 根据聊天世界书重建的总结检索集合。",
          embeddingSpaceId: group.embeddingSpaceId,
          dimensions: group.dimensions,
        });
      } catch (error) {
        const refreshed = await echoesApi.listRetrievalCollections();
        const concurrent = refreshed.find((item) => item.collection.id === collectionId);
        if (!concurrent) throw error;
        validateCollection(concurrent.collection);
      }
    }
    state = await this.store.setRetrievalBinding(state.worldbookName, collectionId, group.embeddingSpaceId);
    if (missingBoundCollection) {
      for (const batchId of new Set(state.slices.filter((slice) => slice.batch.state !== "stale").map((slice) => slice.batch.id))) {
        const activeIds = state.slices.filter((slice) => slice.batch.id === batchId && slice.batch.state !== "stale").map((slice) => slice.id);
        state = await this.store.markBatchState(state.worldbookName, batchId, "pending", activeIds);
      }
    }
    return { state, recreated: missingBoundCollection };
  }

  migrateEmbeddingSpace(groupId: string): Promise<SummaryWorldbookState | null> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) return Promise.reject(new Error("请先选择聊天。"));
    if (this.activeRuns.has(chatId)) return Promise.reject(new Error("请先停止当前总结任务。"));
    const group = getSettings().retrieval.embeddingGroups.find((g) => g.id === groupId);
    if (!group?.endpoints.some((e) => e.enabled)) return Promise.reject(new Error("目标向量组没有可用端点。"));
    return this.startRun(chatId, async (signal) => {
      const state = await this.load();
      if (state.catalog.chatId !== chatId) throw new Error("当前聊天已变化。");
      return this.migrateState(state, structuredClone(group), defaultDecision, signal);
    }, defaultDecision);
  }

  private async migrateState(
    state: SummaryWorldbookState,
    group: EmbeddingEndpointGroup,
    decide: AmbiguousDecisionHandler,
    signal: AbortSignal,
  ): Promise<SummaryWorldbookState> {
    const guard = () => {
      signal.throwIfAborted();
      if (SillyTavern.getContext().chatId !== state.catalog.chatId
        || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
        throw new DOMException("聊天已切换，迁移已停止。", "AbortError");
      }
      const latest = getSettings().retrieval.embeddingGroups.find((g) => g.id === group.id);
      if (JSON.stringify(latest) !== JSON.stringify(group)) throw new Error("迁移期间目标向量配置已变化，请重试。");
    };
    guard();
    const digest = await hashIdentifier(`${state.catalog.namespaceId}\0${group.embeddingSpaceId}\0${group.dimensions}\0${summaryMigrationFingerprint(state)}`);
    const collectionId = `summary_${digest.slice(0, 48)}`;
    const existing = (await echoesApi.listRetrievalCollections()).find((c) => c.collection.id === collectionId);
    if (existing && (existing.collection.dimensions !== group.dimensions || existing.collection.embeddingSpaceId !== group.embeddingSpaceId)) {
      throw new Error("目标集合的向量空间或维度不一致。");
    }
    if (!existing) await echoesApi.createRetrievalCollection({
      id: collectionId, name: `总结迁移 - ${state.catalog.chatId}`.slice(0, 120),
      description: "Echoes summary migration", embeddingSpaceId: group.embeddingSpaceId, dimensions: group.dimensions,
    });
    const slices = state.slices.filter((s) => s.batch.state !== "stale");
    const settings = getSettings();
    for (let offset = 0; offset < slices.length; offset += 50) {
      guard();
      const batch = slices.slice(offset, offset + 50);
      const documents = await Promise.all(batch.map((s) => summaryRetrievalDocument(collectionId, s, state.catalog.chatId)));
      let resumeAfterEndpointId: string | undefined;
      while (true) {
        guard();
        const result = (await this.trackedJob(state.catalog.chatId, () => echoesApi.syncRetrievalDocuments({
          documents, deleteDocumentIds: [], embeddingGroup: group,
          embeddingBatchSize: settings.summary.embeddingBatchSize, failoverPolicy: settings.retrieval.failoverPolicy,
          ...(resumeAfterEndpointId ? { resumeAfterEndpointId } : {}),
        }), signal)).result!;
        if (result.decisionRequired) {
          if (!await abortable(decide(result.decisionRequired), signal)) throw new DOMException("迁移已停止，原索引绑定保持不变。", "AbortError");
          resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
          continue;
        }
        if (result.failed || result.pending || result.ambiguous) throw new Error("目标向量尚未全部就绪，原索引绑定保持不变。可重试迁移。");
        break;
      }
      const actual = await echoesApi.retrievalDocumentStatus(documents.map((d) => d.documentId!));
      const byId = new Map(actual.documents.map((d) => [d.documentId, d]));
      for (const [index, slice] of batch.entries()) {
        const d = byId.get(documents[index]!.documentId!);
        if (d?.vectorState !== "ready" || d.contentHash !== await summaryRetrievalContentHash(slice)
          || d.bodyHash !== documents[index]!.metadata.bodyHash) {
          throw new Error("目标向量校验未通过，原索引绑定保持不变。");
        }
      }
    }
    guard();
    return this.store.activateRetrievalMigration(state, collectionId, group.embeddingSpaceId, signal);
  }

}
