import type { MemoryTypeDefinition } from "../../shared/domain";
import { decodeMemoryContent } from "../worldbook/memory-codec";

export function memoryTableHeader(type: MemoryTypeDefinition): string {
  const describedDefaults = type.columns.filter((column) => column.defaultValue !== undefined && column.description);
  return [
    `## 资料表：${type.name}`,
    ...(type.description ? [`用途：${type.description}`] : []),
    `字段：${type.columns.map((column) => column.name).join("、")}`,
    ...(describedDefaults.length ? [
      "字段说明：",
      ...describedDefaults.map((column) => `- ${column.name}：${column.description}`),
    ] : []),
    "本次召回条目：",
  ].join("\n");
}

interface ActivatedEntry {
  world: string;
  uid: number;
  content: string;
  position: number;
  role?: number;
  depth?: number;
  outletName?: string;
}

interface ScanEvent {
  activated: { entries: Map<string, ActivatedEntry> };
}

interface ScanSource {
  books: Map<string, TavernWorldbookEntry[]>;
  originals: Map<string, ActivatedEntry>;
  replacements: Map<string, ActivatedEntry>;
}

// A scan can recurse. Keep its original rows separate from grouped prompt copies.
const sources = new WeakMap<Map<string, ActivatedEntry>, ScanSource>();

async function groupActivatedTables({ activated: { entries } }: ScanEvent): Promise<void> {
  const helper = window.TavernHelper;
  if (!helper || entries.size === 0) return;
  let source = sources.get(entries);
  if (!source) {
    source = { books: new Map(), originals: new Map(), replacements: new Map() };
    sources.set(entries, source);
  }
  for (const [key, entry] of entries) {
    if (entry !== source.replacements.get(key)) source.originals.set(key, entry);
  }
  const worlds = [...new Set([...entries.values()].map((entry) => entry.world))];
  for (const world of worlds) {
    if (!source.books.has(world)) source.books.set(world, await helper.getWorldbook(world));
  }
  const groups = new Map<string, { type: MemoryTypeDefinition; rows: Array<{
    key: string; entry: ActivatedEntry; name: string;
  }> }>();
  for (const [key] of entries) {
    const entry = source.originals.get(key)!;
    const book = source.books.get(entry.world)!;
    const stored = book.find((item) => item.uid === entry.uid);
    const metadata = stored?.extra?.echoes;
    if (metadata?.kind !== "row" || !entry.content.trim()) continue;
    const types: MemoryTypeDefinition[] = book.find((item) =>
      item.extra?.echoes?.kind === "catalog")?.extra?.echoes?.catalog?.types ?? [];
    const type = types.find((item) => item.id === metadata.typeId);
    if (!type || !stored) continue;
    // Respect explicitly different injection positions instead of moving their data.
    const groupKey = JSON.stringify([entry.world, type.id, entry.position, entry.role, entry.depth, entry.outletName]);
    const group = groups.get(groupKey) ?? { type, rows: [] };
    group.rows.push({ key, entry, name: decodeMemoryContent(type, stored.content).dataName });
    groups.set(groupKey, group);
  }
  for (const group of groups.values()) {
    const content = [
      memoryTableHeader(group.type),
      ...group.rows.map(({ entry, name }) => `### ${name}\n${entry.content}`),
    ].join("\n\n");
    for (const [index, { key, entry }] of group.rows.entries()) {
      const replacement = { ...entry, content: index === 0 ? content : "" };
      entries.set(key, replacement);
      source.replacements.set(key, replacement);
    }
  }
}

export function installMemoryTableInjection(): void {
  SillyTavern.getContext().eventSource?.on("worldinfo_scan_done", async (event: ScanEvent) => {
    try {
      await groupActivatedTables(event);
    } catch (error) {
      console.error("[Echoes] 结构化记忆分表注入失败", error);
      toastr.warning("结构化记忆分表注入失败，已保留原条目；请查看控制台日志。", "Echoes");
    }
  });
}
