import { EchoesBackupManager, serializeBackup } from "../../../maintenance/backup";
import { forgetMemoryUndo, listMemoryUndo } from "../../../maintenance/operation-undo";
import { WorldbookMemoryStore } from "../../../worldbook/worldbook-memory";
import { extractionCoordinator } from "../../../memory/extraction-coordinator";
import { h, formatTime, download, readTextFile } from "../../kit/dom";
import { button, badge, menu } from "../../kit/controls";
import { card, stack, kv, lazy, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { modal, confirmAction } from "../../kit/overlays";
import { table } from "../../kit/data";
import type { PageContext } from "../../shell/context";

const manager = new EchoesBackupManager();

export async function backupPage(ctx: PageContext): Promise<HTMLElement> {
  const exportOptions = form([{ key: "global", label: "包含全局设置", type: "switch", value: false, hint: "不包含 API 密钥" }], { track: false, className: "is-single" });
  const restoreOptions = form([
    { key: "mode", label: "恢复方式", type: "select", value: "equivalent_chat",
      options: [["equivalent_chat", "同一个聊天：恢复消息关联与全部记忆"], ["seed_memories", "新的聊天：只导入记忆作为起点"]] },
    { key: "global", label: "同时恢复备份中的全局设置", type: "switch", value: false },
  ], { track: false, className: "is-single" });
  const worldbook = ctx.worldbook;
  const records = worldbook ? await listMemoryUndo(worldbook, ctx.chatId) : [];
  const undoState = (record: (typeof records)[number]) => record.memoryRestored ? "记忆已恢复，待核对其余步骤"
    : record.restoring ? "撤销可能中断，可以再次核对" : record.completed ? "可以撤销" : "写入可能中断，撤销前请核对";
  return stack(
    card("导出备份", { scope: "chat", description: "备份当前聊天的全部 Echoes 数据：结构化记忆、总结、状态快照和隐藏标记。" }, exportOptions.node,
      h("div", "ec-row ec-card-foot", button("导出备份", async () => {
        ctx.guard();
        const backup = await ctx.run("导出备份", () => manager.create(exportOptions.values().global));
        download(`echoes-backup-${backup.createdAt.replaceAll(":", "-")}.json`, serializeBackup(backup));
      }, { variant: "primary", icon: "download" }))),
    card("恢复备份", { scope: "chat", description: "选择备份文件后先预检，确认影响后才会写入。" }, restoreOptions.node,
      h("div", "ec-row ec-card-foot", button("选择备份并预检", async () => {
        const text = await readTextFile();
        if (text === null) return;
        ctx.guard();
        const values = restoreOptions.values();
        const backup = await manager.parse(text);
        const plan = await manager.plan(backup, values.mode, values.global);
        modal("恢复预检", [
          callout("warning", "恢复会替换目标聊天现有的 Echoes 数据，检索索引需要重新建立。"),
          kv([["目标聊天", plan.targetChatId], ["替换的记忆条目", String(plan.echoesEntriesToReplace)], ["状态快照", String(plan.statusSnapshotsToReplace)],
            ["隐藏标记", String(plan.compressionMarkersToReplace)], ["全局设置", plan.restoreGlobalSettings ? "替换" : "保留"]]),
          ...plan.warnings.map((warning) => callout("warning", warning)),
          lazy("预检详情", plan),
        ], { size: "large", primary: { label: "先导出安全备份，再恢复", danger: true, run: async () => {
          if (!await confirmAction({ title: "确认恢复？", message: "恢复前会自动下载一份当前数据的安全备份。", danger: true, confirmLabel: "恢复" })) return false;
          ctx.guard();
          const result = await ctx.run("恢复备份", () => manager.restore(backup, plan, (safety) =>
            download(`echoes-safety-${safety.backupId}.json`, serializeBackup(safety))));
          modal("恢复完成", lazy("恢复结果", result.result));
          await ctx.refresh();
        } } });
      }, { variant: "primary", icon: "file-import" }))),
    card("操作撤销", { scope: "chat", description: "可以撤销最近对结构化条目和总结切片的修改，以及相关的原消息隐藏变化。表结构的变更和导入不能撤销。" },
      table([
        { label: "操作", cell: (record) => h("strong", "", record.label) },
        { label: "时间", cell: (record) => formatTime(record.createdAt) },
        { label: "影响", cell: (record) => `${record.changes.length} 个记忆对象 · ${record.visibility.length} 条可见性变化` },
        { label: "状态", cell: (record) => badge(undoState(record), record.completed && !record.restoring ? "neutral" : "warning") },
        { label: "", className: "is-actions", cell: (record) => h("div", "ec-row",
          button("撤销", async () => {
            ctx.guard();
            if (ctx.summary.isRunning() || extractionCoordinator.isRunning()) throw new Error("请先停止正在运行的记忆任务。");
            if (!await confirmAction({ title: `撤销「${record.label}」？`, confirmLabel: "撤销",
              message: `只恢复这里列出的 ${record.changes.length} 个记忆对象和 ${record.visibility.length} 条可见性变化。之后又被修改过的对象会阻止撤销。不调用模型；总结的文本索引会尝试同步，向量需要另行同步。` })) return;
            await ctx.run("撤销记忆操作", async () => {
              if (record.kind === "structured") await new WorldbookMemoryStore().undoOperation(record.id);
              else await ctx.summary.undoOperation(record.id);
            });
            await ctx.refresh();
          }, { small: true, icon: "rotate-left" }),
          menu(`${record.label} 的操作`, [
            { label: "查看快照", icon: "eye", onSelect: () => modal(record.label, lazy("操作前后", record), { size: "large" }) },
            { label: "导出快照", icon: "download", onSelect: () => download(`echoes-operation-${record.id}.json`, JSON.stringify(record, null, 2)) },
            { label: "清除这条记录", icon: "trash", onSelect: async () => {
              if (!await confirmAction({ title: "清除这条撤销记录？", message: "只删除撤销快照，不改变当前记忆。", confirmLabel: "清除" })) return;
              ctx.guard();
              await forgetMemoryUndo(worldbook!, ctx.chatId, record.id);
              await ctx.refresh();
            } },
          ])) },
      ], records, { empty: "当前聊天没有可以撤销的操作。" })),
  );
}
