import type { JobRecord, RetrievalHit, RetrievalQueryRequest, RetrievalQueryResult } from "../shared/domain";
import type { ContinuitySettings } from "../shared/continuity";
import { echoesApi } from "./api/client";

export interface SupplementResult { hits: RetrievalHit[]; calls: number; messages: string[] }
export function supplementQueryVariants(queries: string[]): string[] {
  const original = new Set(queries.map((query) => query.trim()));
  const variants: string[] = [];
  for (const query of queries) {
    // Narrow to existing clauses, without interpreting a character card or inventing a missing event.
    const clauses = query.split(/[\n。！？!?]+/u).map((text) => text.trim()).filter((text) => text.length >= 4);
    for (const index of [clauses.length - 1, 0, Math.floor(clauses.length / 2)]) {
      const text = clauses[index];
      if (!text || original.has(text)) continue;
      variants.push(text.length > 1000 ? text.slice(-1000) : text);
    }
  }
  return [...new Set(variants)].slice(0, 3);
}
export async function boundedSupplement(options: {
  request: RetrievalQueryRequest; queries: string[]; config: ContinuitySettings["supplement"];
  guard: () => void; signal?: AbortSignal; track?: (id: string | null) => void;
}): Promise<SupplementResult> {
  const output: SupplementResult = { hits: [], calls: 0, messages: [] };
  if (!options.config.maxRequests) return output;
  const deadline = Date.now() + options.config.maxWaitMs;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error("补充检索达到等待上限。")), options.config.maxWaitMs);
  const abort = () => controller.abort(options.signal?.reason);
  options.signal?.addEventListener("abort", abort, { once: true });
  if (options.signal?.aborted) abort();
  const excluded = new Set(options.request.excludeSourceIds ?? []);
  const seen = new Set<string>();
  const queries = [...new Set(options.queries.map((query) => query.trim()).filter(Boolean))];
  let pending: JobRecord<RetrievalQueryResult> | undefined;
  const guard = () => { options.guard(); controller.signal.throwIfAborted(); };
  try {
    for (const query of queries.slice(0, options.config.maxRequests)) {
      guard();
      if (output.hits.length >= options.config.maxItems) break;
      const paid = options.config.allowPaid;
      const request: RetrievalQueryRequest = {
        ...options.request, query, queries: [{ id: "supplement", text: query }],
        excludeSourceIds: [...excluded], vectorEnabled: paid && options.request.vectorEnabled,
        bm25Enabled: true, rerankEnabled: paid && options.request.rerankEnabled,
        minimumRelevance: paid && options.request.rerankEnabled ? options.request.minimumRelevance
          : options.request.fallbackMinimumRelevance ?? options.request.minimumRelevance ?? 0,
        finalTopK: options.config.maxItems - output.hits.length, failoverPolicy: "confirm_ambiguous",
      };
      output.calls++;
      pending = await echoesApi.queryRetrieval(request, { signal: controller.signal,
        taskBudget: { maxProviderCalls: 2, maxInputCharacters: 0, maxDurationMs: Math.max(1, deadline - Date.now()) } });
      options.track?.(pending.id);
      guard();
      while (pending.status === "queued" || pending.status === "running") {
        await new Promise<void>((resolve) => setTimeout(resolve, Math.min(200, Math.max(0, deadline - Date.now()))));
        guard();
        pending = await echoesApi.getJob<RetrievalQueryResult>(pending.id, controller.signal);
      }
      guard();
      if (pending.status !== "succeeded" || !pending.result) {
        output.messages.push(pending.error?.message ?? pending.message);
        break;
      }
      if (pending.result.decisionRequired) {
        output.messages.push("补充检索结果不确定，未切换端点或继续付费请求。");
        break;
      }
      for (const hit of pending.result.hits) {
        const key = `${hit.document.collectionId}:${hit.document.sourceId}`;
        if (seen.has(key) || excluded.has(hit.document.sourceId)) continue;
        seen.add(key); excluded.add(hit.document.sourceId); output.hits.push(hit);
        if (output.hits.length >= options.config.maxItems) break;
      }
      pending = undefined;
      options.track?.(null);
    }
  } catch (error) {
    if (controller.signal.aborted) output.messages.push("补充检索已停止等待或达到总等待上限，未提交后续请求；已提交请求可能仍产生费用。");
    else output.messages.push(error instanceof Error ? error.message : String(error));
    options.guard();
  } finally {
    clearTimeout(timer);
    options.signal?.removeEventListener("abort", abort);
    if (pending && ["queued", "running"].includes(pending.status)) await echoesApi.cancelJob(pending.id).catch(() => undefined);
    options.track?.(null);
  }
  return output;
}
