import { h, icon, isAbort, errorText } from "./dom";
import { overlayHost } from "./theme";

function stack(): HTMLElement {
  const host = overlayHost();
  let node = [...host.children].find((child) => child.classList.contains("ec-toasts")) as HTMLElement | undefined;
  if (!node) {
    node = h("div", "ec-toasts");
    host.append(node);
  }
  return node;
}

export type ToastTone = "info" | "success" | "warning" | "danger";

/** Success and info toasts disappear; warnings and errors stay until dismissed. */
export function toast(message: string, tone: ToastTone = "info"): void {
  const persistent = tone === "danger" || tone === "warning";
  const close = h("button", "ec-toast-close", icon("xmark"));
  close.type = "button";
  close.setAttribute("aria-label", "关闭提示");
  const glyph = { info: "circle-info", success: "circle-check", warning: "triangle-exclamation", danger: "circle-exclamation" }[tone];
  const node = h("div", `ec-toast is-${tone}`, icon(glyph), h("p", "", message), close);
  node.setAttribute("role", tone === "danger" ? "alert" : "status");
  close.addEventListener("click", () => node.remove());
  stack().append(node);
  if (!persistent) setTimeout(() => node.remove(), 4000);
}

export function reportError(error: unknown): void {
  if (isAbort(error)) return;
  console.error("[Echoes] UI operation failed.", error);
  toast(errorText(error), "danger");
}
