import { getSettings, saveSettings } from "../../../state/settings";
import { prepareExtraction } from "../../../memory/extraction-request";
import { extractionProviderMessages } from "../../../../shared/extraction-references";
import { h, nowIso } from "../../kit/dom";
import { button } from "../../kit/controls";
import { card, stack, lazy, code, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { modal } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { promptList } from "../prompt-editor";
import { memoryStore } from "./row-editor";

/** One-line pointer to a setting that lives elsewhere. */
export function continuityPointer(ctx: PageContext): HTMLElement {
  const enabled = getSettings().continuity.extractAttributes;
  return callout("info", `时间与认知属性：${enabled ? "已开启" : "未开启"}。这个开关同时影响结构化提取和总结生成。`,
    button("去设置", () => ctx.navigate("recall/continuity"), { variant: "ghost", small: true, icon: "arrow-right" }));
}

export async function structuredSettingsPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await memoryStore.load();
  const settings = getSettings();
  const preview = () => button("预览最终请求", async () => {
    const prepared = await prepareExtraction(await memoryStore.load(), getSettings(), "manual");
    modal("结构化提取请求", extractionProviderMessages(prepared.request).map((message, index) =>
      lazy(`${index + 1} · ${message.role} · ${message.content.length} 字`, () => code(message.content))), { size: "large" });
  }, { variant: "ghost", small: true, icon: "eye" });

  const rules = form([
    { key: "count", label: "单批消息数", type: "number", min: 2, max: 500, value: settings.extractionMessageCount, required: true,
      hint: "每次提取处理的消息条数" },
  ]);
  const context = form([
    { key: "enabled", label: "按需提供现有条目", type: "switch", value: settings.extractionContext.enabled,
      hint: "只发送与本批剧情相关的完整条目，其余条目只提供名称目录" },
    { key: "maxRows", label: "完整条目上限", type: "number", min: 1, max: 1000, value: settings.extractionContext.maxRows, required: true },
    { key: "maxCharacters", label: "完整条目字符预算", type: "number", min: 2000, max: 500000, value: settings.extractionContext.maxCharacters, required: true },
    { key: "relatedRows", label: "字段引用条目上限", type: "number", min: 0, max: 100, value: settings.extractionContext.relatedRows, required: true },
  ]);
  const sync = () => {
    const on = (context.control("enabled") as HTMLInputElement).checked;
    for (const key of ["maxRows", "maxCharacters", "relatedRows"]) context.field(key).classList.toggle("is-muted", !on);
  };
  context.control("enabled").addEventListener("change", sync);
  sync();

  return stack(
    card("提示词编排", { scope: "chat", description: "发送给结构化提取端点的提示词。表结构、条目和剧情由程序在其后附上。" },
      promptList("structured", state.catalog.promptPreset.items, async (items) => {
        ctx.guard();
        await memoryStore.savePromptPreset({ ...state.catalog.promptPreset, items, updatedAt: nowIso() });
      }, () => [preview()])),
    formCard("提取规则", rules, (values) => {
      const next = getSettings();
      next.extractionMessageCount = values.count;
      saveSettings(next);
    }, { scope: "global" }),
    formCard("写表上下文", context, (values) => {
      const next = getSettings();
      next.extractionContext = { enabled: values.enabled, maxRows: values.maxRows, maxCharacters: values.maxCharacters, relatedRows: values.relatedRows };
      saveSettings(next);
    }, { scope: "global", description: "名称目录、世界书背景和版本校验始终保留。" }),
    h("div", "", continuityPointer(ctx)),
  );
}
