import { randomUuid } from "../../../shared/crypto-compat";

export type Child = Node | string | number | null | undefined | false;

/** Creates an element with a class list and children; falsy children are skipped. */
export function h<K extends keyof HTMLElementTagNameMap>(
  tag: K, className = "", ...children: Child[]
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (tag === "input" || tag === "textarea" || tag === "form") node.setAttribute("autocomplete", "off");
  for (const child of children) {
    if (child === null || child === undefined || child === false) continue;
    node.append(child instanceof Node ? child : String(child));
  }
  return node;
}

/** replaceChildren that skips falsy children, like h(). */
export function fill(node: Element, ...children: Child[]): void {
  node.replaceChildren(...children.flatMap((child) =>
    child === null || child === undefined || child === false ? [] : [child instanceof Node ? child : String(child)]));
}

export function attrs<T extends Element>(node: T, values: Record<string, string | number | boolean | undefined>): T {
  for (const [name, value] of Object.entries(values)) {
    if (value === undefined || value === false) node.removeAttribute(name);
    else node.setAttribute(name, value === true ? "" : String(value));
  }
  return node;
}

export function icon(name: string, className = ""): HTMLElement {
  const node = h("i", `fa-solid fa-${name}${className ? " " + className : ""}`);
  node.setAttribute("aria-hidden", "true");
  return node;
}

export const uid = (prefix: string) => `${prefix}_${randomUuid().replaceAll("-", "")}`;
export const nowIso = () => new Date().toISOString();

export function formatTime(value: string | undefined, withDate = true): string {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return withDate ? date.toLocaleString() : date.toLocaleTimeString();
}

export function preview(value: unknown, length = 80): string {
  const text = typeof value === "string" ? value : value === undefined || value === null ? "" : JSON.stringify(value);
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length > length ? flat.slice(0, length) + "…" : flat;
}

export function lines(value: string): string[] {
  return value.split("\n").map((item) => item.trim()).filter(Boolean);
}

export function isAbort(error: unknown): boolean {
  return error instanceof Error && error.name === "AbortError";
}

export function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export function download(name: string, content: string, type = "application/json;charset=utf-8"): void {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const link = h("a");
  link.href = url;
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function pickFile(accept = ".json"): Promise<File | null> {
  return new Promise((resolve) => {
    const input = h("input");
    input.type = "file";
    input.accept = accept;
    input.addEventListener("change", () => resolve(input.files?.[0] ?? null), { once: true });
    input.addEventListener("cancel", () => resolve(null), { once: true });
    input.click();
  });
}

export async function readTextFile(accept = ".json", limitBytes = 20 * 1024 * 1024): Promise<string | null> {
  const file = await pickFile(accept);
  if (!file) return null;
  if (file.size > limitBytes) throw new Error(`单次导入文件不能超过 ${Math.round(limitBytes / 1024 / 1024)} MB。`);
  return file.text();
}

export async function copyText(text: string): Promise<void> {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }
  const buffer = h("textarea", "ec-copy-buffer");
  buffer.value = text;
  document.body.append(buffer);
  buffer.select();
  try {
    if (!document.execCommand("copy")) throw new Error("浏览器不允许复制，请手动选择文本复制。");
  } finally {
    buffer.remove();
  }
}

export function move<T>(items: readonly T[], from: number, offset: number): T[] {
  const result = [...items];
  const to = from + offset;
  if (to < 0 || to >= result.length) return result;
  const [item] = result.splice(from, 1);
  result.splice(to, 0, item!);
  return result;
}
