import { h, uid, type Child } from "./dom";

export interface TabItem {
  id: string;
  label: string;
  marker?: Child;
  disabled?: boolean | undefined;
}

/**
 * An accessible tab strip. Selection is delegated to onSelect so callers can
 * route or swap content themselves; arrow keys move between tabs.
 */
export function tabStrip(label: string, items: TabItem[], active: string, onSelect: (id: string) => unknown, className = ""): HTMLElement {
  const strip = h("div", `ec-tabs${className ? " " + className : ""}`);
  strip.setAttribute("role", "tablist");
  strip.setAttribute("aria-label", label);
  const buttons = items.map((item) => {
    const node = h("button", "ec-tab", h("span", "", item.label), item.marker);
    node.type = "button";
    node.id = uid("tab");
    node.setAttribute("role", "tab");
    node.setAttribute("aria-selected", String(item.id === active));
    node.tabIndex = item.id === active ? 0 : -1;
    node.disabled = Boolean(item.disabled);
    node.addEventListener("click", () => { if (item.id !== active) void onSelect(item.id); });
    return node;
  });
  strip.addEventListener("keydown", (event) => {
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
    const enabled = buttons.filter((node) => !node.disabled);
    const index = enabled.indexOf(document.activeElement as HTMLButtonElement);
    if (index < 0) return;
    event.preventDefault();
    const next = event.key === "Home" ? 0 : event.key === "End" ? enabled.length - 1
      : (index + (event.key === "ArrowRight" ? 1 : -1) + enabled.length) % enabled.length;
    enabled[next]?.focus();
    enabled[next]?.click();
  });
  strip.append(...buttons);
  return strip;
}

/** In-page sections switched by a tab strip; the active one persists in `state`. */
export function sections(label: string, items: Array<TabItem & { render: () => Child | Promise<Child> }>,
  state: { active: string }): HTMLElement {
  const root = h("div", "ec-sections");
  const host = h("div", "ec-section-body");
  const draw = async () => {
    const current = items.find((item) => item.id === state.active) ?? items[0]!;
    state.active = current.id;
    root.replaceChildren(tabStrip(label, items, current.id, (id) => { state.active = id; void draw(); }, "is-inline"), host);
    const content = await current.render();
    if (content === null || content === undefined || content === false) host.replaceChildren();
    else host.replaceChildren(content instanceof Node ? content : String(content));
  };
  void draw();
  return root;
}
