import { getSettings } from "../../../state/settings";
import { statusCoordinator } from "../../../status/status-coordinator";
import { renderStatusInjection } from "../../../status/status-injection";
import { recallCoordinator } from "../../../recall-coordinator";
import { h, nowIso } from "../../kit/dom";
import { button } from "../../kit/controls";
import { card, stack, code, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { modal } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { injectionSpecs } from "../shared";
import { updateRecall } from "./strategy";

export async function recallInjectionPage(ctx: PageContext): Promise<HTMLElement> {
  const recall = getSettings().retrieval.recall;
  const status = await statusCoordinator.load();
  const budget = form([
    { key: "maxTokens", label: "注入总预算（估算 Token）", type: "number", min: 0, max: 1000000, value: recall.budget?.maxTokens ?? 0, required: true,
      hint: "0 表示不限。Token 为本地粗估，不会截短正文" },
    { key: "overflow", label: "超出预算时", type: "select", value: recall.budget?.overflow ?? "preserve_protected", options: [
      ["preserve_protected", "保留状态、批次总结、近期与滞留切片，普通召回按预算筛选"],
      ["strict", "严格预算：保留状态与批次总结，常驻内容超出时中止生成"],
      ["abort", "任何超出都中止生成"]] },
  ]);
  const recallInjection = form(injectionSpecs(recall.injection));
  const statusInjection = form(injectionSpecs(status.catalog.profile.injection));
  return stack(
    callout("info", "生成回复前，Echoes 会把以下内容注入主模型：状态记忆、常驻批次总结、近期总结、召回的切片，以及激活的结构化表条目（经世界书注入）。"),
    formCard("注入预算", budget, (values) => updateRecall((next) => {
      next.budget = { maxTokens: values.maxTokens, overflow: values.overflow };
    }), { scope: "global" }),
    formCard("召回注入", recallInjection, (values) => updateRecall((next) => {
      next.injection = { position: values.position, role: values.role, depth: values.depth, order: values.order,
        template: values.template, maxWaitMs: values.maxWaitMs };
    }), { scope: "global", description: "模板中用 {{recent_summaries}} 表示近期总结，{{memories}} 表示召回的切片；漏写占位符时内容会补在末尾。",
      actions: [button("预览", async () => {
        const result = await ctx.run("召回预览", () => recallCoordinator.preview());
        modal("召回注入预览", code(result.trace.injectionText || "（本次没有注入内容）"), { size: "large" });
      }, { variant: "ghost", small: true, icon: "eye" })] }),
    formCard("状态注入", statusInjection, async (values) => {
      ctx.guard();
      const fresh = await statusCoordinator.load();
      await statusCoordinator.worldbook.saveConfiguration(fresh.worldbookName, { profile: { ...fresh.catalog.profile,
        injection: { position: values.position, role: values.role, depth: values.depth, order: values.order,
          template: values.template, maxWaitMs: values.maxWaitMs }, updatedAt: nowIso() } });
    }, { scope: "chat", description: "模板中用 {{status}} 表示当前状态。",
      actions: [button("预览", () => {
        const current = statusCoordinator.current(status);
        const text = renderStatusInjection(status.catalog, current?.snapshot.state ?? status.catalog.profile.initialState,
          statusInjection.control("template").value);
        modal("状态注入预览", [status.catalog.enabled ? null : callout("warning", "状态记忆未启用，生成时不会注入。"), code(text)], { size: "large" });
      }, { variant: "ghost", small: true, icon: "eye" })],
      after: status.catalog.enabled ? null : h("div", "", callout("warning", "状态记忆未启用。",
        button("去启用", () => ctx.navigate("status/current"), { variant: "ghost", small: true, icon: "arrow-right" }))) }),
    card("创作要求", { description: "用户确认的写作要求也会注入主模型，在“创作要求”页管理。" },
      h("div", "ec-row", button("前往", () => ctx.navigate("recall/preferences"), { variant: "ghost", small: true, icon: "arrow-right" }))),
  );
}
