import { z } from "zod";

export type StatusVariableValue =
  | { kind: "number"; value: number }
  | { kind: "formula"; value: string };

export interface StatusVariable {
  id: string;
  name: string;
  type: "fixed" | "computed";
  base: StatusVariableValue;
  extra: StatusVariableValue;
}

export interface EvaluatedStatusVariable {
  id: string;
  name: string;
  base: number;
  extra: number;
  final: number;
}

type Part = "base" | "extra" | "final";
type Reference = { kind: "reference"; name: string; part: "base" | "final"; start: number; end: number };
type Expression =
  | { kind: "number"; value: number }
  | Reference
  | { kind: "unary"; operator: string; value: Expression }
  | { kind: "binary"; operator: string; left: Expression; right: Expression }
  | { kind: "call"; name: string; arguments: Expression[] };
type Token = { kind: "number" | "string" | "name" | "symbol" | "end"; text: string; start: number; end: number };

const partNames: Record<Part, string> = { base: "基础值", extra: "额外值", final: "最终值" };
const precedence = new Map([["+", 10], ["-", 10], ["*", 20], ["/", 20], ["%", 20], ["^", 30], ["**", 30]]);
const functions = new Map<string, { min: number; max: number; run: (...args: number[]) => number }>([
  ["abs", { min: 1, max: 1, run: Math.abs }],
  ["floor", { min: 1, max: 1, run: Math.floor }],
  ["ceil", { min: 1, max: 1, run: Math.ceil }],
  ["round", { min: 1, max: 1, run: Math.round }],
  ["sqrt", { min: 1, max: 1, run: Math.sqrt }],
  ["min", { min: 1, max: 32, run: Math.min }],
  ["max", { min: 1, max: 32, run: Math.max }],
]);

function finite(value: number): number {
  if (!Number.isFinite(value)) throw new Error("计算结果必须为有限数值，请检查溢出或函数参数。");
  return Object.is(value, -0) ? 0 : value;
}

// A deliberately closed arithmetic grammar: no property access, assignment,
// arbitrary function calls, or evaluation of JavaScript source.
class FormulaParser {
  private index = 0;
  private nodes = 0;
  private token: Token;

  constructor(private readonly source: string) {
    if (!source.trim() || source.length > 4000) throw new Error("公式不能为空，且不能超过 4000 个字符。");
    const leading = source.match(/^\s*=/);
    if (leading) this.index = leading[0].length;
    this.token = this.next();
  }

  parse(): Expression {
    const result = this.expression(0, 0);
    if (this.token.kind !== "end") throw new Error(`公式第 ${this.token.start + 1} 个字符附近有多余内容。`);
    return result;
  }

  private next(): Token {
    while (/\s/u.test(this.source[this.index] ?? "") && this.index < this.source.length) this.index++;
    const start = this.index;
    const rest = this.source.slice(start);
    if (!rest) return { kind: "end", text: "", start, end: start };
    const number = rest.match(/^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/);
    const name = rest.match(/^[A-Za-z_][A-Za-z0-9_]*/);
    const string = rest.match(/^"(?:[^"\\\r\n]|\\.)*"/u);
    const text = number?.[0] ?? string?.[0] ?? name?.[0] ?? (rest.startsWith("**") ? "**" : rest[0]!);
    if (!number && !name && !string && !["+", "-", "*", "/", "%", "^", "**", "(", ")", ","].includes(text)) {
      throw new Error(`公式第 ${start + 1} 个字符无效；变量引用使用 base("变量名") 或 final("变量名")。`);
    }
    this.index += text.length;
    return { kind: number ? "number" : string ? "string" : name ? "name" : "symbol", text, start, end: this.index };
  }

  private take(): Token {
    const token = this.token;
    this.token = this.next();
    return token;
  }

  private require(text: string): void {
    if (this.token.text !== text) throw new Error(`公式第 ${this.token.start + 1} 个字符处应为 ${text}。`);
    this.take();
  }

  private expression(minimum: number, depth: number): Expression {
    if (depth > 64 || ++this.nodes > 512) throw new Error("公式过于复杂，请减少嵌套和运算项。");
    const token = this.take();
    let left: Expression;
    if (token.kind === "number") left = { kind: "number", value: finite(Number(token.text)) };
    else if (token.text === "+" || token.text === "-") {
      left = { kind: "unary", operator: token.text, value: this.expression(25, depth + 1) };
    } else if (token.text === "(") {
      left = this.expression(0, depth + 1);
      this.require(")");
    } else if (token.kind === "name") {
      this.require("(");
      if (token.text === "base" || token.text === "final") {
        const name = this.take();
        if (name.kind !== "string") throw new Error("变量名必须放在双引号内，例如 base(\"STR\")。");
        let value: unknown;
        try { value = JSON.parse(name.text); } catch { throw new Error("变量引用中的双引号或转义字符无效。"); }
        if (typeof value !== "string" || !value) throw new Error("变量引用名称不能为空。");
        this.require(")");
        left = { kind: "reference", name: value, part: token.text, start: name.start, end: name.end };
      } else {
        const fn = functions.get(token.text);
        if (!fn) throw new Error(`不支持函数 ${token.text}。`);
        const args: Expression[] = [];
        if (this.token.text !== ")") {
          do {
            if (args.length) this.require(",");
            args.push(this.expression(0, depth + 1));
          } while (this.token.text === "," && args.length <= fn.max);
        }
        this.require(")");
        if (args.length < fn.min || args.length > fn.max) throw new Error(`函数 ${token.text} 的参数数量不正确。`);
        left = { kind: "call", name: token.text, arguments: args };
      }
    } else throw new Error(`公式第 ${token.start + 1} 个字符处缺少数值或变量引用。`);
    while (this.token.kind === "symbol") {
      const level = precedence.get(this.token.text);
      if (level === undefined || level < minimum) break;
      if (++this.nodes > 512) throw new Error("公式过于复杂，请减少运算项。");
      const operator = this.take().text;
      const right = this.expression(level + (level === 30 ? 0 : 1), depth + 1);
      left = { kind: "binary", operator, left, right };
    }
    return left;
  }
}

function references(expression: Expression): Reference[] {
  switch (expression.kind) {
    case "reference": return [expression];
    case "unary": return references(expression.value);
    case "binary": return [...references(expression.left), ...references(expression.right)];
    case "call": return expression.arguments.flatMap(references);
    default: return [];
  }
}

function evaluate(expression: Expression, resolve: (reference: Reference) => number): number {
  switch (expression.kind) {
    case "number": return expression.value;
    case "reference": return resolve(expression);
    case "unary": return finite((expression.operator === "-" ? -1 : 1) * evaluate(expression.value, resolve));
    case "call": return finite(functions.get(expression.name)!.run(...expression.arguments.map((arg) => evaluate(arg, resolve))));
    case "binary": {
      const a = evaluate(expression.left, resolve), b = evaluate(expression.right, resolve);
      if ((expression.operator === "/" || expression.operator === "%") && b === 0) throw new Error("公式不能除以零或对零取余。");
      switch (expression.operator) {
        case "+": return finite(a + b);
        case "-": return finite(a - b);
        case "*": return finite(a * b);
        case "/": return finite(a / b);
        case "%": return finite(a % b);
        default: return finite(a ** b);
      }
    }
  }
}

const operandSchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("number"), value: z.number().finite() }).strict(),
  z.object({ kind: z.literal("formula"), value: z.string().min(1).max(4000) }).strict(),
]);
const variableSchema = z.object({
  id: z.string().min(1).max(80).regex(/^[A-Za-z][A-Za-z0-9_-]*$/),
  name: z.string().trim().min(1).max(80).regex(/^[^\u0000-\u001f\u007f\u2028\u2029]+$/u, "变量名必须为单行文本。"),
  type: z.enum(["fixed", "computed"]),
  base: operandSchema,
  extra: operandSchema,
}).strict().refine((variable) => variable.base.kind === (variable.type === "fixed" ? "number" : "formula"), {
  message: "固定变量的基础值必须为数值，变化变量的基础值必须为公式。",
});
const listSchema = z.array(variableSchema).max(500);

function calculate(variables: readonly StatusVariable[]): EvaluatedStatusVariable[] {
  const byName = new Map<string, StatusVariable>();
  const ids = new Set<string>();
  for (const variable of variables) {
    if (byName.has(variable.name)) throw new Error(`变量名重复：${variable.name}。`);
    if (ids.has(variable.id)) throw new Error("变量标识重复。");
    byName.set(variable.name, variable);
    ids.add(variable.id);
  }
  type Node = { variable: StatusVariable; part: Part; expression?: Expression; dependencies: Set<string> };
  const nodes = new Map<string, Node>();
  const key = (variable: StatusVariable, part: Part) => `${variable.id}:${part}`;
  for (const variable of variables) {
    for (const part of ["base", "extra"] as const) {
      try {
        const operand = variable[part];
        const expression: Expression = operand.kind === "number"
          ? { kind: "number", value: operand.value } : new FormulaParser(operand.value).parse();
        const dependencies = new Set(references(expression).map((ref) => {
          const target = byName.get(ref.name);
          if (!target) throw new Error(`引用的变量“${ref.name}”不存在；请先修改引用它的公式。`);
          if (target.id === variable.id) throw new Error("不能引用本变量的基础值或最终值。");
          if (target.type !== "fixed") throw new Error(`只能引用固定变量，“${ref.name}”是变化变量。`);
          return key(target, ref.part);
        }));
        nodes.set(key(variable, part), { variable, part, expression, dependencies });
      } catch (error) {
        throw new Error(`${variable.name} · ${partNames[part]}：${error instanceof Error ? error.message : String(error)}`);
      }
    }
    nodes.set(key(variable, "final"), {
      variable, part: "final", dependencies: new Set([key(variable, "base"), key(variable, "extra")]),
    });
  }
  // Sort value nodes, not just variables: referencing B.base must not depend on B.extra.
  const pending = new Map<string, number>(), dependents = new Map<string, string[]>();
  const ready: string[] = [], order: string[] = [];
  for (const [id, node] of nodes) {
    pending.set(id, node.dependencies.size);
    if (!node.dependencies.size) ready.push(id);
    for (const dependency of node.dependencies) {
      const list = dependents.get(dependency) ?? [];
      list.push(id);
      dependents.set(dependency, list);
    }
  }
  for (let index = 0; index < ready.length; index++) {
    const id = ready[index]!;
    order.push(id);
    for (const child of dependents.get(id) ?? []) {
      const remaining = pending.get(child)! - 1;
      pending.set(child, remaining);
      if (!remaining) ready.push(child);
    }
  }
  if (order.length !== nodes.size) {
    let next = [...pending].find(([, remaining]) => remaining > 0)![0];
    const path: string[] = [];
    while (!path.includes(next)) {
      path.push(next);
      next = [...nodes.get(next)!.dependencies].find((dependency) => pending.get(dependency)! > 0)!;
    }
    const cycle = [...path.slice(path.indexOf(next)), next].map((id) => {
      const node = nodes.get(id)!;
      return `${node.variable.name}.${partNames[node.part]}`;
    });
    throw new Error(`公式循环：${cycle.join(" → ")}。未保存本次修改。`);
  }
  const values = new Map<string, number>();
  for (const id of order) {
    const node = nodes.get(id)!;
    try {
      const value = node.part === "final"
        ? finite(values.get(key(node.variable, "base"))! + values.get(key(node.variable, "extra"))!)
        : evaluate(node.expression!, (ref) => values.get(key(byName.get(ref.name)!, ref.part))!);
      values.set(id, finite(value));
    } catch (error) {
      throw new Error(`${node.variable.name} · ${partNames[node.part]}：${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return variables.map((variable) => ({
    id: variable.id, name: variable.name,
    base: values.get(key(variable, "base"))!, extra: values.get(key(variable, "extra"))!, final: values.get(key(variable, "final"))!,
  }));
}

export const statusVariablesSchema = listSchema.superRefine((variables, ctx) => {
  try { calculate(variables); }
  catch (error) { ctx.addIssue({ code: "custom", message: error instanceof Error ? error.message : String(error) }); }
});

export function evaluateStatusVariables(variables: readonly StatusVariable[]): EvaluatedStatusVariable[] {
  const parsed = listSchema.safeParse(variables);
  if (!parsed.success) throw new Error(parsed.error.issues[0]?.message ?? "变量配置无效。");
  return calculate(parsed.data);
}

function renameReference(operand: StatusVariableValue, oldName: string, newName: string): StatusVariableValue {
  if (operand.kind !== "formula") return operand;
  const matches = references(new FormulaParser(operand.value).parse())
    .filter((ref) => ref.name === oldName).sort((a, b) => b.start - a.start);
  let source = operand.value;
  for (const ref of matches) source = source.slice(0, ref.start) + JSON.stringify(newName) + source.slice(ref.end);
  return { kind: "formula", value: source };
}

export function replaceStatusVariable(variables: readonly StatusVariable[], candidate: StatusVariable): StatusVariable[] {
  const next = structuredClone(candidate);
  next.name = next.name.trim();
  const old = variables.find((variable) => variable.id === next.id);
  let result = old ? variables.map((variable) => variable.id === next.id ? next : structuredClone(variable))
    : [...structuredClone(variables), next];
  if (old && old.name !== next.name) result = result.map((variable) => ({
    ...variable, base: renameReference(variable.base, old.name, next.name), extra: renameReference(variable.extra, old.name, next.name),
  }));
  evaluateStatusVariables(result);
  return result;
}

export function formatStatusVariableNumber(value: number): string {
  return String(Number(finite(value).toPrecision(15)));
}

export function renderStatusVariables(variables: readonly StatusVariable[]): string {
  return evaluateStatusVariables(variables).map(({ name, base, extra, final }) =>
    `${name} : ${formatStatusVariableNumber(base)}(${extra >= 0 ? "+" : ""}${formatStatusVariableNumber(extra)})=${formatStatusVariableNumber(final)}`,
  ).join("\n");
}
