import type { MemoryColumnDefinition, MemoryEntryStatus, MemoryTypeTemplate } from "../../../../shared/domain";
import { MEMORY_COLUMN_TYPES } from "../../../../shared/domain";
import { MemorySchemaBackfillRequiredError, parseMemoryDefaultValue } from "../../../../shared/memory-schema-migration";
import { validateMemoryValues } from "../../../../shared/schemas";
import { h, uid, move } from "../../kit/dom";
import { button, badge, menu } from "../../kit/controls";
import { form, type FieldSpec } from "../../kit/forms";
import { formModal, modal, confirmAction } from "../../kit/overlays";
import { ACTIVATION_OPTIONS } from "../shared";

export type TypeDraft = Pick<MemoryTypeTemplate, "name" | "description" | "columns" | "guide" | "defaultStatus">;
const TYPE_NAMES: Record<string, string> = {
  text: "短文本", long_text: "长文本", number: "数值", boolean: "是 / 否", date: "日期", enum: "枚举", json: "JSON",
};

function editColumn(existing: MemoryColumnDefinition | undefined, done: (column: MemoryColumnDefinition) => void) {
  const target = form([
    { key: "id", label: "字段 ID", value: existing?.id ?? uid("column"), required: true, readonly: Boolean(existing),
      hint: "写入 JSON 时使用的键，创建后不能修改" },
    { key: "name", label: "字段名称", value: existing?.name ?? "", required: true },
    { key: "type", label: "字段类型", type: "select", value: existing?.type ?? "text",
      options: MEMORY_COLUMN_TYPES.map((type) => [type, TYPE_NAMES[type] ?? type]) },
    { key: "required", label: "必填", type: "switch", value: existing?.required ?? false },
    { key: "description", label: "字段说明", type: "textarea", rows: 3, value: existing?.description ?? "", hint: "写表模型会看到这段说明" },
    { key: "enumValues", label: "枚举选项", type: "textarea", rows: 3, value: existing?.enumValues?.join("\n") ?? "", hint: "每行一项，仅枚举类型使用" },
    { key: "defaultValue", label: "默认值", value: existing?.defaultValue === undefined ? ""
      : typeof existing.defaultValue === "string" && existing.type !== "json" ? existing.defaultValue : JSON.stringify(existing.defaultValue),
      hint: "可留空；JSON 字段填写 JSON 文本" },
  ], { className: "is-single" });
  const sync = () => target.show("enumValues", target.control("type").value === "enum");
  target.control("type").addEventListener("change", sync);
  sync();
  formModal(existing ? `编辑字段 · ${existing.name}` : "添加字段", target, (values) => {
    const next: MemoryColumnDefinition = { id: values.id, name: values.name, type: values.type, required: values.required,
      ...(values.description ? { description: values.description } : {}) };
    const options = String(values.enumValues ?? "").split("\n").map((item) => item.trim()).filter(Boolean);
    if (next.type === "enum" && options.length) next.enumValues = options;
    if (String(values.defaultValue ?? "").trim()) {
      next.defaultValue = parseMemoryDefaultValue(next, values.defaultValue);
      validateMemoryValues([next], { [next.id]: next.defaultValue });
    }
    done(next);
  });
}

/** Asks for defaults (or optional) when new required columns lack values in existing rows. */
function backfill(error: MemorySchemaBackfillRequiredError, columns: MemoryColumnDefinition[]): Promise<MemoryColumnDefinition[] | null> {
  return new Promise((resolve) => {
    const specs = error.missing.flatMap(({ column, count, rowNames }, index): FieldSpec[] => [
      { key: `optional_${index}`, label: `${column.name}：改为非必填`, type: "switch", value: false },
      { key: `default_${index}`, label: `${column.name}：默认值`, wide: true,
        hint: `缺值 ${count} 条：${rowNames.join("、")}${count > rowNames.length ? " 等" : ""}` },
    ]);
    const target = form(specs, { className: "is-single" });
    let resolved = false;
    formModal("补齐已有条目的必填字段", target, (values) => {
      const next = structuredClone(columns);
      for (const [index, { column }] of error.missing.entries()) {
        const item = next.find((candidate) => candidate.id === column.id)!;
        if (values[`optional_${index}`]) { item.required = false; continue; }
        const value = parseMemoryDefaultValue(item, values[`default_${index}`]);
        validateMemoryValues([{ ...item, defaultValue: undefined }], { [item.id]: value });
        item.defaultValue = value;
      }
      resolved = true;
      resolve(next);
    }, { saveLabel: "继续保存", onClose: () => { if (!resolved) resolve(null); } });
  });
}

/** Edits a table or template definition in a modal. */
export function typeEditor(current: TypeDraft, save: (value: TypeDraft) => Promise<unknown>, title = "编辑表结构") {
  let columns = structuredClone(current.columns);
  let columnsDirty = false;
  const target = form([
    { key: "name", label: "名称", value: current.name, required: true },
    { key: "defaultStatus", label: "新条目的激活方式", type: "select", value: current.defaultStatus, options: ACTIVATION_OPTIONS },
    { key: "description", label: "用途", type: "textarea", rows: 2, value: current.description },
    { key: "guide", label: "记录说明", type: "textarea", rows: 7, value: current.guide, required: true, hint: "写表模型据此判断什么内容写进这张表" },
  ]);
  const host = h("div", "ec-column-list");
  const count = h("h4", "");
  const changed = () => { columnsDirty = true; host.dataset.dirty = "true"; draw(); };
  const draw = () => {
    count.textContent = `字段 · ${columns.length}`;
    host.replaceChildren(...columns.map((column, index) => h("div", "ec-column-row",
    h("span", "ec-sortable-index", String(index + 1)), h("strong", "", column.name), badge(TYPE_NAMES[column.type] ?? column.type),
    column.required ? badge("必填", "accent") : null,
    h("span", "ec-list-meta", column.description ?? ""),
    menu(`字段 ${column.name} 的操作`, [
      { label: "编辑", icon: "pen", onSelect: () => editColumn(column, (next) => { columns[index] = next; changed(); }) },
      { label: "上移", icon: "arrow-up", disabled: index === 0, onSelect: () => { columns = move(columns, index, -1); changed(); } },
      { label: "下移", icon: "arrow-down", disabled: index === columns.length - 1, onSelect: () => { columns = move(columns, index, 1); changed(); } },
      { label: "删除", icon: "trash", danger: true, onSelect: async () => {
        if (!await confirmAction({ title: `删除字段「${column.name}」？`, message: "保存后，已有条目中的该字段也会一并移除。", confirmLabel: "删除", danger: true })) return;
        columns.splice(index, 1);
        changed();
      } },
    ]))));
  };
  draw();
  const body = [target.node, h("div", "ec-heading", count, button("添加字段", () =>
    editColumn(undefined, (next) => { columns.push(next); changed(); }), { small: true, icon: "plus" })), host];
  return modal(title, body, {
    size: "large", dirty: () => target.dirty() || columnsDirty,
    primary: { label: "保存", run: async () => {
      const values = target.values();
      while (true) {
        try {
          await save({ name: values.name, description: values.description, guide: values.guide,
            defaultStatus: values.defaultStatus as MemoryEntryStatus, columns });
          return;
        } catch (error) {
          if (!(error instanceof MemorySchemaBackfillRequiredError)) throw error;
          const next = await backfill(error, columns);
          if (!next) throw new Error("已取消补齐，表结构和已有条目都没有保存。");
          columns = next;
          changed();
        }
      }
    } },
  });
}
