import { randomUuid } from "../../shared/crypto-compat";
import { readLocalRecord, updateLocalRecord } from "../state/local-journal";
import type { VisibilityChange } from "../summary/compression-coordinator";

export interface MemoryUndoRecord {
  id: string;
  worldbookName: string;
  chatId: string;
  kind: "structured" | "summary";
  namespaceId?: string | undefined;
  label: string;
  createdAt: string;
  changes: Array<{ key: string; before?: TavernWorldbookEntry | undefined; after?: TavernWorldbookEntry | undefined;
    pendingAfter?: TavernWorldbookEntry | null;
    restored?: TavernWorldbookEntry | null }>;
  schemas: unknown[];
  catalogChanges: Array<{ key: string; before: unknown; after: unknown }>;
  visibility: VisibilityChange[];
  completed: boolean;
  restoring?: boolean;
  memoryRestored?: boolean;
}

const MAX_BYTES = 20 * 1024 * 1024;
const journalKey = (worldbookName: string, chatId: string) => `undo:${JSON.stringify([chatId, worldbookName])}`;

export function entryUndoKey(entry: TavernWorldbookEntry): string | undefined {
  const item = entry.extra?.echoes;
  if (item?.kind === "row") return `row:${item.rowId}`;
  if (item?.kind === "summary_slice") return `slice:${item.summaryId}`;
  if (item?.kind === "summary_batch_overview") return `overview:${item.overview.batch.id}`;
  return undefined;
}

export function undoFingerprint(entry?: TavernWorldbookEntry | null): string {
  if (!entry) return "";
  const copy = structuredClone(entry) as Partial<TavernWorldbookEntry>;
  delete copy.uid;
  const item = copy.extra?.echoes;
  if (item?.kind === "summary_slice") {
    item.batch.state = item.batch.state === "stale" ? "stale" : "sync_state";
    delete item.batch.updatedAt;
  }
  return JSON.stringify(copy, (_key, value: unknown) => {
    if (value instanceof RegExp) return { source: value.source, flags: value.flags };
    if (value && typeof value === "object" && !Array.isArray(value))
      return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right)));
    return value;
  });
}

export async function listMemoryUndo(worldbookName: string, chatId: string) {
  return await readLocalRecord<MemoryUndoRecord[]>(journalKey(worldbookName, chatId)) ?? [];
}

function boundedList(records: MemoryUndoRecord[]) {
  const bytes = (value: unknown) => new TextEncoder().encode(JSON.stringify(value)).byteLength;
  if (records.some((record) => bytes(record) > MAX_BYTES)) throw new Error("本次撤销快照超过 20 MiB，请分批操作；本步写入未继续。");
  const retained = records.slice(0, 10);
  while (bytes(retained) > MAX_BYTES) retained.pop();
  return retained;
}

export async function recordMemoryUndo(
  worldbookName: string, kind: MemoryUndoRecord["kind"], label: string,
  before: TavernWorldbookEntry[], after: TavernWorldbookEntry[], visibility: VisibilityChange[] = [],
): Promise<string | undefined> {
  const catalogKind = kind === "structured" ? "catalog" : "summary_catalog";
  const catalogBefore = before.find((entry) => entry.extra?.echoes?.kind === catalogKind)?.extra!.echoes.catalog;
  const catalogAfter = after.find((entry) => entry.extra?.echoes?.kind === catalogKind)?.extra!.echoes.catalog;
  if (!catalogBefore || !catalogAfter) throw new Error("撤销快照缺少所属记忆目录。");
  const matches = (entry: TavernWorldbookEntry) => kind === "structured"
    ? entry.extra?.echoes?.kind === "row"
    : ["summary_slice", "summary_batch_overview"].includes(entry.extra?.echoes?.kind);
  const old = new Map(before.filter(matches).map((entry) => [entryUndoKey(entry)!, entry]));
  const next = new Map(after.filter(matches).map((entry) => [entryUndoKey(entry)!, entry]));
  const changes = [...new Set([...old.keys(), ...next.keys()])]
    .filter((key) => undoFingerprint(old.get(key)) !== undoFingerprint(next.get(key)))
    .map((key) => ({ key, before: old.get(key), after: next.get(key) }));
  if (!changes.length && !visibility.length) return undefined;
  const typeIds = new Set(changes.flatMap((change) => [change.before?.extra?.echoes?.typeId, change.after?.extra?.echoes?.typeId]));
  const record: MemoryUndoRecord = { id: randomUuid(), worldbookName, chatId: catalogBefore.chatId,
    kind, namespaceId: catalogBefore.namespaceId, label, createdAt: new Date().toISOString(), changes,
    schemas: (catalogBefore.types ?? []).filter((type: { id: string }) => typeIds.has(type.id)),
    catalogChanges: ["lastCommittedMessageId", "nextBatchNumber"].filter((key) => catalogBefore[key] !== catalogAfter[key])
      .map((key) => ({ key, before: catalogBefore[key], after: catalogAfter[key] })),
    visibility, completed: false };
  await updateLocalRecord<MemoryUndoRecord[]>(journalKey(worldbookName, record.chatId),
    (records) => boundedList([record, ...records ?? []]));
  return record.id;
}

export async function amendMemoryUndo(worldbookName: string, chatId: string, id: string | undefined,
  update: (record: MemoryUndoRecord) => void) {
  if (!id) return;
  await updateLocalRecord<MemoryUndoRecord[]>(journalKey(worldbookName, chatId), (records) => {
    const record = records?.find((record) => record.id === id);
    if (!record) throw new Error("操作撤销记录已被清理。");
    update(record);
    return boundedList(records!);
  });
}

export async function forgetMemoryUndo(worldbookName: string, chatId: string, id: string) {
  await updateLocalRecord<MemoryUndoRecord[]>(journalKey(worldbookName, chatId),
    (records) => (records ?? []).filter((record) => record.id !== id));
}

export function completeMemoryUndo(worldbookName: string, chatId: string, id: string | undefined,
  entries: TavernWorldbookEntry[], restoring = false) {
  return amendMemoryUndo(worldbookName, chatId, id, (record) => {
    const byKey = new Map(entries.map((entry) => [entryUndoKey(entry), entry]));
    for (const change of record.changes) {
      if (restoring) change.restored = structuredClone(byKey.get(change.key) ?? null);
      else change.after = structuredClone(byKey.get(change.key));
    }
    if (restoring) record.memoryRestored = true;
    else record.completed = true;
  });
}

// Persist the exact undo target before writing, so retrying a partial undo does not bump revisions again.
export function prepareMemoryUndoRestore(record: MemoryUndoRecord, entries: TavernWorldbookEntry[]) {
  return amendMemoryUndo(record.worldbookName, record.chatId, record.id, (saved) => {
    saved.restoring = true;
    const byKey = new Map(entries.map((entry) => [entryUndoKey(entry), entry]));
    for (const change of saved.changes) change.restored = structuredClone(byKey.get(change.key) ?? null);
  });
}

export async function requireMemoryUndo(worldbookName: string, id: string) {
  const chatId = SillyTavern.getContext().chatId ?? "";
  const record = (await listMemoryUndo(worldbookName, chatId)).find((record) => record.id === id);
  if (!record || window.TavernHelper?.getChatWorldbookName("current") !== worldbookName) throw new Error("撤销记录或所属聊天已变化。");
  return record;
}

export function applyMemoryUndo(record: MemoryUndoRecord, entries: TavernWorldbookEntry[]) {
  const catalog = entries.find((entry) => entry.extra?.echoes?.kind === (record.kind === "structured" ? "catalog" : "summary_catalog"))?.extra!.echoes.catalog;
  if (!catalog || catalog.chatId !== record.chatId || catalog.namespaceId !== record.namespaceId) throw new Error("记忆目录已被替换，不能应用旧撤销。");
  for (const schema of record.schemas as Array<{ id: string }>) {
    if (JSON.stringify(catalog.types.find((type: { id: string }) => type.id === schema.id)) !== JSON.stringify(schema))
      throw new Error("相关表结构已变化，撤销已取消；请使用快照对照处理。");
  }
  const current = new Map(entries.map((entry) => [entryUndoKey(entry), entry]));
  for (const change of record.changes) {
    const actual = undoFingerprint(current.get(change.key));
    if (record.restoring && actual === undoFingerprint(change.restored)) continue;
    if (record.memoryRestored) throw new Error("已恢复的记忆又被修改，未再次覆盖；请对照快照处理剩余步骤。");
    if (actual !== undoFingerprint(change.after) && actual !== undoFingerprint(change.before)
      && !(change.pendingAfter !== undefined && actual === undoFingerprint(change.pendingAfter)))
      throw new Error(`「${change.after?.name ?? change.before?.name ?? change.key}」在操作后已变化，未覆盖后续修改。`);
  }
  for (const change of record.catalogChanges) {
    if (catalog[change.key] !== change.after && catalog[change.key] !== change.before)
      throw new Error("检查点或批次编号已被后续操作修改，撤销已取消。");
  }
  let next = structuredClone(entries);
  const now = new Date().toISOString();
  for (const change of record.changes) {
    const actual = current.get(change.key);
    if (record.restoring && undoFingerprint(actual) === undoFingerprint(change.restored)) continue;
    if (undoFingerprint(actual) === undoFingerprint(change.before)) continue;
    const index = next.findIndex((entry) => entryUndoKey(entry) === change.key);
    if (!change.before) { if (index >= 0) next.splice(index, 1); continue; }
    const restored = structuredClone(change.restored ?? change.before);
    if (index >= 0) restored.uid = next[index]!.uid;
    else if (next.some((entry) => entry.uid === restored.uid)) delete (restored as Partial<TavernWorldbookEntry>).uid;
    const item = restored.extra!.echoes;
    if (!record.restoring && item.kind === "row") {
      item.revision = Math.max(item.revision, actual?.extra?.echoes?.revision ?? 0) + 1;
      item.updatedAt = now;
    } else if (!record.restoring && item.kind === "summary_slice") {
      item.batch.revision = Math.max(item.batch.revision, actual?.extra?.echoes?.batch?.revision ?? 0) + 1;
      item.batch.updatedAt = now;
      if (item.batch.state !== "stale") item.batch.state = "pending";
    }
    if (index >= 0) next[index] = restored;
    else next.push(restored);
  }
  const updatedCatalog = next.find((entry) => entry.extra?.echoes?.kind === (record.kind === "structured" ? "catalog" : "summary_catalog"))!.extra!.echoes.catalog;
  for (const change of record.catalogChanges) {
    if (change.before === undefined) delete updatedCatalog[change.key];
    else updatedCatalog[change.key] = change.before;
  }
  updatedCatalog.updatedAt = now;
  if (record.kind === "summary") {
    const restoredIds = new Set(record.changes.flatMap((change) => change.before?.extra?.echoes?.kind === "summary_slice"
      ? [change.before.extra.echoes.summaryId as string] : []));
    const removedIds = new Set(record.changes.flatMap((change) => !change.before && change.after?.extra?.echoes?.kind === "summary_slice"
      ? [change.after.extra.echoes.summaryId as string] : []));
    updatedCatalog.pendingRetrievalDeletes = [...new Set<string>([...updatedCatalog.pendingRetrievalDeletes, ...removedIds])]
      .filter((id) => !restoredIds.has(id));
    if (updatedCatalog.recallPool) for (const field of ["entries", "replay"]) {
      updatedCatalog.recallPool[field] = updatedCatalog.recallPool[field].filter((ref: { namespaceId: string; sliceId: string }) =>
        ref.namespaceId !== record.namespaceId || !removedIds.has(ref.sliceId));
    }
    updatedCatalog.autoRun = false;
  }
  return next;
}
