import type { RecallFlagRule } from "../../../../shared/domain";
import { getSettings } from "../../../state/settings";
import type { SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { h, fill, uid, move } from "../../kit/dom";
import { button, badge, menu } from "../../kit/controls";
import { card, stack } from "../../kit/layout";
import { form, type FieldSpec } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { formModal, confirmAction } from "../../kit/overlays";
import { table, checkbox } from "../../kit/data";
import { toast } from "../../kit/feedback";
import type { PageContext } from "../../shell/context";
import { updateRecall } from "./strategy";

const weightSpecs = (add = 0, multiply = 0): FieldSpec[] => [
  { key: "addWeight", label: "加权重", type: "number", min: -1, max: 1, step: 0.01, value: add, hint: "直接加到分数上" },
  { key: "multiplyWeight", label: "乘权重", type: "number", min: 0, max: 10, step: 0.01, value: multiply, hint: "0 表示不启用" },
];

function sourcesCard(ctx: PageContext, state: SummaryWorldbookState): HTMLElement {
  const own = state.catalog.namespaceId;
  let sources = [
    { chatId: state.catalog.chatId, namespaceId: own, worldbookName: state.worldbookName, enabled: true,
      weight: state.catalog.recallSourceWeight, addWeight: state.catalog.recallSourceAddWeight ?? 0, order: state.catalog.recallSourceOrder },
    ...structuredClone(state.catalog.attachedRecallSources).map((source) => ({ ...source, addWeight: source.addWeight ?? 0 })),
  ].sort((a, b) => a.order - b.order);
  const host = h("div", "ec-stack");
  const bar = h("div", "ec-savebar", h("span", "ec-savebar-text", "来源有未保存的修改"), h("div", "ec-row",
    button("放弃", () => ctx.refresh(), { variant: "ghost", small: true }),
    button("保存", async () => {
      ctx.guard();
      const fresh = await ctx.summary.load();
      sources = sources.map((source, order) => ({ ...source, order }));
      const current = sources.find((source) => source.namespaceId === own)!;
      await ctx.summary.store.saveRecallConfiguration(fresh.worldbookName, {
        enabled: fresh.catalog.recallEnabled, weight: current.weight, addWeight: current.addWeight, order: current.order,
        attachedSources: sources.filter((source) => source.namespaceId !== own),
      });
      dirty(false);
      toast("已保存", "success");
    }, { variant: "primary", small: true, icon: "floppy-disk" })));
  const dirty = (value: boolean) => {
    bar.hidden = !value;
    if (value) host.dataset.dirty = "true";
    else delete host.dataset.dirty;
  };
  const changed = () => { dirty(true); draw(); };
  const draw = () => fill(host, table([
    { label: "来源聊天", cell: (source) => source.namespaceId === own ? h("span", "", source.chatId, " ", badge("当前", "accent")) : source.chatId },
    { label: "加权重", cell: (source) => source.addWeight.toFixed(2) },
    { label: "乘权重", cell: (source) => source.weight.toFixed(2) },
    { label: "启用", cell: (source) => source.namespaceId === own ? "—" : checkbox(`启用 ${source.chatId}`, source.enabled, (value) => { source.enabled = value; changed(); }) },
    { label: "", className: "is-actions", cell: (source, index) => menu(`${source.chatId} 的操作`, [
      { label: "设置权重", icon: "sliders", onSelect: () => formModal("来源权重", form(weightSpecs(source.addWeight, source.weight), { className: "is-single" }), (values) => {
        source.addWeight = values.addWeight; source.weight = values.multiplyWeight; changed();
      }, { size: "small" }) },
      { label: "上移", icon: "arrow-up", disabled: index === 0, onSelect: () => { sources = move(sources, index, -1); changed(); } },
      { label: "下移", icon: "arrow-down", disabled: index === sources.length - 1, onSelect: () => { sources = move(sources, index, 1); changed(); } },
      source.namespaceId !== own && { label: "移除", icon: "trash", danger: true, onSelect: () => { sources.splice(index, 1); changed(); } },
    ]) },
  ], sources));
  dirty(false);
  draw();
  return card("来源聊天", { scope: "chat", description: "可以附加其他聊天的总结一起召回。排序和权重影响结果的先后。", actions: [
    button("附加聊天", async () => {
      const available = (await ctx.summary.store.listAvailableSources()).filter((item) => !sources.some((source) => source.namespaceId === item.catalog.namespaceId));
      if (!available.length) throw new Error("没有可以附加的其他聊天总结。");
      const target = form([{ key: "source", label: "聊天", type: "select", options: available.map((item) => [item.catalog.namespaceId, item.catalog.chatId]) }], { className: "is-single" });
      formModal("附加召回来源", target, (values) => {
        const item = available.find((candidate) => candidate.catalog.namespaceId === values.source)!;
        sources.push({ chatId: item.catalog.chatId, namespaceId: item.catalog.namespaceId, worldbookName: item.worldbookName,
          enabled: true, weight: 0, addWeight: 0, order: sources.length });
        changed();
      }, { size: "small", saveLabel: "附加" });
    }, { small: true, icon: "plus" }),
  ] }, host, bar);
}

export async function recallSourcesPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const flags = getSettings().retrieval.recall.flagRules;
  const editFlag = (flag?: RecallFlagRule) => formModal(flag ? `编辑标志 · ${flag.name}` : "新增标志", form([
    { key: "name", label: "标志名称", value: flag?.name ?? "", required: true },
    ...weightSpecs(flag?.addWeight, flag?.multiplyWeight),
    { key: "retentionTurns", label: "额外滞留回合", type: "number", min: 0, max: 100, value: flag?.retentionTurns ?? 0,
      hint: "被召回后在额外召回池中保留的回合数" },
  ], { className: "is-single" }), async (values) => {
    const next: RecallFlagRule = { id: flag?.id ?? uid("flag"), name: String(values.name).trim(),
      addWeight: values.addWeight, multiplyWeight: values.multiplyWeight, retentionTurns: values.retentionTurns };
    updateRecall((recall) => { recall.flagRules = flag ? recall.flagRules.map((item) => item.id === flag.id ? next : item) : [...recall.flagRules, next]; });
    await ctx.refresh();
  });
  const pool = form([{ key: "maximum", label: "额外召回池最大切片数", type: "number", min: 0, max: 1000,
    value: getSettings().retrieval.recall.retentionMaxSlices, required: true, hint: "0 表示关闭额外召回池" }]);
  const entries = state.catalog.recallPool?.entries ?? [];
  return stack(
    sourcesCard(ctx, state),
    card("人工标志", { scope: "global", description: "在总结切片上设置标志，召回时按标志调整分数或延长滞留。",
      actions: [button("新增标志", () => editFlag(), { small: true, icon: "plus" })] },
    table([
      { label: "标志", cell: (flag) => flag.name },
      { label: "加权重", cell: (flag) => flag.addWeight.toFixed(2) },
      { label: "乘权重", cell: (flag) => flag.multiplyWeight.toFixed(2) },
      { label: "额外滞留", cell: (flag) => `${flag.retentionTurns} 回合` },
      { label: "", className: "is-actions", cell: (flag) => menu(`${flag.name} 的操作`, [
        { label: "编辑", icon: "pen", onSelect: () => editFlag(flag) },
        { label: "删除", icon: "trash", danger: true, onSelect: async () => {
          if (!await confirmAction({ title: `删除标志「${flag.name}」？`, message: "切片上的这个标志会失去作用。", danger: true, confirmLabel: "删除" })) return;
          updateRecall((recall) => { recall.flagRules = recall.flagRules.filter((item) => item.id !== flag.id); });
          await ctx.refresh();
        } },
      ]) },
    ], flags, { empty: "还没有人工标志。" })),
    formCard("额外召回池", pool, async (values) => {
      ctx.guard();
      updateRecall((recall) => { recall.retentionMaxSlices = values.maximum; });
      const fresh = await ctx.summary.load();
      const saved = fresh.catalog.recallPool;
      if (saved) {
        const evicted = new Set<string>();
        while (saved.entries.length > values.maximum) {
          const least = Math.min(...saved.entries.map((item) => item.remaining));
          const [entry] = saved.entries.splice(saved.entries.findIndex((item) => item.remaining === least), 1);
          evicted.add(`${entry!.namespaceId}:${entry!.sliceId}`);
        }
        saved.replay = saved.replay.filter((item) => !evicted.has(`${item.namespaceId}:${item.sliceId}`)).slice(0, values.maximum);
        await ctx.summary.store.saveRecallPool(fresh.worldbookName, saved, ctx.guard);
      }
      await ctx.refresh();
    }, { scope: "global", description: "带滞留回合的切片被召回后会在这里保留几轮，即使后续查询没有命中。",
      after: h("div", "ec-stack", table([
        { label: "切片", cell: (entry) => state.slices.find((slice) => slice.id === entry.sliceId)?.title ?? entry.sliceId },
        { label: "来源", cell: (entry) => entry.namespaceId === state.catalog.namespaceId ? "当前聊天"
          : state.catalog.attachedRecallSources.find((source) => source.namespaceId === entry.namespaceId)?.chatId ?? entry.namespaceId },
        { label: "剩余回合", cell: (entry) => String(entry.remaining) },
      ], entries, { empty: "额外召回池目前是空的。" }), entries.length ? h("div", "ec-row", button("清空召回池", async () => {
        ctx.guard();
        await ctx.summary.store.saveRecallPool(state.worldbookName, { floorKey: "", entries: [], replay: [] }, ctx.guard);
        await ctx.refresh();
      }, { variant: "danger", small: true, icon: "trash" })) : null) }),
  );
}
