import type { MemoryRow } from "../../../../shared/domain";
import { h, fill, preview } from "../../kit/dom";
import { button, badge, selectControl } from "../../kit/controls";
import { callout, empty, lazy } from "../../kit/layout";
import { list, paginate, pager, searchBox, checkbox, keepSearchFocus } from "../../kit/data";
import { drawer } from "../../kit/drawer";
import { confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { stateBadge } from "../shared";
import { memoryStore, newRowModal, displayValue } from "./row-editor";
import { showRow } from "./row-detail";

interface EntriesState { typeId: string; query: string; status: string; page: number; selected: Set<string>; open: string | null }

export async function entriesPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await memoryStore.load();
  const ui = ctx.memo<EntriesState>("structured-entries", () => ({
    typeId: state.catalog.types[0]?.id ?? "", query: "", status: "all", page: 0, selected: new Set(), open: null,
  }));
  if (!state.catalog.types.some((type) => type.id === ui.typeId)) ui.typeId = state.catalog.types[0]?.id ?? "";
  const root = h("div", "ec-stack");
  if (state.issues.length) root.append(callout("warning", lazy(`有 ${state.issues.length} 个世界书条目无法解析`, state.issues)));
  if (!state.catalog.types.length) {
    root.append(empty("当前聊天还没有资料表。", button("前往表与模板", () => ctx.navigate("structured/tables"), { icon: "table-columns" })));
    return root;
  }
  const counts = new Map<string, number>();
  for (const row of state.rows) counts.set(row.typeId, (counts.get(row.typeId) ?? 0) + 1);
  const pane = drawer("条目详情");
  pane.onChange((key) => { ui.open = key; drawList(); });
  const rail = h("nav", "ec-rail");
  rail.setAttribute("aria-label", "资料表");
  const host = h("div", "ec-stack");
  const searchCache = new Map<string, string>();
  const matches = (row: MemoryRow) => {
    if (!ui.query) return true;
    let text = searchCache.get(row.id);
    if (text === undefined) {
      text = [row.dataName, ...(row.aliases ?? []), ...row.keywords, JSON.stringify(row.values)].join("\n").toLocaleLowerCase();
      searchCache.set(row.id, text);
    }
    return text.includes(ui.query.toLocaleLowerCase());
  };
  const drawRail = () => rail.replaceChildren(...state.catalog.types.map((type) => {
    const item = h("button", `ec-rail-item${type.id === ui.typeId ? " is-active" : ""}${type.enabled ? "" : " is-off"}`,
      h("span", "", type.name), h("span", "ec-rail-count", String(counts.get(type.id) ?? 0)));
    item.type = "button";
    if (type.id === ui.typeId) item.setAttribute("aria-current", "true");
    item.title = type.enabled ? type.description : `${type.name}（已停用）`;
    item.addEventListener("click", async () => {
      if (type.id === ui.typeId || !await pane.close()) return;
      ui.typeId = type.id;
      ui.page = 0;
      ui.selected.clear();
      drawRail();
      drawList();
    });
    return item;
  }), button("管理表", () => ctx.navigate("structured/tables"), { variant: "ghost", small: true, icon: "table-columns" }));
  const drawList = () => keepSearchFocus(host, () => {
    const type = state.catalog.types.find((item) => item.id === ui.typeId)!;
    const rows = state.rows.filter((row) => row.typeId === type.id && (ui.status === "all" || row.status === ui.status) && matches(row));
    const live = new Set(state.rows.filter((row) => row.typeId === type.id).map((row) => row.id));
    for (const id of ui.selected) if (!live.has(id)) ui.selected.delete(id);
    const page = paginate(rows, ui);
    const selection = ui.selected.size ? h("div", "ec-selection", h("strong", "", `已选 ${ui.selected.size} 条`),
      button("删除选中", async () => {
        const targets = state.rows.filter((row) => ui.selected.has(row.id));
        if (!await confirmAction({ title: `删除选中的 ${targets.length} 条条目？`, confirmLabel: "删除", danger: true,
          message: "条目会从世界书移除，修改记录仍可在“历史”中查看。" })) return;
        await ctx.run("批量删除结构化条目", () => memoryStore.deleteRows(targets.map((row) => row.id)));
        ui.selected.clear();
        await ctx.refresh();
      }, { variant: "danger", small: true, icon: "trash" }),
      button("取消选择", () => { ui.selected.clear(); drawList(); }, { variant: "ghost", small: true })) : null;
    fill(host,
      h("div", "ec-toolbar",
        h("div", "ec-row", searchBox(ui.query, (value) => { ui.query = value; ui.page = 0; drawList(); }, "搜索名称、别名或内容", ctx.signal),
          selectControl("激活方式", [["all", "全部激活方式"], ["keyword", "关键词"], ["vectorized", "向量"], ["permanent", "常驻"]],
            ui.status, (value) => { ui.status = value; ui.page = 0; drawList(); })),
        h("div", "ec-row ec-toolbar-end",
          rows.length ? button("全选筛选结果", () => { rows.forEach((row) => ui.selected.add(row.id)); drawList(); }, { variant: "ghost", small: true }) : null,
          button("新增条目", () => newRowModal(type, ctx.guard, () => ctx.refresh()), { variant: "primary", icon: "plus" }))),
      h("div", "ec-list-caption", h("strong", "", type.name), badge(`${rows.length} 条`), type.enabled ? null : badge("已停用", "warning")),
      selection,
      list(page.items.map((row) => {
        const first = type.columns.find((column) => displayValue(row.values[column.id]) !== "");
        return {
          key: row.id, selected: ui.open === row.id,
          leading: checkbox(`选择 ${row.dataName}`, ui.selected.has(row.id), (value) => {
            value ? ui.selected.add(row.id) : ui.selected.delete(row.id);
            drawList();
          }),
          title: row.dataName,
          meta: first ? preview(displayValue(row.values[first.id]), 60) : "未填写字段",
          trailing: stateBadge(row.status),
          onOpen: () => showRow(ctx, pane, state.catalog.types, type, row),
        };
      }), ui.query || ui.status !== "all" ? "没有匹配的条目" : "这张表还没有条目"),
      page.pages > 1 ? pager(ui, page.pages, rows.length, drawList) : null,
    );
  });
  pane.list.append(host);
  drawRail();
  drawList();
  root.append(h("div", "ec-rail-layout", rail, pane.node));
  const open = state.rows.find((row) => row.id === ui.open && row.typeId === ui.typeId);
  if (open) await showRow(ctx, pane, state.catalog.types, state.catalog.types.find((type) => type.id === open.typeId)!, open);
  else ui.open = null;
  return root;
}
