import { h, uid, type Child } from "./dom";

export type FieldType = "text" | "textarea" | "code" | "number" | "switch" | "select" | "password" | "json";
export interface FieldSpec {
  key: string;
  label: string;
  type?: FieldType | undefined;
  value?: unknown;
  hint?: string | undefined;
  placeholder?: string | undefined;
  required?: boolean | undefined;
  readonly?: boolean | undefined;
  min?: number | undefined;
  max?: number | undefined;
  step?: number | "any" | undefined;
  rows?: number | undefined;
  wide?: boolean | undefined;
  options?: Array<[string, string]> | undefined;
}

type Control = HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;
export interface Form {
  node: HTMLFormElement;
  control(key: string): Control;
  field(key: string): HTMLElement;
  values(): Record<string, any>;
  dirty(): boolean;
  reset(): void;
  commit(): void;
  show(key: string, visible: boolean): void;
  set(key: string, value: unknown): void;
  onChange(listener: () => void): void;
}

function raw(control: Control): string {
  return control instanceof HTMLInputElement && control.type === "checkbox" ? String(control.checked) : control.value;
}

function write(control: Control, spec: FieldSpec, value: unknown): void {
  if (control instanceof HTMLInputElement && control.type === "checkbox") control.checked = Boolean(value);
  else if (spec.type === "json") control.value = JSON.stringify(value ?? null, null, 2);
  else control.value = value === undefined || value === null ? "" : String(value);
}

/**
 * Builds a form from field specs. Dirty state compares against the last
 * committed values, so undoing an edit by hand also clears it; the form marks
 * itself with data-dirty for the shell's unsaved-change guard.
 */
export function form(specs: FieldSpec[], options: { track?: boolean; className?: string } = {}): Form {
  const node = h("form", `ec-form${options.className ? " " + options.className : ""}`);
  node.noValidate = false;
  node.addEventListener("submit", (event) => event.preventDefault());
  const controls = new Map<string, Control>();
  const wrappers = new Map<string, HTMLElement>();
  const listeners: Array<() => void> = [];
  for (const spec of specs) {
    const type = spec.type ?? "text";
    const control: Control = type === "select" ? h("select", "ec-select")
      : type === "textarea" || type === "code" || type === "json" ? h("textarea", `ec-textarea${type !== "textarea" ? " is-code" : ""}`)
      : h("input", type === "switch" ? "ec-switch" : "ec-input");
    control.id = uid("field");
    control.name = spec.key;
    if (control instanceof HTMLInputElement) {
      control.type = type === "switch" ? "checkbox" : type === "number" ? "number" : type === "password" ? "password" : "text";
      if (type === "switch") control.setAttribute("role", "switch");
      if (type === "number") {
        if (spec.min !== undefined) control.min = String(spec.min);
        if (spec.max !== undefined) control.max = String(spec.max);
        control.step = String(spec.step ?? 1);
      }
      if (spec.placeholder) control.placeholder = spec.placeholder;
    }
    if (control instanceof HTMLTextAreaElement) {
      control.rows = spec.rows ?? (type === "textarea" ? 4 : 10);
      control.spellcheck = false;
      if (spec.placeholder) control.placeholder = spec.placeholder;
    }
    if (control instanceof HTMLSelectElement) for (const [value, label] of spec.options ?? []) control.add(new Option(label, value));
    write(control, spec, spec.value);
    if (spec.readonly) {
      if (control instanceof HTMLSelectElement || type === "switch") control.disabled = true;
      else (control as HTMLInputElement | HTMLTextAreaElement).readOnly = true;
    }
    if (spec.required && type !== "switch") control.required = true;
    const hint: Child = spec.hint ? h("small", "ec-field-hint", spec.hint) : null;
    const label = h("label", "ec-field-label", spec.label, spec.required ? h("span", "ec-required", " *") : null);
    label.htmlFor = control.id;
    const wrapper = type === "switch"
      ? h("div", "ec-field is-switch", h("div", "ec-switch-text", label, hint), control)
      : h("div", `ec-field${spec.wide || ["textarea", "code", "json"].includes(type) ? " is-wide" : ""}`, label, control, hint);
    controls.set(spec.key, control);
    wrappers.set(spec.key, wrapper);
    node.append(wrapper);
  }
  let baseline = new Map([...controls].map(([key, control]) => [key, raw(control)]));
  const dirty = () => [...controls].some(([key, control]) => baseline.get(key) !== raw(control));
  const sync = () => {
    if (options.track !== false && dirty()) node.dataset.dirty = "true";
    else delete node.dataset.dirty;
    for (const listener of listeners) listener();
  };
  node.addEventListener("input", sync);
  node.addEventListener("change", sync);
  const result: Form = {
    node,
    control: (key) => controls.get(key)!,
    field: (key) => wrappers.get(key)!,
    dirty,
    values() {
      if (!node.reportValidity()) throw new Error("请检查标记的字段。");
      const values: Record<string, any> = {};
      for (const spec of specs) {
        const control = controls.get(spec.key)!;
        if (control.disabled && wrappers.get(spec.key)!.hidden) continue;
        const text = raw(control);
        if (spec.type === "switch") values[spec.key] = text === "true";
        else if (spec.type === "number") values[spec.key] = text === "" ? undefined : Number(text);
        else if (spec.type === "json") {
          try { values[spec.key] = JSON.parse(text); }
          catch { throw new Error(`「${spec.label}」不是有效的 JSON。`); }
        } else values[spec.key] = text;
      }
      return values;
    },
    reset() {
      for (const spec of specs) {
        const control = controls.get(spec.key)!;
        const saved = baseline.get(spec.key)!;
        if (control instanceof HTMLInputElement && control.type === "checkbox") control.checked = saved === "true";
        else control.value = saved;
      }
      sync();
      node.dispatchEvent(new Event("ec-reset"));
    },
    commit() {
      baseline = new Map([...controls].map(([key, control]) => [key, raw(control)]));
      sync();
    },
    show(key, visible) {
      const wrapper = wrappers.get(key)!;
      wrapper.hidden = !visible;
      controls.get(key)!.disabled = !visible;
    },
    set(key, value) {
      const spec = specs.find((item) => item.key === key)!;
      write(controls.get(key)!, spec, value);
      sync();
    },
    onChange(listener) {
      listeners.push(listener);
    },
  };
  return result;
}
