import type { MemoryRow, MemoryTypeDefinition } from "../../../../shared/domain";
import { getSettings, importTypeTemplates } from "../../../state/settings";
import {
  parseMemoryTemplates, parseMemoryTables, serializeMemoryTemplates, serializeMemoryTables,
} from "../../../memory/memory-transfer";
import type { WorldbookMemoryState } from "../../../worldbook/worldbook-memory";
import { h, download, readTextFile, errorText } from "../../kit/dom";
import { form } from "../../kit/forms";
import { formModal, modal, confirmAction } from "../../kit/overlays";
import { table, checkbox } from "../../kit/data";
import { callout, muted, empty } from "../../kit/layout";
import { toast } from "../../kit/feedback";
import { IMPORT_POLICIES } from "../shared";
import { memoryStore } from "./row-editor";

export async function importTemplates(done: () => Promise<void>): Promise<void> {
  const text = await readTextFile();
  if (text === null) return;
  const templates = parseMemoryTemplates(text);
  const existing = getSettings().typeTemplates;
  const target = form([{ key: "policy", label: "遇到同 ID 的模板", type: "select", options: IMPORT_POLICIES }], { className: "is-single" });
  formModal("导入模板", target, async (values) => {
    const count = importTypeTemplates(templates, values.policy);
    toast(`已导入 ${count} 个模板。`, "success");
    await done();
  }, { saveLabel: "导入", before: table([
    { label: "模板", cell: (item) => item.name }, { label: "字段", cell: (item) => String(item.columns.length) },
    { label: "冲突", cell: (item) => {
      const current = existing.find((template) => template.id === item.id);
      return current ? current.builtIn ? "与内置模板同 ID" : "同 ID 已存在" : "无";
    } },
  ], templates), after: muted("与内置模板同 ID 时总是创建副本，不受所选策略影响。") });
}

export function exportTables(types: MemoryTypeDefinition[], rows: MemoryRow[], guard: () => void): void {
  const chosen = new Set(types.map((type) => type.id));
  const target = form([{ key: "rows", label: "同时导出条目", type: "switch", value: true }], { className: "is-single" });
  formModal("导出资料表", target, (values) => {
    guard();
    if (!chosen.size) throw new Error("至少选择一张表。");
    download("echoes-memory-tables.json", serializeMemoryTables(types.filter((type) => chosen.has(type.id)), rows, values.rows));
  }, { saveLabel: "导出", before: h("div", "ec-check-list", ...types.map((type) => h("label", "ec-check-row",
    checkbox(type.name, true, (value) => value ? chosen.add(type.id) : chosen.delete(type.id)), h("span", "", type.name)))),
  after: callout("warning", "带条目的文件包含剧情资料，分享前请确认范围。") });
}

export async function importTables(guard: () => void, done: () => Promise<void>): Promise<void> {
  const text = await readTextFile();
  if (text === null) return;
  guard();
  const tables = parseMemoryTables(text);
  const current = await memoryStore.load();
  guard();
  const target = form([{ key: "policy", label: "遇到同 ID 的表", type: "select", options: IMPORT_POLICIES }], { className: "is-single" });
  formModal("导入资料表", target, async (values) => {
    guard();
    if (values.policy === "overwrite" && !await confirmAction({ title: "覆盖同 ID 的表？",
      message: "会替换目标表及其全部条目，建议先导出备份。", irreversible: true, danger: true, confirmLabel: "覆盖" })) return false;
    const result = await memoryStore.importTables(tables, values.policy);
    toast(`导入完成：新增 ${result.added} 条，替换移除 ${result.deleted} 条。`, "success");
    await done();
  }, { saveLabel: "导入", before: table([
    { label: "表", cell: (item) => item.type.name }, { label: "字段", cell: (item) => String(item.type.columns.length) },
    { label: "条目", cell: (item) => String(item.rows?.length ?? 0) },
    { label: "冲突", cell: (item) => current.catalog.types.some((type) => type.id === item.type.id) ? "同 ID 已存在"
      : current.catalog.types.some((type) => type.name.toLocaleLowerCase() === item.type.name.toLocaleLowerCase()) ? "同名，将自动改名" : "无" },
  ], tables), after: muted("策略只处理同 ID 的表；只是同名时会自动改名。选择“创建副本”时所有导入的表都会分配新 ID。") });
}

export function migrateTables(state: WorldbookMemoryState, guard: () => void, done: () => Promise<void>): void {
  const sources = memoryStore.listWorldbooks().filter((name) => name !== state.worldbookName);
  if (!sources.length) throw new Error("没有其他世界书可以迁移。");
  const target = form([
    { key: "source", label: "来源世界书", type: "select", options: sources.map((name) => [name, name]), required: true },
    { key: "policy", label: "遇到同 ID 的表", type: "select", options: IMPORT_POLICIES },
  ], { className: "is-single" });
  const host = h("div", "ec-check-list");
  const chosen = new Set<string>();
  let loaded = "";
  let ticket = 0;
  const load = async () => {
    const sequence = ++ticket;
    const name = target.control("source").value;
    loaded = "";
    chosen.clear();
    host.replaceChildren(muted("正在读取来源世界书…"));
    try {
      const source = await memoryStore.inspect(name);
      if (sequence !== ticket) return;
      loaded = name;
      source.catalog.types.forEach((type) => chosen.add(type.id));
      host.replaceChildren(...(source.catalog.types.length ? source.catalog.types.map((type) => h("label", "ec-check-row",
        checkbox(type.name, true, (value) => value ? chosen.add(type.id) : chosen.delete(type.id)), h("span", "", type.name)))
        : [empty("这本世界书没有资料表。")]));
    } catch (error) {
      if (sequence === ticket) host.replaceChildren(callout("danger", errorText(error)));
    }
  };
  target.control("source").addEventListener("change", () => void load());
  void load();
  formModal("从其他聊天迁移资料表", target, async (values) => {
    guard();
    if (loaded !== values.source) throw new Error("请等待来源世界书读取完成。");
    if (!chosen.size) throw new Error("至少选择一张表。");
    if (values.policy === "overwrite" && !await confirmAction({ title: "覆盖同 ID 的表？",
      message: "会替换目标表已有的条目，建议先导出备份。", irreversible: true, danger: true, confirmLabel: "覆盖" })) return false;
    await memoryStore.migrateFrom(values.source, [...chosen], values.policy);
    await done();
  }, { saveLabel: "迁移", after: host });
}

export function exportTemplates(templates = getSettings().typeTemplates): void {
  download("echoes-memory-templates.json", serializeMemoryTemplates(templates));
}

export function showTemplate(name: string, guide: string): void {
  modal(`记录说明 · ${name}`, h("div", "ec-prose", guide));
}
