import type { StatusProfile, StatusValidationRule } from "../../../../shared/domain";
import { STATUS_VALIDATION_TYPES } from "../../../../shared/domain";
import { statusCoordinator as coordinator } from "../../../status/status-coordinator";
import { renderStatusYaml } from "../../../status/status-request";
import { getSettings, saveSettings, instantiateStatusProfile } from "../../../state/settings";
import { h, uid, nowIso } from "../../kit/dom";
import { button, badge, menu } from "../../kit/controls";
import { card, stack, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { formModal, confirmAction } from "../../kit/overlays";
import { sortable } from "../../kit/sortable";
import { table } from "../../kit/data";
import type { PageContext } from "../../shell/context";
import { promptList } from "../prompt-editor";
import { cleaningList } from "../cleaning-editor";

function editRule(item: StatusValidationRule | undefined, done: (rule: StatusValidationRule) => void): void {
  const target = form([
    { key: "name", label: "名称", value: item?.name ?? "", required: true },
    { key: "path", label: "字段路径", value: item?.path.join(".") ?? "", required: true, hint: "用点分隔，* 表示任意名称，例如 扮演人物状态.*.体力" },
    { key: "type", label: "值类型", type: "select", value: item?.type ?? "string", options: STATUS_VALIDATION_TYPES.map((type) => [type, type]) },
    { key: "required", label: "必须存在", type: "switch", value: item?.required ?? false },
    { key: "enumValues", label: "可选值", value: item?.enumValues ? JSON.stringify(item.enumValues) : "", hint: "JSON 数组，可留空" },
    { key: "minimum", label: "最小值", value: item?.minimum ?? "" },
    { key: "maximum", label: "最大值", value: item?.maximum ?? "" },
    { key: "maxDelta", label: "单次最大变化", value: item?.maxDelta ?? "" },
  ]);
  formModal(item ? `编辑校验规则 · ${item.name}` : "添加校验规则", target, (values) => {
    const rule: StatusValidationRule = { id: item?.id ?? uid("validation"), name: values.name, path: String(values.path).split("."),
      type: values.type, required: values.required };
    for (const key of ["minimum", "maximum", "maxDelta"] as const) {
      if (String(values[key]).trim() === "") continue;
      const value = Number(values[key]);
      if (!Number.isFinite(value)) throw new Error("限制值必须是数字。");
      rule[key] = value;
    }
    if (String(values.enumValues).trim()) rule.enumValues = JSON.parse(values.enumValues);
    done(rule);
  });
}

export async function statusSettingsPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await coordinator.load();
  const profile = state.catalog.profile;
  const saveProfile = async (patch: Partial<StatusProfile>) => {
    ctx.guard();
    const fresh = await coordinator.load();
    await coordinator.worldbook.saveConfiguration(state.worldbookName, { profile: { ...fresh.catalog.profile, ...patch, updatedAt: nowIso() } });
  };
  const basics = form([
    { key: "name", label: "配置名称", value: profile.name, required: true },
    { key: "unknownFields", label: "未声明的字段", type: "select", value: profile.validation.unknownFields,
      options: [["allow", "允许模型新增"], ["reject", "拒绝"]], hint: "是否允许写入校验规则之外的字段" },
    { key: "description", label: "说明", type: "textarea", rows: 2, value: profile.description },
    { key: "initial", label: "初始状态 YAML", type: "code", rows: 14, value: renderStatusYaml(profile.initialState) },
  ]);
  const templates = getSettings().statusTemplates;
  const templateRecord = (name: string) => ({
    name, description: profile.description, initialState: profile.initialState, promptPreset: profile.promptPreset,
    preprocessRules: profile.preprocessRules, validation: profile.validation, injection: profile.injection,
  });
  return stack(
    callout("info", "以下设置只作用于当前聊天。注入位置和模板在“召回与注入 → 注入”中设置。",
      button("前往", () => ctx.navigate("recall/injection"), { variant: "ghost", small: true, icon: "arrow-right" })),
    formCard("基本配置", basics, async (values) => {
      const fresh = await coordinator.load();
      await saveProfile({ name: values.name, description: values.description, initialState: coordinator.parseYaml(values.initial),
        validation: { ...fresh.catalog.profile.validation, unknownFields: values.unknownFields } });
    }, { scope: "chat" }),
    card("校验规则", { scope: "chat", description: "模型给出的状态修改必须符合这些规则，否则整次结果不写入。" },
      sortable<StatusValidationRule>({
        items: profile.validation.rules,
        describe: (rule) => ({ title: rule.name, tag: rule.type, note: rule.path.join(".") }),
        edit: (item, done) => editRule(item, done),
        save: async (rules) => {
          const fresh = await coordinator.load();
          await saveProfile({ validation: { ...fresh.catalog.profile.validation, rules } });
        },
        addLabel: "添加规则", emptyText: "没有校验规则。",
      })),
    card("提示词编排", { scope: "chat" }, promptList("status", profile.promptPreset.items, (items) =>
      saveProfile({ promptPreset: { ...profile.promptPreset, items, updatedAt: nowIso() } }))),
    card("消息清洗", { scope: "chat", description: "发给状态端点前，依次对每条消息执行这些正则规则。" },
      cleaningList(profile.preprocessRules, (rules) => saveProfile({ preprocessRules: rules }))),
    card("状态模板", { scope: "global", description: "模板保存整套状态配置，新聊天或需要重置时可以直接应用。", actions: [
      button("保存当前配置为模板", () => {
        const target = form([{ key: "name", label: "模板名称", value: profile.name, required: true }], { className: "is-single" });
        formModal("保存为状态模板", target, async (values) => {
          const next = getSettings();
          next.statusTemplates.push({ id: uid("status_template"), ...templateRecord(values.name), builtIn: false, version: 1, createdAt: nowIso(), updatedAt: nowIso() });
          saveSettings(next);
          await ctx.refresh();
        }, { size: "small" });
      }, { small: true, icon: "plus" }),
    ] }, table([
      { label: "模板", cell: (template) => h("div", "ec-cell-stack", h("strong", "", template.name),
        template.description ? h("span", "ec-muted", template.description) : null) },
      { label: "来源", cell: (template) => badge(template.builtIn ? "内置" : "自定义", template.builtIn ? "neutral" : "accent") },
      { label: "", className: "is-actions", cell: (template) => h("div", "ec-row",
        button("应用", async () => {
          if (!await confirmAction({ title: `应用模板「${template.name}」？`, message: "会替换当前聊天的整套状态配置，已有的状态快照不变。", confirmLabel: "应用" })) return;
          ctx.guard();
          await coordinator.worldbook.saveConfiguration(state.worldbookName, { profile: instantiateStatusProfile(template) });
          await ctx.refresh();
        }, { small: true }),
        template.builtIn ? null : menu(`${template.name} 的操作`, [
          { label: "用当前配置覆盖", icon: "floppy-disk", onSelect: async () => {
            if (!await confirmAction({ title: `覆盖模板「${template.name}」？`, danger: true, confirmLabel: "覆盖" })) return;
            const next = getSettings();
            next.statusTemplates = next.statusTemplates.map((item) => item.id === template.id
              ? { ...item, ...templateRecord(item.name), description: item.description, version: item.version + 1, updatedAt: nowIso() } : item);
            saveSettings(next);
            await ctx.refresh();
          } },
          { label: "删除", icon: "trash", danger: true, onSelect: async () => {
            if (!await confirmAction({ title: `删除模板「${template.name}」？`, danger: true, confirmLabel: "删除" })) return;
            const next = getSettings();
            next.statusTemplates = next.statusTemplates.filter((item) => item.id !== template.id);
            saveSettings(next);
            await ctx.refresh();
          } },
        ])) },
    ], templates)),
  );
}
