import { recallCoordinator } from "../../../recall-coordinator";
import { redactLog } from "../../logs";
import { h, fill, formatTime, download } from "../../kit/dom";
import { button, badge } from "../../kit/controls";
import { card, stack, empty, lazy } from "../../kit/layout";
import { form } from "../../kit/forms";
import { confirmAction } from "../../kit/overlays";
import { tabStrip } from "../../kit/tabs";
import type { PageContext } from "../../shell/context";
import { traceView } from "./trace";

export function recallDiagnosticsPage(ctx: PageContext): HTMLElement {
  const history = recallCoordinator.history();
  const ui = ctx.memo("recall-diagnostics", () => ({ index: 0, query: "", expected: "", forbidden: "" }));
  ui.index = Math.min(ui.index, Math.max(0, history.length - 1));
  const traceHost = h("div");
  const draw = () => {
    const trace = history[ui.index];
    fill(traceHost, history.length > 1 ? tabStrip("召回记录", history.map((item, index) => ({
      id: String(index), label: `${item.generationType === "preview" ? "预览" : "生成"} · ${formatTime(item.startedAt, false)}`,
    })), String(ui.index), (id) => { ui.index = Number(id); draw(); }, "is-inline") : null,
    trace ? traceView(trace) : empty("本次会话还没有召回记录。"));
  };
  draw();
  const test = form([
    { key: "query", label: "测试查询", type: "textarea", rows: 3, value: ui.query, required: true },
    { key: "expected", label: "应该召回的切片 ID", type: "textarea", rows: 2, value: ui.expected, hint: "每行一个；可在切片详情的“索引检查”中看到 ID" },
    { key: "forbidden", label: "不应注入的切片 ID", type: "textarea", rows: 2, value: ui.forbidden, hint: "每行一个" },
  ], { track: false });
  test.node.addEventListener("input", () => Object.assign(ui, {
    query: test.control("query").value, expected: test.control("expected").value, forbidden: test.control("forbidden").value,
  }));
  const result = h("div", "ec-stack");
  return stack(
    card("最近的召回", { description: "只保留本次页面会话中最近 10 次。", actions: history.length ? [
      button("导出", async () => {
        if (!await confirmAction({ title: "导出召回记录？", message: "文件包含查询和注入正文，可能含有私人剧情。", confirmLabel: "导出" })) return;
        download("echoes-recall-traces.json", JSON.stringify(redactLog({ recall: history }), null, 2));
      }, { variant: "ghost", small: true, icon: "download" }),
      button("清空", async () => { recallCoordinator.clearHistory(); await ctx.refresh(); }, { variant: "ghost", small: true, icon: "trash" }),
    ] : [] }, traceHost),
    card("隔离召回测试", { description: "用指定查询跑一次召回，检查结果是否符合预期。不调用生成模型、不注入、不移动检查点。" }, test.node,
      h("div", "ec-row ec-card-foot", button("运行测试", async () => {
        const values = test.values();
        if (!await confirmAction({ title: "运行召回测试？", message: "可能调用向量与重排序端点。", cost: true, confirmLabel: "运行" })) return;
        const run = await ctx.run("隔离召回测试", () => recallCoordinator.preview([], values.query));
        ctx.guard();
        const ids = new Set([...run.hits.map((hit) => hit.document.sourceId), ...run.recentSlices.map((slice) => slice.id),
          ...(run.retainedSlices ?? []).map((slice) => slice.id)]);
        const parse = (text: string) => [...new Set(text.split(/\s+/).filter(Boolean))];
        const missing = parse(values.expected).filter((id) => !ids.has(id));
        const unexpected = parse(values.forbidden).filter((id) => ids.has(id));
        fill(result, h("div", "ec-row", badge(`漏召回 ${missing.length}`, missing.length ? "warning" : "success"),
          badge(`不应注入 ${unexpected.length}`, unexpected.length ? "danger" : "success")),
        missing.length || unexpected.length ? lazy("差异明细", { missing, unexpected }) : null, traceView(run.trace));
      }, { variant: "primary", icon: "flask" })), result),
  );
}
