import type { GenerationEndpoint } from "../../../../shared/domain";
import { echoesApi as api } from "../../../api/client";
import { getSettings } from "../../../state/settings";
import { h, move } from "../../kit/dom";
import { button, badge, menu, switchControl } from "../../kit/controls";
import { card, stack, empty, kv } from "../../kit/layout";
import { table } from "../../kit/data";
import { modal, confirmAction } from "../../kit/overlays";
import type { PageContext, PageRenderer } from "../../shell/context";
import { attemptsTable } from "../shared";
import { editEndpoint, editGroup, groupsOf, writeGroup, type EndpointKind } from "./endpoint-editor";

const INTRO: Record<EndpointKind, string> = {
  generation: "用于结构化提取、总结、批次总结、状态更新和剧情讨论。组内端点按顺序尝试。",
  embedding: "把总结和查询转成向量。一个向量空间对应一个模型；换模型时建新的空间再迁移。",
  rerank: "召回时对候选再判断一次相关程度，可以不配置。",
};

export function endpointsPage(kind: EndpointKind): PageRenderer {
  return (ctx: PageContext) => {
    const groups = groupsOf(getSettings(), kind);
    const done = () => ctx.refresh();
    const used = (id: string) => {
      const settings = getSettings();
      return kind === "generation" ? Object.values(settings.generationWorkflows).some((item) => item.groupId === id)
        : kind === "embedding" ? settings.summary.embeddingGroupId === id : settings.retrieval.recall.rerankSetId === id;
    };
    const groupCard = (group: (typeof groups)[number]) => {
      const endpoints = [...group.endpoints].sort((a, b) => a.order - b.order);
      const reorder = (index: number, offset: number) => {
        writeGroup(kind, { ...group, endpoints: move(endpoints, index, offset).map((endpoint, order) => ({ ...endpoint, order })) });
        return done();
      };
      return card(group.name, {
        description: kind === "embedding" ? `${group.dimensions} 维 · 空间 ${group.embeddingSpaceId}` : undefined,
        actions: [
          used(group.id) ? badge("使用中", "accent") : null,
          button("添加端点", () => editEndpoint(kind, group, undefined, ctx.job, done), { small: true, icon: "plus" }),
          menu(`${group.name} 的操作`, [
            { label: "编辑组", icon: "pen", onSelect: () => editGroup(kind, group, false, done) },
            kind === "embedding" && { label: "创建新空间副本", icon: "copy", onSelect: () => editGroup(kind, group, true, done) },
            { label: "删除组", icon: "trash", danger: true, onSelect: async () => {
              if (used(group.id)) throw new Error("这个端点组正在被任务使用，请先在“任务分配”中更换。");
              if (!await confirmAction({ title: `删除端点组「${group.name}」？`, danger: true, confirmLabel: "删除" })) return;
              writeGroup(kind, group, true);
              await done();
            } },
          ]),
        ],
      }, endpoints.length ? table([
        { label: "#", cell: (_endpoint, index) => String(index + 1) },
        { label: "端点", cell: (endpoint) => h("div", "ec-cell-stack", h("strong", "", endpoint.name), h("span", "ec-muted", endpoint.baseUrl)) },
        { label: "模型", cell: (endpoint) => endpoint.model },
        { label: "启用", cell: (endpoint) => switchControl(`启用 ${endpoint.name}`, endpoint.enabled, (value) => {
          writeGroup(kind, { ...group, endpoints: endpoints.map((item) => item.id === endpoint.id ? { ...item, enabled: value } : item) });
        }) },
        { label: "", className: "is-actions", cell: (endpoint, index) => h("div", "ec-row",
          button("测试", async () => {
            const result = await ctx.job(`测试 ${endpoint.name}`, () => kind === "generation"
              ? api.testGenerationEndpoint(endpoint as GenerationEndpoint)
              : api.testRetrievalEndpoint({ kind, endpoint, ...(kind === "embedding" && group.requestDimensions ? { requestedDimensions: group.dimensions } : {}) }));
            modal(`测试结果 · ${endpoint.name}`, [
              kv([["结果", badge("成功", "success")], ["耗时", `${result.latencyMs} ms`],
                ...(result.dimensions ? [["实际维度", `${result.dimensions}${group.dimensions && result.dimensions !== group.dimensions ? "（与组设置不一致）" : ""}`] as [string, string]] : [])]),
              attemptsTable(result.attempts)]);
          }, { variant: "ghost", small: true, icon: "flask" }),
          menu(`${endpoint.name} 的操作`, [
            { label: "编辑", icon: "pen", onSelect: () => editEndpoint(kind, group, endpoint, ctx.job, done) },
            { label: "上移", icon: "arrow-up", disabled: index === 0, onSelect: () => reorder(index, -1) },
            { label: "下移", icon: "arrow-down", disabled: index === endpoints.length - 1, onSelect: () => reorder(index, 1) },
            { label: "删除", icon: "trash", danger: true, onSelect: async () => {
              if (!await confirmAction({ title: `删除端点「${endpoint.name}」？`, danger: true, confirmLabel: "删除" })) return;
              writeGroup(kind, { ...group, endpoints: endpoints.filter((item) => item.id !== endpoint.id) });
              await done();
            } },
          ])) },
      ], endpoints) : empty("这个组还没有端点。", button("添加端点", () => editEndpoint(kind, group, undefined, ctx.job, done), { icon: "plus" })));
    };
    return stack(
      h("div", "ec-toolbar", h("p", "ec-muted", INTRO[kind]),
        h("div", "ec-row ec-toolbar-end", button("新增端点组", () => editGroup(kind, undefined, false, done), { variant: "primary", icon: "plus" }))),
      ...(groups.length ? groups.map(groupCard) : [empty("还没有端点组。")]),
    );
  };
}
