import { echoesApi as api } from "../../../api/client";
import { getSettings } from "../../../state/settings";
import { h, fill } from "../../kit/dom";
import { button, badge, menu } from "../../kit/controls";
import { card, stack, lazy, empty } from "../../kit/layout";
import { form } from "../../kit/forms";
import { modal, confirmAction, choose } from "../../kit/overlays";
import { table, checkbox } from "../../kit/data";
import type { PageContext } from "../../shell/context";
import { createCollection, importDocuments, rebuildIndex } from "./retrieval-actions";

export async function retrievalLibraryPage(ctx: PageContext): Promise<HTMLElement> {
  const collections = await api.listRetrievalCollections();
  const settings = getSettings();
  const recall = settings.retrieval.recall;
  const chosen = new Set<string>();
  const query = form([
    { key: "query", label: "查询文本", type: "textarea", rows: 3, required: true },
    { key: "embedding", label: "向量端点组", type: "select", options: [["", "不使用"], ...settings.retrieval.embeddingGroups.map((group): [string, string] => [group.id, group.name])] },
    { key: "rerank", label: "重排序端点组", type: "select", options: [["", "不使用"], ...settings.retrieval.rerankSets.map((set): [string, string] => [set.id, set.name])] },
    { key: "vector", label: "向量检索", type: "switch", value: false },
    { key: "bm25", label: "BM25 检索", type: "switch", value: true },
    { key: "topK", label: "最终结果数", type: "number", min: 1, max: 100, value: recall.finalTopK },
  ], { track: false });
  const results = h("div", "ec-stack");
  const runQuery = async () => {
    const values = query.values();
    if (!chosen.size) throw new Error("至少选择一个集合。");
    if (!values.vector && !values.bm25) throw new Error("至少启用一种检索方式。");
    const embeddingGroup = settings.retrieval.embeddingGroups.find((group) => group.id === values.embedding);
    const rerankSet = settings.retrieval.rerankSets.find((set) => set.id === values.rerank);
    if (values.vector && !embeddingGroup) throw new Error("启用向量检索时需要选择向量端点组。");
    if (values.vector && collections.some((item) => chosen.has(item.collection.id)
      && (item.collection.embeddingSpaceId !== embeddingGroup?.embeddingSpaceId || item.dimensions !== embeddingGroup?.dimensions)))
      throw new Error("所选集合与向量端点组的空间或维度不一致。");
    let result = await ctx.job("检索实验", () => api.queryRetrieval({
      collectionIds: [...chosen], query: values.query, vectorEnabled: values.vector, bm25Enabled: values.bm25, rerankEnabled: Boolean(rerankSet),
      vectorTopK: recall.vectorTopK, bm25TopK: recall.bm25TopK, rerankTopK: recall.rerankTopK, finalTopK: values.topK,
      failoverPolicy: settings.retrieval.failoverPolicy, embeddingGroup, rerankSet,
    }));
    while (result.decisionRequired && result.continuation && await choose({ title: "请求结果不确定", cost: true, cancelValue: false,
      message: `${result.decisionRequired.message}\n继续可能调用其他端点。`,
      choices: [{ value: false, label: "停止" }, { value: true, label: "继续", variant: "primary" }] })) {
      const token = result.continuation.token;
      result = await ctx.job("继续检索", () => api.continueRetrievalQuery({ token, failoverPolicy: settings.retrieval.failoverPolicy, embeddingGroup, rerankSet }));
    }
    if (ctx.signal.aborted) return;
    fill(results, lazy("检索分支与错误", result.branches), result.hits.length ? table([
      { label: "#", cell: (_hit, index) => String(index + 1) },
      { label: "来源", cell: (hit) => hit.document.sourceId },
      { label: "分数", cell: (hit) => (hit.rerankScore ?? hit.rrfScore).toFixed(4) },
      { label: "内容", className: "is-grow", cell: (hit) => lazy(hit.document.text.slice(0, 60), hit) },
    ], result.hits) : empty("没有命中。"));
  };
  return stack(
    card("检索集合", { description: "总结切片和手动导入的文档都存在集合中。索引可以随时从总结重新建立。",
      actions: [button("新建集合", () => createCollection(ctx), { variant: "primary", small: true, icon: "plus" })] },
    table([
      { label: "集合", cell: (item) => h("div", "ec-cell-stack", h("strong", "", item.collection.name), h("span", "ec-muted", item.collection.id)) },
      { label: "文档", cell: (item) => String(item.documents) },
      { label: "就绪", cell: (item) => String(item.ready) },
      { label: "待处理", cell: (item) => String(item.pending) },
      { label: "失败 / 待确认", cell: (item) => h("span", "ec-row", badge(String(item.failed), item.failed ? "danger" : "neutral"),
        badge(String(item.ambiguous), item.ambiguous ? "warning" : "neutral")) },
      { label: "维度", cell: (item) => String(item.dimensions) },
      { label: "", className: "is-actions", cell: (item) => menu(`${item.collection.name} 的操作`, [
        { label: "导入文档", icon: "file-import", onSelect: () => importDocuments(ctx, item) },
        { label: "修复未就绪的向量", icon: "screwdriver-wrench", onSelect: () => rebuildIndex(ctx, item, true) },
        { label: "重建全部向量", icon: "rotate", onSelect: () => rebuildIndex(ctx, item, false) },
        { label: "详情", icon: "circle-info", onSelect: () => modal(item.collection.name, lazy("集合详情", item)) },
        { label: "删除集合", icon: "trash", danger: true, onSelect: async () => {
          if (!await confirmAction({ title: `删除集合「${item.collection.name}」？`, message: "集合中的全部检索文档都会删除；总结原文不受影响。",
            danger: true, confirmLabel: "删除" })) return;
          await ctx.job("删除检索集合", () => api.deleteRetrievalCollection(item.collection.id));
          await ctx.refresh();
        } },
      ]) },
    ], collections, { empty: "还没有检索集合。" })),
    card("检索实验", { description: "直接查询所选集合，不经过召回流程，也不注入。" },
      collections.length ? h("div", "ec-check-list", ...collections.map((item) => h("label", "ec-check-row",
        checkbox(item.collection.name, false, (value) => value ? chosen.add(item.collection.id) : chosen.delete(item.collection.id)),
        h("span", "", `${item.collection.name} · ${item.documents} 篇`)))) : null,
      query.node, h("div", "ec-row ec-card-foot", button("检索", runQuery, { variant: "primary", icon: "magnifying-glass" })), results),
  );
}
