import { sourceMessagesHash } from "../../shared/source-hash";
import type { SummarySlice } from "../../shared/domain";
import { currentChatMessages } from "./summary-request";

export async function summaryOriginalSource(slice: SummarySlice, owner: { worldbookName: string; chatId: string }) {
  const check = () => {
    if (SillyTavern.getContext().chatId !== owner.chatId
      || window.TavernHelper!.getChatWorldbookName("current") !== owner.worldbookName)
      throw new Error("请切换到切片所属聊天查看原文。");
  };
  check();
  if (slice.batch.source?.kind === "imported") throw new Error("导入切片没有当前聊天的原文定位，不能将相同楼层当作证据。");
  const messages = currentChatMessages();
  const selected = messages.filter((message) => slice.batch.messageIds.includes(message.id));
  if (selected.map((message) => message.id).join("\0") !== slice.batch.messageIds.join("\0")
    || await sourceMessagesHash(selected) !== slice.batch.sourceHash) throw new Error("源消息已变化或不存在，无法验证该批次原文。");
  check();
  return { scope: "批次原文，不是该切片的精确证据", messages: selected };
}
