export interface LegacyStructuredCounts {
  rows: number;
  history: number;
}

/**
 * Removes a pre-4.0 structured catalog with its rows and history from the chat worldbook.
 * The caller holds the worldbook write-coordinator lock and has already confirmed the catalog
 * is pre-4.0. Summary, status and other entries are kept.
 */
export async function deleteLegacyStructured(worldbookName: string): Promise<{
  entries: TavernWorldbookEntry[];
  counts: LegacyStructuredCounts;
}> {
  const counts: LegacyStructuredCounts = { rows: 0, history: 0 };
  const entries = await window.TavernHelper!.updateWorldbookWith(worldbookName, (current) => current.filter((entry) => {
    const kind = entry.extra?.echoes?.kind;
    if (kind === "row") counts.rows += 1;
    if (kind === "memory_history") counts.history += 1;
    return kind !== "catalog" && kind !== "row" && kind !== "memory_history";
  }), { render: "debounced" });
  return { entries, counts };
}
