import { getSettings, saveTypeTemplate, deleteTypeTemplate, instantiateType } from "../../../state/settings";
import { DEFAULT_TEMPLATE_GUIDE } from "../../../state/memory-templates";
import { h } from "../../kit/dom";
import { button, badge, menu, switchControl } from "../../kit/controls";
import { card, stack, empty } from "../../kit/layout";
import { table } from "../../kit/data";
import { form } from "../../kit/forms";
import { formModal, confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { stateBadge } from "../shared";
import { memoryStore } from "./row-editor";
import { typeEditor } from "./type-editor";
import { upgradeFromTemplate } from "./type-actions";
import { exportTables, importTables, migrateTables, importTemplates, exportTemplates } from "./transfer";

function nameCell(name: string, description: string) {
  return h("div", "ec-cell-stack", h("strong", "", name), description ? h("span", "ec-muted", description) : null);
}

export async function tablesPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await memoryStore.load();
  const done = () => ctx.refresh();
  const counts = new Map<string, number>();
  for (const row of state.rows) counts.set(row.typeId, (counts.get(row.typeId) ?? 0) + 1);
  const templates = getSettings().typeTemplates;

  const createTable = () => {
    const target = form([
      { key: "template", label: "基于模板", type: "select", options: templates.map((item) => [item.id, item.name]) },
      { key: "name", label: "表名称", required: true },
    ], { className: "is-single" });
    target.control("template").addEventListener("change", () => {
      const template = templates.find((item) => item.id === target.control("template").value);
      if (template && !target.control("name").value) target.set("name", template.name);
    });
    formModal("新建资料表", target, async (values) => {
      ctx.guard();
      const template = templates.find((item) => item.id === values.template)!;
      await memoryStore.saveType(instantiateType(template, values.name));
      await done();
    }, { size: "small", saveLabel: "创建" });
  };

  const chatTables = card("当前聊天的资料表", {
    scope: "chat",
    description: "停用的表不会参与提取和注入，其中的条目保留。",
    actions: [
      button("导入", () => importTables(ctx.guard, done), { small: true, variant: "ghost", icon: "file-import" }),
      button("导出", () => exportTables(state.catalog.types, state.rows, ctx.guard), { small: true, variant: "ghost", icon: "download" }),
      button("从其他聊天迁移", () => migrateTables(state, ctx.guard, done), { small: true, variant: "ghost", icon: "right-left" }),
      button("新建表", createTable, { small: true, variant: "primary", icon: "plus" }),
    ],
  }, state.catalog.types.length ? table([
    { label: "表", cell: (type) => nameCell(type.name, type.description) },
    { label: "字段", cell: (type) => String(type.columns.length) },
    { label: "条目", cell: (type) => String(counts.get(type.id) ?? 0) },
    { label: "新条目激活", cell: (type) => stateBadge(type.defaultStatus) },
    { label: "启用", cell: (type) => switchControl(`启用 ${type.name}`, type.enabled, async (value) => {
      ctx.guard();
      await memoryStore.setTypeEnabled(type.id, value);
    }) },
    { label: "", className: "is-actions", cell: (type) => menu(`${type.name} 的操作`, [
      { label: "编辑表结构", icon: "table-columns", onSelect: () => typeEditor(type, async (value) => {
        ctx.guard();
        await memoryStore.saveType({ ...value, templateId: type.templateId, enabled: type.enabled }, type.id);
        await done();
      }) },
      { label: "从模板更新", icon: "arrows-rotate", onSelect: () => upgradeFromTemplate(type, counts.get(type.id) ?? 0, ctx.guard, done) },
      { label: "删除表及条目", icon: "trash", danger: true, onSelect: async () => {
        if (!await confirmAction({ title: `删除「${type.name}」？`, message: `表中的 ${counts.get(type.id) ?? 0} 条条目会一并删除。`,
          irreversible: true, danger: true, confirmLabel: "删除" })) return;
        ctx.guard();
        await memoryStore.deleteType(type.id);
        await done();
      } },
    ]) },
  ], state.catalog.types) : empty("还没有资料表。", button("新建表", createTable, { icon: "plus" })));

  const templateLibrary = card("模板库", {
    scope: "global",
    description: "模板是建表的起点。修改模板不会改变已经建好的表；需要时在表上选择“从模板更新”。",
    actions: [
      button("导入", () => importTemplates(done), { small: true, variant: "ghost", icon: "file-import" }),
      button("导出全部", () => exportTemplates(), { small: true, variant: "ghost", icon: "download" }),
      button("新建模板", () => typeEditor({ name: "", description: "", guide: DEFAULT_TEMPLATE_GUIDE, defaultStatus: "keyword",
        columns: [{ id: "content", name: "内容", type: "long_text", required: true }] },
      async (value) => { saveTypeTemplate(value); await done(); }, "新建模板"), { small: true, variant: "primary", icon: "plus" }),
    ],
  }, table([
    { label: "模板", cell: (template) => nameCell(template.name, template.description) },
    { label: "字段", cell: (template) => String(template.columns.length) },
    { label: "来源", cell: (template) => badge(template.builtIn ? "内置" : "自定义", template.builtIn ? "neutral" : "accent") },
    { label: "", className: "is-actions", cell: (template) => menu(`${template.name} 的操作`, [
      !template.builtIn && { label: "编辑", icon: "pen", onSelect: () => typeEditor(template, async (value) => {
        saveTypeTemplate({ ...value, id: template.id }, template);
        await done();
      }, "编辑模板") },
      { label: template.builtIn ? "查看并复制为新模板" : "复制为新模板", icon: "copy", onSelect: () =>
        typeEditor({ ...template, name: `${template.name} 副本` }, async (value) => { saveTypeTemplate(value); await done(); }, "复制模板") },
      { label: "导出", icon: "download", onSelect: () => exportTemplates([template]) },
      !template.builtIn && { label: "删除", icon: "trash", danger: true, onSelect: async () => {
        if (!await confirmAction({ title: `删除模板「${template.name}」？`, message: "已经用它建好的表不受影响。", danger: true, confirmLabel: "删除" })) return;
        deleteTypeTemplate(template.id);
        await done();
      } },
    ]) },
  ], templates));

  return stack(chatTables, templateLibrary);
}
