import { messageRangeByFloor, checkpointFloor } from "../../../chat-message-index";
import { inspectSummaryCoverage } from "../../../summary/coverage";
import { WorldbookMemoryStore } from "../../../worldbook/worldbook-memory";
import { h, fill, formatTime } from "../../kit/dom";
import { button, badge, iconButton } from "../../kit/controls";
import { card, stack, stats, callout, lazy, code, muted } from "../../kit/layout";
import { form } from "../../kit/forms";
import { modal, confirmAction } from "../../kit/overlays";
import { table, paginate, pager, checkbox } from "../../kit/data";
import type { PageContext } from "../../shell/context";
import { floorFields, lastFloor } from "../shared";

export async function summaryCoveragePage(ctx: PageContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const range = ctx.memo("summary-coverage-range", () => ({ start: 0, end: lastFloor(), instructions: "" }));
  const target = form([...floorFields(range.start, range.end),
    { key: "instructions", label: "定向补全要求", type: "textarea", rows: 3, value: range.instructions,
      hint: "只用于“生成补全候选”，例如：补充第 40 楼的日常对话细节。" }], { track: false });
  target.node.addEventListener("input", () => Object.assign(range, {
    start: Number(target.control("start").value), end: Number(target.control("end").value), instructions: target.control("instructions").value,
  }));
  const pick = (floor: number) => {
    if (floor < 0) throw new Error("原楼层已不存在，请重新检查。");
    target.set("start", floor);
    target.set("end", floor);
    Object.assign(range, { start: floor, end: floor });
    target.node.scrollIntoView({ block: "nearest" });
  };
  const result = h("div", "ec-stack");
  const localCheck = async () => {
    ctx.guard();
    const values = target.values();
    const { messages } = messageRangeByFloor(values.start, values.end);
    const ids = new Set(messages.map((message) => message.id));
    const latest = await ctx.summary.load();
    const slices = latest.slices.filter((slice) => slice.batch.state !== "stale" && slice.batch.source?.kind !== "imported"
      && slice.batch.messageIds.some((id) => ids.has(id)));
    const entries = await window.TavernHelper!.getWorldbook(state.worldbookName);
    // A chat without structured memory has no names; a damaged catalog must still surface its error.
    const memory = entries.some((entry) => entry.extra?.echoes?.kind === "catalog") ? await new WorldbookMemoryStore().inspect(state.worldbookName) : null;
    ctx.guard();
    const report = inspectSummaryCoverage(messages, slices, memory?.rows.map((row) => row.dataName) ?? []);
    const paging = { page: 0 };
    const regions = h("div");
    const draw = () => {
      const page = paginate(report.regions, paging, 25);
      fill(regions, table([
        { label: "楼层 / 字符", cell: (region) => `${checkpointFloor(region.messageId)} / ${region.start}–${region.end}` },
        { label: "词面匹配", cell: (region) => badge(region.matchedRatio === null ? "无法评估" : `${Math.round(region.matchedRatio * 100)}%`, region.warning ? "warning" : "neutral") },
        { label: "年份线索", cell: (region) => region.years.join(" / ") || "—" },
        { label: "命名条目", cell: (region) => region.names.join(" / ") || "—" },
        { label: "", className: "is-actions", cell: (region) => h("div", "ec-row",
          iconButton("查看原文", "eye", () => {
            const message = messages.find((item) => item.id === region.messageId)!;
            modal("原文区域", [muted("这是按字符切分的区域，不是精确的证据标注。"), code(message.content.slice(region.start, region.end))]);
          }),
          iconButton("用此楼层补全", "arrow-up", () => pick(checkpointFloor(region.messageId)))) },
      ], page.items), page.pages > 1 ? pager(paging, page.pages, report.regions.length, draw, "个区域") : null);
    };
    draw();
    fill(result,
      stats([["输入消息", String(report.inputMessages)], ["输入字符", String(report.inputCharacters)],
        ["对应切片", String(report.outputSlices)], ["低匹配区域", String(report.regions.filter((region) => region.warning).length)]]),
      callout("info", "词面匹配只用于提示可能的遗漏，不能据此断定漏记；来源按批次关联，不是切片的精确证据。"),
      lazy("输出时间分布", report.timestamps), lazy("命名条目覆盖", report.names), regions);
  };

  const review = ctx.summary.coverageReview(state);
  const reviewCard = review ? (() => {
    const paging = { page: 0 };
    const host = h("div");
    const draw = () => {
      const page = paginate(review.findings, paging, 25);
      fill(host, table([
        { label: "楼层 / 字符", cell: (finding) => `${checkpointFloor(finding.messageId)} / ${finding.start}–${finding.end}` },
        { label: "模型建议", cell: (finding) => finding.reason },
        { label: "", className: "is-actions", cell: (finding) => h("div", "ec-row",
          iconButton("查看检查时的输入", "eye", () => modal("检查时的输入", code(finding.text))),
          iconButton("用此楼层补全", "arrow-up", () => pick(checkpointFloor(finding.messageId)))) },
      ], review.findings, { empty: "这次检查没有提出遗漏建议；这不代表已证明完全覆盖。" }), page.pages > 1 ? pager(paging, page.pages, review.findings.length, draw) : null);
    };
    draw();
    return card("模型检查结果", { description: `${formatTime(review.checkedAt)} · 第 ${review.startFloor}–${review.endFloor} 楼。消息或切片变化后需要重新检查。` }, host);
  })() : null;

  const draft = ctx.summary.supplementDraft();
  const candidatesCard = draft ? (() => {
    const existing = draft.state.slices.filter((slice) => slice.batch.state !== "stale");
    const selected = new Set(draft.comparisons.filter((item) => !item.duplicate).map((item) => item.index));
    return card("补全候选审核", { description: "候选只保留在本次会话。提交后作为独立的补全批次写入，不移动检查点。" },
      table([
        { label: "", cell: (_candidate, index) => checkbox(`选择候选 ${index + 1}`, selected.has(index),
          (value) => value ? selected.add(index) : selected.delete(index), draft.comparisons[index]!.duplicate) },
        { label: "时间", cell: (candidate) => candidate.timestamp },
        { label: "标题", cell: (candidate) => candidate.title },
        { label: "对照", cell: (_candidate, index) => {
          const comparison = draft.comparisons[index]!;
          return comparison.duplicate ? badge("与已有切片完全重复", "warning") : comparison.similar.length
            ? button("查看相近切片", () => modal("相近的已有切片", code(JSON.stringify(comparison.similar.map((item) => existing[item.existingIndex]), null, 2))), { variant: "ghost", small: true })
            : badge("没有相近切片");
        } },
        { label: "正文", cell: (candidate) => lazy("展开", candidate.content) },
      ], draft.candidates),
      h("div", "ec-row ec-card-foot",
        button("丢弃候选", async () => {
          if (!await confirmAction({ title: "丢弃这些补全候选？", danger: true, confirmLabel: "丢弃" })) return;
          await ctx.summary.discardSupplement();
          await ctx.refresh();
        }, { variant: "danger", icon: "trash" }),
        button("追加选中的切片", async () => {
          if (!await confirmAction({ title: `追加 ${selected.size} 个候选？`, cost: true, confirmLabel: "追加",
            message: "原有切片保持不变；追加后会单独调用总结端点生成这批的批次总结。" })) return;
          await ctx.run("提交补全切片", () => ctx.summary.commitSupplement([...selected]), () => ctx.summary.stop());
          await ctx.refresh();
        }, { variant: "primary", icon: "floppy-disk" })));
  })() : null;

  return stack(
    card("覆盖检查", { description: "检查所选楼层是否有经历没有写进总结，并针对遗漏生成补全候选。" }, target.node,
      h("div", "ec-row ec-card-foot",
        button("本地检查", localCheck, { icon: "magnifying-glass" }),
        button("模型深度检查", async () => {
          const values = target.values();
          ctx.guard();
          const preview = await ctx.summary.previewManual(values.start, values.end);
          if (!await confirmAction({ title: "进行模型深度检查？", cost: true, confirmLabel: "检查",
            message: `会提交 ${preview.subRequests?.length ?? 1} 个检查请求，只输出可能遗漏的区域，不生成切片、不移动检查点。` })) return;
          await ctx.run("模型覆盖检查", () => ctx.summary.checkCoverage(values.start, values.end), () => ctx.summary.stop());
          await ctx.refresh();
        }, { icon: "robot" }),
        button("预览子请求", async () => {
          const values = target.values();
          ctx.guard();
          modal("总结子请求预览", lazy("楼层范围、清洗结果与子请求", await ctx.summary.previewManual(values.start, values.end)), { size: "large" });
        }, { variant: "ghost", icon: "eye" }),
        button("生成补全候选", async () => {
          const values = target.values();
          ctx.guard();
          const preview = await ctx.summary.previewManual(values.start, values.end);
          if (!await confirmAction({ title: "生成补全候选？", cost: true, confirmLabel: "生成",
            message: `会提交 ${preview.subRequests?.length ?? 1} 个总结子请求。结果只进入下方的待审核区，不修改原切片和检查点。` })) return;
          await ctx.run("定向补全", () => ctx.summary.generateSupplement(values.start, values.end, values.instructions), () => ctx.summary.stop());
          await ctx.refresh();
        }, { variant: "primary", icon: "plus" })),
      result),
    reviewCard, candidatesCard,
  );
}
