import type { DiagnosticCheck, RepairKind } from "../../../../shared/domain";
import { ECHOES_BUILD_INFO } from "../../../../shared/build-info";
import { echoesApi as api } from "../../../api/client";
import { getSettings, saveSettings, storedSettingsFormatVersion } from "../../../state/settings";
import { inspectWorldbookDiagnostics } from "../../../maintenance/diagnostics";
import { statusCoordinator } from "../../../status/status-coordinator";
import { recallCoordinator } from "../../../recall-coordinator";
import { clearCreativePreferences } from "../../../memory/creative-preferences";
import { redactLog } from "../../logs";
import { h, fill, download } from "../../kit/dom";
import { button } from "../../kit/controls";
import { card, stack, callout, lazy, muted } from "../../kit/layout";
import { table, checkbox } from "../../kit/data";
import { modal, confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { stateBadge } from "../shared";

const FRONTEND_REPAIRS = new Set<RepairKind>(["settings_format", "summary_format", "temporary_injections", "retrieval_index"]);

export function diagnosticsPage(ctx: PageContext): HTMLElement {
  const host = h("div", "ec-stack", muted("运行诊断后，这里会列出各项检查的结果。"));
  const selected = new Set<RepairKind>();
  let lastReport: unknown = null;
  const run = async () => {
    const inspected = await inspectWorldbookDiagnostics();
    const helper = window.TavernHelper;
    const settings = getSettings();
    const endpoints = [...settings.generationGroups, ...settings.retrieval.embeddingGroups, ...settings.retrieval.rerankSets].flatMap((group) => group.endpoints);
    const result = await ctx.job("运行系统诊断", () => api.startDiagnostics({
      clientProtocol: ECHOES_BUILD_INFO.apiProtocolVersion, clientVersion: ECHOES_BUILD_INFO.appVersion,
      settingsFormatVersion: storedSettingsFormatVersion(), worldbook: inspected.worldbook,
      tavernHelper: Object.fromEntries(["getWorldbook", "updateWorldbookWith", "getChatMessages", "setChatMessages"]
        .map((key) => [key, typeof (helper as unknown as Record<string, unknown> | undefined)?.[key] === "function"])),
      credentialIds: [...new Set(endpoints.flatMap((endpoint) => endpoint.credentialId ? [endpoint.credentialId] : []))],
    }));
    lastReport = result;
    selected.clear();
    fill(host, ...inspected.errors.map((message) => callout("warning", message)), table<DiagnosticCheck>([
      { label: "", cell: (check) => check.repairKind ? checkbox(`修复 ${check.title}`, false,
        (value) => value ? selected.add(check.repairKind!) : selected.delete(check.repairKind!)) : "" },
      { label: "检查项", cell: (check) => check.title },
      { label: "结果", cell: (check) => stateBadge(check.state) },
      { label: "说明", className: "is-grow", cell: (check) => h("div", "ec-cell-stack", h("span", "", check.message),
        check.details ? lazy("详情", check.details) : null) },
    ], result.checks));
  };
  return stack(
    card("诊断与修复", { description: "检查设置、世界书、索引、临时注入和服务端状态。勾选可修复的项目后执行修复。", actions: [
      button("导出报告", () => {
        if (!lastReport) throw new Error("请先运行诊断。");
        download("echoes-diagnostics.json", JSON.stringify(redactLog(lastReport), null, 2));
      }, { variant: "ghost", small: true, icon: "download" }),
    ] }, h("div", "ec-row",
      button("运行诊断", run, { variant: "primary", icon: "stethoscope" }),
      button("修复所选项目", async () => {
        if (!selected.size) throw new Error("请先运行诊断并勾选要修复的项目。");
        if (!await confirmAction({ title: `修复 ${selected.size} 个项目？`, message: "建议先在“备份与撤销”中导出备份。", confirmLabel: "修复" })) return;
        ctx.guard();
        if (selected.has("settings_format")) saveSettings(getSettings());
        if (selected.has("summary_format")) await ctx.summary.checkIntegrity();
        if (selected.has("retrieval_index")) {
          await ctx.run("修复总结索引", () => ctx.summary.repairIndex(), () => ctx.summary.stop());
          const verified = await inspectWorldbookDiagnostics();
          if (verified.worldbook.summaryIndexMismatches !== 0) {
            await run();
            throw new Error(verified.errors.join("；") || "总结索引仍有不一致的项目，请在任务日志中查看失败原因。");
          }
        }
        if (selected.has("temporary_injections")) {
          await recallCoordinator.clear();
          await statusCoordinator.clearInjection();
          await clearCreativePreferences();
        }
        const backend = [...selected].filter((kind) => !FRONTEND_REPAIRS.has(kind));
        if (backend.length) modal("修复结果", lazy("完整结果", await ctx.job("系统修复", () => api.startRepair({ kinds: backend, confirmed: true }))));
        await run();
      }, { icon: "screwdriver-wrench" })), host),
  );
}
