import { getSettings, saveSettings } from "../../../state/settings";
import { summaryProviderMessages } from "../../../../shared/summary-protocol";
import { DEFAULT_BATCH_OVERVIEW_PROMPT } from "../../../../shared/batch-overview";
import { checkpointFloor } from "../../../chat-message-index";
import { h, nowIso } from "../../kit/dom";
import { button } from "../../kit/controls";
import { card, stack, callout, lazy, code } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { modal, confirmAction } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { promptList } from "../prompt-editor";
import { cleaningList } from "../cleaning-editor";
import { continuityPointer } from "../structured/settings";
import { lastFloor } from "../shared";

export async function summarySettingsPage(ctx: PageContext): Promise<HTMLElement> {
  const settings = getSettings();
  const batching = settings.summary.batching;
  const rules = form([
    { key: "count", label: "自动总结的消息阈值", type: "number", min: 2, max: 500, value: settings.summary.messageCount, required: true,
      hint: "检查点之后积累到这么多条消息时开始一批" },
    { key: "limit", label: "单轮自动总结批次上限", type: "number", min: 0, max: 10000, value: settings.automaticBatchLimit, required: true,
      hint: "一次自动运行最多连续生成的批次数；0 表示不限" },
    { key: "adaptive", label: "按文本量拆分子请求", type: "switch", value: batching.enabled, hint: "一批剧情过长时拆成多个请求" },
    { key: "characters", label: "单个子请求的正文字符预算", type: "number", min: 2000, max: 200000, value: batching.maxCharacters, required: true },
    { key: "overlap", label: "相邻子请求的重叠字符", type: "number", min: 0, max: 10000, value: batching.overlapCharacters, required: true },
    { key: "parts", label: "每批最多子请求数", type: "number", min: 1, max: 100, value: batching.maxSubBatches, required: true },
  ]);
  const overview = form([{ key: "prompt", label: "批次总结提示词", type: "code", rows: 14, value: settings.summary.batchOverviewPrompt, required: true,
    hint: "“时间范围 / 主要事件”的格式要求由程序附在最后，不需要写在这里" }], { className: "is-single" });
  const embedding = settings.retrieval.embeddingGroups.find((group) => group.id === settings.summary.embeddingGroupId);

  const preview = () => button("预览请求", async () => {
    if (!ctx.chatId) throw new Error("需要先打开一个聊天。");
    const state = await ctx.summary.load();
    const start = Math.min(checkpointFloor(state.catalog.lastCommittedMessageId) + 1, lastFloor());
    const request = await ctx.summary.previewManual(start, lastFloor());
    const messages = summaryProviderMessages({ promptMessages: request.promptMessages, extractAttributes: getSettings().continuity.extractAttributes });
    modal("总结请求预览（检查点之后的全部消息）", messages.map((message, index) =>
      lazy(`${index + 1} · ${message.role} · ${message.content.length} 字`, () => code(message.content))), { size: "large" });
  }, { small: true, variant: "ghost", icon: "eye" });

  return stack(
    formCard("生成规则", rules, (values) => {
      const next = getSettings();
      next.summary.messageCount = values.count;
      next.automaticBatchLimit = values.limit;
      next.summary.batching = { enabled: values.adaptive, maxCharacters: values.characters, overlapCharacters: values.overlap, maxSubBatches: values.parts };
      saveSettings(next);
    }, { scope: "global" }),
    card("提示词编排", { scope: "global", description: "总结请求的消息顺序。输出格式由程序附在最后。" },
      promptList("summary", settings.summary.promptPreset.items, (items) => {
        const next = getSettings();
        next.summary.promptPreset = { ...next.summary.promptPreset, items, updatedAt: nowIso() };
        saveSettings(next);
      }, () => [preview()])),
    formCard("批次总结", overview, (values) => {
      const next = getSettings();
      next.summary.batchOverviewPrompt = values.prompt;
      saveSettings(next);
    }, { scope: "global", actions: [button("恢复默认", async () => {
      if (!await confirmAction({ title: "把批次总结提示词恢复为默认？", message: "恢复后仍需点击保存才会生效。", confirmLabel: "恢复" })) return;
      overview.set("prompt", DEFAULT_BATCH_OVERVIEW_PROMPT);
    }, { variant: "ghost", small: true, icon: "rotate-left" })] }),
    card("消息清洗", { scope: "global", description: "发给总结端点前，依次对每条消息执行这些正则规则。" },
      cleaningList(settings.summary.preprocessRules, (items) => {
        const next = getSettings();
        next.summary.preprocessRules = items;
        saveSettings(next);
      })),
    h("div", "ec-stack",
      callout("info", `向量化端点组：${embedding?.name ?? "未设置"}（单次 ${settings.summary.embeddingBatchSize} 个切片）。`,
        button("去设置", () => ctx.navigate("api/assignment"), { variant: "ghost", small: true, icon: "arrow-right" })),
      continuityPointer(ctx)),
  );
}
