import type { InjectionBudgetConfig, InjectionBudgetReport, InjectionCategory } from "../shared/domain";

export interface InjectionItem {
  id: string;
  title: string;
  category: InjectionCategory;
  text: string;
  repetitions?: number;
}

export function estimateInjectionTokens(text: string): number {
  return Math.ceil(new TextEncoder().encode(text).length / 3);
}

export function planInjectionBudget(items: InjectionItem[], overhead: string, config?: InjectionBudgetConfig) {
  const limit = config?.maxTokens ?? 0;
  const policy = config?.overflow ?? "preserve_protected";
  const tokens = (item: InjectionItem) => estimateInjectionTokens(item.text + "\n\n") * (item.repetitions ?? 1);
  const base = estimateInjectionTokens(overhead);
  const requestedTokens = base + items.reduce((sum, item) => sum + tokens(item), 0);
  const selected = new Set<string>();
  const order: InjectionCategory[] = ["status", "batch_overview", "retained", "recent", "semantic"];
  let used = base;
  let blocked = limit > 0 && policy === "abort" && requestedTokens > limit;
  if (!blocked) for (const category of order) {
    for (const item of items.filter((item) => item.category === category)) {
      const next = used + tokens(item);
      const protectedItem = category === "status" || category === "batch_overview"
        || policy === "preserve_protected" && (category === "retained" || category === "recent");
      if (!limit || protectedItem || next <= limit) {
        selected.add(item.id);
        used = next;
      }
    }
  }
  if (limit > 0 && policy === "strict" && used > limit) blocked = true;
  if (blocked) { selected.clear(); used = 0; }
  const report: InjectionBudgetReport = {
    limit, estimated: true, requestedTokens, injectedTokens: used,
    overflow: limit > 0 && used > limit, blocked,
    categories: order.map((category) => ({
      category,
      requestedTokens: items.filter((item) => item.category === category).reduce((sum, item) => sum + tokens(item), 0),
      injectedTokens: items.filter((item) => item.category === category && selected.has(item.id)).reduce((sum, item) => sum + tokens(item), 0),
    })),
    omitted: items.filter((item) => !selected.has(item.id)).map(({ id, title, category }) => ({
      id, title, category, reason: blocked ? "预算不足，中止本轮生成" : "本轮注入预算不足，保留完整存储正文",
    })),
  };
  return { selected, report };
}
