export type ConsoleLevel = "log" | "info" | "warn" | "error" | "debug";
export interface ConsoleRecord {
  id: number;
  time: string;
  level: ConsoleLevel;
  text: string;
}
const records: ConsoleRecord[] = [];
const listeners = new Set<() => void>();
let installed = false;
let sequence = 0;
const secretKey =
  /^(api[-_]?key|secret|password|authorization|access[-_]?token|refresh[-_]?token)$/i;
export function redactLog(
  value: unknown,
  depth = 0,
  seen = new WeakSet<object>(),
): unknown {
  if (depth > 8) return "[depth limit]";
  if (typeof value === "string")
    return value
      .replace(/\bBearer\s+\S+/gi, "Bearer [redacted]")
      .replace(/\bsk-[\w-]{8,}/g, "[redacted]")
      .replace(/([?&](?:api_key|key|token|secret)=)[^&\s]+/gi, "$1[redacted]")
      .replace(
        /((?:api[_-]?key|secret|password|authorization)\s*[:=]\s*)[^\s,;]+/gi,
        "$1[redacted]",
      )
      .slice(0, 16000);
  if (!value || typeof value !== "object") return value;
  if (seen.has(value)) return "[circular]";
  seen.add(value);
  if (value instanceof Error)
    return {
      name: value.name,
      message: redactLog(value.message),
      stack: redactLog(value.stack),
    };
  if (Array.isArray(value))
    return value.slice(0, 100).map((v) => redactLog(v, depth + 1, seen));
  return Object.fromEntries(
    Object.entries(value)
      .slice(0, 100)
      .map(([key, v]) => [
        key,
        secretKey.test(key) ? "[redacted]" : redactLog(v, depth + 1, seen),
      ]),
  );
}
export function consoleRecords(): ConsoleRecord[] {
  return records.slice();
}
export function clearConsoleRecords() {
  records.length = 0;
  listeners.forEach((fn) => fn());
}
export function subscribeConsole(fn: () => void) {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
}
export function installConsoleLogRecorder() {
  if (installed) return;
  installed = true;
  for (const level of ["log", "info", "warn", "error", "debug"] as const) {
    const original = console[level].bind(console);
    console[level] = (...args: unknown[]) => {
      original(...args);
      if (!args.some((v) => typeof v === "string" && /echoes/i.test(v))) return;
      try {
        const text = args
          .map((v) => {
            const safe = redactLog(v);
            return typeof safe === "string" ? safe : JSON.stringify(safe);
          })
          .join(" ")
          .slice(0, 24000);
        records.push({
          id: ++sequence,
          time: new Date().toISOString(),
          level,
          text,
        });
        if (records.length > 500) records.splice(0, records.length - 500);
        for (const listener of listeners)
          try {
            listener();
          } catch {}
      } catch {}
    };
  }
}
