import { DEFAULT_DISCUSSION_SYSTEM_PROMPT } from "../../../../shared/discussion";
import { getSettings } from "../../../state/settings";
import { h } from "../../kit/dom";
import { button, menu } from "../../kit/controls";
import { card, stack } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { confirmAction } from "../../kit/overlays";
import { table } from "../../kit/data";
import type { PageContext } from "../../shell/context";
import { editPreset, saveDiscussion } from "./chat";

export function discussionPresetsPage(ctx: PageContext): HTMLElement {
  const discussion = getSettings().discussion;
  const system = form([{ key: "systemPrompt", label: "系统提示词", type: "code", rows: 16, value: discussion.systemPrompt, required: true,
    hint: "附在完整的聊天上下文之后，让主模型暂停扮演、进入讨论" }], { className: "is-single" });
  return stack(
    card("用户提示词预设", { scope: "global", actions: [button("新增预设", () => editPreset(undefined, "", () => ctx.refresh()), { small: true, icon: "plus" })] },
      table([
        { label: "名称", cell: (preset) => h("strong", "", preset.name) },
        { label: "字数", cell: (preset) => String(preset.content.length) },
        { label: "", className: "is-actions", cell: (preset) => menu(`${preset.name} 的操作`, [
          { label: "修改", icon: "pen", onSelect: () => editPreset(preset.id, preset.content, () => ctx.refresh()) },
          { label: "删除", icon: "trash", danger: true, onSelect: async () => {
            if (!await confirmAction({ title: `删除预设「${preset.name}」？`, danger: true, confirmLabel: "删除" })) return;
            saveDiscussion((settings) => { settings.presets = settings.presets.filter((item) => item.id !== preset.id); });
            await ctx.refresh();
          } },
        ]) },
      ], discussion.presets, { empty: "还没有讨论预设。" })),
    formCard("系统提示词", system, (values) => saveDiscussion((settings) => { settings.systemPrompt = values.systemPrompt; }), {
      scope: "global", actions: [button("恢复默认", async () => {
        if (!await confirmAction({ title: "恢复默认系统提示词？", message: "恢复后仍需点击保存才会生效。", confirmLabel: "恢复" })) return;
        system.set("systemPrompt", DEFAULT_DISCUSSION_SYSTEM_PROMPT);
      }, { variant: "ghost", small: true, icon: "rotate-left" })],
    }),
  );
}
