import type { MemoryRow, MemoryTypeDefinition } from "../../../../shared/domain";
import { extractionCoordinator as extraction, type PendingExtractionReview } from "../../../memory/extraction-coordinator";
import { h } from "../../kit/dom";
import { button, badge } from "../../kit/controls";
import { card, callout, code, kv } from "../../kit/layout";
import { table, checkbox } from "../../kit/data";
import { modal, confirmAction } from "../../kit/overlays";
import { toast } from "../../kit/feedback";
import type { PageContext } from "../../shell/context";
import { displayValue } from "./row-editor";

const ACTION = { add: ["新增", "success"], update: ["更新", "accent"], delete: ["删除", "danger"] } as const;

function operationDetail(operation: any, types: MemoryTypeDefinition[], previous?: MemoryRow): HTMLElement {
  const type = types.find((item) => item.id === operation?.typeId);
  const values = operation?.action === "add" ? operation.values : operation?.changes?.values;
  const column = (id: string) => type?.columns.find((item) => item.id === id)?.name ?? id;
  return h("div", "ec-stack",
    kv([["表", type?.name ?? String(operation?.typeId ?? "—")], ["条目", String(operation?.dataName ?? previous?.dataName ?? operation?.rowId ?? "—")]]),
    ...Object.entries((values ?? {}) as Record<string, unknown>).map(([id, value]) => h("div", "ec-compare",
      h("div", "", h("h4", "", `${column(id)} · 修改前`), h("div", "ec-prose", previous ? displayValue(previous.values[id]) || "（空）" : "（新建）")),
      h("div", "", h("h4", "", `${column(id)} · 提议`), h("div", "ec-prose", displayValue(value) || "（空）")))),
    h("details", "ec-disclosure", h("summary", "", "完整操作 JSON"), code(JSON.stringify(operation, null, 2))));
}

/** The pending-review card shared by normal extraction and data cleaning. */
export function reviewCard(ctx: PageContext, review: PendingExtractionReview, types: MemoryTypeDefinition[], rows: MemoryRow[]): HTMLElement {
  const items = review.result.reviewItems;
  const selected = new Set(review.selectedIndexes.filter((index) => items.some((item) => item.index === index && item.state === "valid")));
  const valid = items.filter((item) => item.state === "valid").length;
  const count = h("span", "ec-muted");
  const updateCount = () => { count.textContent = `已选 ${selected.size} / ${valid} 条有效操作`; };
  updateCount();
  const cleaning = review.prepared.batch.mode === "cleaning";
  const setAll = (value: boolean) => {
    selected.clear();
    if (value) for (const item of items) if (item.state === "valid") selected.add(item.index);
    for (const input of body.querySelectorAll<HTMLInputElement>("input.ec-check:not(:disabled)")) input.checked = value;
    updateCount();
  };
  const body = card(cleaning ? "资料清洗结果待审核" : "待审核的操作", {
    description: cleaning ? "清洗结果只有在你提交后才会写入，不影响普通提取的检查点。" : "只有勾选的有效操作会写入；未勾选和无效的操作会被跳过。",
    actions: [badge(`${items.length} 条`, "warning")],
  },
  table([
    { label: "", cell: (item) => checkbox(`选择操作 ${item.index + 1}`, selected.has(item.index),
      (value) => { value ? selected.add(item.index) : selected.delete(item.index); updateCount(); }, item.state !== "valid") },
    { label: "#", cell: (item) => String(item.index + 1) },
    { label: "操作", cell: (item) => {
      const action = (item.operation as any)?.action as keyof typeof ACTION | undefined;
      return item.state === "valid" && action ? badge(ACTION[action][0], ACTION[action][1]) : badge("无效", "danger");
    } },
    { label: "对象 / 原因", cell: (item) => {
      const operation = item.operation as any;
      const previous = operation?.rowId ? rows.find((row) => row.id === operation.rowId) : undefined;
      return item.state === "valid" ? String(operation?.dataName ?? previous?.dataName ?? operation?.rowId ?? "") : item.reason ?? "";
    } },
    { label: "", cell: (item) => button("查看", () => {
      const operation = item.operation as any;
      const previous = operation?.rowId ? rows.find((row) => row.id === operation.rowId) : undefined;
      modal(`操作 ${item.index + 1}`, [item.reason ? callout("danger", item.reason) : null, operationDetail(operation, types, previous)], { size: "large" });
    }, { variant: "ghost", small: true }) },
  ], items),
  h("div", "ec-row ec-card-foot", count,
    button("全选", () => setAll(true), { variant: "ghost", small: true }),
    button("全不选", () => setAll(false), { variant: "ghost", small: true }),
    button("重新请求", async () => {
      if (!await confirmAction({ title: "放弃这批结果并重新请求？", message: "会再次调用提取端点。", cost: true, confirmLabel: "重新请求" })) return;
      await ctx.run("重试结构化提取", () => extraction.retryCurrent(), () => extraction.stopCurrent());
      await ctx.refresh();
    }, { small: true, icon: "rotate" }),
    button("提交选中操作", async () => {
      ctx.guard();
      const summary = await extraction.submitReview([...selected]);
      toast(`已写入：新增 ${summary.added}、更新 ${summary.updated}、删除 ${summary.deleted}。`, "success");
      await ctx.refresh();
    }, { variant: "primary", icon: "check" })));
  return body;
}
