import { extractionCoordinator } from "../../memory/extraction-coordinator";
import { statusCoordinator } from "../../status/status-coordinator";
import type { SummaryCoordinator } from "../../summary/summary-coordinator";
import { getSettings } from "../../state/settings";

export interface AttentionItem {
  route: string;
  tone: "warning" | "danger";
  text: string;
  action: string;
}

/**
 * Cheap, synchronous checks for things the user must act on. Asynchronous
 * checks (stored recovery drafts) are added by the overview page itself.
 */
export function attentionItems(summary: SummaryCoordinator): AttentionItem[] {
  const chatId = SillyTavern.getContext().chatId ?? "";
  const items: AttentionItem[] = [];
  if (chatId) {
    const review = extractionCoordinator.review(chatId);
    if (review) {
      const valid = review.result.reviewItems.filter((item) => item.state === "valid").length;
      items.push({ route: "structured/extraction", tone: "warning", text: `结构化提取有 ${valid} 条操作待审核`, action: "去审核" });
    }
    const trace = extractionCoordinator.trace(chatId);
    if (!review && (trace?.state === "failed" || trace?.state === "blocked"))
      items.push({ route: "structured/extraction", tone: "danger", text: `最近一次结构化提取未完成：${trace.message ?? trace.state}`, action: "查看" });
    if (summary.supplementDraft())
      items.push({ route: "summary/coverage", tone: "warning", text: "总结补全有待审核的候选", action: "去审核" });
    for (const draft of summary.rebuildDrafts())
      items.push({ route: "summary/generation", tone: "warning", text: `总结批次 ${draft.batch.batchNumber} 有未写入的重建候选`, action: "去确认" });
    const status = statusCoordinator.trace;
    if (status?.chatId === chatId && (status.outcome === "failed" || status.outcome === "decision_required"))
      items.push({ route: "status/current", tone: "danger", text: `状态同步未完成：${status.message ?? status.outcome}`, action: "查看" });
  }
  const workflows = getSettings().generationWorkflows;
  const missing = (["extraction", "summary", "status"] as const).filter((key) => !workflows[key].groupId);
  if (missing.length) {
    const names = { extraction: "结构化提取", summary: "总结生成", status: "状态更新" };
    items.push({ route: "api/assignment", tone: "warning", text: `${missing.map((key) => names[key]).join("、")}尚未分配生成端点组`, action: "去分配" });
  }
  return items;
}

/** Routes (module or module/tab) that currently carry a marker. */
export function markedRoutes(items: AttentionItem[]): Set<string> {
  const marked = new Set<string>();
  for (const item of items) {
    marked.add(item.route);
    marked.add(item.route.split("/")[0]!);
  }
  return marked;
}
