import type {
  RetrievalHit,
  RetrievalQueryPreset,
  RetrievalQueryPresetItem,
  RetrievalSourceIssue,
  SummarySlice,
} from "../shared/domain";
import {
  summaryRetrievalContentHash,
  summaryRetrievalText,
} from "./summary/retrieval-document";
import { sha256Hex } from "../shared/crypto-compat";

export interface RecallQueryInput {
  state?: Record<string, unknown> | undefined;
  chat: Array<Record<string, unknown>>;
  preset: RetrievalQueryPreset;
  characterName: string;
  characterDescription: string;
  userName: string;
  personaDescription: string;
}

export interface PreparedRecallQuery {
  queries: Array<{ id: string; text: string }>;
  query: string;
  messageIds: string[];
  blocks: Array<{ id: string; title: string; content: string }>;
}

interface RecallMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
}

function messages(chat: Array<Record<string, unknown>>): RecallMessage[] {
  const seen = new Set<string>();
  return chat.flatMap((message, index): RecallMessage[] => {
    const content = String(message.mes ?? message.message ?? message.content ?? "").trim();
    if (!content) return [];
    const rawId = String(message.message_id ?? message.id ?? index);
    const id = seen.has(rawId) ? `${rawId}:${index}` : rawId;
    seen.add(id);
    return [{
      id,
      role: message.is_user === true || message.role === "user" ? "user" : "assistant",
      content,
    }];
  });
}

function macro(value: string, characterName: string, userName: string): string {
  return value
    .replaceAll("{{char}}", characterName)
    .replaceAll("{{user}}", userName);
}

function itemContent(
  item: RetrievalQueryPresetItem,
  chatMessages: RecallMessage[],
  input: RecallQueryInput,
): { content: string; messageIds: string[] } {
  const current = chatMessages.at(-1);
  if (item.kind === "current_message") {
    return current
      ? { content: `${current.role}: ${current.content}`, messageIds: [current.id] }
      : { content: "", messageIds: [] };
  }
  if (item.kind === "recent_messages") {
    const count = Math.max(0, item.count);
    const selected = chatMessages.slice(Math.max(0, chatMessages.length - count - 1), -1);
    return {
      content: selected.map((message) => `${message.role}: ${message.content}`).join("\n"),
      messageIds: selected.map((message) => message.id),
    };
  }
  if (item.kind === "character") {
    return {
      content: input.characterDescription.trim()
        ? `${input.characterName}:\n${input.characterDescription.trim()}`
        : "",
      messageIds: [],
    };
  }
  if (item.kind === "persona") {
    return {
      content: input.personaDescription.trim()
        ? `${input.userName}:\n${input.personaDescription.trim()}`
        : "",
      messageIds: [],
    };
  }
  if (item.kind === "custom") {
    return {
      content: macro(item.content, input.characterName, input.userName).trim(),
      messageIds: [],
    };
  }
  if (["scene", "participants", "commitments"].includes(item.kind)) {
    const scene = input.state?.["时空状态"] as Record<string, unknown> | undefined;
    const value = item.kind === "commitments" ? input.state?.["计划与承诺"]
      : item.kind === "participants" ? scene?.["在场角色"] : scene;
    return { content: value ? typeof value === "string" ? value : JSON.stringify(value) : "", messageIds: [] };
  }
  return { content: "", messageIds: [] };
}

export function prepareRecallQuery(input: RecallQueryInput): PreparedRecallQuery {
  const chatMessages = messages(input.chat);
  const blocks = input.preset.items.flatMap((item) => {
    if (!item.enabled) return [];
    const prepared = itemContent(item, chatMessages, input);
    return prepared.content
      ? [{ id: item.id, title: item.title, ...prepared, sourceLength: prepared.content.length }]
      : [];
  });
  const maximum = input.preset.maxCharacters ?? 12000;
  const selected = blocks.slice(0, input.preset.mode === "multi" ? input.preset.maxQueries ?? 4 : blocks.length);
  const perBlock = Math.max(1, Math.floor((maximum - Math.max(0, selected.length - 1) * 2) / Math.max(1, selected.length)));
  const bounded = selected.map((block) => ({
    ...block, content: balancedQueryText(block.content, perBlock),
  }));
  const query = bounded.map((block) => block.content).join("\n\n").trim();
  return {
    queries: input.preset.mode === "multi"
      ? bounded.map((block) => ({ id: block.id, text: block.content }))
      : query ? [{ id: "combined", text: query }] : [],
    query,
    // A clipped block cannot stand in for all memories from its source messages.
    messageIds: [...new Set(selected.filter((block) => block.sourceLength <= perBlock)
      .flatMap((block) => block.messageIds))],
    blocks: bounded.map(({ id, title, content }) => ({ id, title, content })),
  };
}

export function balancedQueryText(text: string, maximum: number): string {
  if (text.length <= maximum) return text;
  if (maximum < 8) return text.slice(-maximum);
  const half = Math.floor((maximum - 5) / 2);
  return text.slice(0, half) + "\n...\n" + text.slice(-(maximum - half - 5));
}


export async function authoritativeRecallHits(
  hits: RetrievalHit[],
  sources: Array<{ collectionId: string; slices: SummarySlice[]; worldbookName?: string; chatId?: string }>,
): Promise<{
  hits: RetrievalHit[];
  dropped: string[];
  issues: RetrievalSourceIssue[];
  sliceByDocumentId: Map<string, SummarySlice>;
}> {
  const sourceByCollection = new Map(sources.map((source) => [source.collectionId, source]));
  const sliceByDocumentId = new Map<string, SummarySlice>();
  const issues: RetrievalSourceIssue[] = [];
  const validated = await Promise.all(hits.map(async (hit) => {
    const source = sourceByCollection.get(hit.document.collectionId);
    const slice = source?.slices.find((candidate) => candidate.id === hit.document.sourceId);
    const reject = (code: RetrievalSourceIssue["code"], reason: string, action: string,
      hashes: Pick<RetrievalSourceIssue, "expectedHash" | "indexedHash"> = {}) => {
      issues.push({
        documentId: hit.document.documentId, collectionId: hit.document.collectionId, sliceId: hit.document.sourceId,
        worldbookName: source?.worldbookName, chatId: source?.chatId,
        batchNumber: slice?.batch.batchNumber, sliceNumber: slice?.sliceNumber, title: slice?.title,
        code, reason, action, ...hashes,
      });
      return null;
    };
    if (!source) return reject("source_unavailable", "索引对应的来源未加载", "检查召回来源绑定");
    if (hit.document.sourceType !== "chat_summary") return reject("source_type", "索引不是总结切片", "检查来源集合绑定");
    if (!slice) return reject("slice_missing", "世界书中已不存在该切片，索引仍有残留", "在来源聊天修复总结索引");
    if (slice.batch.state === "stale") return reject("slice_stale", "原消息已变化，该切片已失效", "重新总结该批次");
    if (slice.continuity?.validity === "superseded") return reject("slice_superseded", "该切片已被更正取代", "保持排除，不作为当前事实注入");
    const expectedHash = await summaryRetrievalContentHash(slice);
    if (hit.document.text !== summaryRetrievalText(slice)) {
      return reject("retrieval_text", "索引文本与当前标题、时间戳或检索表示不一致", "在来源聊天同步该切片或修复总结索引",
        { expectedHash, indexedHash: hit.document.contentHash });
    }
    if (hit.document.contentHash !== expectedHash) {
      return reject("content_hash", "索引文本指纹不一致", "在来源聊天修复总结索引",
        { expectedHash, indexedHash: hit.document.contentHash });
    }
    if (typeof hit.document.metadata.bodyHash === "string") {
      const bodyHash = await sha256Hex(slice.content);
      if (hit.document.metadata.bodyHash !== bodyHash) {
        return reject("body_hash", "切片正文已变化，但索引仍记录旧正文", "在来源聊天同步该切片或修复总结索引",
          { expectedHash: bodyHash, indexedHash: hit.document.metadata.bodyHash });
      }
    }
    sliceByDocumentId.set(hit.document.documentId, slice);
    return hit;
  }));
  return {
    hits: validated.filter((hit): hit is RetrievalHit => Boolean(hit)),
    dropped: [...new Set(issues.map((issue) => issue.sliceId))],
    issues,
    sliceByDocumentId,
  };
}
