import { ECHOES_BUILD_INFO } from "../../../shared/build-info";
import { SummaryCoordinator } from "../../summary/summary-coordinator";
import { extractionCoordinator } from "../../memory/extraction-coordinator";
import { discussionCoordinator } from "../../discussion/discussion-coordinator";
import { statusCoordinator } from "../../status/status-coordinator";
import { h, icon, errorText } from "../kit/dom";
import { themeRoot, layer, setThemeChoice, themeChoice, type ThemeChoice } from "../kit/theme";
import { iconButton, dot, button } from "../kit/controls";
import { empty } from "../kit/layout";
import { tabStrip } from "../kit/tabs";
import { confirmAction } from "../kit/overlays";
import { reportError } from "../kit/feedback";
import { TaskTray } from "./tasks";
import { attentionItems, markedRoutes } from "./attention";
import { GROUP_LABELS, type ModuleDefinition, type PageContext } from "./context";
import { MODULES } from "./routes";

const THEME_ICONS: Record<ThemeChoice, [string, string]> = {
  system: ["circle-half-stroke", "主题：跟随系统"], dark: ["moon", "主题：深色"], light: ["sun", "主题：浅色"],
};

/** The workbench window: sidebar modules, tab strip, routed page and task tray. */
export class EchoesApp {
  readonly summary = new SummaryCoordinator();
  private readonly root = themeRoot(h("div", "ec-app"));
  private readonly sidebar = h("nav", "ec-sidebar");
  private readonly titleNode = h("h1", "ec-page-title");
  private readonly tabsHost = h("div", "ec-page-tabs");
  private readonly content = h("div", "ec-content");
  private readonly main = h("main", "ec-main", h("div", "ec-page-head", this.titleNode, this.tabsHost), this.content);
  private readonly contextLabel = h("div", "ec-context");
  private readonly footerNote = h("span", "ec-footer-note");
  private readonly themeButton = iconButton("切换主题", "circle-half-stroke", () => this.cycleTheme());
  private readonly tray = new TaskTray(this.summary, () => this.navigate("system/logs"));
  private route = "overview/home";
  private readonly lastTab = new Map<string, string>();
  private scope = new AbortController();
  private readonly memos = new Map<string, Map<string, unknown>>();
  private readonly scrolls = new Map<string, number>();
  private readonly hostInert = new Map<HTMLElement, boolean>();
  private previousFocus: HTMLElement | null = null;
  private activeChat = "";

  constructor() {
    this.root.id = "echoes-app";
    this.root.hidden = true;
    this.root.setAttribute("role", "dialog");
    this.root.setAttribute("aria-modal", "true");
    this.root.setAttribute("aria-label", "Echoes 记忆工作台");
    this.sidebar.setAttribute("aria-label", "Echoes 模块");
    this.main.tabIndex = -1;
    const navToggle = iconButton("打开导航", "bars", () => this.root.classList.toggle("nav-open"));
    navToggle.classList.add("ec-nav-toggle");
    const scrim = h("div", "ec-scrim");
    scrim.addEventListener("click", () => this.root.classList.remove("nav-open"));
    const header = h("header", "ec-header", navToggle,
      h("div", "ec-brand", icon("layer-group"), h("span", "", "Echoes")), this.contextLabel,
      h("div", "ec-row ec-header-actions", this.tray.button, this.themeButton, iconButton("关闭 Echoes", "xmark", () => this.close())));
    const footer = h("footer", "ec-footer", h("span", "", `前端 ${ECHOES_BUILD_INFO.appVersion}`), this.footerNote);
    this.root.append(h("div", "ec-window", header, this.tray.panel,
      h("div", "ec-body", this.sidebar, scrim, this.main), footer));
    this.updateThemeButton();
    this.root.addEventListener("keydown", (event) => {
      if (event.key !== "Escape" || event.defaultPrevented) return;
      if (this.root.classList.contains("nav-open")) { this.root.classList.remove("nav-open"); return; }
      event.preventDefault();
      void this.close();
    });
    window.addEventListener("beforeunload", (event) => {
      if (!this.root.hidden && this.dirty()) { event.preventDefault(); event.returnValue = ""; }
    });
    const markers = () => { this.tray.update(); this.drawMarkers(); };
    extractionCoordinator.subscribe(markers);
    discussionCoordinator.subscribe(markers);
    statusCoordinator.subscribe(markers);
    this.summary.subscribeProgress(markers);
  }

  get isOpen(): boolean {
    return !this.root.hidden;
  }

  async open(): Promise<void> {
    if (!this.root.isConnected) document.body.append(this.root);
    const overlays = layer();
    if (this.root.hidden) {
      this.previousFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      for (const sibling of document.body.children)
        if (sibling instanceof HTMLElement && sibling !== this.root && sibling !== overlays) {
          this.hostInert.set(sibling, sibling.inert);
          sibling.inert = true;
        }
      this.root.hidden = false;
    }
    await this.render();
    this.main.focus();
  }

  async close(): Promise<boolean> {
    if (this.dirty() && !await confirmAction({ title: "放弃未保存的修改并关闭？", confirmLabel: "放弃并关闭", danger: true })) return false;
    this.scope.abort();
    for (const dialog of layer().querySelectorAll<HTMLDialogElement>("dialog[open]")) dialog.close();
    this.root.hidden = true;
    this.root.classList.remove("nav-open");
    this.tray.toggle(false);
    for (const [node, inert] of this.hostInert) node.inert = inert;
    this.hostInert.clear();
    this.previousFocus?.focus();
    return true;
  }

  async reload(): Promise<void> {
    const changed = (SillyTavern.getContext().chatId ?? "") !== this.activeChat;
    if (changed) {
      this.scope.abort();
      for (const dialog of layer().querySelectorAll<HTMLDialogElement>("dialog[open]")) dialog.close();
    }
    if (this.root.hidden) return;
    if (changed || !this.dirty()) await this.render();
    else this.footerNote.textContent = "数据已在后台更新；刷新页面前未保存的编辑保持不变。";
  }

  async checkSummaryAutomation(): Promise<void> {
    if (!SillyTavern.getContext().chatId || this.summary.isRunning()) return;
    try {
      await this.summary.runAutomatic();
    } catch (error) {
      reportError(error);
    }
    await this.reload();
  }

  async checkExtractionAutomation(): Promise<void> {
    if (!SillyTavern.getContext().chatId || extractionCoordinator.isRunning()) return;
    await extractionCoordinator.runAutomatic();
    await this.reload();
  }

  private dirty(): boolean {
    return Boolean(this.root.querySelector('[data-dirty="true"]') || layer().querySelector('[data-dirty="true"]'));
  }

  private cycleTheme(): void {
    const order: ThemeChoice[] = ["system", "dark", "light"];
    setThemeChoice(order[(order.indexOf(themeChoice()) + 1) % order.length]!);
    this.updateThemeButton();
  }

  private updateThemeButton(): void {
    const [glyph, label] = THEME_ICONS[themeChoice()];
    this.themeButton.querySelector("i")!.className = `fa-solid fa-${glyph}`;
    this.themeButton.title = label;
    this.themeButton.setAttribute("aria-label", label);
  }

  private resolve(route: string): { module: ModuleDefinition; tab: ModuleDefinition["tabs"][number] } {
    const [moduleId, tabId] = route.split("/");
    const module = MODULES.find((item) => item.id === moduleId) ?? MODULES[0]!;
    const tab = module.tabs.find((item) => item.id === tabId) ?? module.tabs[0]!;
    return { module, tab };
  }

  async navigate(route: string): Promise<void> {
    const [moduleId, tabId] = route.split("/");
    const target = tabId ? route : `${moduleId}/${this.lastTab.get(moduleId!) ?? ""}`;
    const { module, tab } = this.resolve(target);
    const next = `${module.id}/${tab.id}`;
    this.root.classList.remove("nav-open");
    if (next === this.route) return;
    if (this.dirty() && !await confirmAction({ title: "放弃未保存的修改并离开？", confirmLabel: "放弃修改", danger: true })) return;
    // Open modals belong to the page being left; their context is about to be aborted.
    for (const dialog of layer().querySelectorAll<HTMLDialogElement>("dialog[open]")) dialog.close();
    this.scrolls.set(`${this.activeChat}:${this.route}`, this.content.scrollTop);
    this.route = next;
    this.lastTab.set(module.id, tab.id);
    await this.render();
  }

  private drawNavigation(active: ModuleDefinition, hasChat: boolean): void {
    const marked = markedRoutes(attentionItems(this.summary));
    this.sidebar.replaceChildren();
    let group: ModuleDefinition["group"] | null = null;
    for (const module of MODULES) {
      if (module.group !== group) {
        group = module.group;
        if (GROUP_LABELS[group]) this.sidebar.append(h("div", "ec-nav-group", GROUP_LABELS[group]));
      }
      const unavailable = module.requiresChat && !hasChat && module.tabs.every((tab) => tab.requiresChat ?? module.requiresChat);
      const link = h("button", "ec-nav-item", icon(module.icon), h("span", "ec-nav-label", module.label),
        marked.has(module.id) ? dot("warning") : null);
      link.type = "button";
      link.title = unavailable ? `${module.label}（需要先打开聊天）` : module.label;
      link.dataset.module = module.id;
      if (unavailable) link.classList.add("is-unavailable");
      if (module.id === active.id) link.setAttribute("aria-current", "page");
      link.addEventListener("click", () => void this.navigate(module.id));
      this.sidebar.append(link);
    }
  }

  private drawTabs(module: ModuleDefinition, activeTab: string): void {
    const marked = markedRoutes(attentionItems(this.summary));
    this.titleNode.textContent = module.label;
    this.tabsHost.replaceChildren(module.tabs.length > 1 ? tabStrip(`${module.label}分页`, module.tabs.map((tab) => ({
      id: tab.id, label: tab.label, marker: marked.has(`${module.id}/${tab.id}`) ? dot("warning") : null,
    })), activeTab, (id) => this.navigate(`${module.id}/${id}`)) : "");
  }

  private drawMarkers(): void {
    if (this.root.hidden) return;
    const { module, tab } = this.resolve(this.route);
    this.drawNavigation(module, Boolean(SillyTavern.getContext().chatId));
    this.drawTabs(module, tab.id);
  }

  private contextText(chatId: string, worldbook: string | null): string {
    return chatId ? `${chatId}${worldbook ? " · " + worldbook : " · 尚未建立记忆世界书"}` : "未打开聊天";
  }

  private async render(retried = false): Promise<void> {
    this.scope.abort();
    this.scope = new AbortController();
    const signal = this.scope.signal;
    const chatId = SillyTavern.getContext().chatId ?? "";
    const worldbook = window.TavernHelper?.getChatWorldbookName("current") ?? null;
    this.activeChat = chatId;
    this.contextLabel.textContent = this.contextText(chatId, worldbook);
    this.contextLabel.title = this.contextLabel.textContent;
    const { module, tab } = this.resolve(this.route);
    this.route = `${module.id}/${tab.id}`;
    this.drawNavigation(module, Boolean(chatId));
    this.drawTabs(module, tab.id);
    this.content.replaceChildren(h("div", "ec-loading", icon("spinner", "fa-spin"), h("span", "", "正在读取…")));
    this.main.setAttribute("aria-busy", "true");
    if (!this.memos.has(chatId)) this.memos.set(chatId, new Map());
    const memo = this.memos.get(chatId)!;
    const guard = () => {
      if ((SillyTavern.getContext().chatId ?? "") !== chatId
        || (window.TavernHelper?.getChatWorldbookName("current") ?? null) !== worldbook)
        throw new Error("当前聊天或世界书已变化，请重新打开页面后操作。");
    };
    const ctx: PageContext = {
      route: this.route, chatId, worldbook, summary: this.summary, signal,
      memo: <T>(key: string, initial: () => T) => {
        if (!memo.has(key)) memo.set(key, initial());
        return memo.get(key) as T;
      },
      forget: (key) => { memo.delete(key); },
      guard,
      refresh: async () => { if (!signal.aborted) { guard(); await this.render(); } },
      navigate: (route) => void this.navigate(route),
      run: (label, work, stop) => { guard(); return this.tray.run(label, chatId, () => work(), stop); },
      job: (label, start) => { guard(); return this.tray.job(label, chatId, start); },
      markers: () => this.drawMarkers(),
    };
    try {
      if ((tab.requiresChat ?? module.requiresChat) && !chatId) {
        this.content.replaceChildren(empty("这一页需要先在 SillyTavern 中打开一个聊天。"));
        return;
      }
      const page = await tab.render(ctx);
      if (signal.aborted) return;
      const bound = window.TavernHelper?.getChatWorldbookName("current") ?? null;
      if (worldbook === null && bound !== null && (SillyTavern.getContext().chatId ?? "") === chatId && !retried) {
        // Loading the page created the chat's memory worldbook; render once more so
        // the page's guard is bound to the new name.
        await this.render(true);
        return;
      }
      guard();
      this.content.replaceChildren(page);
      this.content.scrollTop = this.scrolls.get(`${chatId}:${this.route}`) ?? 0;
      this.footerNote.textContent = "";
    } catch (error) {
      if (signal.aborted) return;
      console.error("[Echoes] Page failed to render.", error);
      this.content.replaceChildren(empty(errorText(error), button("重试", () => this.render(), { icon: "rotate" })));
    } finally {
      if (!signal.aborted) {
        this.main.removeAttribute("aria-busy");
        this.tray.update();
      }
    }
  }
}
