import {
  creativePreferenceSchema, creativePreferencesSchema, EMPTY_CREATIVE_PREFERENCES, renderCreativePreferences,
  type CreativePreference, type CreativePreferences,
} from "../../../../shared/creative-preferences";
import { getSettings, saveSettings } from "../../../state/settings";
import { clearCreativePreferences } from "../../../memory/creative-preferences";
import { WorldbookMemoryStore } from "../../../worldbook/worldbook-memory";
import { h, uid, nowIso } from "../../kit/dom";
import { button, badge, menu, switchControl } from "../../kit/controls";
import { card, stack, code, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { formModal, modal, confirmAction } from "../../kit/overlays";
import { table, checkbox } from "../../kit/data";
import type { PageContext } from "../../shell/context";

const CATEGORIES: Record<CreativePreference["category"], string> = { expression: "表达方式", pace: "叙事节奏", boundary: "互动边界", other: "其他" };

export async function recallPreferencesPage(ctx: PageContext): Promise<HTMLElement> {
  const store = new WorldbookMemoryStore();
  const state = await store.load();
  let chat = state.catalog.creativePreferences;
  let global = getSettings().creativePreferences;
  const save = async (scope: "global" | "chat", next: CreativePreferences) => {
    ctx.guard();
    const parsed = creativePreferencesSchema.parse(next);
    if (scope === "global") {
      const settings = getSettings();
      if (JSON.stringify(settings.creativePreferences) !== JSON.stringify(global)) throw new Error("全局创作要求已在别处修改，请刷新后重试。");
      settings.creativePreferences = parsed;
      saveSettings(settings);
      global = parsed;
    } else {
      await store.saveCreativePreferences(parsed, chat);
      chat = parsed;
    }
    await clearCreativePreferences();
    await ctx.refresh();
  };
  const edit = (scope: "global" | "chat", current?: CreativePreference) => {
    const baseline = structuredClone((scope === "global" ? global : chat) ?? EMPTY_CREATIVE_PREFERENCES);
    const target = form([
      { key: "title", label: "标题", value: current?.title ?? "", required: true },
      { key: "category", label: "类别", type: "select", value: current?.category ?? "expression", options: Object.entries(CATEGORIES) },
      { key: "condition", label: "适用条件", type: "textarea", rows: 2, value: current?.condition ?? "", hint: "留空表示始终适用" },
      { key: "rule", label: "创作要求", type: "textarea", rows: 5, value: current?.rule ?? "", required: true },
      { key: "source", label: "来源", type: "textarea", rows: 2, value: current?.source ?? "用户手工填写" },
      { key: "confirmed", label: "已人工确认", type: "switch", value: current?.confirmed ?? false, hint: "只有已确认的规则才会注入" },
      { key: "enabled", label: "启用", type: "switch", value: current?.enabled ?? true },
    ], { className: "is-single" });
    formModal(current ? `编辑创作要求 · ${current.title}` : "添加创作要求", target, async (values) => {
      const rule = creativePreferenceSchema.parse({ ...values, id: current?.id ?? uid("preference"), updatedAt: nowIso() });
      baseline.rules = current ? baseline.rules.map((item) => item.id === current.id ? rule : item) : [...baseline.rules, rule];
      await save(scope, baseline);
    }, { size: "large" });
  };
  const section = (scope: "global" | "chat") => {
    const settings = (scope === "global" ? global : chat) ?? EMPTY_CREATIVE_PREFERENCES;
    return card(scope === "global" ? "全局创作要求" : "当前聊天的创作要求", { scope, actions: [
      button("添加", () => edit(scope), { small: true, icon: "plus" }),
    ] },
    switchControl("注入这一组要求", settings.enabled, (enabled) => save(scope, { ...settings, enabled })),
    table([
      { label: "标题", cell: (rule) => h("div", "ec-cell-stack", h("strong", "", rule.title), h("span", "ec-muted", rule.condition || "始终适用")) },
      { label: "类别", cell: (rule) => CATEGORIES[rule.category] },
      { label: "确认", cell: (rule) => badge(rule.confirmed ? "已确认" : "待确认", rule.confirmed ? "success" : "warning") },
      { label: "启用", cell: (rule) => checkbox(`启用 ${rule.title}`, rule.enabled, (enabled) =>
        void save(scope, { ...settings, rules: settings.rules.map((item) => item.id === rule.id ? { ...item, enabled, updatedAt: nowIso() } : item) })) },
      { label: "", className: "is-actions", cell: (rule) => menu(`${rule.title} 的操作`, [
        { label: "编辑", icon: "pen", onSelect: () => edit(scope, rule) },
        { label: "删除", icon: "trash", danger: true, onSelect: async () => {
          if (!await confirmAction({ title: `删除「${rule.title}」？`, danger: true, confirmLabel: "删除" })) return;
          await save(scope, { ...settings, rules: settings.rules.filter((item) => item.id !== rule.id) });
        } },
      ]) },
    ], settings.rules, { empty: "还没有创作要求。" }));
  };
  return stack(
    callout("info", "写作方式上的要求，不是剧情事实。条件成立时应用；当前聊天的要求优先于全局要求。只有已确认且启用的规则会注入。",
      button("预览生效文本", () => modal("创作要求注入", code(renderCreativePreferences(
        global ?? EMPTY_CREATIVE_PREFERENCES, chat ?? EMPTY_CREATIVE_PREFERENCES) || "没有已启用且已确认的规则。")), { small: true, variant: "ghost", icon: "eye" })),
    section("chat"), section("global"),
  );
}
