import type { JobRecord } from "../../../shared/domain";
import { echoesApi } from "../../api/client";
import { extractionCoordinator } from "../../memory/extraction-coordinator";
import { discussionCoordinator } from "../../discussion/discussion-coordinator";
import type { SummaryCoordinator } from "../../summary/summary-coordinator";
import { h, fill, icon, isAbort, errorText, formatTime } from "../kit/dom";
import { button, iconButton, badge } from "../kit/controls";
import { empty } from "../kit/layout";

interface TrackedTask {
  id: number;
  label: string;
  chatId: string;
  status: "running" | "done" | "failed" | "cancelled";
  message: string;
  progress: number;
  startedAt: string;
  stop?: (() => Promise<unknown>) | undefined;
}

export async function waitJob<T>(initial: JobRecord<T>, update: (job: JobRecord<T>) => void): Promise<T> {
  let job = initial;
  const deadline = Date.now() + 2 * 60 * 60_000;
  while (true) {
    update(job);
    if (job.status === "succeeded") {
      if (job.result === undefined) throw new Error("任务没有返回结果。");
      return job.result;
    }
    if (job.status === "cancelled") throw new DOMException(job.message || "任务已取消", "AbortError");
    if (job.status === "failed" || job.status === "ambiguous") throw new Error(job.error?.message ?? job.message);
    if (Date.now() >= deadline) throw new Error("任务等待超时，请在任务日志中检查后台状态。");
    await new Promise((resolve) => setTimeout(resolve, 750));
    job = await echoesApi.getJob<T>(job.id);
  }
}

const STATUS_TEXT = { running: "运行中", done: "已完成", failed: "失败", cancelled: "已取消" } as const;

/** The header task tray: session tasks started from the window plus stop shortcuts. */
export class TaskTray {
  readonly button: HTMLButtonElement;
  readonly panel = h("div", "ec-tray");
  private readonly count = h("span", "ec-tray-count");
  private tasks: TrackedTask[] = [];
  private sequence = 0;

  constructor(private readonly summary: SummaryCoordinator, private readonly openLogs: () => void) {
    this.button = h("button", "ec-btn is-ghost ec-tray-button", icon("list-check"), h("span", "", "任务"), this.count);
    this.button.type = "button";
    this.button.setAttribute("aria-haspopup", "dialog");
    this.button.setAttribute("aria-expanded", "false");
    this.button.addEventListener("click", () => this.toggle());
    this.panel.hidden = true;
    this.panel.setAttribute("role", "dialog");
    this.panel.setAttribute("aria-label", "任务");
    this.panel.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") return;
      event.stopPropagation();
      this.toggle(false);
      this.button.focus();
    });
    document.addEventListener("pointerdown", (event) => {
      if (!this.panel.hidden && !this.panel.contains(event.target as Node) && !this.button.contains(event.target as Node)) this.toggle(false);
    }, true);
  }

  toggle(open = this.panel.hidden): void {
    this.panel.hidden = !open;
    this.button.setAttribute("aria-expanded", String(open));
    if (open) { this.draw(); this.panel.querySelector<HTMLElement>("button")?.focus(); }
  }

  async run<T>(label: string, chatId: string, work: (task: TrackedTask) => Promise<T>, stop?: () => Promise<unknown>): Promise<T> {
    const task: TrackedTask = { id: ++this.sequence, label, chatId, status: "running", message: "", progress: 0, startedAt: new Date().toISOString(), stop };
    this.tasks.push(task);
    this.update();
    try {
      const result = await work(task);
      task.status = "done";
      task.progress = 1;
      return result;
    } catch (error) {
      task.status = isAbort(error) ? "cancelled" : "failed";
      task.message = errorText(error);
      throw error;
    } finally {
      task.stop = undefined;
      this.tasks = this.tasks.slice(-50);
      this.update();
    }
  }

  job<T>(label: string, chatId: string, start: () => Promise<JobRecord<T>>): Promise<T> {
    let current: JobRecord<T> | undefined;
    return this.run(label, chatId, async (task) => {
      current = await start();
      return waitJob(current, (job) => {
        current = job;
        task.progress = job.progress;
        task.message = job.message;
        this.update();
      });
    }, async () => {
      if (!current) throw new Error("任务正在提交，稍后再停止。");
      if (!(await echoesApi.cancelJob(current.id)).cancelled) throw new Error("后台未确认取消，请查看任务日志。");
    });
  }

  update(): void {
    const running = this.tasks.filter((task) => task.status === "running").length + (discussionCoordinator.running ? 1 : 0);
    this.count.textContent = running ? String(running) : "";
    this.button.classList.toggle("is-busy", running > 0);
    if (!this.panel.hidden) this.draw();
  }

  private draw(): void {
    const chatId = SillyTavern.getContext().chatId ?? "";
    const stops = [
      discussionCoordinator.running ? button("停止剧情讨论", () => discussionCoordinator.stop(), { variant: "danger", small: true, icon: "stop" }) : null,
      this.summary.isRunning() ? button("停止总结", () => this.summary.stop(), { variant: "danger", small: true, icon: "stop" }) : null,
      extractionCoordinator.isRunning() ? button("停止提取", () => extractionCoordinator.stopCurrent(), { variant: "danger", small: true, icon: "stop" }) : null,
    ];
    const items = this.tasks.slice().reverse().map((task) => {
      const tone = task.status === "failed" ? "danger" : task.status === "done" ? "success" : task.status === "running" ? "accent" : "neutral";
      const progress = task.status === "running" ? Object.assign(h("progress", "ec-progress"), { max: 1, value: task.progress }) : null;
      const stop = task.stop ? iconButton("停止任务", "stop", async () => {
        if (task.chatId !== chatId) throw new Error("请先切回此任务所属的聊天，或在服务端任务日志中取消。");
        task.message = "正在停止，等待后台确认";
        this.update();
        await task.stop?.();
      }, { variant: "danger" }) : null;
      return h("div", "ec-tray-item", h("div", "ec-tray-main", h("strong", "", task.label),
        h("span", "ec-muted", `${formatTime(task.startedAt, false)} · ${task.chatId || "无聊天"}`),
        task.message ? h("p", "ec-tray-message", task.message) : null, progress), badge(STATUS_TEXT[task.status], tone), stop);
    });
    fill(this.panel,
      h("header", "ec-tray-head", h("strong", "", "本次会话的任务"),
        button("服务端任务日志", () => { this.toggle(false); this.openLogs(); }, { variant: "ghost", small: true, icon: "arrow-right" })),
      stops.some(Boolean) ? h("div", "ec-row ec-tray-stops", ...stops) : null,
      items.length ? h("div", "ec-tray-list", ...items) : empty("本次会话还没有手动任务"),
    );
  }
}
