import type { SummarySlice } from "../../../../shared/domain";
import { renderContinuity } from "../../../../shared/continuity";
import { getSettings } from "../../../state/settings";
import type { SummaryWorldbookState } from "../../../worldbook/summary-worldbook";
import { h, formatTime, lines } from "../../kit/dom";
import { button, menu } from "../../kit/controls";
import { kv, code, callout } from "../../kit/layout";
import { form } from "../../kit/forms";
import { saveBar } from "../../kit/save";
import type { Drawer } from "../../kit/drawer";
import type { PageContext } from "../../shell/context";
import { editContinuity, showOriginalSource, stateBadge } from "../shared";
import { runBatchAction } from "./batch-actions";
import { assignFlags, editRetrieval, inspectIndex } from "./slice-tools";

export function showSlice(ctx: PageContext, pane: Drawer, state: SummaryWorldbookState, slice: SummarySlice, editing = false): Promise<boolean> {
  const title = `${slice.batch.batchNumber}.${slice.sliceNumber} ${slice.title}`;
  const actions = [
    editing ? null : button("编辑", () => showSlice(ctx, pane, state, slice, true), { icon: "pen", small: true }),
    menu(`${slice.title} 的更多操作`, [
      { label: "时间与认知", icon: "clock", onSelect: () => editContinuity(`${slice.title} · 时间与认知`, slice.continuity, async (continuity) => {
        ctx.guard();
        await ctx.summary.store.saveSlice(state.worldbookName, slice.id, {
          timestamp: slice.timestamp, title: slice.title, content: slice.content, tags: slice.tags, continuity,
        }, slice.batch.revision);
        await ctx.refresh();
      }) },
      { label: "设置标志", icon: "flag", onSelect: () => assignFlags(ctx, state, [slice]) },
      { label: "编辑检索表示", icon: "magnifying-glass", onSelect: () => editRetrieval(ctx, state, slice) },
      { label: "检查索引", icon: "stethoscope", onSelect: () => inspectIndex(ctx, slice) },
      { label: "查看批次原文", icon: "file-lines", onSelect: () => showOriginalSource(state, slice) },
      { label: "删除切片", icon: "trash", danger: true, onSelect: async () => {
        if (await runBatchAction(ctx, state, "delete", [slice])) { await pane.close(); await ctx.refresh(); }
      } },
    ]),
  ];
  if (editing) {
    const target = form([
      { key: "timestamp", label: "故事时间", value: slice.timestamp, required: true },
      { key: "title", label: "标题", value: slice.title, required: true },
      { key: "tags", label: "标签", type: "textarea", rows: 2, value: slice.tags.join("\n"), hint: "每行一项" },
      { key: "content", label: "正文", type: "textarea", rows: 16, value: slice.content, required: true },
    ], { className: "is-single" });
    target.node.addEventListener("ec-reset", () => void showSlice(ctx, pane, state, slice));
    return pane.open(slice.id, title, [target.node,
      h("div", "ec-row", button("取消编辑", () => target.dirty() ? target.reset() : showSlice(ctx, pane, state, slice), { variant: "ghost", small: true })),
      saveBar(target, async (values) => {
        ctx.guard();
        await ctx.run("保存并同步切片", () => ctx.summary.editSlice(slice.id, {
          timestamp: values.timestamp, title: values.title, content: values.content, tags: lines(values.tags),
        }, slice.batch.revision));
        target.commit();
        await ctx.refresh();
      }, "保存并同步")], actions);
  }
  const flags = getSettings().retrieval.recall.flagRules;
  const flagNames = (slice.recallFlags ?? []).map((id) => flags.find((flag) => flag.id === id)?.name ?? id);
  const continuity = renderContinuity(slice.continuity);
  return pane.open(slice.id, title, [
    kv([
      ["故事时间", slice.timestamp], ["向量状态", stateBadge(slice.batch.state)],
      ["标签", slice.tags.join("、") || "—"], ["标志", flagNames.join("、") || "—"],
      ["检索表示", slice.retrievalText ? "独立表示" : "使用正文"],
      ["批次", `第 ${slice.batch.batchNumber} 批 · 第 ${slice.batch.revision} 版 · ${formatTime(slice.batch.updatedAt)}`],
    ]),
    slice.batch.source?.kind === "imported" ? callout("info", "这个切片来自备份导入，没有当前聊天的原文定位。") : null,
    slice.batch.purpose === "supplement" ? callout("info", "这是定向补全生成的切片。") : null,
    h("div", "ec-prose", slice.content),
    continuity ? h("div", "ec-field-block", h("h4", "", "时间与认知"), code(continuity)) : null,
    slice.retrievalText ? h("div", "ec-field-block", h("h4", "", "检索表示"), code(slice.retrievalText)) : null,
  ], actions);
}
