import { getSettings, saveSettings, type EchoesSettings } from "../../../state/settings";
import { recallCoordinator } from "../../../recall-coordinator";
import { h } from "../../kit/dom";
import { button, switchControl } from "../../kit/controls";
import { card, stack, callout } from "../../kit/layout";
import { form, type FieldSpec } from "../../kit/forms";
import { formCard } from "../../kit/save";
import { modal } from "../../kit/overlays";
import type { PageContext } from "../../shell/context";
import { traceView } from "./trace";

export function updateRecall(change: (recall: EchoesSettings["retrieval"]["recall"], settings: EchoesSettings) => void): void {
  const settings = getSettings();
  change(settings.retrieval.recall, settings);
  saveSettings(settings);
}

export async function recallStrategyPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await ctx.summary.load();
  const settings = getSettings();
  const recall = settings.retrieval.recall;
  const rerankSet = settings.retrieval.rerankSets.find((set) => set.id === recall.rerankSetId);
  const topK = (key: "vectorTopK" | "bm25TopK" | "rerankTopK" | "finalTopK", label: string, max: number, hint?: string): FieldSpec =>
    ({ key, label, type: "number", min: 1, max, value: recall[key], required: true, hint });
  const candidates = form([
    { key: "vectorEnabled", label: "向量检索", type: "switch", value: recall.vectorEnabled, hint: "按语义相似度查找" },
    topK("vectorTopK", "向量候选数", 200),
    { key: "bm25Enabled", label: "BM25 文本检索", type: "switch", value: recall.bm25Enabled, hint: "按词面匹配查找" },
    topK("bm25TopK", "BM25 候选数", 200),
  ]);
  const rerank = form([
    { key: "rerankEnabled", label: "结果重排序", type: "switch", value: recall.rerankEnabled, hint: "对融合后的候选再判断一次相关程度" },
    topK("rerankTopK", "送去重排序的候选数", 100),
  ]);
  const output = form([
    topK("finalTopK", "最终结果数", 100, "普通召回最多注入的切片数"),
    { key: "minimumRelevance", label: "最低相关性", type: "number", step: 0.001, value: recall.minimumRelevance, hint: "0 表示不过滤" },
  ]);
  const profiles: Array<[string, string]> = [["rrf", "RRF 融合分数（含重排序失败时的降级）"],
    ...settings.retrieval.rerankSets.map((set): [string, string] => [`rerank:${set.id}`, `重排序分数 · ${set.name}`])];
  const thresholds = form(profiles.map(([key, label]) => ({ key, label, type: "number" as const, step: 0.0001,
    value: recall.relevanceProfiles?.[key], hint: "留空时使用上面的最低相关性" })));
  return stack(
    card("总结召回", { scope: "chat", actions: [button("召回预览", async () => {
      const result = await ctx.run("召回预览", () => recallCoordinator.preview());
      modal("召回预览", traceView(result.trace), { size: "large" });
    }, { small: true, icon: "flask" })] },
      switchControl("为当前聊天召回总结", state.catalog.recallEnabled, async (value) => {
        ctx.guard();
        await ctx.summary.setRecallEnabled(value);
      }, { hint: "生成回复前，按下面的策略找出相关的总结切片注入主模型" })),
    formCard("① 候选检索", candidates, (values) => updateRecall((next) => {
      next.vectorEnabled = values.vectorEnabled; next.vectorTopK = values.vectorTopK;
      next.bm25Enabled = values.bm25Enabled; next.bm25TopK = values.bm25TopK;
    }), { scope: "global", description: "两路检索的结果用 RRF 融合。" }),
    formCard("② 重排序", rerank, (values) => updateRecall((next) => {
      next.rerankEnabled = values.rerankEnabled; next.rerankTopK = values.rerankTopK;
    }), { scope: "global", after: h("div", "", callout(rerankSet ? "info" : "warning", `重排序端点组：${rerankSet?.name ?? "未设置"}`,
      button("去设置", () => ctx.navigate("api/assignment"), { variant: "ghost", small: true, icon: "arrow-right" }))) }),
    formCard("③ 输出与过滤", output, (values) => updateRecall((next) => {
      next.finalTopK = values.finalTopK; next.minimumRelevance = values.minimumRelevance ?? 0;
    }), { scope: "global" }),
    formCard("分模式阈值", thresholds, (values) => updateRecall((next) => {
      const profilesNext = { ...next.relevanceProfiles };
      for (const [key] of profiles) {
        if (values[key] === undefined) delete profilesNext[key];
        else profilesNext[key] = values[key];
      }
      next.relevanceProfiles = profilesNext;
    }), { scope: "global", description: "不同评分方式的分数尺度不同，可以分别设置最低相关性。" }),
  );
}
