import type { ProviderAttempt, RetrievalInjectionConfig, SummarySlice } from "../../../shared/domain";
import { continuitySchema, type ContinuityAttributes } from "../../../shared/continuity";
import { checkpointFloor } from "../../chat-message-index";
import { summaryOriginalSource } from "../../summary/summary-original-source";
import type { SummaryWorldbookState } from "../../worldbook/summary-worldbook";
import { h } from "../kit/dom";
import { badge, type Tone } from "../kit/controls";
import { form, type FieldSpec } from "../kit/forms";
import { formModal, modal } from "../kit/overlays";
import { table } from "../kit/data";
import { card, code } from "../kit/layout";

const STATES: Record<string, [string, Tone]> = {
  ready: ["向量就绪", "success"], pending: ["待同步", "neutral"], failed: ["失败", "danger"],
  ambiguous: ["结果待确认", "warning"], stale: ["源消息已变化", "warning"],
  running: ["运行中", "accent"], queued: ["排队中", "neutral"], succeeded: ["已完成", "success"], cancelled: ["已取消", "neutral"],
  permanent: ["常驻", "accent"], keyword: ["关键词", "neutral"], vectorized: ["向量", "neutral"],
  pass: ["正常", "success"], warning: ["需关注", "warning"], fail: ["异常", "danger"], unavailable: ["不可用", "neutral"],
};

export function stateBadge(state: string): HTMLElement {
  const [label, tone] = STATES[state] ?? [state, "neutral" as Tone];
  return badge(label, tone);
}
export const ACTIVATION_OPTIONS: Array<[string, string]> = [["keyword", "关键词"], ["vectorized", "向量"], ["permanent", "常驻"]];
export const IMPORT_POLICIES: Array<[string, string]> = [["copy", "创建副本"], ["skip", "跳过"], ["overwrite", "覆盖"]];
export const FAILOVER_OPTIONS: Array<[string, string]> = [
  ["confirm_ambiguous", "结果不确定时询问"], ["definitive_only", "仅在明确失败时切换"], ["always", "自动切换"],
];

export function lastFloor(): number {
  return Math.max(0, SillyTavern.getContext().chat.length - 1);
}

export function floorText(messageId?: string | null): string {
  if (!messageId) return "尚未处理";
  const floor = checkpointFloor(messageId);
  return floor < 0 ? "原消息已不存在" : `第 ${floor} 楼`;
}

export function floorFields(start: number, end: number): FieldSpec[] {
  const max = lastFloor();
  return [
    { key: "start", label: "起始楼层", type: "number", min: 0, max, value: Math.min(start, max), required: true },
    { key: "end", label: "结束楼层", type: "number", min: 0, max, value: Math.min(end, max), required: true },
  ];
}

export function injectionSpecs(value: RetrievalInjectionConfig): FieldSpec[] {
  return [
    { key: "position", label: "注入位置", type: "select", value: value.position,
      options: [["before_character", "角色定义前"], ["after_character", "角色定义后"], ["at_depth", "指定深度"]] },
    { key: "role", label: "消息角色", type: "select", value: value.role,
      options: [["system", "System"], ["user", "User"], ["assistant", "Assistant"]] },
    { key: "depth", label: "深度", type: "number", min: 0, max: 100, value: value.depth, hint: "仅在“指定深度”时使用" },
    { key: "order", label: "顺序", type: "number", min: -10000, max: 10000, value: value.order },
    { key: "maxWaitMs", label: "最长等待（毫秒）", type: "number", min: 1000, max: 300000, value: value.maxWaitMs },
    { key: "template", label: "注入模板", type: "code", rows: 6, value: value.template, required: true },
  ];
}

export function attemptsTable(attempts: ReadonlyArray<Pick<ProviderAttempt, "endpointName" | "outcome" | "durationMs" | "status" | "message">>): HTMLElement {
  const outcome = { succeeded: "成功", definitive_failure: "明确失败", ambiguous_failure: "结果不确定", skipped: "跳过" };
  return table([
    { label: "端点", cell: (item) => item.endpointName },
    { label: "结果", cell: (item) => badge(outcome[item.outcome], item.outcome === "succeeded" ? "success"
      : item.outcome === "ambiguous_failure" ? "warning" : item.outcome === "skipped" ? "neutral" : "danger") },
    { label: "耗时", cell: (item) => `${item.durationMs} ms` },
    { label: "说明", cell: (item) => [item.status, item.message].filter(Boolean).join(" · ") || "—" },
  ], attempts, { empty: "没有端点尝试记录" });
}

const VALIDITY: Array<[string, string]> = [["", "未标记"], ["current", "当前资料"], ["historical", "历史经历"], ["superseded", "整条已更正失效"]];
const CHANGE: Array<[string, string]> = [["", "未分类"], ["fact_change", "事实变化"], ["knowledge_change", "认知变化"], ["canon_correction", "设定更正"]];

/** Edits time, validity and character-knowledge attributes of an entry or slice. */
export function editContinuity(title: string, value: ContinuityAttributes | undefined, save: (value: ContinuityAttributes) => Promise<unknown>) {
  const target = form([
    { key: "eventTime", label: "事件时间", value: value?.eventTime ?? "", placeholder: "如 2081-03-03 或 unknown" },
    { key: "learnedTime", label: "得知时间", value: value?.learnedTime ?? "" },
    { key: "validFrom", label: "有效起点", value: value?.validFrom ?? "" },
    { key: "validUntil", label: "有效终点", value: value?.validUntil ?? "" },
    { key: "validity", label: "有效状态", type: "select", value: value?.validity ?? "", options: VALIDITY },
    { key: "changeKind", label: "本次变更性质", type: "select", value: "", options: CHANGE },
    { key: "note", label: "限定与不确定性说明", type: "textarea", rows: 3, value: value?.note ?? "" },
    { key: "knowledge", label: "角色认知（JSON 数组）", type: "json", rows: 8, value: value?.knowledge ?? [],
      hint: '每项形如 {"character":"人物","state":"known","claim":"内容"}；state 可为 known / believed / suspected / misunderstood / unknown' },
  ]);
  return formModal(title, target, async (raw) => {
    const cleaned = Object.fromEntries(Object.entries(raw).filter(([, item]) => item !== "" && !(Array.isArray(item) && !item.length)));
    await save(continuitySchema.parse(cleaned));
  }, { size: "large" });
}

export async function showOriginalSource(state: SummaryWorldbookState, slice: SummarySlice): Promise<void> {
  const source = await summaryOriginalSource(slice, { worldbookName: state.worldbookName, chatId: state.catalog.chatId });
  modal(`批次 ${slice.batch.batchNumber} 原文`, [
    h("p", "ec-muted", source.scope),
    ...source.messages.map((message) => card(`${message.role === "user" ? "主持人" : "助手"} · ${message.id}`, {}, code(message.content))),
  ], { size: "large" });
}
