import { h, type Child } from "./dom";
import { iconButton } from "./controls";
import { empty } from "./layout";

export interface Column<T> {
  label: string;
  cell: (item: T, index: number) => Child;
  className?: string | undefined;
}

/** A table that collapses to labelled cards on narrow screens. */
export function table<T>(columns: Array<Column<T>>, items: readonly T[], options: { empty?: string; className?: string } = {}): HTMLElement {
  if (!items.length) return empty(options.empty ?? "没有数据");
  const head = h("tr", "", ...columns.map((column) => {
    const cell = h("th", column.className ?? "", column.label);
    cell.scope = "col";
    return cell;
  }));
  const body = h("tbody", "", ...items.map((item, index) => h("tr", "", ...columns.map((column) => {
    const cell = h("td", column.className ?? "", column.cell(item, index));
    cell.dataset.label = column.label;
    return cell;
  }))));
  return h("div", `ec-table-wrap${options.className ? " " + options.className : ""}`,
    h("table", "ec-table", h("thead", "", head), body));
}

export interface PageState { page: number }

export function paginate<T>(items: readonly T[], state: PageState, size = 50): { items: T[]; pages: number } {
  const pages = Math.max(1, Math.ceil(items.length / size));
  state.page = Math.max(0, Math.min(state.page, pages - 1));
  return { items: items.slice(state.page * size, (state.page + 1) * size), pages };
}

export function pager(state: PageState, pages: number, total: number, onChange: () => void, unit = "条"): HTMLElement {
  const previous = iconButton("上一页", "chevron-left", () => { state.page--; onChange(); });
  const next = iconButton("下一页", "chevron-right", () => { state.page++; onChange(); });
  previous.disabled = state.page <= 0;
  next.disabled = state.page >= pages - 1;
  return h("div", "ec-pager", h("span", "ec-muted", `共 ${total} ${unit}`),
    h("div", "ec-row", previous, h("span", "ec-pager-page", `${state.page + 1} / ${pages}`), next));
}

/** A search field that waits for typing (and IME composition) to settle. */
export function searchBox(value: string, onSearch: (value: string) => void, label = "搜索", signal?: AbortSignal): HTMLInputElement {
  const input = h("input", "ec-input ec-search");
  input.type = "search";
  input.value = value;
  input.placeholder = label;
  input.setAttribute("aria-label", label);
  let timer: ReturnType<typeof setTimeout> | undefined;
  let composing = false;
  let delivered = value;
  const cancel = () => { clearTimeout(timer); timer = undefined; };
  const flush = () => {
    cancel();
    if (composing || signal?.aborted || !input.isConnected || input.value === delivered) return;
    delivered = input.value;
    onSearch(delivered);
  };
  const schedule = () => {
    cancel();
    if (!composing) timer = setTimeout(flush, 500);
  };
  input.addEventListener("compositionstart", () => { composing = true; cancel(); });
  input.addEventListener("compositionend", () => { composing = false; schedule(); });
  input.addEventListener("input", (event) => {
    if ((event as InputEvent).isComposing) cancel();
    else schedule();
  });
  input.addEventListener("keydown", (event) => {
    if (event.key === "Enter" && !event.isComposing && !composing) {
      event.preventDefault();
      flush();
    }
  });
  signal?.addEventListener("abort", cancel, { once: true });
  return input;
}

/** Re-renders a region while keeping focus and caret in its search box. */
export function keepSearchFocus(host: HTMLElement, render: () => void): void {
  const active = host.querySelector<HTMLInputElement>(".ec-search");
  const focused = active !== null && document.activeElement === active;
  const caret = active?.selectionStart ?? null;
  render();
  if (!focused) return;
  const next = host.querySelector<HTMLInputElement>(".ec-search");
  next?.focus();
  if (next && caret !== null) next.setSelectionRange(caret, caret);
}

export interface ListRow {
  key: string;
  title: Child;
  meta?: Child;
  trailing?: Child;
  leading?: Child;
  selected?: boolean | undefined;
  onOpen: () => unknown;
}

/** A vertical list of openable rows; `leading` usually carries a checkbox. */
export function list(rows: ListRow[], emptyText = "没有匹配的条目"): HTMLElement {
  if (!rows.length) return empty(emptyText);
  return h("div", "ec-list", ...rows.map((row) => {
    const open = h("button", "ec-list-open", h("span", "ec-list-title", row.title),
      row.meta ? h("span", "ec-list-meta", row.meta) : null);
    open.type = "button";
    open.addEventListener("click", () => void row.onOpen());
    const node = h("div", `ec-list-row${row.selected ? " is-active" : ""}`, row.leading, open,
      row.trailing ? h("span", "ec-list-trailing", row.trailing) : null);
    node.dataset.key = row.key;
    return node;
  }));
}

export function checkbox(label: string, checked: boolean, onChange: (value: boolean) => void, disabled = false): HTMLInputElement {
  const input = h("input", "ec-check");
  input.type = "checkbox";
  input.checked = checked;
  input.disabled = disabled;
  input.setAttribute("aria-label", label);
  input.addEventListener("change", () => onChange(input.checked));
  return input;
}
