import { readMemoryHistory, type MemoryHistoryRecord } from "../../../worldbook/memory-history";
import { h, fill, formatTime } from "../../kit/dom";
import { badge } from "../../kit/controls";
import { code, lazy, muted } from "../../kit/layout";
import { list, paginate, pager, searchBox, keepSearchFocus } from "../../kit/data";
import { drawer } from "../../kit/drawer";
import type { PageContext } from "../../shell/context";
import { memoryStore } from "./row-editor";

const KINDS: Record<string, string> = {
  fact_change: "事实变化", knowledge_change: "认知变化", canon_correction: "设定更正", unclassified: "未分类变更", deleted: "删除条目",
};

function compare(record: MemoryHistoryRecord): HTMLElement {
  return h("div", "ec-compare",
    h("div", "", h("h4", "", "修改前"), code(record.before?.content ?? "（新建）")),
    h("div", "", h("h4", "", "修改后"), code(record.after?.content ?? "（已删除）")));
}

export async function historyPage(ctx: PageContext): Promise<HTMLElement> {
  const state = await memoryStore.load();
  const records = await readMemoryHistory(state.worldbookName);
  const types = new Map(state.catalog.types.map((type) => [type.id, type.name]));
  const ui = ctx.memo("structured-history", () => ({ query: "", page: 0 }));
  const pane = drawer("变更对照");
  const host = h("div", "ec-stack");
  const open = (record: MemoryHistoryRecord) => pane.open(record.id, record.after?.name ?? record.before?.name ?? record.rowId, [
    h("div", "ec-row", badge(KINDS[record.kind] ?? record.kind), badge(types.get(record.typeId) ?? "已删除的表"),
      h("span", "ec-muted", formatTime(record.recordedAt))),
    compare(record),
    lazy("元数据对照", { before: record.before?.metadata, after: record.after?.metadata }),
  ]);
  const draw = () => keepSearchFocus(host, () => {
    const query = ui.query.toLocaleLowerCase();
    const matched = records.filter((record) => !query
      || `${record.rowId} ${record.before?.name ?? ""} ${record.after?.name ?? ""}`.toLocaleLowerCase().includes(query));
    const page = paginate(matched, ui);
    fill(host,
      h("div", "ec-toolbar", h("div", "ec-row", searchBox(ui.query, (value) => { ui.query = value; ui.page = 0; draw(); }, "搜索条目名称", ctx.signal))),
      muted("每次修改或删除结构化条目都会记录修改前后的内容。"),
      list(page.items.map((record) => ({
        key: record.id, selected: pane.current() === record.id,
        title: record.after?.name ?? record.before?.name ?? record.rowId,
        meta: `${formatTime(record.recordedAt)} · ${types.get(record.typeId) ?? "已删除的表"}`,
        trailing: badge(KINDS[record.kind] ?? record.kind, record.kind === "deleted" ? "danger" : "neutral"),
        onOpen: () => open(record),
      })), query ? "没有匹配的变更" : "还没有变更记录"),
      page.pages > 1 ? pager(ui, page.pages, matched.length, draw) : null,
    );
  });
  pane.onChange(() => draw());
  pane.list.append(host);
  draw();
  return pane.node;
}
