import { h, icon, move, type Child } from "./dom";
import { button, badge, menu } from "./controls";
import { toast } from "./feedback";
import { empty } from "./layout";
import { confirmAction } from "./overlays";

export interface SortableOptions<T> {
  items: readonly T[];
  describe: (item: T) => { title: string; tag?: string | undefined; note?: string | undefined };
  /** Opens an editor; call done with the edited item. drafts are the unsaved list. */
  edit: (item: T | undefined, done: (item: T) => void, drafts: T[]) => unknown;
  save: (items: T[]) => unknown;
  toggle?: { get: (item: T) => boolean; set: (item: T, value: boolean) => T } | undefined;
  addLabel?: string | undefined;
  extra?: (drafts: () => T[]) => Child[];
  emptyText?: string | undefined;
}

/**
 * An ordered list edited as a draft (reorder by drag or menu, toggle, edit,
 * delete) and written with one explicit save.
 */
export function sortable<T>(options: SortableOptions<T>): HTMLElement {
  let items = structuredClone([...options.items]) as T[];
  const root = h("div", "ec-sortable");
  const rows = h("div", "ec-sortable-rows");
  const status = h("span", "ec-savebar-text", "排列有未保存的修改");
  const bar = h("div", "ec-savebar", status, h("div", "ec-row",
    button("放弃", () => { items = structuredClone([...options.items]) as T[]; setDirty(false); render(); }, { variant: "ghost", small: true }),
    button("保存", async () => {
      await options.save(structuredClone(items));
      setDirty(false);
      toast("已保存", "success");
    }, { variant: "primary", small: true, icon: "floppy-disk" })));
  const setDirty = (value: boolean) => {
    bar.hidden = !value;
    if (value) root.dataset.dirty = "true";
    else delete root.dataset.dirty;
  };
  const changed = () => { setDirty(true); render(); };
  const render = () => {
    if (!items.length) { rows.replaceChildren(empty(options.emptyText ?? "暂无项目")); return; }
    rows.replaceChildren(...items.map((item, index) => {
      const info = options.describe(item);
      const toggle = options.toggle;
      const enabled = toggle ? toggle.get(item) : true;
      const control = toggle ? (() => {
        const input = h("input", "ec-switch");
        input.type = "checkbox";
        input.setAttribute("role", "switch");
        input.setAttribute("aria-label", `启用 ${info.title}`);
        input.checked = enabled;
        input.addEventListener("change", () => { items[index] = toggle.set(item, input.checked); changed(); });
        return input;
      })() : null;
      const open = h("button", "ec-sortable-open", h("span", "ec-sortable-title", info.title),
        info.note ? h("span", "ec-list-meta", info.note) : null);
      open.type = "button";
      open.addEventListener("click", () => options.edit(item, (next) => { items[index] = next; changed(); }, structuredClone(items)));
      const node = h("div", `ec-sortable-row${enabled ? "" : " is-off"}`,
        h("span", "ec-drag", icon("grip-vertical")), h("span", "ec-sortable-index", String(index + 1)), open,
        info.tag ? badge(info.tag) : null, control,
        menu(`${info.title} 的操作`, [
          { label: "编辑", icon: "pen", onSelect: () => options.edit(item, (next) => { items[index] = next; changed(); }, structuredClone(items)) },
          { label: "上移", icon: "arrow-up", disabled: index === 0, onSelect: () => { items = move(items, index, -1); changed(); } },
          { label: "下移", icon: "arrow-down", disabled: index === items.length - 1, onSelect: () => { items = move(items, index, 1); changed(); } },
          { label: "删除", icon: "trash", danger: true, onSelect: async () => {
            if (!await confirmAction({ title: `删除「${info.title}」？`, message: "保存排列后才会生效。", confirmLabel: "删除", danger: true })) return;
            items.splice(index, 1);
            changed();
          } },
        ]));
      node.draggable = true;
      node.addEventListener("dragstart", (event) => {
        event.dataTransfer?.setData("text/plain", String(index));
        node.classList.add("is-dragging");
      });
      node.addEventListener("dragend", () => node.classList.remove("is-dragging"));
      node.addEventListener("dragover", (event) => event.preventDefault());
      node.addEventListener("drop", (event) => {
        event.preventDefault();
        const from = Number(event.dataTransfer?.getData("text/plain"));
        if (!Number.isInteger(from) || from === index || from < 0 || from >= items.length) return;
        items = move(items, from, index - from);
        changed();
      });
      return node;
    }));
  };
  const head = h("div", "ec-row",
    button(options.addLabel ?? "添加", () => options.edit(undefined, (next) => { items.push(next); changed(); }, structuredClone(items)), { icon: "plus", small: true }),
    ...(options.extra?.(() => structuredClone(items)) ?? []));
  setDirty(false);
  render();
  root.append(head, rows, bar);
  return root;
}
